            ["Enter the slot ClawTweaks sits at, then Run."] = "ClawTweaks\uAC00 \uC788\uB294 \uC704\uCE58\uB97C \uC785\uB825\uD55C \uB4A4 \uC2E4\uD589\uD558\uC138\uC694.",
            ["Exit"] = "\uC885\uB8CC",
            ["Expected for a same-version reinstall \u2014 the helper doesn't restart or show a UAC prompt when nothing changed. Open the Game Bar (Win+G) to check it's still running."] = "\uB3D9\uC77C\uD55C \uBC84\uC804\uC744 \uB2E4\uC2DC \uC124\uCE58\uD560 \uB54C\uB294 \uC815\uC0C1\uC785\uB2C8\uB2E4 \u2014 \uBCC0\uACBD\uB41C \uAC83\uC774 \uC5C6\uC73C\uBA74 \uD5EC\uD37C\uB294 \uB2E4\uC2DC \uC2DC\uC791\uD558\uAC70\uB098 UAC \uCC3D\uC744 \uD45C\uC2DC\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4. Game Bar(Win+G)\uB97C \uC5F4\uC5B4 \uC2E4\uD589 \uC911\uC778\uC9C0 \uD655\uC778\uD558\uC138\uC694.",
            ["Experimental versions (nightly)"] = "\uC2E4\uD5D8 \uBC84\uC804 (\uB098\uC774\uD2B8\uB9AC)",
            ["Folder is gone"] = "\uD3F4\uB354 \uC5C6\uC74C",
            ["FPS cap"] = "FPS \uC81C\uD55C",
            ["Favorites"] = "\uC990\uACA8\uCC3E\uAE30",
            ["Final clean-up and check. MSI Center M is handled here (after installation) because it fights ClawTweaks for the controller and LED."] = "\uB9C8\uC9C0\uB9C9 \uC815\uB9AC \uBC0F \uD655\uC778\uC785\uB2C8\uB2E4. MSI Center M\uC740 \uCEE8\uD2B8\uB864\uB7EC\uC640 LED\uB97C \uB450\uACE0 ClawTweaks\uC640 \uCDA9\uB3CC\uD558\uBBC0\uB85C \uC124\uCE58 \uD6C4 \uC5EC\uAE30\uC11C \uCC98\uB9AC\uD569\uB2C8\uB2E4.",
            ["Final controller check"] = "\uB9C8\uC9C0\uB9C9 \uCEE8\uD2B8\uB864\uB7EC \uD655\uC778",
            ["Finish here and close the window."] = "\uC5EC\uAE30\uC11C \uB05D\uB0B4\uACE0 \uCC3D\uC744 \uB2EB\uC2B5\uB2C8\uB2E4.",
            ["Firmware button remapping is there too, and works without it."] = "\uD38C\uC6E8\uC5B4 \uBC84\uD2BC \uB9AC\uB9E4\uD551\uB3C4 \uC788\uC73C\uBA70, \uC774\uAC83 \uC5C6\uC774\uB3C4 \uB3D9\uC791\uD569\uB2C8\uB2E4.",
            ["First install on this PC \u2014 Windows will ask for permission once."] = "\uC774 PC\uC758 \uCCAB \uC124\uCE58\uC785\uB2C8\uB2E4 \u2014 Windows\uAC00 \uD55C \uBC88 \uAD8C\uD55C\uC744 \uBB3B\uC2B5\uB2C8\uB2E4.",
            ["Frame generation"] = "\uD504\uB808\uC784 \uC0DD\uC131",
            ["Front and M back-button mapping, gyro with smoothing, per-game profiles."] = "\uC804\uBA74 \uBC0F M \uBC31 \uBC84\uD2BC \uB9E4\uD551, \uC2A4\uBB34\uB529 \uC790\uC774\uB85C, \uAC8C\uC784\uBCC4 \uD504\uB85C\uD544.",
            ["Fullscreen"] = "\uC804\uCCB4 \uD654\uBA74",
            ["GPU scaling"] = "GPU \uC2A4\uCF00\uC77C\uB9C1",
            ["Game Library"] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC",
            ["Get ClawTweaks"] = "ClawTweaks \uBC1B\uAE30",
            ["Go into Library Settings and switch on Start in the library."] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC \uC124\uC815\uC5D0\uC11C \uB77C\uC774\uBE0C\uB7EC\uB9AC\uC5D0\uC11C \uC2DC\uC791\uC744 \uCF1C\uC138\uC694.",
            ["Guided setup"] = "\uB2E8\uACC4\uBCC4 \uC124\uCE58",
            ["Gyro"] = "\uC790\uC774\uB85C",
            ["Hair triggers"] = "\uD5E4\uC5B4 \uD2B8\uB9AC\uAC70",
            ["Hardware controller confirmed."] = "\uD558\uB4DC\uC6E8\uC5B4 \uCEE8\uD2B8\uB864\uB7EC\uB97C \uD655\uC778\uD588\uC2B5\uB2C8\uB2E4.",
            ["Helps set the most important ClawTweaks settings."] = "\uAC00\uC7A5 \uC911\uC694\uD55C ClawTweaks \uC124\uC815\uC744 \uB3C4\uC640\uC90D\uB2C8\uB2E4.",
            ["Hidden"] = "\uC228\uAE40",
            ["Hidden until you unlock it."] = "\uB2EC\uC131\uD560 \uB54C\uAE4C\uC9C0 \uC228\uACA8\uC9D0.",
            ["Hide"] = "\uC228\uAE30\uAE30",
            ["Hide a tab with A."] = "A\uB85C \uD0ED\uC744 \uC228\uAE30\uC138\uC694.",
            ["HidHide and usbip install kernel drivers. Reboot the device once after installing them, then run this setup again."] = "HidHide\uC640 usbip\uC740 \uCEE4\uB110 \uB4DC\uB77C\uC774\uBC84\uB97C \uC124\uCE58\uD569\uB2C8\uB2E4. \uC124\uCE58 \uD6C4 \uC7A5\uCE58\uB97C \uD55C \uBC88 \uC7AC\uBD80\uD305\uD55C \uB2E4\uC74C \uC774 \uC124\uCE58\uB97C \uB2E4\uC2DC \uC2E4\uD589\uD558\uC138\uC694.",
            ["How do I uninstall and go back to MSI Center M?"] = "\uC5B4\uB5BB\uAC8C \uC81C\uAC70\uD558\uACE0 MSI Center M\uC73C\uB85C \uB3CC\uC544\uAC00\uB098\uC694?",
            ["In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\uAC00\uC0C1 \uBAA8\uB4DC\uC5D0\uC11C\uB294 \uBB3C\uB9AC \uD328\uB4DC\uAC00 \uC228\uACA8\uC9C0\uACE0 VIIPER \uAC00\uC0C1 \uCEE8\uD2B8\uB864\uB7EC\uAC00 \uD65C\uC131\uD654\uB418\uBA70, \uD558\uB4DC\uC6E8\uC5B4 \uBAA8\uB4DC\uC5D0\uC11C\uB294 \uBB3C\uB9AC \uD328\uB4DC\uB97C \uC9C1\uC811 \uC0AC\uC6A9\uD569\uB2C8\uB2E4.",
            ["Info"] = "\uC815\uBCF4",
            ["Install"] = "\uC124\uCE58",
            ["Install ClawTweaks"] = "ClawTweaks \uC124\uCE58",
            ["Install ClawTweaks Center"] = "ClawTweaks Center \uC124\uCE58",
            ["Install failed \u2014 see the log for details. Try again, or run as Administrator."] = "\uC124\uCE58 \uC2E4\uD328 \u2014 \uC790\uC138\uD55C \uB0B4\uC6A9\uC740 \uB85C\uADF8\uB97C \uBCF4\uC138\uC694. \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uAC70\uB098 \uAD00\uB9AC\uC790 \uAD8C\uD55C\uC73C\uB85C \uC2E4\uD589\uD558\uC138\uC694.",
            ["Install releases, test builds and nightlies."] = "\uB9B4\uB9AC\uC988, \uD14C\uC2A4\uD2B8 \uBE4C\uB4DC, \uB098\uC774\uD2B8\uB9AC\uB97C \uC124\uCE58\uD569\uB2C8\uB2E4.",
            ["Install this version"] = "\uC774 \uBC84\uC804 \uC124\uCE58",
            ["Install this version?"] = "\uC774 \uBC84\uC804\uC744 \uC124\uCE58\uD560\uAE4C\uC694?",
            ["Install timed out."] = "\uC124\uCE58 \uC2DC\uAC04\uC774 \uCD08\uACFC\uB418\uC5C8\uC2B5\uB2C8\uB2E4.",
            ["Installation complete"] = "\uC124\uCE58 \uC644\uB8CC",
            ["Installed but not running (fine). Uninstall it from Windows Settings \u203A Apps if you want it gone permanently."] = "\uC124\uCE58\uB418\uC5B4 \uC788\uC73C\uB098 \uC2E4\uD589 \uC911 \uC544\uB2D8 (\uC815\uC0C1). \uC644\uC804\uD788 \uC5C6\uC560\uB824\uBA74 Windows \uC124\uC815 \u203A \uC571\uC5D0\uC11C \uC81C\uAC70\uD558\uC138\uC694.",
            ["Installed \u2014 background helper started"] = "\uC124\uCE58\uB428 \u2014 \uBC31\uADF8\uB77C\uC6B4\uB4DC \uD5EC\uD37C \uC2DC\uC791\uB428",
            ["Installing package\u2026"] = "\uD328\uD0A4\uC9C0 \uC124\uCE58 \uC911\u2026",
            ["Installing..."] = "\uC124\uCE58 \uC911...",
            ["Integer"] = "\uC815\uC218 \uBC30\uC728",
            ["Invisible"] = "\uC624\uD504\uB77C\uC778 \uD45C\uC2DC",
            ["Invisible (short)"] = "\uC624\uD504\uB77C\uC778 \uD45C\uC2DC",
            ["It is the standard mode in ClawTweaks."] = "ClawTweaks\uC758 \uAE30\uBCF8 \uBAA8\uB4DC\uC785\uB2C8\uB2E4.",
            ["It resets the charge limit, the fan and the controller first."] = "\uBA3C\uC800 \uCDA9\uC804 \uC81C\uD55C\uACFC \uD32C, \uCEE8\uD2B8\uB864\uB7EC\uB97C \uB418\uB3CC\uB9BD\uB2C8\uB2E4.",
            ["It starts with Windows through its scheduled task."] = "\uC608\uC57D \uC791\uC5C5\uC744 \uD1B5\uD574 Windows\uC640 \uD568\uAED8 \uC2DC\uC791\uD569\uB2C8\uB2E4.",
            ["It walks you through every step."] = "\uBAA8\uB4E0 \uB2E8\uACC4\uB97C \uC548\uB0B4\uD574 \uC90D\uB2C8\uB2E4.",
