            ["Leave the library open."] = "\uB77C\uC774\uBE0C\uB7EC\uB9AC\uB97C \uC5F4\uC5B4 \uB461\uB2C8\uB2E4.",
            ["Left stick"] = "\uC67C\uCABD \uC2A4\uD2F1",
