            ["Answer Yes when it asks about the full screen mode."] = "\uC804\uCCB4 \uD654\uBA74 \uBAA8\uB4DC\uB97C \uBB3B\uB294 \uC9C8\uBB38\uC5D0 \uC608\uB77C\uACE0 \uB2F5\uD558\uC138\uC694.",
            ["Open releases"] = "\uB9B4\uB9AC\uC2A4 \uC5F4\uAE30",
