            ["MSI Center M is not installed on this device."] = "\uC774 \uAE30\uAE30\uC5D0\uB294 MSI Center M\uC774 \uC124\uCE58\uB418\uC5B4 \uC788\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4.",
            ["Macro"] = "\uB9E4\uD06C\uB85C",
            ["Main versions"] = "\uC8FC\uC694 \uBC84\uC804",
            ["Manage your ClawTweaks settings \u2014 back them up, restore a previous backup, or reset everything to a clean state."] = "ClawTweaks \uC124\uC815\uC744 \uAD00\uB9AC\uD569\uB2C8\uB2E4 \u2014 \uBC31\uC5C5, \uBCF5\uC6D0, \uB610\uB294 \uC804\uCCB4 \uCD08\uAE30\uD654.",
