            ["No .cer bundled with this setup build (dev run)."] = "\uC774 \uC124\uCE58 \uBE4C\uB4DC\uC5D0 .cer\uC774 \uC5C6\uC2B5\uB2C8\uB2E4 (\uAC1C\uBC1C \uC2E4\uD589).",
            ["No .msix bundled with this setup build (dev run)."] = "\uC774 \uC124\uCE58 \uBE4C\uB4DC\uC5D0 .msix\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4 (\uAC1C\uBC1C \uC2E4\uD589).",
            ["No Epic games installed."] = "\uC124\uCE58\uB41C Epic \uAC8C\uC784\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
