            ["No portrait covers found for that search."] = "\uD574\uB2F9 \uAC80\uC0C9\uC5D0 \uC138\uB85C \uCEE4\uBC84\uAC00 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["No restart necessary."] = "\uC7AC\uBD80\uD305\uC774 \uD544\uC694 \uC5C6\uC2B5\uB2C8\uB2E4.",
