            ["Preview versions for trying upcoming changes"] = "\uB2E4\uAC00\uC62C \uBCC0\uACBD \uC0AC\uD56D\uC744 \uBBF8\uB9AC \uC2DC\uD5D8\uD574 \uBCF4\uB294 \uBC84\uC804",
            ["Probing controller topology"] = "\uCEE8\uD2B8\uB864\uB7EC \uAD6C\uC131\uC744 \uD655\uC778\uD558\uB294 \uC911",
