            ["{0}% of players"] = "\uD50C\uB808\uC774\uC5B4 {0}%",
            ["Drivers & Windows Updates"] = "\uB4DC\uB77C\uC774\uBC84 \uBC0F Windows \uC5C5\uB370\uC774\uD2B8",
            ["Device drivers"] = "\uC7A5\uCE58 \uB4DC\uB77C\uC774\uBC84",
            ["Drivers could not be checked"] = "\uB4DC\uB77C\uC774\uBC84\uB97C \uD655\uC778\uD560 \uC218 \uC5C6\uC74C",
            ["ClawTweaks is not running."] = "ClawTweaks\uAC00 \uC2E4\uD589 \uC911\uC774 \uC544\uB2D9\uB2C8\uB2E4.",
            ["No answer from ClawTweaks."] = "ClawTweaks\uC5D0\uC11C \uC751\uB2F5\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The driver list could not be read."] = "\uB4DC\uB77C\uC774\uBC84 \uBAA9\uB85D\uC744 \uC77D\uC9C0 \uBABB\uD588\uC2B5\uB2C8\uB2E4.",
            ["The driver check failed."] = "\uB4DC\uB77C\uC774\uBC84 \uD655\uC778\uC5D0 \uC2E4\uD328\uD588\uC2B5\uB2C8\uB2E4.",
            ["Graphics"] = "\uADF8\uB798\uD53D",
            ["Devices"] = "\uC7A5\uCE58",
            ["Nothing to show for this device."] = "\uC774 \uAE30\uAE30\uC5D0 \uB300\uD574 \uD45C\uC2DC\uD560 \uB0B4\uC6A9\uC774 \uC5C6\uC2B5\uB2C8\uB2E4.",
            ["The list could not be refreshed; showing what was known last."] = "\uBAA9\uB85D\uC744 \uC0C8\uB85C \uACE0\uCE60 \uC218 \uC5C6\uC5B4 \uB9C8\uC9C0\uB9C9\uC73C\uB85C \uD655\uC778\uB41C \uB0B4\uC6A9\uC744 \uD45C\uC2DC\uD569\uB2C8\uB2E4.",
            ["installed"] = "\uC124\uCE58\uB428",
