            ["D-Pad Right"] = "Cruz derecha",
            ["Xbox Button"] = "Bot\u00F3n Xbox",
            ["Action {0}"] = "Acci\u00F3n {0}",
            ["Downloads"] = "Descargas",
            ["Desktop"] = "Escritorio",
            ["Pictures"] = "Im\u00E1genes",
            ["No release notes."] = "Sin notas de la versi\u00F3n.",
            ["Backups live in {0}. Create one first."] = "Las copias est\u00E1n en {0}. Crea una primero.",
            ["Safety copy of the previous state: {0}"] = "Copia de seguridad del estado anterior: {0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "Todos los ajustes de ClawTweaks se restablecieron a un estado limpio. Vuelve a abrir la Game Bar (Win+G) para continuar.",
            ["Saved {0} stores to:\n{1}"] = "{0} almacenes guardados en:\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "{0} archivos restaurados. El helper se est\u00E1 reiniciando \u2014 vuelve a abrir la Game Bar (Win+G) para continuar.",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "Esta copia es de '{0}', pero este dispositivo parece {1}. Los valores propios del dispositivo (l\u00EDmites TDP, escala del ventilador) se restaurar\u00E1n tal cual.",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "La copia es de {0}; tienes {1} instalado. Restaurar entre versiones suele funcionar, pero no est\u00E1 garantizado.",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "Est\u00E1s en el canal \"{0}\" \u2014 se sabe que la rutina de instalaci\u00F3n no funciona bien en builds Insider por ahora.",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 Actualizaci\u00F3n disponible en GitHub: {0} ({1})",
