            ["Add it under Settings \u2192 SteamGridDB key."] = "\u0414\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E \u0432 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2192 \u043A\u043B\u044E\u0447 SteamGridDB.",
            ["Add to Favorites"] = "\u0412 \u0438\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435",
            ["After starting a game"] = "\u041F\u043E\u0441\u043B\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430 \u0438\u0433\u0440\u044B",
            ["All"] = "\u0412\u0441\u0435",
            ["All achievements\u2026"] = "\u0412\u0441\u0435 \u0434\u043E\u0441\u0442\u0438\u0436\u0435\u043D\u0438\u044F\u2026",
            ["All systems"] = "\u0412\u0441\u0435 \u0441\u0438\u0441\u0442\u0435\u043C\u044B",
            ["All tabs shown"] = "\u0412\u0441\u0435 \u0432\u043A\u043B\u0430\u0434\u043A\u0438",
            ["Almost done"] = "\u041F\u043E\u0447\u0442\u0438 \u0433\u043E\u0442\u043E\u0432\u043E",
            ["Almost \u2014 but in the wrong place"] = "\u041F\u043E\u0447\u0442\u0438 \u2014 \u043D\u043E \u043D\u0435 \u0442\u0443\u0434\u0430",
            ["Already disabled."] = "\u0423\u0436\u0435 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E.",
            ["Already enabled."] = "\u0423\u0436\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u043E.",
            ["Also looks for new cover art"] = "\u0422\u0430\u043A\u0436\u0435 \u0438\u0449\u0435\u0442 \u043D\u043E\u0432\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438",
            ["An automatic backup of your current settings is created before the reset, so you can restore it later from Restore Backup. The Game Bar will be closed \u2014 reopen it (Win+G) afterwards."] = "\u041F\u0435\u0440\u0435\u0434 \u0441\u0431\u0440\u043E\u0441\u043E\u043C \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0437\u0434\u0430\u0451\u0442\u0441\u044F \u043A\u043E\u043F\u0438\u044F \u0442\u0435\u043A\u0443\u0449\u0438\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A, \u043A\u043E\u0442\u043E\u0440\u0443\u044E \u043F\u043E\u0442\u043E\u043C \u043C\u043E\u0436\u043D\u043E \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0447\u0435\u0440\u0435\u0437 \u00AB\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043A\u043E\u043F\u0438\u044E\u00BB. Game Bar \u0431\u0443\u0434\u0435\u0442 \u0437\u0430\u043A\u0440\u044B\u0442 \u2014 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0435\u0433\u043E \u0441\u043D\u043E\u0432\u0430 (Win+G).",
            ["An existing ClawTweaks installation was found. The setup will re-check all prerequisites and install the latest package."] = "\u041D\u0430\u0439\u0434\u0435\u043D\u0430 \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0443\u044E\u0449\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 ClawTweaks. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u0437\u0430\u043D\u043E\u0432\u043E \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F \u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u0439 \u043F\u0430\u043A\u0435\u0442.",
            ["An older ClawTweaks Center is still installed"] = "\u0421\u0442\u0430\u0440\u044B\u0439 ClawTweaks Center \u0432\u0441\u0451 \u0435\u0449\u0451 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["Answers to the questions that come up most."] = "\u041E\u0442\u0432\u0435\u0442\u044B \u043D\u0430 \u0441\u0430\u043C\u044B\u0435 \u0447\u0430\u0441\u0442\u044B\u0435 \u0432\u043E\u043F\u0440\u043E\u0441\u044B.",
            ["Anti-cheat"] = "\u0410\u043D\u0442\u0438\u0447\u0438\u0442",
            ["App package"] = "\u041F\u0430\u043A\u0435\u0442 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F",
            ["Back"] = "\u041D\u0430\u0437\u0430\u0434",
            ["Back to library"] = "\u0412 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443",
            ["Back to the cover Center finds itself"] = "\u0412\u0435\u0440\u043D\u0443\u0442\u044C \u043E\u0431\u043B\u043E\u0436\u043A\u0443, \u043A\u043E\u0442\u043E\u0440\u0443\u044E Center \u043D\u0430\u0445\u043E\u0434\u0438\u0442 \u0441\u0430\u043C",
            ["Backup created"] = "\u041A\u043E\u043F\u0438\u044F \u0441\u043E\u0437\u0434\u0430\u043D\u0430",
            ["Backup failed"] = "\u041E\u0448\u0438\u0431\u043A\u0430 \u043A\u043E\u043F\u0438\u0438",
            ["Blocked"] = "\u0411\u043B\u043E\u043A\u0438\u0440\u043E\u0432\u0430\u043D\u043E",
            ["Both write the same hardware, and the last one to write wins."] = "\u041E\u0431\u0430 \u043F\u0438\u0448\u0443\u0442 \u0432 \u043E\u0434\u043D\u043E \u0438 \u0442\u043E \u0436\u0435 \u0436\u0435\u043B\u0435\u0437\u043E, \u0438 \u043F\u043E\u0431\u0435\u0436\u0434\u0430\u0435\u0442 \u0442\u043E\u0442, \u043A\u0442\u043E \u0437\u0430\u043F\u0438\u0441\u0430\u043B \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0438\u043C.",
            ["Bring back a previous backup. A safety copy of the current state is taken automatically first."] = "\u0412\u0435\u0440\u043D\u0443\u0442\u044C \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u043A\u043E\u043F\u0438\u044E. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u0442\u0440\u0430\u0445\u043E\u0432\u043E\u0447\u043D\u0430\u044F \u043A\u043E\u043F\u0438\u044F \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044F.",
            ["Browse for a file"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0444\u0430\u0439\u043B",
            ["Browse\u2026"] = "\u041E\u0431\u0437\u043E\u0440\u2026",
            ["Center background"] = "\u0424\u043E\u043D Center",
            ["Change folder"] = "\u0421\u043C\u0435\u043D\u0438\u0442\u044C \u043F\u0430\u043F\u043A\u0443",
            ["Choose one of your images"] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0441\u0432\u043E\u0451 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435",
            ["Choose a background"] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0444\u043E\u043D",
            ["CPU boost"] = "Boost \u0426\u041F",
            ["CTW Full Reset"] = "\u041F\u043E\u043B\u043D\u044B\u0439 \u0441\u0431\u0440\u043E\u0441 CTW",
            ["Cancel"] = "\u041E\u0442\u043C\u0435\u043D\u0430",
            ["Center is how you update ClawTweaks and reset the device. Remove ClawTweaks first if you meant to remove both."] = "\u0427\u0435\u0440\u0435\u0437 Center \u0432\u044B \u043E\u0431\u043D\u043E\u0432\u043B\u044F\u0435\u0442\u0435 ClawTweaks \u0438 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0443\u0434\u0430\u043B\u0438\u0442\u0435 ClawTweaks, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u043E\u0431\u0430.",
            ["Center itself never asks for admin rights."] = "\u0421\u0430\u043C Center \u043D\u0438\u043A\u043E\u0433\u0434\u0430 \u043D\u0435 \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u043F\u0440\u0430\u0432\u0430 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0430.",
            ["Center settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center",
            ["Center start screen"] = "\u0421\u0442\u0430\u0440\u0442\u043E\u0432\u044B\u0439 \u044D\u043A\u0440\u0430\u043D Center",
            ["Centered"] = "\u041F\u043E \u0446\u0435\u043D\u0442\u0440\u0443",
            ["Certificate already trusted."] = "\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442 \u0443\u0436\u0435 \u0434\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u0439.",
            ["Charge limit off and fan handed back to firmware."] = "\u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0451\u043D, \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0451\u043D \u043F\u0440\u043E\u0448\u0438\u0432\u043A\u0435.",
            ["Check"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C",
            ["Check hardware controller health"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Check the controller first."] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440.",
            ["Checking controller mode\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0440\u0435\u0436\u0438\u043C\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430\u2026",
            ["Checking for duplicate helpers\u2026"] = "\u041F\u043E\u0438\u0441\u043A \u0434\u0443\u0431\u043B\u0438\u0440\u0443\u044E\u0449\u0438\u0445 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u043E\u0432\u2026",
            ["Checking prerequisites\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0442\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u0439\u2026",
            ["Checking the Game Bar\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 Game Bar\u2026",
            ["Checking the controller\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430\u2026",
            ["Checking whether the device can be restored."] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430, \u043C\u043E\u0436\u043D\u043E \u043B\u0438 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E.",
            ["Checking\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430\u2026",
            ["Choose"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C",
            ["Choose cover"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u043B\u043E\u0436\u043A\u0443",
            ["Choose cover art"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u043B\u043E\u0436\u043A\u0443",
            ["Choose cover art\u2026"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u043E\u0431\u043B\u043E\u0436\u043A\u0443\u2026",
            ["Choose from installed apps"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C \u0438\u0437 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0439",
            ["Choose how the library starts and looks."] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u043A\u0430\u043A \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0438 \u0432\u044B\u0433\u043B\u044F\u0434\u0438\u0442.",
            ["Choose the language and how the window opens."] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u044F\u0437\u044B\u043A \u0438 \u0441\u043F\u043E\u0441\u043E\u0431 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u044F \u043E\u043A\u043D\u0430.",
            ["Choose what to add"] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u0447\u0442\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C",
            ["Choose what to do next."] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435, \u0447\u0442\u043E \u0434\u0435\u043B\u0430\u0442\u044C \u0434\u0430\u043B\u044C\u0448\u0435.",
            ["ClawTweaks Center is already installed"] = "ClawTweaks Center \u0443\u0436\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["ClawTweaks Library Overview"] = "\u041E\u0431\u0437\u043E\u0440 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438 ClawTweaks",
            ["ClawTweaks installed"] = "ClawTweaks \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["ClawTweaks is in your Game Bar."] = "ClawTweaks \u0432 \u0432\u0430\u0448\u0435\u043C Game Bar.",
            ["ClawTweaks is installed and its helper is answering."] = "ClawTweaks \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D, \u0438 \u0435\u0433\u043E \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442.",
            ["ClawTweaks is not installed"] = "ClawTweaks \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["ClawTweaks is not installed."] = "ClawTweaks \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D.",
            ["ClawTweaks is not running. Start it and try again."] = "ClawTweaks \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D. \u0417\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0435\u0433\u043E \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435.",
            ["ClawTweaks is removed. Its helper clears its own scheduled task and exits \u2014 give it a minute."] = "ClawTweaks \u0443\u0434\u0430\u043B\u0451\u043D. \u041F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u0441\u0432\u043E\u044E \u0437\u0430\u0434\u0430\u0447\u0443 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u0430 \u0438 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044F \u2014 \u0434\u0430\u0439\u0442\u0435 \u0435\u043C\u0443 \u043C\u0438\u043D\u0443\u0442\u0443.",
            ["ClawTweaks not installed"] = "ClawTweaks \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["ClawTweaks removed."] = "ClawTweaks \u0443\u0434\u0430\u043B\u0451\u043D.",
            ["ClawTweaks stays installed"] = "ClawTweaks \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u043C",
            ["ClawTweaks updated"] = "ClawTweaks \u043E\u0431\u043D\u043E\u0432\u043B\u0451\u043D",
            ["Click the right stick to show the button hints"] = "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u043F\u0440\u0430\u0432\u044B\u0439 \u0441\u0442\u0438\u043A, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043A\u0438 \u043A\u043D\u043E\u043F\u043E\u043A",
            ["Close"] = "\u0417\u0430\u043A\u0440\u044B\u0442\u044C",
            ["Close Center"] = "\u0417\u0430\u043A\u0440\u044B\u0442\u044C Center",
            ["Close MSI Center M"] = "\u0417\u0430\u043A\u0440\u044B\u0442\u044C MSI Center M",
            ["Close all"] = "\u0417\u0430\u043A\u0440\u044B\u0442\u044C \u0432\u0441\u0435",
            ["Closes everything and powers off."] = "\u0417\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u0451 \u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0430\u0435\u0442.",
            ["Closes everything and starts again."] = "\u0417\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u0451 \u0438 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442.",
            ["Connecting to the helper\u2026"] = "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u043A \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u0443\u2026",
            ["Controller"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440",
            ["Controller health"] = "\u0421\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Copy your key from Preferences \u2192 API Key."] = "\u0421\u043A\u043E\u043F\u0438\u0440\u0443\u0439\u0442\u0435 \u043A\u043B\u044E\u0447 \u0438\u0437 Preferences \u2192 API Key.",
            ["Could not reach the helper."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u0432\u044F\u0437\u0430\u0442\u044C\u0441\u044F \u0441 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u043E\u043C.",
            ["Couldn't load"] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u044C",
            ["Covers for Xbox, Epic and your own games"] = "\u041E\u0431\u043B\u043E\u0436\u043A\u0438 \u0434\u043B\u044F Xbox, Epic \u0438 \u0432\u0430\u0448\u0438\u0445 \u0438\u0433\u0440",
            ["Create Backup"] = "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043A\u043E\u043F\u0438\u044E",
            ["Create Backup writes one ZIP to Documents\\ClawTweaks\\Backups."] = "\u00AB\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043A\u043E\u043F\u0438\u044E\u00BB \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 \u043E\u0434\u0438\u043D ZIP \u0432 \u0414\u043E\u043A\u0443\u043C\u0435\u043D\u0442\u044B\\ClawTweaks\\Backups.",
            ["Create a free SteamGridDB account."] = "\u0421\u043E\u0437\u0434\u0430\u0439\u0442\u0435 \u0431\u0435\u0441\u043F\u043B\u0430\u0442\u043D\u044B\u0439 \u0430\u043A\u043A\u0430\u0443\u043D\u0442 SteamGridDB.",
            ["Create backup"] = "\u0421\u043E\u0437\u0434\u0430\u0442\u044C \u043A\u043E\u043F\u0438\u044E",
            ["Creating backup\u2026"] = "\u0421\u043E\u0437\u0434\u0430\u043D\u0438\u0435 \u043A\u043E\u043F\u0438\u0438\u2026",
            ["Currently disabled."] = "\u0421\u0435\u0439\u0447\u0430\u0441 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E.",
            ["Currently installed"] = "\u0421\u0435\u0439\u0447\u0430\u0441 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E",
            ["Currently running."] = "\u0421\u0435\u0439\u0447\u0430\u0441 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043E.",
            ["Deletes the entry, not the app"] = "\u0423\u0434\u0430\u043B\u044F\u0435\u0442 \u0437\u0430\u043F\u0438\u0441\u044C, \u0430 \u043D\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435",
            ["Desktop icon"] = "\u0417\u043D\u0430\u0447\u043E\u043A \u043D\u0430 \u0441\u0442\u043E\u043B\u0435",
            ["Detecting device\u2026"] = "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430\u2026",
            ["Did not confirm in time."] = "\u041D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B \u0432\u043E\u0432\u0440\u0435\u043C\u044F.",
            ["Did not enable in time."] = "\u041D\u0435 \u0432\u043A\u043B\u044E\u0447\u0438\u043B\u0441\u044F \u0432\u043E\u0432\u0440\u0435\u043C\u044F.",
            ["Different device"] = "\u0414\u0440\u0443\u0433\u043E\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E",
            ["Disable MSI Center M"] = "\u041E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C MSI Center M",
            ["Disable MSI Center M first."] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u0435 MSI Center M.",
            ["Disabled"] = "\u041E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u043E",
            ["Do I have to switch MSI Center M off?"] = "\u041D\u0443\u0436\u043D\u043E \u043B\u0438 \u0432\u044B\u043A\u043B\u044E\u0447\u0430\u0442\u044C MSI Center M?",
            ["Do I need the Game Bar for the game library?"] = "\u041D\u0443\u0436\u0435\u043D \u043B\u0438 Game Bar \u0434\u043B\u044F \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438 \u0438\u0433\u0440?",
            ["Do not remove ClawTweaks through the Windows app list."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u044F\u0439\u0442\u0435 ClawTweaks \u0447\u0435\u0440\u0435\u0437 \u0441\u043F\u0438\u0441\u043E\u043A \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0439 Windows.",
            ["Downgrade"] = "\u041E\u0442\u043A\u0430\u0442\u0438\u0442\u044C",
            ["Download and package install in progress."] = "\u0418\u0434\u0451\u0442 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u0430\u043A\u0435\u0442\u0430.",
            ["Download the ClawTweaks setup and run that instead."] = "\u0421\u043A\u0430\u0447\u0430\u0439\u0442\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A ClawTweaks \u0438 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0435\u0433\u043E \u0432\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E.",
            ["Downloading"] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430",
            ["E-core EPP"] = "EPP E-\u044F\u0434\u0435\u0440",
            ["E-core max"] = "\u041C\u0430\u043A\u0441. E-\u044F\u0434\u0435\u0440",
            ["E-core state"] = "\u0421\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 E-\u044F\u0434\u0435\u0440",
            ["Edit name"] = "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0438\u043C\u044F",
            ["Edit search"] = "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0437\u0430\u043F\u0440\u043E\u0441",
            ["Enable the virtual controller first."] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440.",
            ["Enable virtual controller"] = "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440",
            ["Enabled"] = "\u0412\u043A\u043B\u044E\u0447\u0435\u043D\u043E",
            ["Enter the slot ClawTweaks sits at, then Run."] = "\u0423\u043A\u0430\u0436\u0438\u0442\u0435 \u043F\u043E\u0437\u0438\u0446\u0438\u044E ClawTweaks, \u0437\u0430\u0442\u0435\u043C \u00AB\u0412\u044B\u043F\u043E\u043B\u043D\u0438\u0442\u044C\u00BB.",
            ["Exit"] = "\u0412\u044B\u0445\u043E\u0434",
            ["Expected for a same-version reinstall \u2014 the helper doesn't restart or show a UAC prompt when nothing changed. Open the Game Bar (Win+G) to check it's still running."] = "\u041E\u0436\u0438\u0434\u0430\u0435\u043C\u043E \u043F\u0440\u0438 \u043F\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 \u0442\u043E\u0439 \u0436\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u2014 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043D\u0435 \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0438 \u043D\u0435 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 UAC, \u0435\u0441\u043B\u0438 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u0438\u0437\u043C\u0435\u043D\u0438\u043B\u043E\u0441\u044C. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar (Win+G), \u0447\u0442\u043E\u0431\u044B \u0443\u0431\u0435\u0434\u0438\u0442\u044C\u0441\u044F, \u0447\u0442\u043E \u043E\u043D \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442.",
            ["Experimental versions (nightly)"] = "\u042D\u043A\u0441\u043F\u0435\u0440\u0438\u043C\u0435\u043D\u0442\u0430\u043B\u044C\u043D\u044B\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 (nightly)",
            ["Folder is gone"] = "\u041F\u0430\u043F\u043A\u0430 \u043F\u0440\u043E\u043F\u0430\u043B\u0430",
            ["FPS cap"] = "\u041B\u0438\u043C\u0438\u0442 FPS",
            ["Favorites"] = "\u0418\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435",
            ["Final clean-up and check. MSI Center M is handled here (after installation) because it fights ClawTweaks for the controller and LED."] = "\u0424\u0438\u043D\u0430\u043B\u044C\u043D\u0430\u044F \u043E\u0447\u0438\u0441\u0442\u043A\u0430 \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430. MSI Center M \u043E\u0431\u0440\u0430\u0431\u0430\u0442\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u0437\u0434\u0435\u0441\u044C (\u043F\u043E\u0441\u043B\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438), \u043F\u043E\u0442\u043E\u043C\u0443 \u0447\u0442\u043E \u043E\u043D \u0431\u043E\u0440\u0435\u0442\u0441\u044F \u0441 ClawTweaks \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0438 \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0443.",
            ["Final controller check"] = "\u0424\u0438\u043D\u0430\u043B\u044C\u043D\u0430\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Finish here and close the window."] = "\u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u044C \u0437\u0434\u0435\u0441\u044C \u0438 \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u043E\u043A\u043D\u043E.",
            ["Firmware button remapping is there too, and works without it."] = "\u041F\u0435\u0440\u0435\u043D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043A\u043D\u043E\u043F\u043E\u043A \u0432 \u043F\u0440\u043E\u0448\u0438\u0432\u043A\u0435 \u0442\u043E\u0436\u0435 \u0435\u0441\u0442\u044C \u0438 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0431\u0435\u0437 \u043D\u0435\u0433\u043E.",
            ["First install on this PC \u2014 Windows will ask for permission once."] = "\u041F\u0435\u0440\u0432\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0430 \u044D\u0442\u043E\u043C \u041F\u041A \u2014 Windows \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u0442 \u0440\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435.",
            ["Frame generation"] = "\u0413\u0435\u043D\u0435\u0440\u0430\u0446\u0438\u044F \u043A\u0430\u0434\u0440\u043E\u0432",
            ["Front and M back-button mapping, gyro with smoothing, per-game profiles."] = "\u041D\u0430\u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u043F\u0435\u0440\u0435\u0434\u043D\u0438\u0445 \u0438 \u0437\u0430\u0434\u043D\u0438\u0445 \u043A\u043D\u043E\u043F\u043E\u043A M, \u0433\u0438\u0440\u043E\u0441\u043A\u043E\u043F \u0441\u043E \u0441\u0433\u043B\u0430\u0436\u0438\u0432\u0430\u043D\u0438\u0435\u043C, \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u0434\u043B\u044F \u0438\u0433\u0440.",
            ["Fullscreen"] = "\u041F\u043E\u043B\u043D\u044B\u0439 \u044D\u043A\u0440\u0430\u043D",
            ["GPU scaling"] = "\u041C\u0430\u0441\u0448\u0442\u0430\u0431 GPU",
            ["Game Library"] = "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0438\u0433\u0440",
            ["Get ClawTweaks"] = "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C ClawTweaks",
            ["Go into Library Settings and switch on Start in the library."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438 \u0438 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u00AB\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435\u00BB.",
            ["Guided setup"] = "\u041F\u043E\u0448\u0430\u0433\u043E\u0432\u0430\u044F \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430",
            ["Gyro"] = "\u0413\u0438\u0440\u043E\u0441\u043A\u043E\u043F",
            ["Hair triggers"] = "\u0427\u0443\u0442\u043A\u0438\u0435 \u0442\u0440\u0438\u0433\u0433\u0435\u0440\u044B",
            ["Hardware controller confirmed."] = "\u0410\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043D.",
            ["Helps set the most important ClawTweaks settings."] = "\u041F\u043E\u043C\u043E\u0433\u0430\u0435\u0442 \u0437\u0430\u0434\u0430\u0442\u044C \u0441\u0430\u043C\u044B\u0435 \u0432\u0430\u0436\u043D\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 ClawTweaks.",
            ["Hidden"] = "\u0421\u043A\u0440\u044B\u0442\u043E",
            ["Hidden until you unlock it."] = "\u0421\u043A\u0440\u044B\u0442\u043E, \u043F\u043E\u043A\u0430 \u043D\u0435 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0435.",
            ["Hide"] = "\u0421\u043A\u0440\u044B\u0442\u044C",
            ["Hide a tab with A."] = "\u0421\u043A\u0440\u043E\u0439\u0442\u0435 \u0432\u043A\u043B\u0430\u0434\u043A\u0443 \u043A\u043D\u043E\u043F\u043A\u043E\u0439 A.",
            ["HidHide and usbip install kernel drivers. Reboot the device once after installing them, then run this setup again."] = "HidHide \u0438 usbip \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u044E\u0442 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u044B \u044F\u0434\u0440\u0430. \u041F\u043E\u0441\u043B\u0435 \u0438\u0445 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E \u0438 \u0441\u043D\u043E\u0432\u0430 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u044D\u0442\u043E\u0442 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A.",
            ["How do I uninstall and go back to MSI Center M?"] = "\u041A\u0430\u043A \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F \u043A MSI Center M?",
            ["In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u0412 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u0441\u043A\u0440\u044B\u0442 \u0438 \u0430\u043A\u0442\u0438\u0432\u0435\u043D \u043E\u0434\u0438\u043D \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 VIIPER; \u0432 \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043D\u0430\u043F\u0440\u044F\u043C\u0443\u044E.",
            ["Info"] = "\u0418\u043D\u0444\u043E",
            ["Install"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Install ClawTweaks"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C ClawTweaks",
            ["Install ClawTweaks Center"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C ClawTweaks Center",
            ["Install failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0435 \u0443\u0434\u0430\u043B\u0430\u0441\u044C \u2014 \u043F\u043E\u0434\u0440\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u0432 \u043B\u043E\u0433\u0435. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0438\u043B\u0438 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043E\u0442 \u0438\u043C\u0435\u043D\u0438 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0430.",
            ["Install releases, test builds and nightlies."] = "\u0423\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0439\u0442\u0435 \u0440\u0435\u043B\u0438\u0437\u044B, \u0442\u0435\u0441\u0442\u043E\u0432\u044B\u0435 \u0441\u0431\u043E\u0440\u043A\u0438 \u0438 nightly.",
            ["Install this version"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u044D\u0442\u0443 \u0432\u0435\u0440\u0441\u0438\u044E",
            ["Install this version?"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u044D\u0442\u0443 \u0432\u0435\u0440\u0441\u0438\u044E?",
            ["Install timed out."] = "\u0412\u0440\u0435\u043C\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u0438\u0441\u0442\u0435\u043A\u043B\u043E.",
            ["Installation complete"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0430",
            ["Installed but not running (fine). Uninstall it from Windows Settings \u203A Apps if you want it gone permanently."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D, \u043D\u043E \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D (\u044D\u0442\u043E \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E). \u0423\u0434\u0430\u043B\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B Windows \u203A \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0435\u0441\u043B\u0438 \u0445\u043E\u0442\u0438\u0442\u0435 \u0438\u0437\u0431\u0430\u0432\u0438\u0442\u044C\u0441\u044F \u043D\u0430\u0441\u043E\u0432\u0441\u0435\u043C.",
            ["Installed \u2014 background helper started"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u2014 \u0444\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u0437\u0430\u043F\u0443\u0449\u0435\u043D",
            ["Installing package\u2026"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043F\u0430\u043A\u0435\u0442\u0430\u2026",
            ["Installing..."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430...",
            ["Integer"] = "\u0426\u0435\u043B\u043E\u0435",
            ["Invisible"] = "\u041D\u0435\u0432\u0438\u0434\u0438\u043C\u043A\u0430",
            ["Invisible (short)"] = "\u041D\u0435\u0432\u0438\u0434.",
            ["It is the standard mode in ClawTweaks."] = "\u042D\u0442\u043E \u0441\u0442\u0430\u043D\u0434\u0430\u0440\u0442\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C \u0432 ClawTweaks.",
            ["It resets the charge limit, the fan and the controller first."] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u043E\u043D \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u043B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430, \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440 \u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440.",
            ["It starts with Windows through its scheduled task."] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 Windows \u0447\u0435\u0440\u0435\u0437 \u0437\u0430\u0434\u0430\u0447\u0443 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u0430.",
            ["It walks you through every step."] = "\u041F\u0440\u043E\u0432\u0435\u0434\u0451\u0442 \u0432\u0430\u0441 \u0447\u0435\u0440\u0435\u0437 \u043A\u0430\u0436\u0434\u044B\u0439 \u0448\u0430\u0433.",
            ["It writes TDP, fan curve, LEDs, controller and the on-screen display."] = "\u041E\u043D \u0437\u0430\u043F\u0438\u0441\u044B\u0432\u0430\u0435\u0442 TDP, \u043A\u0440\u0438\u0432\u0443\u044E \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430, \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0443, \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0438 \u044D\u043A\u0440\u0430\u043D\u043D\u044B\u0439 \u043E\u0432\u0435\u0440\u043B\u0435\u0439.",
            ["Keep everything"] = "\u041E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0432\u0441\u0451",
            ["Keeps your session in memory."] = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0441\u0435\u0441\u0441\u0438\u044E \u0432 \u043F\u0430\u043C\u044F\u0442\u0438.",
            ["Keyboard"] = "\u041A\u043B\u0430\u0432\u0438\u0430\u0442\u0443\u0440\u0430",
            ["Language"] = "\u042F\u0437\u044B\u043A",
            ["Last played"] = "\u041F\u043E\u0441\u043B\u0435\u0434\u043D\u044F\u044F \u0438\u0433\u0440\u0430",
            ["Layout"] = "\u0420\u0430\u0441\u043A\u043B\u0430\u0434\u043A\u0430",
            ["Library quick menu"] = "\u0411\u044B\u0441\u0442\u0440\u043E\u0435 \u043C\u0435\u043D\u044E \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438",
            ["Leave the library open."] = "\u041E\u0441\u0442\u0430\u0432\u0438\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u043E\u0442\u043A\u0440\u044B\u0442\u043E\u0439.",
            ["Left stick"] = "\u041B\u0435\u0432\u044B\u0439 \u0441\u0442\u0438\u043A",
            ["Left trigger"] = "\u041B\u0435\u0432\u044B\u0439 \u0442\u0440\u0438\u0433\u0433\u0435\u0440",
            ["Looking for pictures\u2026"] = "\u041F\u043E\u0438\u0441\u043A \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0439\u2026",
            ["Move a tab with LB and RB."] = "\u041F\u0435\u0440\u0435\u043C\u0435\u0441\u0442\u0438\u0442\u0435 \u0432\u043A\u043B\u0430\u0434\u043A\u0443 \u043A\u043D\u043E\u043F\u043A\u0430\u043C\u0438 LB \u0438 RB.",
            ["None"] = "\u041D\u0435\u0442",
            ["Not set"] = "\u041D\u0435 \u0437\u0430\u0434\u0430\u043D\u043E",
            ["No background"] = "\u0411\u0435\u0437 \u0444\u043E\u043D\u0430",
            ["No JPG, PNG or BMP files in that folder."] = "\u0412 \u044D\u0442\u043E\u0439 \u043F\u0430\u043F\u043A\u0435 \u043D\u0435\u0442 \u0444\u0430\u0439\u043B\u043E\u0432 JPG, PNG \u0438\u043B\u0438 BMP.",
            ["Needs the mouse or the touchscreen"] = "\u041D\u0443\u0436\u043D\u0430 \u043C\u044B\u0448\u044C \u0438\u043B\u0438 \u0441\u0435\u043D\u0441\u043E\u0440\u043D\u044B\u0439 \u044D\u043A\u0440\u0430\u043D",
            ["No suggestions on this machine."] = "\u041D\u0430 \u044D\u0442\u043E\u043C \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u0435 \u043D\u0435\u0442 \u043F\u043E\u0434\u0441\u043A\u0430\u0437\u043E\u043A.",
            ["No picked cover on this game"] = "\u0414\u043B\u044F \u044D\u0442\u043E\u0439 \u0438\u0433\u0440\u044B \u043E\u0431\u043B\u043E\u0436\u043A\u0430 \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u0430",
            ["Nothing unlocked yet."] = "\u041F\u043E\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043E\u0442\u043A\u0440\u044B\u0442\u043E.",
            ["Open release page"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0440\u0435\u043B\u0438\u0437\u0430",
            ["Recent reflections"] = "\u041E\u0442\u0440\u0430\u0436\u0435\u043D\u0438\u044F \u0432 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB",
            ["Set"] = "\u0417\u0430\u0434\u0430\u0442\u044C",
            ["Remove background"] = "\u0423\u0431\u0440\u0430\u0442\u044C \u0444\u043E\u043D",
            ["Setting the picture\u2026"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F\u2026",
            ["Pick a folder once. Sub-folders are included."] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0430\u043F\u043A\u0443 \u043E\u0434\u0438\u043D \u0440\u0430\u0437. \u041F\u043E\u0434\u043F\u0430\u043F\u043A\u0438 \u0443\u0447\u0438\u0442\u044B\u0432\u0430\u044E\u0442\u0441\u044F.",
            ["Reset"] = "\u0421\u0431\u0440\u043E\u0441\u0438\u0442\u044C",
