            ["Own image"] = "\u0421\u0432\u043E\u044F \u043A\u0430\u0440\u0442\u0438\u043D\u043A\u0430",
            ["Pick the folder your pictures are in"] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043F\u0430\u043F\u043A\u0443 \u0441 \u0432\u0430\u0448\u0438\u043C\u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F\u043C\u0438",
            ["Show"] = "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C",
            ["Shown"] = "\u041F\u043E\u043A\u0430\u0437\u0430\u043D\u043E",
            ["Steam games only"] = "\u0422\u043E\u043B\u044C\u043A\u043E \u0438\u0433\u0440\u044B Steam",
            ["Steam has no list for this game"] = "\u0423 Steam \u043D\u0435\u0442 \u0441\u043F\u0438\u0441\u043A\u0430 \u0434\u043B\u044F \u044D\u0442\u043E\u0439 \u0438\u0433\u0440\u044B",
            ["System tray / Processes"] = "\u0421\u0438\u0441\u0442\u0435\u043C\u043D\u044B\u0439 \u0442\u0440\u0435\u0439 / \u041F\u0440\u043E\u0446\u0435\u0441\u0441\u044B",
            ["This file does not install ClawTweaks Center"] = "\u042D\u0442\u043E\u0442 \u0444\u0430\u0439\u043B \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 ClawTweaks Center",
            ["Use as background"] = "\u0421\u0434\u0435\u043B\u0430\u0442\u044C \u0444\u043E\u043D\u043E\u043C",
            ["Use this folder"] = "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u044D\u0442\u0443 \u043F\u0430\u043F\u043A\u0443",
            ["View"] = "\u0412\u0438\u0434",
            ["Where are your pictures?"] = "\u0413\u0434\u0435 \u0432\u0430\u0448\u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F?",
            ["Use one of your own images\u2026"] = "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0441\u0432\u043E\u0451 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435\u2026",
            ["Windows tools"] = "\u0418\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B Windows",
            ["Windows Explorer"] = "\u041F\u0440\u043E\u0432\u043E\u0434\u043D\u0438\u043A Windows",
            ["Task Manager"] = "\u0414\u0438\u0441\u043F\u0435\u0442\u0447\u0435\u0440 \u0437\u0430\u0434\u0430\u0447",
            ["Windows Settings"] = "\u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B Windows",
            ["Control Panel (classic)"] = "\u041F\u0430\u043D\u0435\u043B\u044C \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u044F (\u043A\u043B\u0430\u0441\u0441\u0438\u0447\u0435\u0441\u043A\u0430\u044F)",
            ["Computer Management"] = "\u0423\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u043C\u043F\u044C\u044E\u0442\u0435\u0440\u043E\u043C",
            ["Installed apps"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043B. \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F",
            ["Use the library as the Windows full screen experience"] = "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u043A\u0430\u043A \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C Windows",
            ["Download the ClawTweaks setup from the releases page."] = "\u0421\u043A\u0430\u0447\u0430\u0439\u0442\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A ClawTweaks \u0441\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0440\u0435\u043B\u0438\u0437\u043E\u0432.",
            ["Answer Yes when it asks about the full screen mode."] = "\u041E\u0442\u0432\u0435\u0442\u044C\u0442\u0435 \u00AB\u0414\u0430\u00BB, \u043A\u043E\u0433\u0434\u0430 \u0441\u043F\u0440\u043E\u0441\u0438\u0442 \u043E \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435.",
            ["Open releases"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0440\u0435\u043B\u0438\u0437\u044B",
            ["Default browser"] = "\u0411\u0440\u0430\u0443\u0437\u0435\u0440 \u043F\u043E \u0443\u043C\u043E\u043B\u0447\u0430\u043D\u0438\u044E",
            ["Download CTW wallpapers"] = "\u0421\u043A\u0430\u0447\u0430\u0442\u044C \u043E\u0431\u043E\u0438 CTW",
            ["ClawTweaks wallpapers"] = "\u041E\u0431\u043E\u0438 ClawTweaks",
            ["Downloaded when you pick one."] = "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0441\u044F \u043F\u0440\u0438 \u0432\u044B\u0431\u043E\u0440\u0435.",
            ["Looking for wallpapers\u2026"] = "\u041F\u043E\u0438\u0441\u043A \u043E\u0431\u043E\u0435\u0432\u2026",
            ["The wallpaper list could not be reached. Check your connection."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u043E\u0431\u043E\u0435\u0432. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435.",
            ["No wallpapers published yet."] = "\u041E\u0431\u043E\u0438 \u0435\u0449\u0451 \u043D\u0435 \u043E\u043F\u0443\u0431\u043B\u0438\u043A\u043E\u0432\u0430\u043D\u044B.",
            ["Library Settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438",
            ["Library settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438",
            ["Loading the page\u2026"] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B\u2026",
            ["Loading\u2026"] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430\u2026",
            ["MSI Center M and its Game Bar widget are back."] = "MSI Center M \u0438 \u0435\u0433\u043E \u0432\u0438\u0434\u0436\u0435\u0442 Game Bar \u0432\u0435\u0440\u043D\u0443\u043B\u0438\u0441\u044C.",
            ["MSI Center M is back, but its Game Bar widget could not be restored. Reinstall MSI Center M to get the widget back."] = "MSI Center M \u0432\u0435\u0440\u043D\u0443\u043B\u0441\u044F, \u043D\u043E \u0435\u0433\u043E \u0432\u0438\u0434\u0436\u0435\u0442 Game Bar \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C. \u041F\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 MSI Center M, \u0447\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0432\u0438\u0434\u0436\u0435\u0442.",
            ["MSI Center M is not installed on this device."] = "MSI Center M \u043D\u0430 \u044D\u0442\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D.",
            ["Macro"] = "\u041C\u0430\u043A\u0440\u043E\u0441",
            ["Main versions"] = "\u041E\u0441\u043D\u043E\u0432\u043D\u044B\u0435 \u0432\u0435\u0440\u0441\u0438\u0438",
            ["Manage your ClawTweaks settings \u2014 back them up, restore a previous backup, or reset everything to a clean state."] = "\u0423\u043F\u0440\u0430\u0432\u043B\u044F\u0439\u0442\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\u0438 ClawTweaks \u2014 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0435 \u043A\u043E\u043F\u0438\u044E, \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u043F\u0440\u0435\u0436\u043D\u044E\u044E \u0438\u043B\u0438 \u0441\u0431\u0440\u043E\u0441\u044C\u0442\u0435 \u0432\u0441\u0451.",
            ["Menu"] = "\u041C\u0435\u043D\u044E",
            ["Minimize"] = "\u0421\u0432\u0435\u0440\u043D\u0443\u0442\u044C",
            ["Minimize Center"] = "\u0421\u0432\u0435\u0440\u043D\u0443\u0442\u044C Center",
            ["Mode: Fresh install"] = "\u0420\u0435\u0436\u0438\u043C: \u0447\u0438\u0441\u0442\u0430\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430",
            ["Mode: Update"] = "\u0420\u0435\u0436\u0438\u043C: \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435",
            ["Mouse"] = "\u041C\u044B\u0448\u044C",
            ["My Apps"] = "\u041C\u043E\u0438 \u043F\u0440\u0438\u043B\u043E\u0436.",
            ["NOT detected (VID_0DB0). The controller is missing, or MSI Center M has taken it over."] = "\u041D\u0415 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D (VID_0DB0). \u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, \u0438\u043B\u0438 \u0435\u0433\u043E \u0437\u0430\u0445\u0432\u0430\u0442\u0438\u043B MSI Center M.",
            ["Nearest Neighbour"] = "\u0411\u043B\u0438\u0436\u0430\u0439\u0448\u0438\u0439 \u0441\u043E\u0441\u0435\u0434",
            ["New update \u2014 background helper started"] = "\u041D\u043E\u0432\u043E\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u2014 \u0444\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u0437\u0430\u043F\u0443\u0449\u0435\u043D",
            ["Newer than installed"] = "\u041D\u043E\u0432\u0435\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0439",
            ["Next: controller health, required tools, the signing certificate, then the app itself. Each step re-checks live and won't let you continue until it's satisfied."] = "\u0414\u0430\u043B\u0435\u0435: \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430, \u043D\u0443\u0436\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B, \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442 \u043F\u043E\u0434\u043F\u0438\u0441\u0438, \u0437\u0430\u0442\u0435\u043C \u0441\u0430\u043C\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435. \u041A\u0430\u0436\u0434\u044B\u0439 \u0448\u0430\u0433 \u043F\u0440\u043E\u0432\u0435\u0440\u044F\u0435\u0442\u0441\u044F \u0432\u0436\u0438\u0432\u0443\u044E \u0438 \u043D\u0435 \u043F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442 \u0434\u0430\u043B\u044C\u0448\u0435, \u043F\u043E\u043A\u0430 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D.",
            ["No .cer bundled with this setup build (dev run)."] = "\u0412 \u044D\u0442\u043E\u0439 \u0441\u0431\u043E\u0440\u043A\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 \u043D\u0435\u0442 .cer (dev-\u0437\u0430\u043F\u0443\u0441\u043A).",
            ["No .msix bundled with this setup build (dev run)."] = "\u0412 \u044D\u0442\u043E\u0439 \u0441\u0431\u043E\u0440\u043A\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 \u043D\u0435\u0442 .msix (dev-\u0437\u0430\u043F\u0443\u0441\u043A).",
            ["No Epic games installed."] = "\u0418\u0433\u0440\u044B Epic \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u044B.",
            ["No ROM has been played yet."] = "\u041D\u0438 \u043E\u0434\u0438\u043D ROM \u0435\u0449\u0451 \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043B\u0441\u044F.",
            ["No ROMs in your Playnite library."] = "\u0412 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435 Playnite \u043D\u0435\u0442 ROM-\u043E\u0432.",
            ["No Steam games installed."] = "\u0418\u0433\u0440\u044B Steam \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u044B.",
            ["No Steam library found on this device."] = "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 Steam \u043D\u0430 \u044D\u0442\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430.",
            ["No Xbox games installed."] = "\u0418\u0433\u0440\u044B Xbox \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u044B.",
            ["No apps added yet."] = "\u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0435\u0449\u0451 \u043D\u0435 \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u044B.",
            ["No backup selected"] = "\u041A\u043E\u043F\u0438\u044F \u043D\u0435 \u0432\u044B\u0431\u0440\u0430\u043D\u0430",
            ["No backups found"] = "\u041A\u043E\u043F\u0438\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B",
            ["No duplicate helper detected"] = "\u0414\u0443\u0431\u043B\u0438\u0440\u0443\u044E\u0449\u0438\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D",
            ["No existing ClawTweaks installation was found. The setup will guide you through the full first-time installation."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 ClawTweaks \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u0430. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u043F\u0440\u043E\u0432\u0435\u0434\u0451\u0442 \u0432\u0430\u0441 \u0447\u0435\u0440\u0435\u0437 \u043F\u043E\u043B\u043D\u0443\u044E \u043F\u0435\u0440\u0432\u0443\u044E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0443.",
            ["No favorites yet."] = "\u0418\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E \u043F\u043E\u043A\u0430 \u043D\u0435\u0442.",
            ["No game has been played yet."] = "\u041D\u0438 \u043E\u0434\u043D\u0430 \u0438\u0433\u0440\u0430 \u0435\u0449\u0451 \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u043B\u0430\u0441\u044C.",
            ["No games found."] = "\u0418\u0433\u0440\u044B \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u044B.",
            ["No games from these stores installed."] = "\u0418\u0433\u0440\u044B \u0438\u0437 \u044D\u0442\u0438\u0445 \u043C\u0430\u0433\u0430\u0437\u0438\u043D\u043E\u0432 \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u044B.",
            ["No installable package found after staging."] = "\u041F\u043E\u0441\u043B\u0435 \u043F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u043C\u044B\u0439 \u043F\u0430\u043A\u0435\u0442.",
            ["No portrait covers found for that search."] = "\u041F\u043E \u044D\u0442\u043E\u043C\u0443 \u0437\u0430\u043F\u0440\u043E\u0441\u0443 \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C\u043D\u044B\u0445 \u043E\u0431\u043B\u043E\u0436\u0435\u043A \u043D\u0435\u0442.",
            ["No restart necessary."] = "\u041F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u043D\u0435 \u043D\u0443\u0436\u043D\u0430.",
            ["No uninstaller found for the older version."] = "\u0414\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440 \u0441\u0442\u0430\u0440\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D.",
            ["No virtual pad detected \u2014 rolled back to the hardware controller."] = "\u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u043D\u0435 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D \u2014 \u0432\u043E\u0437\u0432\u0440\u0430\u0442 \u043A \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u043C\u0443 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0443.",
            ["No. The library runs on its own, without the Game Bar."] = "\u041D\u0435\u0442. \u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0441\u0430\u043C\u0430, \u0431\u0435\u0437 Game Bar.",
            ["Not Installed"] = "\u041D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E",
            ["Not a recognized backup"] = "\u041A\u043E\u043F\u0438\u044F \u043D\u0435 \u0440\u0430\u0441\u043F\u043E\u0437\u043D\u0430\u043D\u0430",
            ["Not checked yet."] = "\u0415\u0449\u0451 \u043D\u0435 \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u043E.",
            ["Not in the bar yet \u2014 favorite ClawTweaks in the Game Bar (Win+G), then Check."] = "\u0415\u0449\u0451 \u043D\u0435 \u0432 \u043F\u0430\u043D\u0435\u043B\u0438 \u2014 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 ClawTweaks \u0432 \u0438\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435 Game Bar (Win+G), \u0437\u0430\u0442\u0435\u043C \u00AB\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C\u00BB.",
            ["Not installed"] = "\u041D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E",
            ["Not mounted right now. Expected only while virtual mode is running \u2014 normal at setup time."] = "\u0421\u0435\u0439\u0447\u0430\u0441 \u043D\u0435 \u0441\u043C\u043E\u043D\u0442\u0438\u0440\u043E\u0432\u0430\u043D. \u041E\u0436\u0438\u0434\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E \u0432 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u2014 \u043F\u0440\u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 \u044D\u0442\u043E \u043D\u043E\u0440\u043C\u0430\u043B\u044C\u043D\u043E.",
            ["Not now"] = "\u041D\u0435 \u0441\u0435\u0439\u0447\u0430\u0441",
            ["Not present (good)."] = "\u041E\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 (\u0445\u043E\u0440\u043E\u0448\u043E).",
            ["Not running (good)."] = "\u041D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D (\u0445\u043E\u0440\u043E\u0448\u043E).",
            ["Not running yet \u2014 starts after install via the Game Bar."] = "\u0415\u0449\u0451 \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D \u2014 \u0441\u0442\u0430\u0440\u0442\u0443\u0435\u0442 \u043F\u043E\u0441\u043B\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u0447\u0435\u0440\u0435\u0437 Game Bar.",
            ["Not set."] = "\u041D\u0435 \u0437\u0430\u0434\u0430\u043D\u043E.",
            ["Not supported on this device"] = "\u041D\u0435 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u044D\u0442\u043E\u043C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435",
            ["Not trusted yet \u2014 will be trusted during install."] = "\u041F\u043E\u043A\u0430 \u043D\u0435 \u0434\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u0439 \u2014 \u0441\u0442\u0430\u043D\u0435\u0442 \u0434\u043E\u0432\u0435\u0440\u0435\u043D\u043D\u044B\u043C \u043F\u0440\u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435.",
            ["Nothing found"] = "\u041D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E",
            ["Nothing found to add."] = "\u041D\u0435\u0447\u0435\u0433\u043E \u0434\u043E\u0431\u0430\u0432\u0438\u0442\u044C.",
            ["Nothing found yet."] = "\u041F\u043E\u043A\u0430 \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D\u043E.",
            ["Off"] = "\u0412\u044B\u043A\u043B.",
            ["Older than installed"] = "\u0421\u0442\u0430\u0440\u0435\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0439",
            ["On"] = "\u0412\u043A\u043B.",
            ["Onboarding lists it as a to-do the first time you install ClawTweaks."] = "\u041F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u0439 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435 ClawTweaks \u044D\u0442\u043E \u0443\u043A\u0430\u0437\u0430\u043D\u043E \u043A\u0430\u043A \u0437\u0430\u0434\u0430\u0447\u0430 \u0432 \u043E\u043D\u0431\u043E\u0440\u0434\u0438\u043D\u0433\u0435.",
            ["Once, at the first install, to register its background task."] = "\u041E\u0434\u0438\u043D \u0440\u0430\u0437, \u043F\u0440\u0438 \u043F\u0435\u0440\u0432\u043E\u0439 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0435, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0444\u043E\u043D\u043E\u0432\u0443\u044E \u0437\u0430\u0434\u0430\u0447\u0443.",
            ["One click in the widget or in Center brings Center M back."] = "\u041E\u0434\u0438\u043D \u043A\u043B\u0438\u043A \u0432 \u0432\u0438\u0434\u0436\u0435\u0442\u0435 \u0438\u043B\u0438 \u0432 Center \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 Center M.",
            ["Only Steam is supported for now."] = "\u041F\u043E\u043A\u0430 \u043F\u043E\u0434\u0434\u0435\u0440\u0436\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0442\u043E\u043B\u044C\u043A\u043E Steam.",
            ["Only for apps you added yourself"] = "\u0422\u043E\u043B\u044C\u043A\u043E \u0434\u043B\u044F \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0439, \u0434\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u0432\u0440\u0443\u0447\u043D\u0443\u044E",
            ["Only the ClawTweaks widget lives in the Game Bar."] = "\u0412 Game Bar \u0436\u0438\u0432\u0451\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0432\u0438\u0434\u0436\u0435\u0442 ClawTweaks.",
            ["Open"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C",
            ["Open OptiClick"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C OptiClick",
            ["Open Reset \u00B7 Backup \u00B7 Restore on the start screen."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u00AB\u0421\u0431\u0440\u043E\u0441 \u00B7 \u041A\u043E\u043F\u0438\u044F \u00B7 \u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435\u00BB \u043D\u0430 \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u043E\u043C \u044D\u043A\u0440\u0430\u043D\u0435.",
            ["Open Steam"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C Steam",
            ["Open SteamGridDB"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C SteamGridDB",
            ["Open Windows Settings, go to Apps, find \"ClawTweaks Center\" and uninstall it, then press Re-check."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B Windows, \u043F\u0435\u0440\u0435\u0439\u0434\u0438\u0442\u0435 \u0432 \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u043D\u0430\u0439\u0434\u0438\u0442\u0435 \u00ABClawTweaks Center\u00BB, \u0443\u0434\u0430\u043B\u0438\u0442\u0435 \u0435\u0433\u043E \u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u00AB\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0441\u043D\u043E\u0432\u0430\u00BB.",
            ["Open all"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0432\u0441\u0435",
            ["Open download page"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438",
            ["ClawTweaks is not running"] = "ClawTweaks \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D",
            ["Install ClawTweaks with the Setup to get versions here."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 ClawTweaks \u0447\u0435\u0440\u0435\u0437 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A, \u0447\u0442\u043E\u0431\u044B \u0432\u0438\u0434\u0435\u0442\u044C \u0437\u0434\u0435\u0441\u044C \u0432\u0435\u0440\u0441\u0438\u0438.",
            ["Get the Setup"] = "\u041F\u043E\u043B\u0443\u0447\u0438\u0442\u044C \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A",
            ["Open download pages"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438",
            ["Open in browser"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435",
            ["Open the Game Bar (Win+G) once to start it, then press \u24CE. You can still uninstall Center."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar (Win+G) \u043E\u0434\u0438\u043D \u0440\u0430\u0437, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u0435\u0433\u043E, \u0437\u0430\u0442\u0435\u043C \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u24CE. Center \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0436\u043D\u043E \u0443\u0434\u0430\u043B\u0438\u0442\u044C.",
            ["Open the Game Bar (Win+G), favorite ClawTweaks, then Check."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar (Win+G), \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 ClawTweaks \u0432 \u0438\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435, \u0437\u0430\u0442\u0435\u043C \u00AB\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C\u00BB.",
            ["Open the Game Bar manually (Win+G)."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar \u0432\u0440\u0443\u0447\u043D\u0443\u044E (Win+G).",
            ["Open the Game Bar once if it is not running."] = "\u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar \u043E\u0434\u0438\u043D \u0440\u0430\u0437, \u0435\u0441\u043B\u0438 \u043E\u043D \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D.",
            ["Opening Game Bar \u2014 the ClawTweaks widget will start the helper\u2026"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u0438\u0435 Game Bar \u2014 \u0432\u0438\u0434\u0436\u0435\u0442 ClawTweaks \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u2026",
            ["OptiScaler wiki"] = "\u0412\u0438\u043A\u0438 OptiScaler",
            ["Other Stores"] = "\u0414\u0440\u0443\u0433\u0438\u0435 \u043C\u0430\u0433\u0430\u0437\u0438\u043D\u044B",
            ["Output"] = "\u0412\u044B\u0432\u043E\u0434",
            ["P-core EPP"] = "EPP P-\u044F\u0434\u0435\u0440",
            ["P-core max"] = "\u041C\u0430\u043A\u0441. P-\u044F\u0434\u0435\u0440",
            ["P-core state"] = "\u0421\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 P-\u044F\u0434\u0435\u0440",
            ["Package installed."] = "\u041F\u0430\u043A\u0435\u0442 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D.",
            ["Performance"] = "\u041F\u0440\u043E\u0438\u0437\u0432\u043E\u0434\u0438\u0442\u0435\u043B\u044C\u043D\u043E\u0441\u0442\u044C",
            ["Physical MSI Claw controller"] = "\u0424\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 MSI Claw",
            ["Pick a backup to restore. A safety copy of the current state is taken automatically first, then the helper restarts to load the restored settings."] = "\u0412\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u043A\u043E\u043F\u0438\u044E \u0434\u043B\u044F \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F. \u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442\u0441\u044F \u0441\u0442\u0440\u0430\u0445\u043E\u0432\u043E\u0447\u043D\u0430\u044F \u043A\u043E\u043F\u0438\u044F \u0442\u0435\u043A\u0443\u0449\u0435\u0433\u043E \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u044F, \u0437\u0430\u0442\u0435\u043C \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F \u0441 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u043C\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\u0438.",
            ["Platform"] = "\u041F\u043B\u0430\u0442\u0444\u043E\u0440\u043C\u0430",
            ["Play"] = "\u0418\u0433\u0440\u0430\u0442\u044C",
            ["Play your Steam, Epic and Xbox games."] = "\u0418\u0433\u0440\u0430\u0439\u0442\u0435 \u0432 \u0441\u0432\u043E\u0438 \u0438\u0433\u0440\u044B Steam, Epic \u0438 Xbox.",
            ["Playnite is not installed."] = "Playnite \u043D\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D.",
            ["Portrait covers only. No match? Edit the text above and search again."] = "\u0422\u043E\u043B\u044C\u043A\u043E \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438. \u041D\u0435\u0442 \u0441\u043E\u0432\u043F\u0430\u0434\u0435\u043D\u0438\u0439? \u0418\u0437\u043C\u0435\u043D\u0438\u0442\u0435 \u0442\u0435\u043A\u0441\u0442 \u0432\u044B\u0448\u0435 \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u043F\u043E\u0438\u0441\u043A.",
            ["Preparing your library\u2026"] = "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438\u2026",
            ["Preparing\u2026"] = "\u041F\u043E\u0434\u0433\u043E\u0442\u043E\u0432\u043A\u0430\u2026",
            ["Present \u2014 a common double-input source. Check Steam Input if you see doubled inputs."] = "\u041F\u0440\u0438\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442 \u2014 \u0447\u0430\u0441\u0442\u044B\u0439 \u0438\u0441\u0442\u043E\u0447\u043D\u0438\u043A \u0434\u0432\u043E\u0439\u043D\u043E\u0433\u043E \u0432\u0432\u043E\u0434\u0430. \u041F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 Steam Input, \u0435\u0441\u043B\u0438 \u0432\u0438\u0434\u0438\u0442\u0435 \u0434\u0432\u043E\u0439\u043D\u044B\u0435 \u043D\u0430\u0436\u0430\u0442\u0438\u044F.",
            ["Preserve Aspect Ratio"] = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0442\u044C \u043F\u0440\u043E\u043F\u043E\u0440\u0446\u0438\u0438",
            ["Preset"] = "\u041F\u0440\u0435\u0441\u0435\u0442",
            ["Press \u24B6 on a question to open it."] = "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u24B6 \u043D\u0430 \u0432\u043E\u043F\u0440\u043E\u0441\u0435, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0435\u0433\u043E.",
            ["Press \u24B6 to install ClawTweaks."] = "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u24B6, \u0447\u0442\u043E\u0431\u044B \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C ClawTweaks.",
            ["Press \u24B6 to open the download pages for the missing tools, install them, then press \u24CE to re-check."] = "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u24B6, \u0447\u0442\u043E\u0431\u044B \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u043D\u0435\u0434\u043E\u0441\u0442\u0430\u044E\u0449\u0438\u0445 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u043E\u0432, \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0438\u0445, \u0437\u0430\u0442\u0435\u043C \u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u24CE \u0434\u043B\u044F \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0439 \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438.",
            ["Preview versions for trying upcoming changes"] = "\u041F\u0440\u0435\u0434\u0432\u0430\u0440\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0432\u0435\u0440\u0441\u0438\u0438 \u0434\u043B\u044F \u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0438 \u0431\u0443\u0434\u0443\u0449\u0438\u0445 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u0439",
            ["Probing controller topology"] = "\u041E\u043F\u0440\u0435\u0434\u0435\u043B\u0435\u043D\u0438\u0435 \u0442\u043E\u043F\u043E\u043B\u043E\u0433\u0438\u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Puts the charge limit, the fan and the controller back."] = "\u0412\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u043B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430, \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440 \u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440.",
            ["REBOOT REQUIRED"] = "\u041D\u0423\u0416\u041D\u0410 \u041F\u0415\u0420\u0415\u0417\u0410\u0413\u0420\u0423\u0417\u041A\u0410",
            ["Re-check"] = "\u041F\u0435\u0440\u0435\u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C",
            ["Re-enables MSI's tasks, service and Game Bar widget."] = "\u0421\u043D\u043E\u0432\u0430 \u0432\u043A\u043B\u044E\u0447\u0430\u0435\u0442 \u0437\u0430\u0434\u0430\u0447\u0438, \u0441\u043B\u0443\u0436\u0431\u0443 \u0438 \u0432\u0438\u0434\u0436\u0435\u0442 Game Bar \u043E\u0442 MSI.",
            ["Reading installed apps\u2026"] = "\u0427\u0442\u0435\u043D\u0438\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0445 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0439\u2026",
            ["Recent"] = "\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0435",
            ["Recommendation"] = "\u0420\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0430\u0446\u0438\u044F",
            ["Recommended for everyday use"] = "\u0420\u0435\u043A\u043E\u043C\u0435\u043D\u0434\u0443\u0435\u0442\u0441\u044F \u0434\u043B\u044F \u043F\u043E\u0432\u0441\u0435\u0434\u043D\u0435\u0432\u043D\u043E\u0433\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u043D\u0438\u044F",
            ["Refresh"] = "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Refresh rate"] = "\u0427\u0430\u0441\u0442\u043E\u0442\u0430 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F",
            ["Refresh status"] = "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C \u0441\u0442\u0430\u0442\u0443\u0441",
            ["Relaunching from install location..."] = "\u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A \u0438\u0437 \u043F\u0430\u043F\u043A\u0438 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438...",
            ["Remove from Favorites"] = "\u0423\u0431\u0440\u0430\u0442\u044C \u0438\u0437 \u0438\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0433\u043E",
            ["Remove from library"] = "\u0423\u0431\u0440\u0430\u0442\u044C \u0438\u0437 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438",
            ["Remove the old version"] = "\u0423\u0434\u0430\u043B\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E",
            ["Removes the app, its background helper and its scheduled task."] = "\u0423\u0434\u0430\u043B\u044F\u0435\u0442 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435, \u0435\u0433\u043E \u0444\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u0438 \u0437\u0430\u0434\u0430\u0447\u0443 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u0430.",
            ["Removes this app and closes it."] = "\u0423\u0434\u0430\u043B\u044F\u0435\u0442 \u044D\u0442\u043E \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0435\u0433\u043E.",
            ["Removing Center\u2026"] = "\u0423\u0434\u0430\u043B\u0435\u043D\u0438\u0435 Center\u2026",
            ["Removing ClawTweaks\u2026"] = "\u0423\u0434\u0430\u043B\u0435\u043D\u0438\u0435 ClawTweaks\u2026",
            ["Removing leftover helper\u2026"] = "\u0423\u0434\u0430\u043B\u0435\u043D\u0438\u0435 \u043E\u0441\u0442\u0430\u0432\u0448\u0435\u0433\u043E\u0441\u044F \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u0430\u2026",
            ["Renaming looks for new cover art."] = "\u041F\u0435\u0440\u0435\u0438\u043C\u0435\u043D\u043E\u0432\u0430\u043D\u0438\u0435 \u0438\u0449\u0435\u0442 \u043D\u043E\u0432\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438.",
            ["Required tools"] = "\u041D\u0443\u0436\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B",
            ["Required tools (HidHide, RTSS, usbip, PawnIO) already installed."] = "\u041D\u0443\u0436\u043D\u044B\u0435 \u0438\u043D\u0441\u0442\u0440\u0443\u043C\u0435\u043D\u0442\u044B (HidHide, RTSS, usbip, PawnIO) \u0443\u0436\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u044B.",
            ["Requirements"] = "\u0422\u0440\u0435\u0431\u043E\u0432\u0430\u043D\u0438\u044F",
            ["Rescan"] = "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Reset complete"] = "\u0421\u0431\u0440\u043E\u0441 \u0437\u0430\u0432\u0435\u0440\u0448\u0451\u043D",
            ["Reset failed"] = "\u041E\u0448\u0438\u0431\u043A\u0430 \u0441\u0431\u0440\u043E\u0441\u0430",
            ["Reset the app, or back up your profiles."] = "\u0421\u0431\u0440\u043E\u0441\u044C\u0442\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 \u0438\u043B\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u0435 \u043A\u043E\u043F\u0438\u044E \u043F\u0440\u043E\u0444\u0438\u043B\u0435\u0439.",
            ["Resetting all ClawTweaks settings\u2026"] = "\u0421\u0431\u0440\u043E\u0441 \u0432\u0441\u0435\u0445 \u043D\u0430\u0441\u0442\u0440\u043E\u0435\u043A ClawTweaks\u2026",
            ["Resolution"] = "\u0420\u0430\u0437\u0440\u0435\u0448\u0435\u043D\u0438\u0435",
            ["Restart"] = "\u041F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A",
            ["Restore"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Restore Backup"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043A\u043E\u043F\u0438\u044E",
            ["Restore Backup takes a safety copy before it writes."] = "\u00AB\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u043A\u043E\u043F\u0438\u044E\u00BB \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0441\u0442\u0440\u0430\u0445\u043E\u0432\u043E\u0447\u043D\u0443\u044E \u043A\u043E\u043F\u0438\u044E \u043F\u0435\u0440\u0435\u0434 \u0437\u0430\u043F\u0438\u0441\u044C\u044E.",
            ["Restore complete"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u043E",
            ["Restore failed"] = "\u041E\u0448\u0438\u0431\u043A\u0430 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F",
            ["Restore the device"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E",
            ["Restore the device and remove everything."] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E \u0438 \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u0432\u0441\u0451.",
            ["Restore the device first"] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E",
            ["Restore this backup?"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u044D\u0442\u0443 \u043A\u043E\u043F\u0438\u044E?",
            ["Restoring the hardware\u2026"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u0436\u0435\u043B\u0435\u0437\u0430\u2026",
            ["Retro scaling"] = "\u0420\u0435\u0442\u0440\u043E-\u043C\u0430\u0441\u0448\u0442\u0430\u0431\u0438\u0440\u043E\u0432\u0430\u043D\u0438\u0435",
            ["Right stick"] = "\u041F\u0440\u0430\u0432\u044B\u0439 \u0441\u0442\u0438\u043A",
            ["Right stick actions"] = "\u0414\u0435\u0439\u0441\u0442\u0432\u0438\u044F \u043F\u0440\u0430\u0432\u043E\u0433\u043E \u0441\u0442\u0438\u043A\u0430",
            ["Right stick: right jumps to the end, left to the start"] = "\u041F\u0440\u0430\u0432\u044B\u0439 \u0441\u0442\u0438\u043A: \u0432\u043F\u0440\u0430\u0432\u043E \u2014 \u0432 \u043A\u043E\u043D\u0435\u0446, \u0432\u043B\u0435\u0432\u043E \u2014 \u0432 \u043D\u0430\u0447\u0430\u043B\u043E",
            ["Right trigger"] = "\u041F\u0440\u0430\u0432\u044B\u0439 \u0442\u0440\u0438\u0433\u0433\u0435\u0440",
            ["Route"] = "\u041C\u0430\u0440\u0448\u0440\u0443\u0442",
            ["Run"] = "\u0417\u0430\u043F\u0443\u0441\u043A",
            ["Run in background"] = "\u0420\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0432 \u0444\u043E\u043D\u0435",
            ["Running \u2014 it can fight ClawTweaks for the controller and LED. You'll be guided to deactivate it after the app is installed."] = "\u0417\u0430\u043F\u0443\u0449\u0435\u043D \u2014 \u043C\u043E\u0436\u0435\u0442 \u0431\u043E\u0440\u043E\u0442\u044C\u0441\u044F \u0441 ClawTweaks \u0437\u0430 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0438 \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u0443. \u041F\u043E\u0441\u043B\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0432\u0430\u043C \u043F\u043E\u043C\u043E\u0433\u0443\u0442 \u0435\u0433\u043E \u043E\u0442\u043A\u043B\u044E\u0447\u0438\u0442\u044C.",
            ["Running. Press \u24B6 to close it now. For a permanent fix, uninstall it from Windows Settings \u203A Apps and reinstall the latest version if you still need it."] = "\u0417\u0430\u043F\u0443\u0449\u0435\u043D. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u24B6, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u043A\u0440\u044B\u0442\u044C \u0435\u0433\u043E \u0441\u0435\u0439\u0447\u0430\u0441. \u0414\u043B\u044F \u043E\u043A\u043E\u043D\u0447\u0430\u0442\u0435\u043B\u044C\u043D\u043E\u0433\u043E \u0440\u0435\u0448\u0435\u043D\u0438\u044F \u0443\u0434\u0430\u043B\u0438\u0442\u0435 \u0435\u0433\u043E \u0432 \u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B Windows \u203A \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0438 \u043F\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u044E\u044E \u0432\u0435\u0440\u0441\u0438\u044E, \u0435\u0441\u043B\u0438 \u043E\u043D \u0432\u0430\u043C \u0435\u0449\u0451 \u043D\u0443\u0436\u0435\u043D.",
            ["Save"] = "\u0421\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C",
            ["Saves all your profiles and settings into a single ZIP. The Game Bar is briefly closed so the widget's data can be copied \u2014 reopen it (Win+G) afterwards."] = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0432\u0441\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0432 \u043E\u0434\u0438\u043D ZIP. Game Bar \u043D\u0435\u043D\u0430\u0434\u043E\u043B\u0433\u043E \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F, \u0447\u0442\u043E\u0431\u044B \u0441\u043A\u043E\u043F\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0434\u0430\u043D\u043D\u044B\u0435 \u0432\u0438\u0434\u0436\u0435\u0442\u0430 \u2014 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0435\u0433\u043E \u0441\u043D\u043E\u0432\u0430 (Win+G).",
            ["Saves your session to disk."] = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0441\u0435\u0441\u0441\u0438\u044E \u043D\u0430 \u0434\u0438\u0441\u043A.",
            ["Search"] = "\u041F\u043E\u0438\u0441\u043A",
            ["Search SteamGridDB for a different cover"] = "\u0418\u0441\u043A\u0430\u0442\u044C \u0434\u0440\u0443\u0433\u0443\u044E \u043E\u0431\u043B\u043E\u0436\u043A\u0443 \u0432 SteamGridDB",
            ["Searching\u2026"] = "\u041F\u043E\u0438\u0441\u043A\u2026",
            ["Select"] = "\u0412\u044B\u0431\u0440\u0430\u0442\u044C",
            ["Set a SteamGridDB key in Settings first"] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u0434\u0430\u0439\u0442\u0435 \u043A\u043B\u044E\u0447 SteamGridDB \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445",
            ["Set as cover"] = "\u0421\u0434\u0435\u043B\u0430\u0442\u044C \u043E\u0431\u043B\u043E\u0436\u043A\u043E\u0439",
            ["Set the library as the screen Center opens on in Library Settings."] = "\u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u044B\u043C \u044D\u043A\u0440\u0430\u043D\u043E\u043C Center \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438.",
            ["Set up Center M, controller and Game Bar."] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u0442\u0435 Center M, \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0438 Game Bar.",
            ["Set your status"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0441\u0442\u0430\u0442\u0443\u0441",
            ["Set. Covers are downloaded for games with none."] = "\u0417\u0430\u0434\u0430\u043D. \u041E\u0431\u043B\u043E\u0436\u043A\u0438 \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u044E\u0442\u0441\u044F \u0434\u043B\u044F \u0438\u0433\u0440, \u0443 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0438\u0445 \u043D\u0435\u0442.",
            ["Setting cover\u2026"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043E\u0431\u043B\u043E\u0436\u043A\u0438\u2026",
            ["Settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438",
            ["Settings reset."] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u044B.",
            ["Show the certificate in Explorer"] = "\u041F\u043E\u043A\u0430\u0437\u0430\u0442\u044C \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442 \u0432 \u041F\u0440\u043E\u0432\u043E\u0434\u043D\u0438\u043A\u0435",
            ["Shows your installed Steam, Xbox and Epic games."] = "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0438\u0433\u0440\u044B Steam, Xbox \u0438 Epic.",
            ["Shut down"] = "\u0412\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u044C",
            ["Signing certificate"] = "\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442 \u043F\u043E\u0434\u043F\u0438\u0441\u0438",
            ["Some hardware commands could not be sent."] = "\u041D\u0435\u043A\u043E\u0442\u043E\u0440\u044B\u0435 \u043A\u043E\u043C\u0430\u043D\u0434\u044B \u0436\u0435\u043B\u0435\u0437\u0443 \u043E\u0442\u043F\u0440\u0430\u0432\u0438\u0442\u044C \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C.",
            ["Square ROM art"] = "\u041A\u0432\u0430\u0434\u0440\u0430\u0442\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 ROM",
            ["Start"] = "\u0421\u0442\u0430\u0440\u0442",
            ["Start Center with ClawTweaks"] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C Center \u0441 ClawTweaks",
            ["Start in the library"] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u0432 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435",
            ["Start menu, desktop and startup"] = "\u041C\u0435\u043D\u044E \u00AB\u041F\u0443\u0441\u043A\u00BB, \u0440\u0430\u0431\u043E\u0447\u0438\u0439 \u0441\u0442\u043E\u043B \u0438 \u0430\u0432\u0442\u043E\u0437\u0430\u043F\u0443\u0441\u043A",
            ["Started from Windows"] = "\u0417\u0430\u043F\u0443\u0449\u0435\u043D\u043E \u0438\u0437 Windows",
            ["Starting\u2026"] = "\u0417\u0430\u043F\u0443\u0441\u043A\u2026",
            ["Stay open"] = "\u041D\u0435 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0442\u044C",
            ["Steam Xbox filter driver"] = "\u0414\u0440\u0430\u0439\u0432\u0435\u0440-\u0444\u0438\u043B\u044C\u0442\u0440 Xbox \u043E\u0442 Steam",
            ["Steam asks you where to put it."] = "Steam \u0441\u043F\u0440\u043E\u0441\u0438\u0442, \u043A\u0443\u0434\u0430 \u0435\u0451 \u043F\u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C.",
            ["Steam cover art is found automatically."] = "\u041E\u0431\u043B\u043E\u0436\u043A\u0438 Steam \u043D\u0430\u0445\u043E\u0434\u044F\u0442\u0441\u044F \u0430\u0432\u0442\u043E\u043C\u0430\u0442\u0438\u0447\u0435\u0441\u043A\u0438.",
            ["Steam has taken over. The download shows in Recent."] = "Steam \u0432\u0437\u044F\u043B \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435. \u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0432\u0438\u0434\u043D\u0430 \u0432 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB.",
            ["SteamGridDB key"] = "\u041A\u043B\u044E\u0447 SteamGridDB",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "\u0428\u0430\u0433 1 \u043D\u0435 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D. \u041F\u043E\u0441\u043B\u0435 \u044D\u0442\u043E\u0433\u043E \u043D\u0438\u0447\u0442\u043E \u043D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0435 \u043D\u0435 \u0441\u043C\u043E\u0436\u0435\u0442 \u0432\u044B\u043A\u043B\u044E\u0447\u0438\u0442\u044C \u043B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430 \u0438\u043B\u0438 \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440 \u043F\u0440\u043E\u0448\u0438\u0432\u043A\u0435.",
            ["Stick deadzone"] = "\u041C\u0451\u0440\u0442\u0432\u0430\u044F \u0437\u043E\u043D\u0430 \u0441\u0442\u0438\u043A\u0430",
            ["Stretch"] = "\u0420\u0430\u0441\u0442\u044F\u043D\u0443\u0442\u044C",
            ["System"] = "\u0421\u0438\u0441\u0442\u0435\u043C\u0430",
            ["System language"] = "\u042F\u0437\u044B\u043A \u0441\u0438\u0441\u0442\u0435\u043C\u044B",
            ["TDP boost"] = "Boost TDP",
            ["Test versions"] = "\u0422\u0435\u0441\u0442\u043E\u0432\u044B\u0435 \u0432\u0435\u0440\u0441\u0438\u0438",
            ["That is what makes the extra controller features possible."] = "\u0418\u043C\u0435\u043D\u043D\u043E \u044D\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442 \u0432\u043E\u0437\u043C\u043E\u0436\u043D\u044B\u043C\u0438 \u0434\u043E\u043F\u043E\u043B\u043D\u0438\u0442\u0435\u043B\u044C\u043D\u044B\u0435 \u0444\u0443\u043D\u043A\u0446\u0438\u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430.",
            ["That key was rejected."] = "\u042D\u0442\u043E\u0442 \u043A\u043B\u044E\u0447 \u043E\u0442\u043A\u043B\u043E\u043D\u0451\u043D.",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430, \u043A\u0440\u0438\u0432\u0443\u044E \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430 \u0438 \u0440\u0435\u0436\u0438\u043C \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430 \u043C\u043E\u0436\u0435\u0442 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0442\u043E\u043B\u044C\u043A\u043E ClawTweaks. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0435\u0433\u043E \u0441\u043D\u043E\u0432\u0430, \u0447\u0442\u043E\u0431\u044B \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0438\u0445, \u0437\u0430\u0442\u0435\u043C \u0432\u0435\u0440\u043D\u0438\u0442\u0435\u0441\u044C \u0441\u044E\u0434\u0430. Center \u0432\u0441\u0451 \u0435\u0449\u0451 \u043C\u043E\u0436\u043D\u043E \u0443\u0434\u0430\u043B\u0438\u0442\u044C.",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B \u2014 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435 \u0435\u0433\u043E \u043F\u0435\u0440\u0435\u0434 \u043E\u0442\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435\u043C.",
            ["The device can be restored"] = "\u0423\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E \u043C\u043E\u0436\u043D\u043E \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["The helper did not confirm in time."] = "\u041F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043D\u0435 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043B \u0432\u043E\u0432\u0440\u0435\u043C\u044F.",
            ["The helper is not answering"] = "\u041F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043D\u0435 \u043E\u0442\u0432\u0435\u0447\u0430\u0435\u0442",
            ["The library comes back when the game ends."] = "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u0438\u0433\u0440\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0430\u0435\u0442\u0441\u044F.",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u0420\u043E\u0434\u043D\u043E\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0434\u043E\u043B\u0436\u0435\u043D \u0431\u044B\u0442\u044C \u0447\u0438\u0441\u0442\u044B\u043C, \u043F\u0440\u0435\u0436\u0434\u0435 \u0447\u0435\u043C \u0437\u0430\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u0440\u0435\u0436\u0438\u043C. \u0412 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u0441\u043A\u0440\u044B\u0442 \u0438 \u0430\u043A\u0442\u0438\u0432\u0435\u043D \u043E\u0434\u0438\u043D \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 VIIPER; \u0432 \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0444\u0438\u0437\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442\u0441\u044F \u043D\u0430\u043F\u0440\u044F\u043C\u0443\u044E.",
            ["The newest changes, least tested"] = "\u0421\u0430\u043C\u044B\u0435 \u043D\u043E\u0432\u044B\u0435 \u0438\u0437\u043C\u0435\u043D\u0435\u043D\u0438\u044F, \u043C\u0435\u043D\u044C\u0448\u0435 \u0432\u0441\u0435\u0433\u043E \u043F\u0440\u043E\u0432\u0435\u0440\u0435\u043D\u044B",
            ["The old helper exited on its own."] = "\u0421\u0442\u0430\u0440\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0441\u044F \u0441\u0430\u043C.",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "\u0417\u0430\u043F\u0443\u0449\u0435\u043D \u0434\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440 \u0441\u0442\u0430\u0440\u043E\u0439 \u0432\u0435\u0440\u0441\u0438\u0438 \u2014 \u043F\u043E\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0435 \u0435\u0433\u043E \u0437\u0430\u043F\u0440\u043E\u0441. \u042D\u0442\u043E \u0443\u0432\u0435\u0434\u043E\u043C\u043B\u0435\u043D\u0438\u0435 \u0438\u0441\u0447\u0435\u0437\u043D\u0435\u0442, \u043A\u043E\u0433\u0434\u0430 \u043E\u043D \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0441\u044F (\u043D\u0430\u0436\u043C\u0438\u0442\u0435 \u24CE \u0434\u043B\u044F \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F).",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u043F\u0430\u043A\u0435\u0442. \u0417\u0430\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar \u0438 \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0438\u043B\u0438 \u0443\u0434\u0430\u043B\u0438\u0442\u0435 ClawTweaks \u0432 \u041F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u044B \u2192 \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F.",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\u0421\u0435\u043C\u0435\u0439\u0441\u0442\u0432\u043E \u043F\u0430\u043A\u0435\u0442\u0430 \u043A\u043E\u043D\u0444\u043B\u0438\u043A\u0442\u0443\u0435\u0442 \u0441 \u044D\u0442\u0438\u043C \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435\u043C. \u041E\u0447\u0438\u0441\u0442\u043A\u0430 \u0438 \u043E\u0434\u043D\u0430 \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u0430\u044F \u043F\u043E\u043F\u044B\u0442\u043A\u0430\u2026",
            ["The reset did not finish."] = "\u0421\u0431\u0440\u043E\u0441 \u043D\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u043B\u0441\u044F.",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\u0421\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442 \u043F\u043E\u0434\u043F\u0438\u0441\u0438 \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0435\u0442 \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0437\u0430\u043F\u0440\u043E\u0441 Windows, \u043E\u0434\u0438\u043D \u0440\u0430\u0437 \u043D\u0430 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E.",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\u0412\u0438\u0434\u0436\u0435\u0442 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442, \u0447\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A; \u0441\u0430\u043C \u043E\u043D \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043C\u0435\u043D\u044F\u0435\u0442.",
            ["The wiki page could not be read. Open it in a browser."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u0443 \u0432\u0438\u043A\u0438. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0435\u0451 \u0432 \u0431\u0440\u0430\u0443\u0437\u0435\u0440\u0435.",
            ["This Setup build is outdated"] = "\u042D\u0442\u0430 \u0441\u0431\u043E\u0440\u043A\u0430 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 \u0443\u0441\u0442\u0430\u0440\u0435\u043B\u0430",
            ["This installs an OLDER version than the one installed."] = "\u042D\u0442\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442 \u0432\u0435\u0440\u0441\u0438\u044E \u0421\u0422\u0410\u0420\u0415\u0415 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043D\u043E\u0439.",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\u042D\u0442\u043E \u043A\u0430\u0440\u043A\u0430\u0441\u043D\u0430\u044F \u0441\u0431\u043E\u0440\u043A\u0430 \u0431\u0435\u0437 \u043F\u0430\u043A\u0435\u0442\u0430, \u043F\u043E\u044D\u0442\u043E\u043C\u0443 \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0442\u044C \u0437\u0434\u0435\u0441\u044C \u043D\u0435\u0447\u0435\u0433\u043E. \u0412 \u043D\u0430\u0441\u0442\u043E\u044F\u0449\u0435\u043C \u043A\u043E\u043C\u043F\u043B\u0435\u043A\u0442\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430 .msix \u0438 .cer \u043B\u0435\u0436\u0430\u0442 \u0440\u044F\u0434\u043E\u043C \u0441 \u044D\u0442\u0438\u043C exe.",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\u042D\u0442\u043E \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442 \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E \u0432 \u0438\u0441\u0445\u043E\u0434\u043D\u043E\u0435 \u0441\u043E\u0441\u0442\u043E\u044F\u043D\u0438\u0435 \u0438 \u043E\u0447\u0438\u0449\u0430\u0435\u0442 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 ClawTweaks:",
            ["This removes ClawTweaks Center and closes it."] = "\u042D\u0442\u043E \u0443\u0434\u0430\u043B\u044F\u0435\u0442 ClawTweaks Center \u0438 \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0435\u0433\u043E.",
            ["This removes the ClawTweaks app from Windows."] = "\u042D\u0442\u043E \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 ClawTweaks \u0438\u0437 Windows.",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "\u042D\u0442\u043E \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0412\u0421\u0415 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 ClawTweaks:",
            ["This takes a moment."] = "\u042D\u0442\u043E \u0437\u0430\u0439\u043C\u0451\u0442 \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438.",
            ["This version can't be installed"] = "\u042D\u0442\u0443 \u0432\u0435\u0440\u0441\u0438\u044E \u043D\u0435\u043B\u044C\u0437\u044F \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\u042D\u0442\u0430 \u0432\u0435\u0440\u0441\u0438\u044F \u0443\u0436\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0430. \u041E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0435\u0451 \u0438\u0437 \u043C\u0435\u043D\u044E \u00AB\u041F\u0443\u0441\u043A\u00BB \u0438\u043B\u0438 \u0432\u0438\u0434\u0436\u0435\u0442\u0430 ClawTweaks \u0432 Game Bar \u0432\u043C\u0435\u0441\u0442\u043E \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0433\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430 \u044D\u0442\u043E\u0433\u043E \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A\u0430.",
            ["Timed out"] = "\u0412\u0440\u0435\u043C\u044F \u0438\u0441\u0442\u0435\u043A\u043B\u043E",
            ["Transition to new Center App - Uninstall the old version"] = "\u041F\u0435\u0440\u0435\u0445\u043E\u0434 \u043D\u0430 \u043D\u043E\u0432\u043E\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 Center - \u0443\u0434\u0430\u043B\u0438\u0442\u0435 \u0441\u0442\u0430\u0440\u0443\u044E \u0432\u0435\u0440\u0441\u0438\u044E",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\u0414\u043E\u0432\u0435\u0440\u044F\u0435\u0442 \u0441\u0435\u0440\u0442\u0438\u0444\u0438\u043A\u0430\u0442\u0443 \u043F\u043E\u0434\u043F\u0438\u0441\u0438, \u0443\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442 \u043F\u0430\u043A\u0435\u0442 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 Game Bar \u0438 \u0436\u0434\u0451\u0442 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A. \u0411\u0435\u0437\u043E\u043F\u0430\u0441\u043D\u043E \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C \u043F\u043E\u0432\u0442\u043E\u0440\u043D\u043E \u043F\u0440\u0438 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0438.",
            ["Turn MSI Center M back on"] = "\u0421\u043D\u043E\u0432\u0430 \u0432\u043A\u043B\u044E\u0447\u0438\u0442\u044C MSI Center M",
            ["Turn on"] = "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u044C",
            ["Turning MSI Center M back on\u2026"] = "\u041F\u043E\u0432\u0442\u043E\u0440\u043D\u043E\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 MSI Center M\u2026",
            ["Uninstall"] = "\u0423\u0434\u0430\u043B\u0438\u0442\u044C",
            ["Uninstall Center"] = "\u0423\u0434\u0430\u043B\u0438\u0442\u044C Center",
            ["Update ClawTweaks Center"] = "\u041E\u0431\u043D\u043E\u0432\u0438\u0442\u044C ClawTweaks Center",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u2014 \u043F\u043E\u0434\u0440\u043E\u0431\u043D\u043E\u0441\u0442\u0438 \u0432 \u043B\u043E\u0433\u0435. \u041F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u0435 \u0438\u043B\u0438 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u043E\u0442 \u0438\u043C\u0435\u043D\u0438 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0430.",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F \u043D\u0435 \u0442\u0440\u0435\u0431\u0443\u044E\u0442 \u0437\u0430\u043F\u0440\u043E\u0441\u0430 \u2014 \u0437\u0430\u0434\u0430\u0447\u0430 \u043D\u0435 \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u0442 \u043D\u043E\u043C\u0435\u0440\u0430 \u0432\u0435\u0440\u0441\u0438\u0438.",
            ["Updating..."] = "\u041E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\u0412\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u0438\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u00AB\u0423\u0434\u0430\u043B\u0438\u0442\u044C ClawTweaks\u00BB \u0437\u0434\u0435\u0441\u044C, \u0432 Center.",
            ["Verifying the virtual pad\u2026"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u0433\u0435\u0439\u043C\u043F\u0430\u0434\u0430\u2026",
            ["Vibration"] = "\u0412\u0438\u0431\u0440\u0430\u0446\u0438\u044F",
            ["Virtual controller (VIIPER)"] = "\u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0443\u0436\u0435 \u0430\u043A\u0442\u0438\u0432\u0435\u043D \u2014 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0432 \u043F\u043E\u0440\u044F\u0434\u043A\u0435.",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u043D\u0435 \u0441\u043C\u043E\u043D\u0442\u0438\u0440\u043E\u0432\u0430\u043B\u0441\u044F \u2014 \u0432\u043E\u0437\u0432\u0440\u0430\u0442 \u043A \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u043C\u0443 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0443.",
            ["Waiting for UAC\u2026"] = "\u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 UAC\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "\u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u0430 ClawTweaks. \u0415\u0441\u043B\u0438 Game Bar \u043E\u0442\u043A\u0440\u044B\u043B\u0441\u044F, \u043D\u043E \u043D\u0438\u0447\u0435\u0433\u043E \u043D\u0435 \u043F\u0440\u043E\u0438\u0441\u0445\u043E\u0434\u0438\u0442, \u0432\u044B\u0431\u0435\u0440\u0438\u0442\u0435 \u0432\u0438\u0434\u0436\u0435\u0442 ClawTweaks \u0432 \u043C\u0435\u043D\u044E \u0432\u0438\u0434\u0436\u0435\u0442\u043E\u0432 \u0438 \u0434\u043E\u0431\u0430\u0432\u044C\u0442\u0435 \u0435\u0433\u043E \u2014 \u0432\u0438\u0434\u0436\u0435\u0442, \u043A\u043E\u0442\u043E\u0440\u043E\u0433\u043E \u0435\u0449\u0451 \u043D\u0435\u0442 \u0432 Game Bar, \u0441\u0430\u043C \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043D\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442.",
            ["Waiting for the virtual controller to settle\u2026"] = "\u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u0441\u0442\u0430\u0431\u0438\u043B\u0438\u0437\u0430\u0446\u0438\u0438 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430\u2026",
            ["What does the background helper do?"] = "\u0427\u0442\u043E \u0434\u0435\u043B\u0430\u0435\u0442 \u0444\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A?",
            ["What happens"] = "\u0427\u0442\u043E \u043F\u0440\u043E\u0438\u0437\u043E\u0439\u0434\u0451\u0442",
            ["What is the virtual controller for?"] = "\u0417\u0430\u0447\u0435\u043C \u043D\u0443\u0436\u0435\u043D \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440?",
            ["What's new"] = "\u0427\u0442\u043E \u043D\u043E\u0432\u043E\u0433\u043E",
            ["Where are my settings, and how do I back them up?"] = "\u0413\u0434\u0435 \u043C\u043E\u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0438 \u043A\u0430\u043A \u0441\u0434\u0435\u043B\u0430\u0442\u044C \u0438\u0445 \u043A\u043E\u043F\u0438\u044E?",
            ["Why does ClawTweaks ask for admin rights?"] = "\u041F\u043E\u0447\u0435\u043C\u0443 ClawTweaks \u0437\u0430\u043F\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u0442 \u043F\u0440\u0430\u0432\u0430 \u0430\u0434\u043C\u0438\u043D\u0438\u0441\u0442\u0440\u0430\u0442\u043E\u0440\u0430?",
            ["Will be saved to"] = "\u0411\u0443\u0434\u0435\u0442 \u0441\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u043E \u0432",
            ["Windowed"] = "\u0412 \u043E\u043A\u043D\u0435",
            ["Windows Insider Preview detected"] = "\u041E\u0431\u043D\u0430\u0440\u0443\u0436\u0435\u043D Windows Insider Preview",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows \u0437\u0430\u043F\u0440\u043E\u0441\u0438\u043B \u0443\u0434\u0430\u043B\u0435\u043D\u0438\u0435 Center. \u0417\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0437\u0434\u0435\u0441\u044C \u0438\u043B\u0438 \u043D\u0430\u0436\u043C\u0438\u0442\u0435 B, \u0447\u0442\u043E\u0431\u044B \u0432\u0441\u0451 \u043E\u0441\u0442\u0430\u0432\u0438\u0442\u044C.",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows \u043D\u0435 \u0441\u043C\u043E\u0433 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0444\u0430\u0439\u043B \u043F\u0430\u043A\u0435\u0442\u0430. \u0414\u0435\u043B\u043E \u043D\u0435 \u0432 \u0441\u0430\u043C\u043E\u043C \u043F\u0430\u043A\u0435\u0442\u0435 \u2014 \u0441\u043B\u0443\u0436\u0431\u0430 \u0440\u0430\u0437\u0432\u0451\u0440\u0442\u044B\u0432\u0430\u043D\u0438\u044F (\u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u043E\u0442 SYSTEM) \u043D\u0435 \u0441\u043C\u043E\u0433\u043B\u0430 \u0435\u0433\u043E \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C. \u041F\u043E\u043F\u0440\u043E\u0431\u0443\u0439\u0442\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0438\u0437 \u043F\u0430\u043F\u043A\u0438 \u0432\u043D\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u044F \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F \u0438 \u043F\u0440\u043E\u0432\u0435\u0440\u044C\u0442\u0435, \u0432 \u043F\u043E\u0440\u044F\u0434\u043A\u0435 \u043B\u0438 Gaming Services.",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows \u043D\u0435 \u0441\u043C\u043E\u0433 \u043E\u0442\u043A\u0440\u044B\u0442\u044C \u043F\u0430\u043A\u0435\u0442 \u0438\u0437 \u044D\u0442\u043E\u0439 \u043F\u0430\u043F\u043A\u0438. \u041F\u043E\u0432\u0442\u043E\u0440 \u0438\u0437 \u043E\u0431\u0449\u0435\u0441\u0438\u0441\u0442\u0435\u043C\u043D\u043E\u0433\u043E \u0440\u0430\u0441\u043F\u043E\u043B\u043E\u0436\u0435\u043D\u0438\u044F\u2026",
            ["Windows file picker"] = "\u0412\u044B\u0431\u043E\u0440 \u0444\u0430\u0439\u043B\u0430 Windows",
            ["Work down the list. Each step is optional except the last."] = "\u041F\u0440\u043E\u0439\u0434\u0438\u0442\u0435 \u0441\u043F\u0438\u0441\u043E\u043A \u043F\u043E \u043F\u043E\u0440\u044F\u0434\u043A\u0443. \u041A\u0430\u0436\u0434\u044B\u0439 \u0448\u0430\u0433 \u043D\u0435\u043E\u0431\u044F\u0437\u0430\u0442\u0435\u043B\u0435\u043D, \u043A\u0440\u043E\u043C\u0435 \u043F\u043E\u0441\u043B\u0435\u0434\u043D\u0435\u0433\u043E.",
            ["Working\u2026"] = "\u0412\u044B\u043F\u043E\u043B\u043D\u044F\u0435\u0442\u0441\u044F\u2026",
            ["XInput controllers"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u044B XInput",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\u0414\u0430, \u0435\u0441\u043B\u0438 ClawTweaks \u0434\u043E\u043B\u0436\u0435\u043D \u0443\u043F\u0440\u0430\u0432\u043B\u044F\u0442\u044C \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u043E\u043C, \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u043E\u043C \u0438 \u043F\u043E\u0434\u0441\u0432\u0435\u0442\u043A\u043E\u0439.",
            ["Yes, install"] = "\u0414\u0430, \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Yes, reset everything"] = "\u0414\u0430, \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0432\u0441\u0451",
            ["Yes, restore"] = "\u0414\u0430, \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C",
            ["Yes, restore the device"] = "\u0414\u0430, \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u043E",
            ["Yes, uninstall Center"] = "\u0414\u0430, \u0443\u0434\u0430\u043B\u0438\u0442\u044C Center",
            ["Yes, uninstall ClawTweaks"] = "\u0414\u0430, \u0443\u0434\u0430\u043B\u0438\u0442\u044C ClawTweaks",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "\u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0433\u0435\u0439\u043C\u043F\u0430\u0434 \u0432\u0430\u0448\u0435\u0433\u043E Claw \u0441\u043A\u0440\u044B\u0442 \u0438 \u0437\u0430\u043C\u0435\u043D\u0451\u043D \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u043C.",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\u0422\u0435\u043A\u0443\u0449\u0438\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0441\u043E\u0445\u0440\u0430\u043D\u044F\u044E\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0434 \u0441\u0431\u0440\u043E\u0441\u043E\u043C. Game Bar \u0437\u0430\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u2014 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 \u0435\u0433\u043E \u0441\u043D\u043E\u0432\u0430 \u0447\u0435\u0440\u0435\u0437 Win+G.",
            ["Your games"] = "\u0412\u0430\u0448\u0438 \u0438\u0433\u0440\u044B",
            ["usbip  (required for virtual controller)"] = "usbip  (\u043D\u0443\u0436\u0435\u043D \u0434\u043B\u044F \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430)",
            ["version"] = "\u0432\u0435\u0440\u0441\u0438\u044F",
            ["versions"] = "\u0432\u0435\u0440\u0441\u0438\u0438",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \u0412\u0441\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438, \u043A\u0440\u0438\u0432\u044B\u0435 \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430, TDP \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430 \u0441\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u044E\u0442\u0441\u044F",
            ["\u2022 Center's own settings are cleared"] = "\u2022 \u0421\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center \u043E\u0447\u0438\u0449\u0430\u044E\u0442\u0441\u044F",
            ["\u2022 Global and per-game profiles (TDP, fan curves, controller, gyro)"] = "\u2022 \u0413\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u044B\u0435 \u0438 \u0438\u0433\u0440\u043E\u0432\u044B\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 (TDP, \u043A\u0440\u0438\u0432\u044B\u0435 \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430, \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440, \u0433\u0438\u0440\u043E\u0441\u043A\u043E\u043F)",
            ["\u2022 Helper settings (global TDP, fan curve, controller emulation)"] = "\u2022 \u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A\u0430 (\u0433\u043B\u043E\u0431\u0430\u043B\u044C\u043D\u044B\u0439 TDP, \u043A\u0440\u0438\u0432\u0430\u044F \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430, \u044D\u043C\u0443\u043B\u044F\u0446\u0438\u044F \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430)",
            ["\u2022 The ClawTweaks app is NOT removed by this"] = "\u2022 \u041F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 ClawTweaks \u043F\u0440\u0438 \u044D\u0442\u043E\u043C \u041D\u0415 \u0443\u0434\u0430\u043B\u044F\u0435\u0442\u0441\u044F",
            ["\u2022 The Start Menu entry and the desktop shortcut go"] = "\u2022 \u041F\u0443\u043D\u043A\u0442 \u0432 \u043C\u0435\u043D\u044E \u00AB\u041F\u0443\u0441\u043A\u00BB \u0438 \u044F\u0440\u043B\u044B\u043A \u043D\u0430 \u0440\u0430\u0431\u043E\u0447\u0435\u043C \u0441\u0442\u043E\u043B\u0435 \u0443\u0434\u0430\u043B\u044F\u044E\u0442\u0441\u044F",
            ["\u2022 The background helper stops and removes its scheduled task"] = "\u2022 \u0424\u043E\u043D\u043E\u0432\u044B\u0439 \u043F\u043E\u043C\u043E\u0449\u043D\u0438\u043A \u043E\u0441\u0442\u0430\u043D\u0430\u0432\u043B\u0438\u0432\u0430\u0435\u0442\u0441\u044F \u0438 \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u0441\u0432\u043E\u044E \u0437\u0430\u0434\u0430\u0447\u0443 \u043F\u043B\u0430\u043D\u0438\u0440\u043E\u0432\u0449\u0438\u043A\u0430",
            ["\u2022 The battery charge limit is switched off"] = "\u2022 \u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430 \u0431\u0430\u0442\u0430\u0440\u0435\u0438 \u043E\u0442\u043A\u043B\u044E\u0447\u0430\u0435\u0442\u0441\u044F",
            ["\u2022 The fan goes back to firmware control"] = "\u2022 \u0412\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F \u043F\u043E\u0434 \u0443\u043F\u0440\u0430\u0432\u043B\u0435\u043D\u0438\u0435 \u043F\u0440\u043E\u0448\u0438\u0432\u043A\u0438",
            ["\u2022 The hardware controller comes back"] = "\u2022 \u0410\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0432\u043E\u0437\u0432\u0440\u0430\u0449\u0430\u0435\u0442\u0441\u044F",
            ["\u2022 The widget disappears from the Game Bar"] = "\u2022 \u0412\u0438\u0434\u0436\u0435\u0442 \u0438\u0441\u0447\u0435\u0437\u0430\u0435\u0442 \u0438\u0437 Game Bar",
            ["\u2022 Your profiles and settings are deleted with the app"] = "\u2022 \u041F\u0440\u043E\u0444\u0438\u043B\u0438 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0443\u0434\u0430\u043B\u044F\u044E\u0442\u0441\u044F \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C",
            ["Could not start {0}."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C {0}.",
            ["Install {0}?"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C {0}?",
            ["Start Steam with the library"] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C Steam \u0441 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u043E\u0439",
            ["Denser grid"] = "\u041F\u043B\u043E\u0442\u043D\u0435\u0435 \u0441\u0435\u0442\u043A\u0430",
            ["Interface sounds"] = "\u0417\u0432\u0443\u043A\u0438 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430",
            ["Background music"] = "\u0424\u043E\u043D\u043E\u0432\u0430\u044F \u043C\u0443\u0437\u044B\u043A\u0430",
            ["Sound settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0437\u0432\u0443\u043A\u0430",
            ["Effects volume"] = "\u0413\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u044D\u0444\u0444\u0435\u043A\u0442\u043E\u0432",
            ["Music volume"] = "\u0413\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u043C\u0443\u0437\u044B\u043A\u0438",
            ["Change a value with left and right."] = "\u041C\u0435\u043D\u044F\u0439\u0442\u0435 \u0437\u043D\u0430\u0447\u0435\u043D\u0438\u0435 \u0432\u043B\u0435\u0432\u043E \u0438 \u0432\u043F\u0440\u0430\u0432\u043E.",
            ["Navigate"] = "\u041D\u0430\u0432\u0438\u0433\u0430\u0446\u0438\u044F",
            ["Go back"] = "\u041D\u0430\u0437\u0430\u0434",
            ["Change"] = "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C",
            ["Toggle"] = "\u041F\u0435\u0440\u0435\u043A\u043B\u044E\u0447\u0438\u0442\u044C",
            ["Reading your stores\u2026"] = "\u0427\u0442\u0435\u043D\u0438\u0435 \u043C\u0430\u0433\u0430\u0437\u0438\u043D\u043E\u0432\u2026",
            ["Reading your Steam library\u2026"] = "\u0427\u0442\u0435\u043D\u0438\u0435 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438 Steam\u2026",
            ["Center opens on the library, not on Home."] = "Center \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0441\u044F \u043D\u0430 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0435, \u0430 \u043D\u0435 \u043D\u0430 \u0433\u043B\u0430\u0432\u043D\u043E\u0439.",
            ["ClawTweaks starts Center when it starts itself."] = "ClawTweaks \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 Center \u0432\u043C\u0435\u0441\u0442\u0435 \u0441 \u0441\u043E\u0431\u043E\u0439.",
            ["Closing the window leaves Center running in the tray."] = "\u0417\u0430\u043A\u0440\u044B\u0442\u0438\u0435 \u043E\u043A\u043D\u0430 \u043E\u0441\u0442\u0430\u0432\u043B\u044F\u0435\u0442 Center \u0440\u0430\u0431\u043E\u0442\u0430\u0442\u044C \u0432 \u0442\u0440\u0435\u0435.",
            ["What Center does with itself once a game runs."] = "\u0427\u0442\u043E Center \u0434\u0435\u043B\u0430\u0435\u0442 \u0441 \u0441\u043E\u0431\u043E\u0439, \u043A\u043E\u0433\u0434\u0430 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u0430 \u0438\u0433\u0440\u0430.",
            ["Which tabs the library shows, and in which order."] = "\u041A\u0430\u043A\u0438\u0435 \u0432\u043A\u043B\u0430\u0434\u043A\u0438 \u043F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0435\u0442 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0438 \u0432 \u043A\u0430\u043A\u043E\u043C \u043F\u043E\u0440\u044F\u0434\u043A\u0435.",
            ["More covers per row, and a smaller Recent reel."] = "\u0411\u043E\u043B\u044C\u0448\u0435 \u043E\u0431\u043B\u043E\u0436\u0435\u043A \u0432 \u0440\u044F\u0434\u0443 \u0438 \u043C\u0435\u043D\u044C\u0448\u0430\u044F \u043B\u0435\u043D\u0442\u0430 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB.",
            ["Fades the tabs and the footer out on Recent while you idle."] = "\u0421\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0432\u043A\u043B\u0430\u0434\u043A\u0438 \u0438 \u043D\u0438\u0436\u043D\u044E\u044E \u043F\u0430\u043D\u0435\u043B\u044C \u0432 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB \u043F\u0440\u0438 \u0431\u0435\u0437\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0438.",
            ["Mirrors every cover in the Recent reel."] = "\u041E\u0442\u0440\u0430\u0436\u0430\u0435\u0442 \u043A\u0430\u0436\u0434\u0443\u044E \u043E\u0431\u043B\u043E\u0436\u043A\u0443 \u0432 \u043B\u0435\u043D\u0442\u0435 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB.",
            ["Show own apps in Recent"] = "\u041C\u043E\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u0432 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB",
            ["Apps you added show up in Recent after you start them here."] = "\u0414\u043E\u0431\u0430\u0432\u043B\u0435\u043D\u043D\u044B\u0435 \u0432\u0430\u043C\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F \u043F\u043E\u044F\u0432\u044F\u0442\u0441\u044F \u0432 \u00AB\u041D\u0435\u0434\u0430\u0432\u043D\u0438\u0445\u00BB \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u043F\u0443\u0441\u043A\u0430 \u043E\u0442\u0441\u044E\u0434\u0430.",
            ["ROM covers are square instead of upright."] = "\u041E\u0431\u043B\u043E\u0436\u043A\u0438 ROM \u043A\u0432\u0430\u0434\u0440\u0430\u0442\u043D\u044B\u0435, \u0430 \u043D\u0435 \u0432\u0435\u0440\u0442\u0438\u043A\u0430\u043B\u044C\u043D\u044B\u0435.",
            ["The folder your own covers and backgrounds come from."] = "\u041F\u0430\u043F\u043A\u0430, \u043E\u0442\u043A\u0443\u0434\u0430 \u0431\u0435\u0440\u0443\u0442\u0441\u044F \u0432\u0430\u0448\u0438 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0438 \u0444\u043E\u043D\u044B.",
            ["The picture behind the library."] = "\u0418\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u0437\u0430 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u043E\u0439.",
            ["Interface sounds, music, and a volume for each."] = "\u0417\u0432\u0443\u043A\u0438 \u0438\u043D\u0442\u0435\u0440\u0444\u0435\u0439\u0441\u0430, \u043C\u0443\u0437\u044B\u043A\u0430 \u0438 \u0433\u0440\u043E\u043C\u043A\u043E\u0441\u0442\u044C \u0434\u043B\u044F \u043A\u0430\u0436\u0434\u043E\u0433\u043E.",
            ["Downloads covers for games that have none."] = "\u0417\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0434\u043B\u044F \u0438\u0433\u0440, \u0443 \u043A\u043E\u0442\u043E\u0440\u044B\u0445 \u0438\u0445 \u043D\u0435\u0442.",
            ["Start {0}?"] = "\u0417\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C {0}?",
            ["Steam starts first. This takes longer."] = "\u0421\u043D\u0430\u0447\u0430\u043B\u0430 \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F Steam. \u042D\u0442\u043E \u0434\u043E\u043B\u044C\u0448\u0435.",
            ["This can take a moment."] = "\u042D\u0442\u043E \u043C\u043E\u0436\u0435\u0442 \u0437\u0430\u043D\u044F\u0442\u044C \u043D\u0435\u043C\u043D\u043E\u0433\u043E \u0432\u0440\u0435\u043C\u0435\u043D\u0438.",
            ["Your images"] = "\u0412\u0430\u0448\u0438 \u0438\u0437\u043E\u0431\u0440\u0430\u0436\u0435\u043D\u0438\u044F",
            ["{0} \u00B7 charging"] = "{0} \u00B7 \u0437\u0430\u0440\u044F\u0436\u0430\u0435\u0442\u0441\u044F",
            ["{0} \u00B7 charging \u00B7 {1} h"] = "{0} \u00B7 \u0437\u0430\u0440\u044F\u0436\u0430\u0435\u0442\u0441\u044F \u00B7 {1} \u0447",
            ["{0} \u00B7 discharging"] = "{0} \u00B7 \u0440\u0430\u0437\u0440\u044F\u0436\u0430\u0435\u0442\u0441\u044F",
            ["{0} \u00B7 discharging \u00B7 {1} h"] = "{0} \u00B7 \u0440\u0430\u0437\u0440\u044F\u0436\u0430\u0435\u0442\u0441\u044F \u00B7 {1} \u0447",
            ["{0} \u00B7 AC power \u00B7 fully charged"] = "{0} \u00B7 \u043E\u0442 \u0441\u0435\u0442\u0438 \u00B7 \u0437\u0430\u0440\u044F\u0436\u0435\u043D\u0430",
            ["{0} \u00B7 AC power \u00B7 not charging"] = "{0} \u00B7 \u043E\u0442 \u0441\u0435\u0442\u0438 \u00B7 \u043D\u0435 \u0437\u0430\u0440\u044F\u0436\u0430\u0435\u0442\u0441\u044F",
            ["{0} is downloading"] = "{0} \u0437\u0430\u0433\u0440\u0443\u0436\u0430\u0435\u0442\u0441\u044F",
            ["{0} is running"] = "{0} \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u0430",
            ["{0} is starting"] = "{0} \u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F",
            ["{0} of {1} unlocked"] = "{0} \u0438\u0437 {1} \u043E\u0442\u043A\u0440\u044B\u0442\u043E",
            ["{0}% of players"] = "{0}% \u0438\u0433\u0440\u043E\u043A\u043E\u0432",
            ["Drivers & Windows Updates"] = "\u0414\u0440\u0430\u0439\u0432\u0435\u0440\u044B \u0438 Windows Update",
            ["Device drivers"] = "\u0414\u0440\u0430\u0439\u0432\u0435\u0440\u044B \u0443\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432",
            ["Drivers could not be checked"] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u044B",
            ["ClawTweaks is not running."] = "ClawTweaks \u043D\u0435 \u0437\u0430\u043F\u0443\u0449\u0435\u043D.",
            ["No answer from ClawTweaks."] = "\u041D\u0435\u0442 \u043E\u0442\u0432\u0435\u0442\u0430 \u043E\u0442 ClawTweaks.",
            ["The driver list could not be read."] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0447\u0438\u0442\u0430\u0442\u044C \u0441\u043F\u0438\u0441\u043E\u043A \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u043E\u0432.",
            ["The driver check failed."] = "\u041F\u0440\u043E\u0432\u0435\u0440\u043A\u0430 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u043E\u0432 \u043D\u0435 \u0443\u0434\u0430\u043B\u0430\u0441\u044C.",
            ["Graphics"] = "\u0413\u0440\u0430\u0444\u0438\u043A\u0430",
            ["Devices"] = "\u0423\u0441\u0442\u0440\u043E\u0439\u0441\u0442\u0432\u0430",
