            ["Open Library"] = "\u041E\u0442\u043A\u0440\u044B\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443",
            ["Exit Center"] = "\u0412\u044B\u0439\u0442\u0438 \u0438\u0437 Center",
