            ["Auto-jump set to position {0}."] = "\u0410\u0432\u0442\u043E\u043F\u0435\u0440\u0435\u0445\u043E\u0434 \u0437\u0430\u0434\u0430\u043D \u043D\u0430 \u043F\u043E\u0437\u0438\u0446\u0438\u044E {0}.",
            ["Could not start the old uninstaller: {0}"] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u044C \u0441\u0442\u0430\u0440\u044B\u0439 \u0434\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440: {0}",
            ["it is a launcher for the .dll next to it, not a standalone build."] = "\u044D\u0442\u043E \u043B\u0430\u0443\u043D\u0447\u0435\u0440 \u0434\u043B\u044F .dll \u0440\u044F\u0434\u043E\u043C, \u0430 \u043D\u0435 \u0430\u0432\u0442\u043E\u043D\u043E\u043C\u043D\u0430\u044F \u0441\u0431\u043E\u0440\u043A\u0430.",
            ["it is only {0} KB, too small to carry its own runtime."] = "\u043E\u043D \u0432\u0441\u0435\u0433\u043E {0} \u041A\u0411, \u0441\u043B\u0438\u0448\u043A\u043E\u043C \u043C\u0430\u043B, \u0447\u0442\u043E\u0431\u044B \u0441\u043E\u0434\u0435\u0440\u0436\u0430\u0442\u044C \u0441\u0432\u043E\u044E \u0441\u0440\u0435\u0434\u0443 \u0432\u044B\u043F\u043E\u043B\u043D\u0435\u043D\u0438\u044F.",
            ["its own file could not be inspected ({0})."] = "\u043D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u043F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0435\u0433\u043E \u0441\u043E\u0431\u0441\u0442\u0432\u0435\u043D\u043D\u044B\u0439 \u0444\u0430\u0439\u043B ({0}).",
            ["This copy of Center cannot install itself: {0} Use the single-file build from the release page (or publish/), not the executable from a plain build output."] = "\u042D\u0442\u0430 \u043A\u043E\u043F\u0438\u044F Center \u043D\u0435 \u043C\u043E\u0436\u0435\u0442 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u044C \u0441\u0435\u0431\u044F: {0} \u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u043E\u0434\u043D\u043E\u0444\u0430\u0439\u043B\u043E\u0432\u0443\u044E \u0441\u0431\u043E\u0440\u043A\u0443 \u0441\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0440\u0435\u043B\u0438\u0437\u0430 (\u0438\u043B\u0438 publish/), \u0430 \u043D\u0435 exe \u0438\u0437 \u043E\u0431\u044B\u0447\u043D\u043E\u0439 \u0441\u0431\u043E\u0440\u043A\u0438.",
            ["Installing to {0}..."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u0432 {0}...",
            ["Could not create the desktop icon: {0}"] = "\u041D\u0435 \u0443\u0434\u0430\u043B\u043E\u0441\u044C \u0441\u043E\u0437\u0434\u0430\u0442\u044C \u0437\u043D\u0430\u0447\u043E\u043A \u043D\u0430 \u0440\u0430\u0431\u043E\u0447\u0435\u043C \u0441\u0442\u043E\u043B\u0435: {0}",
            ["Install failed: {0}"] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u043A\u0430 \u043D\u0435 \u0443\u0434\u0430\u043B\u0430\u0441\u044C: {0}",
            ["Waiting for the running Center to close ({0}/{1})..."] = "\u041E\u0436\u0438\u0434\u0430\u043D\u0438\u0435 \u0437\u0430\u043A\u0440\u044B\u0442\u0438\u044F \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u043D\u043E\u0433\u043E Center ({0}/{1})...",
            ["Connecting controller"] = "\u041F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Setting up virtual gamepad\u2026"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u043E\u0433\u043E \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430\u2026",
            ["Controller connected"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0451\u043D",
            ["Ready to play"] = "\u041C\u043E\u0436\u043D\u043E \u0438\u0433\u0440\u0430\u0442\u044C",
            ["Controller not connected"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043D\u0435 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0451\u043D",
            ["Restoring controller"] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0435 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Switching back to the hardware gamepad\u2026"] = "\u0412\u043E\u0437\u0432\u0440\u0430\u0442 \u043A \u0430\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u043E\u043C\u0443 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0443\u2026",
            ["Controller restored"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["Hardware gamepad is back"] = "\u0410\u043F\u043F\u0430\u0440\u0430\u0442\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u0432\u0435\u0440\u043D\u0443\u043B\u0441\u044F",
            ["Controller not restored"] = "\u041A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043D\u0435 \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D",
            ["It stays in DInput mode"] = "\u041E\u043D \u043E\u0441\u0442\u0430\u0451\u0442\u0441\u044F \u0432 \u0440\u0435\u0436\u0438\u043C\u0435 DInput",
            ["HW Mouse ON \u2014 controller paused. Click the HW Mouse tile or press the keyboard hotkey to return."] = "HW-\u043C\u044B\u0448\u044C \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u0430 \u2014 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440 \u043F\u0440\u0438\u043E\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u043F\u043B\u0438\u0442\u043A\u0443 HW-\u043C\u044B\u0448\u0438 \u0438\u043B\u0438 \u0441\u043E\u0447\u0435\u0442\u0430\u043D\u0438\u0435 \u043A\u043B\u0430\u0432\u0438\u0448, \u0447\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F.",
            ["Virtual mouse restored"] = "\u0412\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u0430\u044F \u043C\u044B\u0448\u044C \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0430",
            ["Controller mode"] = "\u0420\u0435\u0436\u0438\u043C \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u0430",
            ["Mouse mode"] = "\u0420\u0435\u0436\u0438\u043C \u043C\u044B\u0448\u0438",
            ["Charge Limit: set it up in Settings first"] = "\u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430: \u0441\u043D\u0430\u0447\u0430\u043B\u0430 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u0442\u0435 \u0435\u0433\u043E \u0432 \u043F\u0430\u0440\u0430\u043C\u0435\u0442\u0440\u0430\u0445",
            ["Charge Limit: On {0}%"] = "\u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430: \u0432\u043A\u043B. {0}%",
            ["Charge Limit: Off"] = "\u041B\u0438\u043C\u0438\u0442 \u0437\u0430\u0440\u044F\u0434\u0430: \u0432\u044B\u043A\u043B.",
            ["FPS Limit: {0} FPS"] = "\u041B\u0438\u043C\u0438\u0442 FPS: {0} FPS",
            ["FPS Limit: Off"] = "\u041B\u0438\u043C\u0438\u0442 FPS: \u0432\u044B\u043A\u043B.",
            ["Center Settings"] = "\u041D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center",
            ["Uninstall ClawTweaks"] = "\u0423\u0434\u0430\u043B\u0438\u0442\u044C ClawTweaks",
            ["Onboarding"] = "\u041F\u0435\u0440\u0432\u0438\u0447\u043D\u0430\u044F \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430",
            ["FAQ"] = "\u0427\u0430\u0441\u0442\u044B\u0435 \u0432\u043E\u043F\u0440\u043E\u0441\u044B",
            ["Fixed while Center is the Windows full-screen start app."] = "\u0417\u0430\u043A\u0440\u0435\u043F\u043B\u0435\u043D\u043E, \u043F\u043E\u043A\u0430 Center \u2014 \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u043E\u0435 \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u043E\u0435 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435 Windows.",
            ["Turn on \"Start Steam with the library\" in the library settings to speed this up next time."] = "\u0412\u043A\u043B\u044E\u0447\u0438\u0442\u0435 \u00AB\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0442\u044C Steam \u0441 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u043E\u0439\u00BB \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438, \u0447\u0442\u043E\u0431\u044B \u0432 \u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0438\u0439 \u0440\u0430\u0437 \u0431\u044B\u043B\u043E \u0431\u044B\u0441\u0442\u0440\u0435\u0435.",
            ["Make the library your Xbox full-screen start app"] = "\u0421\u0434\u0435\u043B\u0430\u0439\u0442\u0435 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u044B\u043C \u0441\u0442\u0430\u0440\u0442\u043E\u0432\u044B\u043C \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0435\u043C Xbox",
            ["Saves memory and start-up time. Run the setup from the GitHub releases page to register it."] = "\u042D\u043A\u043E\u043D\u043E\u043C\u0438\u0442 \u043F\u0430\u043C\u044F\u0442\u044C \u0438 \u0432\u0440\u0435\u043C\u044F \u0437\u0430\u043F\u0443\u0441\u043A\u0430. \u0417\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0443\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u0441\u043E \u0441\u0442\u0440\u0430\u043D\u0438\u0446\u044B \u0440\u0435\u043B\u0438\u0437\u043E\u0432 GitHub, \u0447\u0442\u043E\u0431\u044B \u0437\u0430\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043E\u0432\u0430\u0442\u044C \u0435\u0451.",
            ["Automatic check: off"] = "\u0410\u0432\u0442\u043E\u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430: \u0432\u044B\u043A\u043B.",
            ["Automatic check: {0}"] = "\u0410\u0432\u0442\u043E\u043F\u0440\u043E\u0432\u0435\u0440\u043A\u0430: {0}",
            ["Change in Center settings"] = "\u0418\u0437\u043C\u0435\u043D\u0438\u0442\u044C \u0432 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u0445 Center",
            ["Mute"] = "\u0421\u043A\u0440\u044B\u0442\u044C",
            ["Unmute"] = "\u041F\u043E\u043A\u0430\u0437\u044B\u0432\u0430\u0442\u044C",
            ["Tabs order and visibility"] = "\u041F\u043E\u0440\u044F\u0434\u043E\u043A \u0438 \u0432\u0438\u0434\u0438\u043C\u043E\u0441\u0442\u044C \u0432\u043A\u043B\u0430\u0434\u043E\u043A",
            ["Opens Steam in the tray when you open the library. The first Steam game after a boot starts faster."] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 Steam \u0432 \u0442\u0440\u0435\u0435 \u043F\u0440\u0438 \u043E\u0442\u043A\u0440\u044B\u0442\u0438\u0438 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0438. \u041F\u0435\u0440\u0432\u0430\u044F \u0438\u0433\u0440\u0430 Steam \u043F\u043E\u0441\u043B\u0435 \u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0438 \u0441\u0442\u0430\u0440\u0442\u0443\u0435\u0442 \u0431\u044B\u0441\u0442\u0440\u0435\u0435.",
            ["In fullscreen mode, Steam's window can open behind Center."] = "\u0412 \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u043E\u043A\u043D\u043E Steam \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044C\u0441\u044F \u043F\u043E\u0437\u0430\u0434\u0438 Center.",
            ["Steam removes the game files. In fullscreen, Steam's dialog can open behind Center."] = "Steam \u0443\u0434\u0430\u043B\u044F\u0435\u0442 \u0444\u0430\u0439\u043B\u044B \u0438\u0433\u0440\u044B. \u0412 \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u0434\u0438\u0430\u043B\u043E\u0433 Steam \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044C\u0441\u044F \u043F\u043E\u0437\u0430\u0434\u0438 Center.",
            ["Opens your Epic library. Uninstall the game there."] = "\u041E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 Epic. \u0423\u0434\u0430\u043B\u0438\u0442\u0435 \u0438\u0433\u0440\u0443 \u0442\u0430\u043C.",
            ["Deletes the game for this Windows user."] = "\u0423\u0434\u0430\u043B\u044F\u0435\u0442 \u0438\u0433\u0440\u0443 \u0434\u043B\u044F \u044D\u0442\u043E\u0433\u043E \u043F\u043E\u043B\u044C\u0437\u043E\u0432\u0430\u0442\u0435\u043B\u044F Windows.",
            ["Press again to delete the game."] = "\u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u0435\u0449\u0451 \u0440\u0430\u0437, \u0447\u0442\u043E\u0431\u044B \u0443\u0434\u0430\u043B\u0438\u0442\u044C \u0438\u0433\u0440\u0443.",
            ["No uninstaller found"] = "\u0414\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440 \u043D\u0435 \u043D\u0430\u0439\u0434\u0435\u043D",
            ["Runs the game's own uninstaller"] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0434\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440 \u0438\u0433\u0440\u044B",
            ["Runs the game's own uninstaller. In fullscreen, it can open behind Center."] = "\u0417\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442 \u0434\u0435\u0438\u043D\u0441\u0442\u0430\u043B\u043B\u044F\u0442\u043E\u0440 \u0438\u0433\u0440\u044B. \u0412 \u043F\u043E\u043B\u043D\u043E\u044D\u043A\u0440\u0430\u043D\u043D\u043E\u043C \u0440\u0435\u0436\u0438\u043C\u0435 \u043E\u043D \u043C\u043E\u0436\u0435\u0442 \u043E\u0442\u043A\u0440\u044B\u0442\u044C\u0441\u044F \u0437\u0430 Center.",
            ["Graphics (WHQL only)"] = "\u0413\u0440\u0430\u0444\u0438\u043A\u0430 (\u0442\u043E\u043B\u044C\u043A\u043E WHQL)",
            ["Graphics (WHQL and non-WHQL)"] = "\u0413\u0440\u0430\u0444\u0438\u043A\u0430 (WHQL \u0438 \u043D\u0435-WHQL)",
            ["Download started in the background. The installer opens when it is done."] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u0430 \u0432 \u0444\u043E\u043D\u0435. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u043F\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438.",
            ["Download started in the background - over 800 MB. The installer opens when it is done."] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u0430 \u0432 \u0444\u043E\u043D\u0435 \u2014 \u0431\u043E\u043B\u0435\u0435 800 \u041C\u0411. \u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0449\u0438\u043A \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u043F\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438.",
            ["Download started in the background. The folder opens when it is done - run Setup.bat there."] = "\u0417\u0430\u0433\u0440\u0443\u0437\u043A\u0430 \u0437\u0430\u043F\u0443\u0449\u0435\u043D\u0430 \u0432 \u0444\u043E\u043D\u0435. \u041F\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438 \u043E\u0442\u043A\u0440\u043E\u0435\u0442\u0441\u044F \u043F\u0430\u043F\u043A\u0430 \u2014 \u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0435 \u0442\u0430\u043C Setup.bat.",
            ["{0} update(s) ready, restart pending"] = "\u0413\u043E\u0442\u043E\u0432\u043E \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u0439: {0}, \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u043A\u0430",
            ["Install them in Windows Update, then restart."] = "\u0423\u0441\u0442\u0430\u043D\u043E\u0432\u0438\u0442\u0435 \u0438\u0445 \u0432 \u0426\u0435\u043D\u0442\u0440\u0435 \u043E\u0431\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F Windows, \u0437\u0430\u0442\u0435\u043C \u043F\u0435\u0440\u0435\u0437\u0430\u0433\u0440\u0443\u0437\u0438\u0442\u0435\u0441\u044C.",
            ["Check drivers again"] = "\u041F\u0440\u043E\u0432\u0435\u0440\u0438\u0442\u044C \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u044B \u0441\u043D\u043E\u0432\u0430",
            ["Also non-WHQL graphics drivers"] = "\u0422\u0430\u043A\u0436\u0435 \u043D\u0435-WHQL \u0433\u0440\u0430\u0444\u0438\u0447\u0435\u0441\u043A\u0438\u0435 \u0434\u0440\u0430\u0439\u0432\u0435\u0440\u044B",
            ["Modded Wi-Fi driver instead of stock"] = "\u041C\u043E\u0434\u0438\u0444\u0438\u0446\u0438\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0439 \u0434\u0440\u0430\u0439\u0432\u0435\u0440 Wi-Fi \u0432\u043C\u0435\u0441\u0442\u043E \u0448\u0442\u0430\u0442\u043D\u043E\u0433\u043E",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). Optionally the library and Center settings too."] = "\u0421\u0431\u0440\u0430\u0441\u044B\u0432\u0430\u0435\u0442 \u0432\u0441\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 ClawTweaks (\u043F\u0440\u043E\u0444\u0438\u043B\u0438, \u043A\u0440\u0438\u0432\u044B\u0435 \u0432\u0435\u043D\u0442\u0438\u043B\u044F\u0442\u043E\u0440\u0430, TDP, \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440). \u041F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E \u2014 \u0442\u0430\u043A\u0436\u0435 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center.",
            ["Save all your profiles and settings into a single ZIP you can restore later. Optionally with the library, Center settings and your game art."] = "\u0421\u043E\u0445\u0440\u0430\u043D\u044F\u0435\u0442 \u0432\u0441\u0435 \u043F\u0440\u043E\u0444\u0438\u043B\u0438 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u0432 \u043E\u0434\u0438\u043D ZIP \u0434\u043B\u044F \u043F\u043E\u0441\u043B\u0435\u0434\u0443\u044E\u0449\u0435\u0433\u043E \u0432\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u0438\u044F. \u041F\u043E \u0436\u0435\u043B\u0430\u043D\u0438\u044E \u2014 \u0441 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u043E\u0439, \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\u0438 Center \u0438 \u0432\u0430\u0448\u0438\u043C\u0438 \u043E\u0431\u043B\u043E\u0436\u043A\u0430\u043C\u0438.",
            ["Also reset the library and Center settings"] = "\u0422\u0430\u043A\u0436\u0435 \u0441\u0431\u0440\u043E\u0441\u0438\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center",
            ["Favorites, play history, your own apps, cover picks and every Center setting. Center restarts afterwards. The safety backup includes them too."] = "\u0418\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0438\u0433\u0440, \u0432\u0430\u0448\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0438 \u0432\u0441\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center. \u0417\u0430\u0442\u0435\u043C Center \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0441\u044F. \u0421\u0442\u0440\u0430\u0445\u043E\u0432\u043E\u0447\u043D\u0430\u044F \u043A\u043E\u043F\u0438\u044F \u0442\u043E\u0436\u0435 \u0438\u0445 \u0441\u043E\u0434\u0435\u0440\u0436\u0438\u0442.",
            ["Also back up the library and Center settings"] = "\u0422\u0430\u043A\u0436\u0435 \u0441\u043E\u0445\u0440\u0430\u043D\u0438\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center",
            ["Favorites, play history, your own apps, cover picks, the art cache and every Center setting."] = "\u0418\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0438\u0433\u0440, \u0432\u0430\u0448\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438, \u043A\u044D\u0448 \u043E\u0431\u043B\u043E\u0436\u0435\u043A \u0438 \u0432\u0441\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center.",
            ["with library and Center settings"] = "\u0441 \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u043E\u0439 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0430\u043C\u0438 Center",
            ["Library and Center settings included"] = "\u0411\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B",
            ["Favorites, play history, your own apps, cover picks and every Center setting come back too. Center restarts when it is done."] = "\u0418\u0437\u0431\u0440\u0430\u043D\u043D\u043E\u0435, \u0438\u0441\u0442\u043E\u0440\u0438\u044F \u0438\u0433\u0440, \u0432\u0430\u0448\u0438 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u044F, \u0432\u044B\u0431\u0440\u0430\u043D\u043D\u044B\u0435 \u043E\u0431\u043B\u043E\u0436\u043A\u0438 \u0438 \u0432\u0441\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center \u0442\u043E\u0436\u0435 \u0432\u0435\u0440\u043D\u0443\u0442\u0441\u044F. \u041F\u043E \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043D\u0438\u0438 Center \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u0442\u0438\u0442\u0441\u044F.",
            ["Center data: included"] = "\u0414\u0430\u043D\u043D\u044B\u0435 Center: \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B",
            ["Center data: not included"] = "\u0414\u0430\u043D\u043D\u044B\u0435 Center: \u043D\u0435 \u0432\u043A\u043B\u044E\u0447\u0435\u043D\u044B",
            ["All ClawTweaks settings, the library and the Center settings were reset. Center restarts now."] = "\u0412\u0441\u0435 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 ClawTweaks, \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0430 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 Center \u0441\u0431\u0440\u043E\u0448\u0435\u043D\u044B. Center \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F.",
            ["Backup created without Center data"] = "\u0420\u0435\u0437\u0435\u0440\u0432\u043D\u0430\u044F \u043A\u043E\u043F\u0438\u044F \u0441\u043E\u0437\u0434\u0430\u043D\u0430 \u0431\u0435\u0437 \u0434\u0430\u043D\u043D\u044B\u0445 Center",
            ["Saved {0} stores and {1} Center files to:\n{2}"] = "\u0421\u043E\u0445\u0440\u0430\u043D\u0435\u043D\u043E \u0445\u0440\u0430\u043D\u0438\u043B\u0438\u0449: {0}, \u0444\u0430\u0439\u043B\u043E\u0432 Center: {1}, \u0432:\n{2}",
            ["Restored {0} files. Center restarts now to bring back the library and its settings \u2014 reopen the Game Bar (Win+G) afterwards."] = "\u0412\u043E\u0441\u0441\u0442\u0430\u043D\u043E\u0432\u043B\u0435\u043D\u043E \u0444\u0430\u0439\u043B\u043E\u0432: {0}. Center \u043F\u0435\u0440\u0435\u0437\u0430\u043F\u0443\u0441\u043A\u0430\u0435\u0442\u0441\u044F, \u0447\u0442\u043E\u0431\u044B \u0432\u0435\u0440\u043D\u0443\u0442\u044C \u0431\u0438\u0431\u043B\u0438\u043E\u0442\u0435\u043A\u0443 \u0438 \u043D\u0430\u0441\u0442\u0440\u043E\u0439\u043A\u0438 \u2014 \u0437\u0430\u0442\u0435\u043C \u0441\u043D\u043E\u0432\u0430 \u043E\u0442\u043A\u0440\u043E\u0439\u0442\u0435 Game Bar (Win+G).",
            ["This panel works only with the virtual controller"] = "\u042D\u0442\u0430 \u043F\u0430\u043D\u0435\u043B\u044C \u0440\u0430\u0431\u043E\u0442\u0430\u0435\u0442 \u0442\u043E\u043B\u044C\u043A\u043E \u0441 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u043C \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440\u043E\u043C",
            ["Use the Game Bar instead."] = "\u0418\u0441\u043F\u043E\u043B\u044C\u0437\u0443\u0439\u0442\u0435 \u0432\u043C\u0435\u0441\u0442\u043E \u043D\u0435\u0451 Game Bar.",
            ["Game Bar opened instead"] = "\u0412\u043C\u0435\u0441\u0442\u043E \u044D\u0442\u043E\u0433\u043E \u043E\u0442\u043A\u0440\u044B\u0442\u0430 Game Bar",
            ["Quick Settings need the virtual controller"] = "Quick Settings \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u0438\u0440\u0442\u0443\u0430\u043B\u044C\u043D\u044B\u0439 \u043A\u043E\u043D\u0442\u0440\u043E\u043B\u043B\u0435\u0440",
