            ["Already enabled."] = "\u0389\u03B4\u03B7 \u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03B7\u03BC\u03AD\u03BD\u03BF.",
            ["Also looks for new cover art"] = "\u03A8\u03AC\u03C7\u03BD\u03B5\u03B9 \u03BA\u03B1\u03B9 \u03B3\u03B9\u03B1 \u03BD\u03AD\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1",
