            ["Back to the cover Center finds itself"] = "\u03A0\u03AF\u03C3\u03C9 \u03C3\u03C4\u03BF \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03BF \u03C0\u03BF\u03C5 \u03B2\u03C1\u03AF\u03C3\u03BA\u03B5\u03B9 \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF\u03C5 \u03C4\u03BF Center",
