            ["Backup failed"] = "\u03A4\u03BF \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5",
            ["Blocked"] = "\u0391\u03C0\u03BF\u03BA\u03BB\u03B5\u03B9\u03C3\u03BC\u03AD\u03BD\u03BF",
            ["Both write the same hardware, and the last one to write wins."] = "\u039A\u03B1\u03B9 \u03C4\u03B1 \u03B4\u03CD\u03BF \u03B3\u03C1\u03AC\u03C6\u03BF\u03C5\u03BD \u03C3\u03C4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC, \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B9\u03BA\u03C1\u03B1\u03C4\u03B5\u03AF \u03CC\u03C0\u03BF\u03B9\u03BF \u03B3\u03C1\u03AC\u03C8\u03B5\u03B9 \u03C4\u03B5\u03BB\u03B5\u03C5\u03C4\u03B1\u03AF\u03BF.",
            ["Bring back a previous backup. A safety copy of the current state is taken automatically first."] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03AD\u03BD\u03B1 \u03C0\u03C1\u03BF\u03B7\u03B3\u03BF\u03CD\u03BC\u03B5\u03BD\u03BF \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF. \u03A0\u03C1\u03CE\u03C4\u03B1 \u03BA\u03C1\u03B1\u03C4\u03B9\u03AD\u03C4\u03B1\u03B9 \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B1 \u03B5\u03C6\u03B5\u03B4\u03C1\u03B9\u03BA\u03CC \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C4\u03B7\u03C2 \u03C4\u03C1\u03AD\u03C7\u03BF\u03C5\u03C3\u03B1\u03C2 \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2.",
            ["Browse for a file"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7 \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF\u03C5",
            ["Browse\u2026"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7\u2026",
            ["Center background"] = "\u03A6\u03CC\u03BD\u03C4\u03BF \u03C4\u03BF\u03C5 Center",
            ["Change folder"] = "\u0391\u03BB\u03BB\u03B1\u03B3\u03AE \u03C6\u03B1\u03BA\u03AD\u03BB\u03BF\u03C5",
            ["Choose one of your images"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03BC\u03AF\u03B1 \u03B1\u03C0\u03CC \u03C4\u03B9\u03C2 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B5\u03C2 \u03C3\u03B1\u03C2",
            ["Choose a background"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C6\u03CC\u03BD\u03C4\u03BF",
            ["CPU boost"] = "Boost CPU",
            ["CTW Full Reset"] = "\u03A0\u03BB\u03AE\u03C1\u03B7\u03C2 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC CTW",
            ["Cancel"] = "\u0386\u03BA\u03C5\u03C1\u03BF",
            ["Center is how you update ClawTweaks and reset the device. Remove ClawTweaks first if you meant to remove both."] = "\u03A4\u03BF Center \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BF \u03C4\u03C1\u03CC\u03C0\u03BF\u03C2 \u03BD\u03B1 \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03BD\u03B5\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03BA\u03B1\u03B9 \u03BD\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE. \u0391\u03BD \u03B8\u03AD\u03BB\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03C3\u03B5\u03C4\u03B5 \u03BA\u03B1\u03B9 \u03C4\u03B1 \u03B4\u03CD\u03BF, \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03C3\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF ClawTweaks.",
            ["Center itself never asks for admin rights."] = "\u03A4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C4\u03BF Center \u03B4\u03B5\u03BD \u03B6\u03B7\u03C4\u03AC \u03C0\u03BF\u03C4\u03AD \u03B4\u03B9\u03BA\u03B1\u03B9\u03CE\u03BC\u03B1\u03C4\u03B1 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE.",
            ["Center settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 Center",
            ["Center start screen"] = "\u0391\u03C1\u03C7\u03B9\u03BA\u03AE \u03BF\u03B8\u03CC\u03BD\u03B7 \u03C4\u03BF\u03C5 Center",
            ["Centered"] = "\u039A\u03B5\u03BD\u03C4\u03C1\u03B1\u03C1\u03B9\u03C3\u03BC\u03AD\u03BD\u03BF",
            ["Certificate already trusted."] = "\u03A4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AE\u03B4\u03B7 \u03AD\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF.",
            ["Charge limit off and fan handed back to firmware."] = "\u03A4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2 \u03B1\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03B8\u03B7\u03BA\u03B5 \u03BA\u03B1\u03B9 \u03BF \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1\u03C2 \u03B5\u03C0\u03AD\u03C3\u03C4\u03C1\u03B5\u03C8\u03B5 \u03C3\u03C4\u03BF firmware.",
            ["Check"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2",
            ["Check hardware controller health"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C5\u03B3\u03B5\u03AF\u03B1\u03C2 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["Check the controller first."] = "\u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["Checking controller mode\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5\u2026",
            ["Checking for duplicate helpers\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03B3\u03B9\u03B1 \u03B4\u03B9\u03C0\u03BB\u03CC helper\u2026",
            ["Checking prerequisites\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C0\u03C1\u03BF\u03B1\u03C0\u03B1\u03B9\u03C4\u03BF\u03CD\u03BC\u03B5\u03BD\u03C9\u03BD\u2026",
            ["Checking the Game Bar\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03BF\u03C5 Game Bar\u2026",
            ["Checking the controller\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5\u2026",
            ["Checking whether the device can be restored."] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03B1\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03B5\u03C1\u03B8\u03B5\u03AF \u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["Checking\u2026"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2\u2026",
            ["Choose"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE",
            ["Choose cover"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5",
            ["Choose cover art"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5",
            ["Choose cover art\u2026"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5\u2026",
            ["Choose from installed apps"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE \u03B1\u03C0\u03CC \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B5\u03C2 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2",
            ["Choose how the library starts and looks."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C0\u03CE\u03C2 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03BA\u03B1\u03B9 \u03C0\u03CE\u03C2 \u03B4\u03B5\u03AF\u03C7\u03BD\u03B5\u03B9 \u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7.",
            ["Choose the language and how the window opens."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C4\u03B7 \u03B3\u03BB\u03CE\u03C3\u03C3\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03BF\u03BD \u03C4\u03C1\u03CC\u03C0\u03BF \u03C0\u03BF\u03C5 \u03B1\u03BD\u03BF\u03AF\u03B3\u03B5\u03B9 \u03C4\u03BF \u03C0\u03B1\u03C1\u03AC\u03B8\u03C5\u03C1\u03BF.",
            ["Choose what to add"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C4\u03B9 \u03B8\u03B1 \u03C0\u03C1\u03BF\u03C3\u03B8\u03AD\u03C3\u03B5\u03C4\u03B5",
            ["Choose what to do next."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C4\u03B9 \u03B8\u03B1 \u03B3\u03AF\u03BD\u03B5\u03B9 \u03BC\u03B5\u03C4\u03AC.",
            ["ClawTweaks Center is already installed"] = "\u03A4\u03BF ClawTweaks Center \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AE\u03B4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["ClawTweaks Library Overview"] = "\u0395\u03C0\u03B9\u03C3\u03BA\u03CC\u03C0\u03B7\u03C3\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2 ClawTweaks",
            ["ClawTweaks installed"] = "\u03A4\u03BF ClawTweaks \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03B8\u03B7\u03BA\u03B5",
            ["ClawTweaks is in your Game Bar."] = "\u03A4\u03BF ClawTweaks \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C3\u03C4\u03BF Game Bar \u03C3\u03B1\u03C2.",
            ["ClawTweaks is installed and its helper is answering."] = "\u03A4\u03BF ClawTweaks \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03BA\u03B1\u03B9 \u03BF helper \u03C4\u03BF\u03C5 \u03B1\u03C0\u03B1\u03BD\u03C4\u03AC.",
            ["ClawTweaks is not installed"] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["ClawTweaks is not installed."] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF.",
            ["ClawTweaks is not running. Start it and try again."] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9. \u039E\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03BA\u03B1\u03B9 \u03B4\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC.",
            ["ClawTweaks is removed. Its helper clears its own scheduled task and exits \u2014 give it a minute."] = "\u03A4\u03BF ClawTweaks \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5. \u039F helper \u03C4\u03BF\u03C5 \u03C3\u03B2\u03AE\u03BD\u03B5\u03B9 \u03BC\u03CC\u03BD\u03BF\u03C2 \u03C4\u03BF\u03C5 \u03C4\u03B7\u03BD \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03B5\u03C1\u03BC\u03B1\u03C4\u03AF\u03B6\u03B5\u03B9 \u2014 \u03B4\u03CE\u03C3\u03C4\u03B5 \u03C4\u03BF\u03C5 \u03AD\u03BD\u03B1 \u03BB\u03B5\u03C0\u03C4\u03CC.",
            ["ClawTweaks not installed"] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["ClawTweaks removed."] = "\u03A4\u03BF ClawTweaks \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5.",
            ["ClawTweaks stays installed"] = "\u03A4\u03BF ClawTweaks \u03C0\u03B1\u03C1\u03B1\u03BC\u03AD\u03BD\u03B5\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["ClawTweaks updated"] = "\u03A4\u03BF ClawTweaks \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["Click the right stick to show the button hints"] = "\u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF\u03BD \u03B4\u03B5\u03BE\u03AF \u03BC\u03BF\u03C7\u03BB\u03CC \u03B3\u03B9\u03B1 \u03C4\u03B9\u03C2 \u03C5\u03C0\u03BF\u03B4\u03B5\u03AF\u03BE\u03B5\u03B9\u03C2 \u03C0\u03BB\u03AE\u03BA\u03C4\u03C1\u03C9\u03BD",
            ["Close"] = "\u039A\u03BB\u03B5\u03AF\u03C3\u03B9\u03BC\u03BF",
            ["Close Center"] = "\u039A\u03BB\u03B5\u03AF\u03C3\u03B9\u03BC\u03BF \u03C4\u03BF\u03C5 Center",
            ["Close MSI Center M"] = "\u039A\u03BB\u03B5\u03AF\u03C3\u03B9\u03BC\u03BF \u03C4\u03BF\u03C5 MSI Center M",
            ["Close all"] = "\u039A\u03BB\u03B5\u03AF\u03C3\u03B9\u03BC\u03BF \u03CC\u03BB\u03C9\u03BD",
            ["Closes everything and powers off."] = "\u039A\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9 \u03C4\u03B1 \u03C0\u03AC\u03BD\u03C4\u03B1 \u03BA\u03B1\u03B9 \u03C3\u03B2\u03AE\u03BD\u03B5\u03B9 \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["Closes everything and starts again."] = "\u039A\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9 \u03C4\u03B1 \u03C0\u03AC\u03BD\u03C4\u03B1 \u03BA\u03B1\u03B9 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03BE\u03B1\u03BD\u03AC.",
            ["Connecting to the helper\u2026"] = "\u03A3\u03CD\u03BD\u03B4\u03B5\u03C3\u03B7 \u03BC\u03B5 \u03C4\u03BF\u03BD helper\u2026",
            ["Controller"] = "\u03A7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF",
            ["Controller health"] = "\u03A5\u03B3\u03B5\u03AF\u03B1 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["Copy your key from Preferences \u2192 API Key."] = "\u0391\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C8\u03C4\u03B5 \u03C4\u03BF \u03BA\u03BB\u03B5\u03B9\u03B4\u03AF \u03C3\u03B1\u03C2 \u03B1\u03C0\u03CC Preferences \u2192 API Key.",
            ["Could not reach the helper."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03BF helper.",
            ["Couldn't load"] = "\u0394\u03B5\u03BD \u03C6\u03BF\u03C1\u03C4\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["Covers for Xbox, Epic and your own games"] = "\u0395\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03B3\u03B9\u03B1 Xbox, Epic \u03BA\u03B1\u03B9 \u03B4\u03B9\u03BA\u03AC \u03C3\u03B1\u03C2 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1",
            ["Create Backup"] = "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5",
            ["Create Backup writes one ZIP to Documents\\ClawTweaks\\Backups."] = "\u0397 \u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5 \u03B3\u03C1\u03AC\u03C6\u03B5\u03B9 \u03AD\u03BD\u03B1 ZIP \u03C3\u03C4\u03BF Documents\\ClawTweaks\\Backups.",
            ["Create a free SteamGridDB account."] = "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AE\u03C3\u03C4\u03B5 \u03B4\u03C9\u03C1\u03B5\u03AC\u03BD \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03CC SteamGridDB.",
            ["Create backup"] = "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5",
            ["Creating backup\u2026"] = "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5\u2026",
            ["Currently disabled."] = "\u0391\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C4\u03B9\u03B3\u03BC\u03AE \u03B1\u03BD\u03B5\u03BD\u03B5\u03C1\u03B3\u03CC.",
            ["Currently installed"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7",
            ["Currently running."] = "\u0395\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C4\u03B9\u03B3\u03BC\u03AE.",
            ["Deletes the entry, not the app"] = "\u0394\u03B9\u03B1\u03B3\u03C1\u03AC\u03C6\u03B5\u03B9 \u03C4\u03B7\u03BD \u03BA\u03B1\u03C4\u03B1\u03C7\u03CE\u03C1\u03B9\u03C3\u03B7, \u03CC\u03C7\u03B9 \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE",
            ["Desktop icon"] = "\u03A3\u03C5\u03BD\u03C4\u03CC\u03BC\u03B5\u03C5\u03C3\u03B7",
            ["Detecting device\u2026"] = "\u0395\u03BD\u03C4\u03BF\u03C0\u03B9\u03C3\u03BC\u03CC\u03C2 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE\u03C2\u2026",
            ["Did not confirm in time."] = "\u0394\u03B5\u03BD \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03B8\u03B7\u03BA\u03B5 \u03B5\u03B3\u03BA\u03B1\u03AF\u03C1\u03C9\u03C2.",
            ["Did not enable in time."] = "\u0394\u03B5\u03BD \u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03B8\u03B7\u03BA\u03B5 \u03B5\u03B3\u03BA\u03B1\u03AF\u03C1\u03C9\u03C2.",
            ["Different device"] = "\u0386\u03BB\u03BB\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE",
            ["Disable MSI Center M"] = "\u0391\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03C4\u03BF\u03C5 MSI Center M",
            ["Disable MSI Center M first."] = "\u0391\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF MSI Center M.",
            ["Disabled"] = "\u0391\u03BD\u03B5\u03BD\u03B5\u03C1\u03B3\u03CC",
            ["Do I have to switch MSI Center M off?"] = "\u03A0\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03BA\u03BB\u03B5\u03AF\u03C3\u03C9 \u03C4\u03BF MSI Center M;",
            ["Do I need the Game Bar for the game library?"] = "\u03A7\u03C1\u03B5\u03B9\u03AC\u03B6\u03BF\u03BC\u03B1\u03B9 \u03C4\u03BF Game Bar \u03B3\u03B9\u03B1 \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7;",
            ["Do not remove ClawTweaks through the Windows app list."] = "\u039C\u03B7\u03BD \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03B1\u03C0\u03CC \u03C4\u03B7 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03CE\u03BD \u03C4\u03C9\u03BD Windows.",
            ["Downgrade"] = "\u03A5\u03C0\u03BF\u03B2\u03AC\u03B8\u03BC\u03B9\u03C3\u03B7",
            ["Download and package install in progress."] = "\u0393\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03BB\u03AE\u03C8\u03B7 \u03BA\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF\u03C5.",
            ["Download the ClawTweaks setup and run that instead."] = "\u039A\u03B1\u03C4\u03B5\u03B2\u03AC\u03C3\u03C4\u03B5 \u03C4\u03BF setup \u03C4\u03BF\u03C5 ClawTweaks \u03BA\u03B1\u03B9 \u03B5\u03BA\u03C4\u03B5\u03BB\u03AD\u03C3\u03C4\u03B5 \u03B5\u03BA\u03B5\u03AF\u03BD\u03BF.",
            ["Downloading"] = "\u0393\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03BB\u03AE\u03C8\u03B7",
            ["E-core EPP"] = "EPP E-core",
            ["E-core max"] = "\u039C\u03AD\u03B3\u03B9\u03C3\u03C4\u03BF E-core",
            ["E-core state"] = "\u039A\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 E-core",
            ["Edit name"] = "\u0391\u03BB\u03BB\u03B1\u03B3\u03AE \u03BF\u03BD\u03CC\u03BC\u03B1\u03C4\u03BF\u03C2",
            ["Edit search"] = "\u0391\u03BB\u03BB\u03B1\u03B3\u03AE \u03B1\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7\u03C2",
            ["Enable the virtual controller first."] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["Enable virtual controller"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03BF\u03CD \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["Enabled"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03CC",
            ["Enter the slot ClawTweaks sits at, then Run."] = "\u0394\u03CE\u03C3\u03C4\u03B5 \u03C4\u03B7 \u03B8\u03AD\u03C3\u03B7 \u03CC\u03C0\u03BF\u03C5 \u03B2\u03C1\u03AF\u03C3\u03BA\u03B5\u03C4\u03B1\u03B9 \u03C4\u03BF ClawTweaks \u03BA\u03B1\u03B9 \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u0395\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7.",
            ["Exit"] = "\u0388\u03BE\u03BF\u03B4\u03BF\u03C2",
            ["Expected for a same-version reinstall \u2014 the helper doesn't restart or show a UAC prompt when nothing changed. Open the Game Bar (Win+G) to check it's still running."] = "\u0391\u03BD\u03B1\u03BC\u03B5\u03BD\u03CC\u03BC\u03B5\u03BD\u03BF \u03C3\u03B5 \u03B5\u03C0\u03B1\u03BD\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03AF\u03B4\u03B9\u03B1\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2 \u2014 \u03BF helper \u03B4\u03B5\u03BD \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03B5\u03AF \u03BF\u03CD\u03C4\u03B5 \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03B9 UAC \u03CC\u03C4\u03B1\u03BD \u03B4\u03B5\u03BD \u03AC\u03BB\u03BB\u03B1\u03BE\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1. \u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03BF Game Bar (Win+G) \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B4\u03B5\u03AF\u03C4\u03B5 \u03CC\u03C4\u03B9 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Experimental versions (nightly)"] = "\u03A0\u03B5\u03B9\u03C1\u03B1\u03BC\u03B1\u03C4\u03B9\u03BA\u03AD\u03C2 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2 (nightly)",
            ["Folder is gone"] = "\u039F \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF\u03C2 \u03B4\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9",
            ["FPS cap"] = "\u038C\u03C1\u03B9\u03BF FPS",
            ["Favorites"] = "\u0391\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03B1",
            ["Final clean-up and check. MSI Center M is handled here (after installation) because it fights ClawTweaks for the controller and LED."] = "\u03A4\u03B5\u03BB\u03B9\u03BA\u03CC \u03BA\u03B1\u03B8\u03AC\u03C1\u03B9\u03C3\u03BC\u03B1 \u03BA\u03B1\u03B9 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2. \u03A4\u03BF MSI Center M \u03C1\u03C5\u03B8\u03BC\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B5\u03B4\u03CE (\u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7) \u03B5\u03C0\u03B5\u03B9\u03B4\u03AE \u03B4\u03B9\u03B5\u03BA\u03B4\u03B9\u03BA\u03B5\u03AF \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03C4\u03BF LED \u03B1\u03C0\u03CC \u03C4\u03BF ClawTweaks.",
            ["Final controller check"] = "\u03A4\u03B5\u03BB\u03B9\u03BA\u03CC\u03C2 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["Finish here and close the window."] = "\u03A4\u03AD\u03BB\u03BF\u03C2 \u03B5\u03B4\u03CE, \u03BA\u03BB\u03B5\u03AF\u03C3\u03C4\u03B5 \u03C4\u03BF \u03C0\u03B1\u03C1\u03AC\u03B8\u03C5\u03C1\u03BF.",
            ["Firmware button remapping is there too, and works without it."] = "\u03A5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03BA\u03B1\u03B9 \u03B1\u03BD\u03C4\u03B9\u03C3\u03C4\u03BF\u03AF\u03C7\u03B9\u03C3\u03B7 \u03C0\u03BB\u03AE\u03BA\u03C4\u03C1\u03C9\u03BD \u03C3\u03C4\u03BF firmware, \u03C0\u03BF\u03C5 \u03B4\u03BF\u03C5\u03BB\u03B5\u03CD\u03B5\u03B9 \u03BA\u03B1\u03B9 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03B1\u03C5\u03C4\u03CC.",
            ["First install on this PC \u2014 Windows will ask for permission once."] = "\u03A0\u03C1\u03CE\u03C4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C3\u03B5 \u03B1\u03C5\u03C4\u03CC\u03BD \u03C4\u03BF\u03BD \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE \u2014 \u03C4\u03B1 Windows \u03B8\u03B1 \u03B6\u03B7\u03C4\u03AE\u03C3\u03BF\u03C5\u03BD \u03AC\u03B4\u03B5\u03B9\u03B1 \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC.",
            ["Frame generation"] = "\u0394\u03B7\u03BC\u03B9\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03BA\u03B1\u03C1\u03AD",
            ["Front and M back-button mapping, gyro with smoothing, per-game profiles."] = "\u0391\u03BD\u03C4\u03B9\u03C3\u03C4\u03BF\u03AF\u03C7\u03B9\u03C3\u03B7 \u03BC\u03C0\u03C1\u03BF\u03C3\u03C4\u03B9\u03BD\u03CE\u03BD \u03BA\u03B1\u03B9 \u03C0\u03AF\u03C3\u03C9 \u03C0\u03BB\u03AE\u03BA\u03C4\u03C1\u03C9\u03BD M, gyro \u03BC\u03B5 \u03B5\u03BE\u03BF\u03BC\u03AC\u03BB\u03C5\u03BD\u03C3\u03B7, \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03B1\u03BD\u03AC \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9.",
            ["Fullscreen"] = "\u03A0\u03BB\u03AE\u03C1\u03B7\u03C2 \u03BF\u03B8\u03CC\u03BD\u03B7",
            ["GPU scaling"] = "\u039A\u03BB\u03B9\u03BC\u03AC\u03BA\u03C9\u03C3\u03B7 GPU",
            ["Game Library"] = "\u0392\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7",
            ["Get ClawTweaks"] = "\u039B\u03AE\u03C8\u03B7 \u03C4\u03BF\u03C5 ClawTweaks",
            ["Go into Library Settings and switch on Start in the library."] = "\u03A0\u03B7\u03B3\u03B1\u03AF\u03BD\u03B5\u03C4\u03B5 \u03C3\u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2 \u03BA\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B7\u03BD \u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03C3\u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7.",
            ["Guided setup"] = "\u039F\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C1\u03CD\u03B8\u03BC\u03B9\u03C3\u03B7\u03C2",
            ["Hair triggers"] = "\u03A3\u03BA\u03B1\u03BD\u03B4\u03AC\u03BB\u03B5\u03C2 \u03B1\u03BA\u03B1\u03C1\u03B9\u03B1\u03AF\u03B5\u03C2",
            ["Hardware controller confirmed."] = "\u03A4\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03B8\u03B7\u03BA\u03B5.",
            ["Helps set the most important ClawTweaks settings."] = "\u0392\u03BF\u03B7\u03B8\u03AC \u03BD\u03B1 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03C3\u03B7\u03BC\u03B1\u03BD\u03C4\u03B9\u03BA\u03CC\u03C4\u03B5\u03C1\u03B5\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C4\u03BF\u03C5 ClawTweaks.",
            ["Hidden"] = "\u039A\u03C1\u03C5\u03C6\u03CC",
            ["Hidden until you unlock it."] = "\u039A\u03C1\u03C5\u03C6\u03CC \u03BC\u03AD\u03C7\u03C1\u03B9 \u03BD\u03B1 \u03C4\u03BF \u03BE\u03B5\u03BA\u03BB\u03B5\u03B9\u03B4\u03CE\u03C3\u03B5\u03C4\u03B5.",
            ["Hide"] = "\u0391\u03C0\u03CC\u03BA\u03C1\u03C5\u03C8\u03B7",
            ["Hide a tab with A."] = "\u039A\u03C1\u03CD\u03C8\u03C4\u03B5 \u03BC\u03B9\u03B1 \u03BA\u03B1\u03C1\u03C4\u03AD\u03BB\u03B1 \u03BC\u03B5 \u24B6.",
            ["HidHide and usbip install kernel drivers. Reboot the device once after installing them, then run this setup again."] = "\u03A4\u03BF HidHide \u03BA\u03B1\u03B9 \u03C4\u03BF usbip \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03BF\u03B4\u03B7\u03B3\u03BF\u03CD\u03C2 \u03C0\u03C5\u03C1\u03AE\u03BD\u03B1. \u0395\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5 \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03AE \u03C4\u03BF\u03C5\u03C2 \u03BA\u03B1\u03B9 \u03C4\u03C1\u03AD\u03BE\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF setup.",
            ["How do I uninstall and go back to MSI Center M?"] = "\u03A0\u03CE\u03C2 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03CE \u03BA\u03B1\u03B9 \u03B3\u03C5\u03C1\u03AF\u03B6\u03C9 \u03C3\u03C4\u03BF MSI Center M;",
            ["In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u03A3\u03C4\u03B7\u03BD \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C4\u03BF \u03C6\u03C5\u03C3\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03C1\u03CD\u03B2\u03B5\u03C4\u03B1\u03B9 \u03BA\u03B1\u03B9 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03CC \u03AD\u03BD\u03B1 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF VIIPER\u00B7 \u03C3\u03C4\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03C0\u03B5\u03C5\u03B8\u03B5\u03AF\u03B1\u03C2 \u03C4\u03BF \u03C6\u03C5\u03C3\u03B9\u03BA\u03CC.",
            ["Install"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Install ClawTweaks"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks",
            ["Install ClawTweaks Center"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks Center",
            ["Install failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u0397 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5 \u2014 \u03B4\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03BA\u03B1\u03C4\u03B1\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2. \u0394\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03AE \u03B5\u03BA\u03C4\u03B5\u03BB\u03AD\u03C3\u03C4\u03B5 \u03C9\u03C2 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C2.",
            ["Install releases, test builds and nightlies."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2, \u03B4\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AD\u03C2 \u03BA\u03B1\u03B9 nightly.",
            ["Install this version"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B1\u03C5\u03C4\u03AE\u03C2 \u03C4\u03B7\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2",
            ["Install this version?"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B1\u03C5\u03C4\u03AE\u03C2 \u03C4\u03B7\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2;",
            ["Install timed out."] = "\u039B\u03AE\u03BE\u03B7 \u03C7\u03C1\u03CC\u03BD\u03BF\u03C5 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2.",
            ["Installation complete"] = "\u0397 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["Installed but not running (fine). Uninstall it from Windows Settings \u203A Apps if you want it gone permanently."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03B1\u03BB\u03BB\u03AC \u03B4\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 (\u03B5\u03BD\u03C4\u03AC\u03BE\u03B5\u03B9). \u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C0\u03CC \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 Windows \u203A \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03B1\u03BD \u03B8\u03AD\u03BB\u03B5\u03C4\u03B5 \u03BD\u03B1 \u03C6\u03CD\u03B3\u03B5\u03B9 \u03BF\u03C1\u03B9\u03C3\u03C4\u03B9\u03BA\u03AC.",
            ["Installed \u2014 background helper started"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03B8\u03B7\u03BA\u03B5 \u2014 \u03BF helper \u03BE\u03B5\u03BA\u03AF\u03BD\u03B7\u03C3\u03B5 \u03C3\u03C4\u03BF \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03AE\u03BD\u03B9\u03BF",
            ["Installing package\u2026"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF\u03C5\u2026",
            ["Installing..."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7...",
            ["Integer"] = "\u0391\u03BA\u03AD\u03C1\u03B1\u03B9\u03BF",
            ["Invisible"] = "\u0391\u03CC\u03C1\u03B1\u03C4\u03BF\u03C2",
            ["Invisible (short)"] = "\u0391\u03CC\u03C1.",
            ["It is the standard mode in ClawTweaks."] = "\u0395\u03AF\u03BD\u03B1\u03B9 \u03B7 \u03BA\u03B1\u03BD\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C3\u03C4\u03BF ClawTweaks.",
            ["It resets the charge limit, the fan and the controller first."] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03B9 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2, \u03C4\u03BF\u03BD \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["It starts with Windows through its scheduled task."] = "\u039E\u03B5\u03BA\u03B9\u03BD\u03AC \u03BC\u03B5 \u03C4\u03B1 Windows \u03BC\u03AD\u03C3\u03C9 \u03C4\u03B7\u03C2 \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7\u03C2 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1\u03C2 \u03C4\u03BF\u03C5.",
            ["It walks you through every step."] = "\u03A3\u03B1\u03C2 \u03BA\u03B1\u03B8\u03BF\u03B4\u03B7\u03B3\u03B5\u03AF \u03C3\u03B5 \u03BA\u03AC\u03B8\u03B5 \u03B2\u03AE\u03BC\u03B1.",
            ["It writes TDP, fan curve, LEDs, controller and the on-screen display."] = "\u0393\u03C1\u03AC\u03C6\u03B5\u03B9 TDP, \u03BA\u03B1\u03BC\u03C0\u03CD\u03BB\u03B7 \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1, LED, \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03B5\u03BC\u03C6\u03AC\u03BD\u03B9\u03C3\u03B7 \u03C3\u03C4\u03B7\u03BD \u03BF\u03B8\u03CC\u03BD\u03B7.",
            ["Keep everything"] = "\u0394\u03B9\u03B1\u03C4\u03AE\u03C1\u03B7\u03C3\u03B7 \u03CC\u03BB\u03C9\u03BD",
            ["Keeps your session in memory."] = "\u039A\u03C1\u03B1\u03C4\u03AC \u03C4\u03B7 \u03C3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1 \u03C3\u03B1\u03C2 \u03C3\u03C4\u03B7 \u03BC\u03BD\u03AE\u03BC\u03B7.",
            ["Keyboard"] = "\u03A0\u03BB\u03B7\u03BA\u03C4\u03C1\u03BF\u03BB\u03CC\u03B3\u03B9\u03BF",
            ["Language"] = "\u0393\u03BB\u03CE\u03C3\u03C3\u03B1",
            ["Last played"] = "\u03A4\u03B5\u03BB\u03B5\u03C5\u03C4\u03B1\u03AF\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9",
            ["Layout"] = "\u0394\u03B9\u03AC\u03C4\u03B1\u03BE\u03B7",
            ["Library quick menu"] = "\u0393\u03C1\u03AE\u03B3\u03BF\u03C1\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2",
            ["Leave the library open."] = "\u0391\u03C6\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 \u03B1\u03BD\u03BF\u03B9\u03C7\u03C4\u03AE.",
            ["Left stick"] = "\u0391\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03CC\u03C2 \u03BC\u03BF\u03C7\u03BB\u03CC\u03C2",
            ["Left trigger"] = "\u0391\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AE \u03C3\u03BA\u03B1\u03BD\u03B4\u03AC\u03BB\u03B7",
            ["Looking for pictures\u2026"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7 \u03B5\u03B9\u03BA\u03CC\u03BD\u03C9\u03BD\u2026",
            ["Move a tab with LB and RB."] = "\u039C\u03B5\u03C4\u03B1\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5 \u03BC\u03B9\u03B1 \u03BA\u03B1\u03C1\u03C4\u03AD\u03BB\u03B1 \u03BC\u03B5 LB \u03BA\u03B1\u03B9 RB.",
            ["None"] = "\u039A\u03B1\u03BC\u03AF\u03B1",
            ["Not set"] = "\u0394\u03B5\u03BD \u03BF\u03C1\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5",
            ["No background"] = "\u03A7\u03C9\u03C1\u03AF\u03C2 \u03C6\u03CC\u03BD\u03C4\u03BF",
            ["No JPG, PNG or BMP files in that folder."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03B1\u03C1\u03C7\u03B5\u03AF\u03B1 JPG, PNG \u03AE BMP \u03C3\u03B5 \u03B1\u03C5\u03C4\u03CC\u03BD \u03C4\u03BF\u03BD \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF.",
            ["Needs the mouse or the touchscreen"] = "\u03A7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03C0\u03BF\u03BD\u03C4\u03AF\u03BA\u03B9 \u03AE \u03BF\u03B8\u03CC\u03BD\u03B7 \u03B1\u03C6\u03AE\u03C2",
            ["No suggestions on this machine."] = "\u039A\u03B1\u03BC\u03AF\u03B1 \u03C0\u03C1\u03CC\u03C4\u03B1\u03C3\u03B7 \u03C3\u03B5 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03BC\u03B7\u03C7\u03AC\u03BD\u03B7\u03BC\u03B1.",
            ["No picked cover on this game"] = "\u0394\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03B5\u03C0\u03B9\u03BB\u03B5\u03B3\u03B5\u03AF \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03BF \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9",
            ["Nothing unlocked yet."] = "\u03A4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03BE\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03C4\u03BF \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Open release page"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2",
            ["Recent reflections"] = "\u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B5\u03C2 \u03C3\u03BA\u03AD\u03C8\u03B5\u03B9\u03C2",
            ["Set"] = "\u039F\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2",
            ["Remove background"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C6\u03CC\u03BD\u03C4\u03BF\u03C5",
            ["Setting the picture\u2026"] = "\u039F\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B1\u03C2\u2026",
            ["Pick a folder once. Sub-folders are included."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC. \u039F\u03B9 \u03C5\u03C0\u03BF\u03C6\u03AC\u03BA\u03B5\u03BB\u03BF\u03B9 \u03C0\u03B5\u03C1\u03B9\u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03BF\u03BD\u03C4\u03B1\u03B9.",
            ["Reset"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC",
            ["Reset cover"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5",
            ["Own image"] = "\u0394\u03B9\u03BA\u03AE \u03C3\u03B1\u03C2 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B1",
            ["Pick the folder your pictures are in"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C4\u03BF\u03BD \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF \u03BC\u03B5 \u03C4\u03B9\u03C2 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B5\u03C2 \u03C3\u03B1\u03C2",
            ["Show"] = "\u0395\u03BC\u03C6\u03AC\u03BD\u03B9\u03C3\u03B7",
            ["Shown"] = "\u039F\u03C1\u03B1\u03C4\u03AE",
            ["Steam games only"] = "\u039C\u03CC\u03BD\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 Steam",
            ["Steam has no list for this game"] = "\u03A4\u03BF Steam \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9",
            ["System tray / Processes"] = "\u03A0\u03B5\u03C1\u03B9\u03BF\u03C7\u03AE \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03B5\u03C9\u03BD / \u0394\u03B9\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B5\u03C2",
            ["This file does not install ClawTweaks Center"] = "\u0391\u03C5\u03C4\u03CC \u03C4\u03BF \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03B4\u03B5\u03BD \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC \u03C4\u03BF ClawTweaks Center",
            ["Use as background"] = "\u03A7\u03C1\u03AE\u03C3\u03B7 \u03C9\u03C2 \u03C6\u03CC\u03BD\u03C4\u03BF",
            ["Use this folder"] = "\u03A7\u03C1\u03AE\u03C3\u03B7 \u03B1\u03C5\u03C4\u03BF\u03CD \u03C4\u03BF\u03C5 \u03C6\u03B1\u03BA\u03AD\u03BB\u03BF\u03C5",
            ["View"] = "\u03A0\u03C1\u03BF\u03B2\u03BF\u03BB\u03AE",
            ["Where are your pictures?"] = "\u03A0\u03BF\u03CD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BF\u03B9 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B5\u03C2 \u03C3\u03B1\u03C2;",
            ["Use one of your own images\u2026"] = "\u03A7\u03C1\u03AE\u03C3\u03B7 \u03B4\u03B9\u03BA\u03AE\u03C2 \u03C3\u03B1\u03C2 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B1\u03C2\u2026",
            ["Windows tools"] = "\u0395\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03B1 Windows",
            ["Windows Explorer"] = "\u0395\u03BE\u03B5\u03C1\u03B5\u03CD\u03BD\u03B7\u03C3\u03B7 \u03C4\u03C9\u03BD Windows",
            ["Task Manager"] = "\u0394\u03B9\u03B1\u03C7\u03B5\u03AF\u03C1\u03B9\u03C3\u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03B9\u03CE\u03BD",
            ["Windows Settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 Windows",
            ["Control Panel (classic)"] = "\u03A0\u03AF\u03BD\u03B1\u03BA\u03B1\u03C2 \u0395\u03BB\u03AD\u03B3\u03C7\u03BF\u03C5 (\u03BA\u03BB\u03B1\u03C3\u03B9\u03BA\u03CC\u03C2)",
            ["Computer Management"] = "\u0394\u03B9\u03B1\u03C7\u03B5\u03AF\u03C1\u03B9\u03C3\u03B7 \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE",
            ["Installed apps"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B5\u03C2 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2",
            ["Use the library as the Windows full screen experience"] = "\u03A7\u03C1\u03AE\u03C3\u03B7 \u03C4\u03B7\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2 \u03C9\u03C2 \u03B5\u03BC\u03C0\u03B5\u03B9\u03C1\u03AF\u03B1 \u03C0\u03BB\u03AE\u03C1\u03BF\u03C5\u03C2 \u03BF\u03B8\u03CC\u03BD\u03B7\u03C2 \u03C4\u03C9\u03BD Windows",
            ["Download the ClawTweaks setup from the releases page."] = "\u039A\u03B1\u03C4\u03B5\u03B2\u03AC\u03C3\u03C4\u03B5 \u03C4\u03BF setup \u03C4\u03BF\u03C5 ClawTweaks \u03B1\u03C0\u03CC \u03C4\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03C9\u03BD.",
            ["Answer Yes when it asks about the full screen mode."] = "\u0391\u03C0\u03B1\u03BD\u03C4\u03AE\u03C3\u03C4\u03B5 \u039D\u03B1\u03B9 \u03CC\u03C4\u03B1\u03BD \u03C1\u03C9\u03C4\u03AE\u03C3\u03B5\u03B9 \u03B3\u03B9\u03B1 \u03C4\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C0\u03BB\u03AE\u03C1\u03BF\u03C5\u03C2 \u03BF\u03B8\u03CC\u03BD\u03B7\u03C2.",
            ["Open releases"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03C9\u03BD",
            ["Default browser"] = "\u03A0\u03C1\u03BF\u03B5\u03C0\u03B9\u03BB\u03B5\u03B3\u03BC\u03AD\u03BD\u03BF\u03C2 \u03C0\u03B5\u03C1\u03B9\u03B7\u03B3\u03B7\u03C4\u03AE\u03C2",
            ["Download CTW wallpapers"] = "\u039B\u03AE\u03C8\u03B7 \u03C4\u03B1\u03C0\u03B5\u03C4\u03C3\u03B1\u03C1\u03B9\u03CE\u03BD CTW",
            ["ClawTweaks wallpapers"] = "\u03A4\u03B1\u03C0\u03B5\u03C4\u03C3\u03B1\u03C1\u03AF\u03B5\u03C2 ClawTweaks",
            ["Downloaded when you pick one."] = "\u039A\u03B1\u03C4\u03B5\u03B2\u03B1\u03AF\u03BD\u03B5\u03B9 \u03CC\u03C4\u03B1\u03BD \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03B5\u03C4\u03B5 \u03BC\u03AF\u03B1.",
            ["Looking for wallpapers\u2026"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7 \u03C4\u03B1\u03C0\u03B5\u03C4\u03C3\u03B1\u03C1\u03B9\u03CE\u03BD\u2026",
            ["The wallpaper list could not be reached. Check your connection."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03B7 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03C4\u03B1\u03C0\u03B5\u03C4\u03C3\u03B1\u03C1\u03B9\u03CE\u03BD. \u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03B7 \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03AE \u03C3\u03B1\u03C2.",
            ["No wallpapers published yet."] = "\u0394\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD \u03B4\u03B7\u03BC\u03BF\u03C3\u03B9\u03B5\u03C5\u03C4\u03B5\u03AF \u03C4\u03B1\u03C0\u03B5\u03C4\u03C3\u03B1\u03C1\u03AF\u03B5\u03C2 \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Library Settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2",
            ["Library settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2",
            ["Loading the page\u2026"] = "\u03A6\u03CC\u03C1\u03C4\u03C9\u03C3\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1\u03C2\u2026",
            ["Loading\u2026"] = "\u03A6\u03CC\u03C1\u03C4\u03C9\u03C3\u03B7\u2026",
            ["MSI Center M and its Game Bar widget are back."] = "\u03A4\u03BF MSI Center M \u03BA\u03B1\u03B9 \u03C4\u03BF widget \u03C4\u03BF\u03C5 \u03C3\u03C4\u03BF Game Bar \u03B5\u03C0\u03AD\u03C3\u03C4\u03C1\u03B5\u03C8\u03B1\u03BD.",
            ["MSI Center M is back, but its Game Bar widget could not be restored. Reinstall MSI Center M to get the widget back."] = "\u03A4\u03BF MSI Center M \u03B5\u03C0\u03AD\u03C3\u03C4\u03C1\u03B5\u03C8\u03B5, \u03B1\u03BB\u03BB\u03AC \u03C4\u03BF widget \u03C4\u03BF\u03C5 \u03C3\u03C4\u03BF Game Bar \u03B4\u03B5\u03BD \u03B1\u03C0\u03BF\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03B8\u03B7\u03BA\u03B5. \u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03BF MSI Center M \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03AD\u03C8\u03B5\u03B9 \u03C4\u03BF widget.",
            ["MSI Center M is not installed on this device."] = "\u03A4\u03BF MSI Center M \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["Main versions"] = "\u039A\u03CD\u03C1\u03B9\u03B5\u03C2 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2",
            ["Manage your ClawTweaks settings \u2014 back them up, restore a previous backup, or reset everything to a clean state."] = "\u0394\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B5\u03AF\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C3\u03B1\u03C2 ClawTweaks \u2014 \u03BA\u03C1\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF, \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03AD\u03BD\u03B1 \u03C0\u03C1\u03BF\u03B7\u03B3\u03BF\u03CD\u03BC\u03B5\u03BD\u03BF \u03AE \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03AC\u03BD\u03C4\u03B1 \u03C3\u03B5 \u03BA\u03B1\u03B8\u03B1\u03C1\u03AE \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["Menu"] = "\u039C\u03B5\u03BD\u03BF\u03CD",
            ["Minimize"] = "\u0395\u03BB\u03B1\u03C7\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7",
            ["Minimize Center"] = "\u0395\u03BB\u03B1\u03C7\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03C4\u03BF\u03C5 Center",
            ["Mode: Fresh install"] = "\u039B\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1: \u039D\u03AD\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Mode: Update"] = "\u039B\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1: \u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7",
            ["Mouse"] = "\u03A0\u03BF\u03BD\u03C4\u03AF\u03BA\u03B9",
            ["My Apps"] = "\u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2",
            ["NOT detected (VID_0DB0). The controller is missing, or MSI Center M has taken it over."] = "\u0394\u0395\u039D \u03B5\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 (VID_0DB0). \u039B\u03B5\u03AF\u03C0\u03B5\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03AE \u03C4\u03BF \u03AD\u03C7\u03B5\u03B9 \u03C0\u03AC\u03C1\u03B5\u03B9 \u03C4\u03BF MSI Center M.",
            ["New update \u2014 background helper started"] = "\u039D\u03AD\u03B1 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 \u2014 \u03BF helper \u03BE\u03B5\u03BA\u03AF\u03BD\u03B7\u03C3\u03B5 \u03C3\u03C4\u03BF \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03AE\u03BD\u03B9\u03BF",
            ["Newer than installed"] = "\u039D\u03B5\u03CC\u03C4\u03B5\u03C1\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["Next: controller health, required tools, the signing certificate, then the app itself. Each step re-checks live and won't let you continue until it's satisfied."] = "\u03A3\u03C4\u03B7 \u03C3\u03C5\u03BD\u03AD\u03C7\u03B5\u03B9\u03B1: \u03C5\u03B3\u03B5\u03AF\u03B1 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5, \u03B1\u03C0\u03B1\u03B9\u03C4\u03BF\u03CD\u03BC\u03B5\u03BD\u03B1 \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03B1, \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03B7 \u03AF\u03B4\u03B9\u03B1 \u03B7 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE. \u039A\u03AC\u03B8\u03B5 \u03B2\u03AE\u03BC\u03B1 \u03B5\u03BB\u03AD\u03B3\u03C7\u03B5\u03B9 \u03BE\u03B1\u03BD\u03AC \u03B6\u03C9\u03BD\u03C4\u03B1\u03BD\u03AC \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BD \u03C3\u03B1\u03C2 \u03B1\u03C6\u03AE\u03BD\u03B5\u03B9 \u03BD\u03B1 \u03C3\u03C5\u03BD\u03B5\u03C7\u03AF\u03C3\u03B5\u03C4\u03B5 \u03C0\u03C1\u03B9\u03BD \u03B9\u03BA\u03B1\u03BD\u03BF\u03C0\u03BF\u03B9\u03B7\u03B8\u03B5\u03AF.",
            ["No .cer bundled with this setup build (dev run)."] = "\u0394\u03B5\u03BD \u03C0\u03B5\u03C1\u03B9\u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03B5\u03C4\u03B1\u03B9 .cer \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 setup (\u03B4\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AE \u03B5\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7).",
            ["No .msix bundled with this setup build (dev run)."] = "\u0394\u03B5\u03BD \u03C0\u03B5\u03C1\u03B9\u03BB\u03B1\u03BC\u03B2\u03AC\u03BD\u03B5\u03C4\u03B1\u03B9 .msix \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 setup (\u03B4\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AE \u03B5\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7).",
            ["No Epic games installed."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 Epic.",
            ["No ROM has been played yet."] = "\u0394\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03C0\u03B1\u03B9\u03C7\u03C4\u03B5\u03AF \u03B1\u03BA\u03CC\u03BC\u03B7 \u03BA\u03B1\u03BD\u03AD\u03BD\u03B1 ROM.",
            ["No ROMs in your Playnite library."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD ROM \u03C3\u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 Playnite.",
            ["No Steam games installed."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 Steam.",
            ["No Steam library found on this device."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 Steam \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["No Xbox games installed."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 Xbox.",
            ["No apps added yet."] = "\u039A\u03B1\u03BC\u03AF\u03B1 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["No backup selected"] = "\u0394\u03B5\u03BD \u03B5\u03C0\u03B9\u03BB\u03AD\u03C7\u03B8\u03B7\u03BA\u03B5 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF",
            ["No backups found"] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B1\u03BD \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03B1",
            ["No duplicate helper detected"] = "\u0394\u03B5\u03BD \u03B5\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B4\u03B9\u03C0\u03BB\u03CC\u03C2 helper",
            ["No existing ClawTweaks installation was found. The setup will guide you through the full first-time installation."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03C3\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 ClawTweaks. \u03A4\u03BF setup \u03B8\u03B1 \u03C3\u03B1\u03C2 \u03BF\u03B4\u03B7\u03B3\u03AE\u03C3\u03B5\u03B9 \u03C3\u03C4\u03B7\u03BD \u03C0\u03BB\u03AE\u03C1\u03B7 \u03C0\u03C1\u03CE\u03C4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["No favorites yet."] = "\u039A\u03B1\u03BD\u03AD\u03BD\u03B1 \u03B1\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03BF \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["No game has been played yet."] = "\u0394\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03C0\u03B1\u03B9\u03C7\u03C4\u03B5\u03AF \u03B1\u03BA\u03CC\u03BC\u03B7 \u03BA\u03B1\u03BD\u03AD\u03BD\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9.",
            ["No games found."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B1\u03BD \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1.",
            ["No games from these stores installed."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03AC \u03C4\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1.",
            ["No installable package found after staging."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03C0\u03C1\u03BF\u03C2 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03C0\u03C1\u03BF\u03B5\u03C4\u03BF\u03B9\u03BC\u03B1\u03C3\u03AF\u03B1.",
            ["No portrait covers found for that search."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B1\u03BD \u03BA\u03AC\u03B8\u03B5\u03C4\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03B1\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7.",
            ["No restart necessary."] = "\u0394\u03B5\u03BD \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7.",
            ["No uninstaller found for the older version."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C0\u03C1\u03CC\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2 \u03B3\u03B9\u03B1 \u03C4\u03B7\u03BD \u03C0\u03B1\u03BB\u03B9\u03CC\u03C4\u03B5\u03C1\u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7.",
            ["No virtual pad detected \u2014 rolled back to the hardware controller."] = "\u0394\u03B5\u03BD \u03B5\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u2014 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03BF\u03C6\u03AE \u03C3\u03C4\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["No. The library runs on its own, without the Game Bar."] = "\u038C\u03C7\u03B9. \u0397 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03B5\u03AF \u03BC\u03CC\u03BD\u03B7 \u03C4\u03B7\u03C2, \u03C7\u03C9\u03C1\u03AF\u03C2 \u03C4\u03BF Game Bar.",
            ["Not Installed"] = "\u039C\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Not a recognized backup"] = "\u039C\u03B7 \u03B1\u03BD\u03B1\u03B3\u03BD\u03C9\u03C1\u03B9\u03C3\u03BC\u03AD\u03BD\u03BF \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF",
            ["Not checked yet."] = "\u0394\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03B5\u03BB\u03B5\u03B3\u03C7\u03B8\u03B5\u03AF \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Not in the bar yet \u2014 favorite ClawTweaks in the Game Bar (Win+G), then Check."] = "\u0394\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03C3\u03C4\u03B7 \u03BC\u03C0\u03AC\u03C1\u03B1 \u2014 \u03BA\u03AC\u03BD\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03B1\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03BF \u03C3\u03C4\u03BF Game Bar (Win+G) \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2.",
            ["Not installed"] = "\u039C\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Not mounted right now. Expected only while virtual mode is running \u2014 normal at setup time."] = "\u0394\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C3\u03C5\u03BD\u03B4\u03B5\u03B4\u03B5\u03BC\u03AD\u03BD\u03BF \u03C4\u03CE\u03C1\u03B1. \u0391\u03BD\u03B1\u03BC\u03AD\u03BD\u03B5\u03C4\u03B1\u03B9 \u03BC\u03CC\u03BD\u03BF \u03CC\u03C3\u03BF \u03C4\u03C1\u03AD\u03C7\u03B5\u03B9 \u03B7 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u2014 \u03C6\u03C5\u03C3\u03B9\u03BF\u03BB\u03BF\u03B3\u03B9\u03BA\u03CC \u03BA\u03B1\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["Not now"] = "\u038C\u03C7\u03B9 \u03C4\u03CE\u03C1\u03B1",
            ["Not present (good)."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 (\u03BA\u03B1\u03BB\u03CC).",
            ["Not running (good)."] = "\u0394\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 (\u03BA\u03B1\u03BB\u03CC).",
            ["Not running yet \u2014 starts after install via the Game Bar."] = "\u0394\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u2014 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03BC\u03AD\u03C3\u03C9 \u03C4\u03BF\u03C5 Game Bar.",
            ["Not set."] = "\u0394\u03B5\u03BD \u03BF\u03C1\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5.",
            ["Not supported on this device"] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03BF\u03C3\u03C4\u03B7\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE",
            ["Not trusted yet \u2014 will be trusted during install."] = "\u0394\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03AD\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF \u2014 \u03B8\u03B1 \u03B3\u03AF\u03BD\u03B5\u03B9 \u03AD\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF \u03BA\u03B1\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["Nothing found"] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1",
            ["Nothing found to add."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03B3\u03B9\u03B1 \u03C0\u03C1\u03BF\u03C3\u03B8\u03AE\u03BA\u03B7.",
            ["Nothing found yet."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Off"] = "\u0391\u03BD\u03B5\u03BD\u03B5\u03C1\u03B3\u03CC",
            ["Older than installed"] = "\u03A0\u03B1\u03BB\u03B9\u03CC\u03C4\u03B5\u03C1\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["On"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03CC",
            ["Onboarding lists it as a to-do the first time you install ClawTweaks."] = "\u0397 \u03B1\u03C1\u03C7\u03B9\u03BA\u03AE \u03C1\u03CD\u03B8\u03BC\u03B9\u03C3\u03B7 \u03C4\u03BF \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03B9 \u03C9\u03C2 \u03B5\u03BA\u03BA\u03C1\u03B5\u03BC\u03CC\u03C4\u03B7\u03C4\u03B1 \u03C4\u03B7\u03BD \u03C0\u03C1\u03CE\u03C4\u03B7 \u03C6\u03BF\u03C1\u03AC \u03C0\u03BF\u03C5 \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC\u03C4\u03B5 \u03C4\u03BF ClawTweaks.",
            ["Once, at the first install, to register its background task."] = "\u039C\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC, \u03C3\u03C4\u03B7\u03BD \u03C0\u03C1\u03CE\u03C4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7, \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B4\u03B7\u03BB\u03C9\u03B8\u03B5\u03AF \u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03B7\u03BD\u03AF\u03BF\u03C5 \u03C4\u03BF\u03C5.",
            ["One click in the widget or in Center brings Center M back."] = "\u0388\u03BD\u03B1 \u03BA\u03BB\u03B9\u03BA \u03C3\u03C4\u03BF widget \u03AE \u03C3\u03C4\u03BF Center \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03B9 \u03C4\u03BF Center M.",
            ["Only Steam is supported for now."] = "\u03A0\u03C1\u03BF\u03C2 \u03C4\u03BF \u03C0\u03B1\u03C1\u03CC\u03BD \u03C5\u03C0\u03BF\u03C3\u03C4\u03B7\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF Steam.",
            ["Only for apps you added yourself"] = "\u039C\u03CC\u03BD\u03BF \u03B3\u03B9\u03B1 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03C0\u03BF\u03C5 \u03C0\u03C1\u03BF\u03C3\u03B8\u03AD\u03C3\u03B1\u03C4\u03B5 \u03B5\u03C3\u03B5\u03AF\u03C2",
            ["Only the ClawTweaks widget lives in the Game Bar."] = "\u039C\u03CC\u03BD\u03BF \u03C4\u03BF widget \u03C4\u03BF\u03C5 ClawTweaks \u03B2\u03C1\u03AF\u03C3\u03BA\u03B5\u03C4\u03B1\u03B9 \u03C3\u03C4\u03BF Game Bar.",
            ["Open"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1",
            ["Open OptiClick"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 OptiClick",
            ["Open Reset \u00B7 Backup \u00B7 Restore on the start screen."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u00B7 \u0391\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u00B7 \u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5 \u03C3\u03C4\u03B7\u03BD \u03B1\u03C1\u03C7\u03B9\u03BA\u03AE \u03BF\u03B8\u03CC\u03BD\u03B7.",
            ["Open Steam"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 Steam",
            ["Open SteamGridDB"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 SteamGridDB",
            ["Open Windows Settings, go to Apps, find \"ClawTweaks Center\" and uninstall it, then press Re-check."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C4\u03C9\u03BD Windows, \u03C0\u03B7\u03B3\u03B1\u03AF\u03BD\u03B5\u03C4\u03B5 \u03C3\u03C4\u03B9\u03C2 \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2, \u03B2\u03C1\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF \"ClawTweaks Center\" \u03BA\u03B1\u03B9 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF, \u03BC\u03B5\u03C4\u03AC \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u0395\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2.",
            ["Open all"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03CC\u03BB\u03C9\u03BD",
            ["Open download page"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1\u03C2 \u03BB\u03AE\u03C8\u03B7\u03C2",
            ["ClawTweaks is not running"] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9",
            ["Install ClawTweaks with the Setup to get versions here."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03BC\u03B5 \u03C4\u03BF Setup \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B5\u03BC\u03C6\u03B1\u03BD\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03B5\u03B4\u03CE \u03BF\u03B9 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2.",
            ["Get the Setup"] = "\u039B\u03AE\u03C8\u03B7 \u03C4\u03BF\u03C5 Setup",
            ["Open download pages"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C3\u03B5\u03BB\u03AF\u03B4\u03C9\u03BD \u03BB\u03AE\u03C8\u03B7\u03C2",
            ["Open in browser"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C3\u03C4\u03BF\u03BD \u03C0\u03B5\u03C1\u03B9\u03B7\u03B3\u03B7\u03C4\u03AE",
            ["Open the Game Bar (Win+G) once to start it, then press \u24CE. You can still uninstall Center."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC \u03C4\u03BF Game Bar (Win+G) \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24CE. \u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03BD\u03B1 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03B5\u03C4\u03B5 \u03C4\u03BF Center.",
            ["Open the Game Bar (Win+G), favorite ClawTweaks, then Check."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03BF Game Bar (Win+G), \u03BA\u03AC\u03BD\u03C4\u03B5 \u03B1\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03BF \u03C4\u03BF ClawTweaks \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2.",
            ["Open the Game Bar manually (Win+G)."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03BF Game Bar \u03C7\u03B5\u03B9\u03C1\u03BF\u03BA\u03AF\u03BD\u03B7\u03C4\u03B1 (Win+G).",
            ["Open the Game Bar once if it is not running."] = "\u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC \u03C4\u03BF Game Bar \u03B1\u03BD \u03B4\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9.",
            ["Opening Game Bar \u2014 the ClawTweaks widget will start the helper\u2026"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 Game Bar \u2014 \u03C4\u03BF widget \u03C4\u03BF\u03C5 ClawTweaks \u03B8\u03B1 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9 \u03C4\u03BF\u03BD helper\u2026",
            ["OptiScaler wiki"] = "Wiki \u03C4\u03BF\u03C5 OptiScaler",
            ["Other Stores"] = "\u0386\u03BB\u03BB\u03B1 \u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1",
            ["Output"] = "\u0388\u03BE\u03BF\u03B4\u03BF\u03C2",
            ["P-core EPP"] = "EPP P-core",
            ["P-core max"] = "\u039C\u03AD\u03B3\u03B9\u03C3\u03C4\u03BF P-core",
            ["P-core state"] = "\u039A\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 P-core",
            ["Package installed."] = "\u03A4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03B8\u03B7\u03BA\u03B5.",
            ["Performance"] = "\u0395\u03C0\u03B9\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2",
            ["Physical MSI Claw controller"] = "\u03A6\u03C5\u03C3\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF MSI Claw",
            ["Pick a backup to restore. A safety copy of the current state is taken automatically first, then the helper restarts to load the restored settings."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC. \u03A0\u03C1\u03CE\u03C4\u03B1 \u03BA\u03C1\u03B1\u03C4\u03B9\u03AD\u03C4\u03B1\u03B9 \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B1 \u03B5\u03C6\u03B5\u03B4\u03C1\u03B9\u03BA\u03CC \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C4\u03B7\u03C2 \u03C4\u03C1\u03AD\u03C7\u03BF\u03C5\u03C3\u03B1\u03C2 \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03BF helper \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03B5\u03AF \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C6\u03BF\u03C1\u03C4\u03CE\u03C3\u03B5\u03B9 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2.",
            ["Platform"] = "\u03A0\u03BB\u03B1\u03C4\u03C6\u03CC\u03C1\u03BC\u03B1",
            ["Play"] = "\u03A0\u03B1\u03AF\u03BE\u03C4\u03B5",
            ["Play your Steam, Epic and Xbox games."] = "\u03A0\u03B1\u03AF\u03BE\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03C3\u03B1\u03C2 \u03B1\u03C0\u03CC Steam, Epic \u03BA\u03B1\u03B9 Xbox.",
            ["Playnite is not installed."] = "\u03A4\u03BF Playnite \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF.",
            ["Portrait covers only. No match? Edit the text above and search again."] = "\u039C\u03CC\u03BD\u03BF \u03BA\u03AC\u03B8\u03B5\u03C4\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1. \u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5; \u0391\u03BB\u03BB\u03AC\u03BE\u03C4\u03B5 \u03C4\u03BF \u03BA\u03B5\u03AF\u03BC\u03B5\u03BD\u03BF \u03C0\u03B9\u03BF \u03C0\u03AC\u03BD\u03C9 \u03BA\u03B1\u03B9 \u03C8\u03AC\u03BE\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC.",
            ["Preparing your library\u2026"] = "\u03A0\u03C1\u03BF\u03B5\u03C4\u03BF\u03B9\u03BC\u03B1\u03C3\u03AF\u03B1 \u03C4\u03B7\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2 \u03C3\u03B1\u03C2\u2026",
            ["Preparing\u2026"] = "\u03A0\u03C1\u03BF\u03B5\u03C4\u03BF\u03B9\u03BC\u03B1\u03C3\u03AF\u03B1\u2026",
            ["Present \u2014 a common double-input source. Check Steam Input if you see doubled inputs."] = "\u03A5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u2014 \u03C3\u03C5\u03BD\u03B7\u03B8\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7 \u03C0\u03B7\u03B3\u03AE \u03B4\u03B9\u03C0\u03BB\u03AE\u03C2 \u03B5\u03B9\u03C3\u03CC\u03B4\u03BF\u03C5. \u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03BF Steam Input \u03B1\u03BD \u03B2\u03BB\u03AD\u03C0\u03B5\u03C4\u03B5 \u03B4\u03B9\u03C0\u03BB\u03AD\u03C2 \u03B5\u03B9\u03C3\u03CC\u03B4\u03BF\u03C5\u03C2.",
            ["Preserve Aspect Ratio"] = "\u0394\u03B9\u03B1\u03C4\u03AE\u03C1\u03B7\u03C3\u03B7 \u03B1\u03BD\u03B1\u03BB\u03BF\u03B3\u03B9\u03CE\u03BD",
            ["Preset"] = "\u03A0\u03C1\u03BF\u03B5\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE",
            ["Press \u24B6 on a question to open it."] = "\u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24B6 \u03C3\u03B5 \u03BC\u03B9\u03B1 \u03B5\u03C1\u03CE\u03C4\u03B7\u03C3\u03B7 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C4\u03B7\u03BD \u03B1\u03BD\u03BF\u03AF\u03BE\u03B5\u03C4\u03B5.",
            ["Press \u24B6 to install ClawTweaks."] = "\u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24B6 \u03B3\u03B9\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks.",
            ["Press \u24B6 to open the download pages for the missing tools, install them, then press \u24CE to re-check."] = "\u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24B6 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03B1\u03BD\u03BF\u03AF\u03BE\u03BF\u03C5\u03BD \u03BF\u03B9 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B5\u03C2 \u03BB\u03AE\u03C8\u03B7\u03C2 \u03C4\u03C9\u03BD \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03C9\u03BD \u03C0\u03BF\u03C5 \u03BB\u03B5\u03AF\u03C0\u03BF\u03C5\u03BD, \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B1 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24CE \u03B3\u03B9\u03B1 \u03B5\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF.",
            ["Preview versions for trying upcoming changes"] = "\u0395\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2 \u03C0\u03C1\u03BF\u03B5\u03C0\u03B9\u03C3\u03BA\u03CC\u03C0\u03B7\u03C3\u03B7\u03C2 \u03B3\u03B9\u03B1 \u03B4\u03BF\u03BA\u03B9\u03BC\u03AE \u03B5\u03C0\u03B5\u03C1\u03C7\u03CC\u03BC\u03B5\u03BD\u03C9\u03BD \u03B1\u03BB\u03BB\u03B1\u03B3\u03CE\u03BD",
            ["Probing controller topology"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03BF\u03C0\u03BF\u03BB\u03BF\u03B3\u03AF\u03B1\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["Puts the charge limit, the fan and the controller back."] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03B9 \u03C4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2, \u03C4\u03BF\u03BD \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["REBOOT REQUIRED"] = "\u0391\u03A0\u0391\u0399\u03A4\u0395\u0399\u03A4\u0391\u0399 \u0395\u03A0\u0391\u039D\u0395\u039A\u039A\u0399\u039D\u0397\u03A3\u0397",
            ["Re-check"] = "\u0395\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2",
            ["Re-enables MSI's tasks, service and Game Bar widget."] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF \u03BE\u03B1\u03BD\u03AC \u03C4\u03B9\u03C2 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B5\u03C2, \u03C4\u03B7\u03BD \u03C5\u03C0\u03B7\u03C1\u03B5\u03C3\u03AF\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03BF widget \u03C4\u03B7\u03C2 MSI.",
            ["Reading installed apps\u2026"] = "\u0391\u03BD\u03AC\u03B3\u03BD\u03C9\u03C3\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03C9\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03CE\u03BD\u2026",
            ["Recent"] = "\u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1",
            ["Recommendation"] = "\u03A3\u03CD\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Recommended for everyday use"] = "\u03A3\u03C5\u03BD\u03B9\u03C3\u03C4\u03AC\u03C4\u03B1\u03B9 \u03B3\u03B9\u03B1 \u03BA\u03B1\u03B8\u03B7\u03BC\u03B5\u03C1\u03B9\u03BD\u03AE \u03C7\u03C1\u03AE\u03C3\u03B7",
            ["Refresh"] = "\u0391\u03BD\u03B1\u03BD\u03AD\u03C9\u03C3\u03B7",
            ["Refresh rate"] = "\u03A1\u03C5\u03B8\u03BC\u03CC\u03C2 \u03B1\u03BD\u03B1\u03BD\u03AD\u03C9\u03C3\u03B7\u03C2",
            ["Refresh status"] = "\u0391\u03BD\u03B1\u03BD\u03AD\u03C9\u03C3\u03B7 \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2",
            ["Relaunching from install location..."] = "\u0395\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B7 \u03B8\u03AD\u03C3\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2...",
            ["Remove from Favorites"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B1 \u03B1\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03B1",
            ["Remove from library"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7",
            ["Remove the old version"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C4\u03B7\u03C2 \u03C0\u03B1\u03BB\u03B9\u03AC\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2",
            ["Removes the app, its background helper and its scheduled task."] = "\u0391\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE, \u03C4\u03BF\u03BD helper \u03C4\u03B7\u03C2 \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03C4\u03B7\u03C2.",
            ["Removes this app and closes it."] = "\u0391\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE \u03BA\u03B1\u03B9 \u03C4\u03B7\u03BD \u03BA\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9.",
            ["Removing Center\u2026"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C4\u03BF\u03C5 Center\u2026",
            ["Removing ClawTweaks\u2026"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks\u2026",
            ["Removing leftover helper\u2026"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C5\u03C0\u03BF\u03BB\u03B5\u03B9\u03C0\u03CC\u03BC\u03B5\u03BD\u03BF\u03C5 helper\u2026",
            ["Renaming looks for new cover art."] = "\u0397 \u03BC\u03B5\u03C4\u03BF\u03BD\u03BF\u03BC\u03B1\u03C3\u03AF\u03B1 \u03C8\u03AC\u03C7\u03BD\u03B5\u03B9 \u03B3\u03B9\u03B1 \u03BD\u03AD\u03BF \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03BF.",
            ["Required tools"] = "\u0391\u03C0\u03B1\u03B9\u03C4\u03BF\u03CD\u03BC\u03B5\u03BD\u03B1 \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03B1",
            ["Required tools (HidHide, RTSS, usbip, PawnIO) already installed."] = "\u03A4\u03B1 \u03B1\u03C0\u03B1\u03B9\u03C4\u03BF\u03CD\u03BC\u03B5\u03BD\u03B1 \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03B1 (HidHide, RTSS, usbip, PawnIO) \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AE\u03B4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B1.",
            ["Requirements"] = "\u0391\u03C0\u03B1\u03B9\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2",
            ["Rescan"] = "\u039D\u03AD\u03B1 \u03C3\u03AC\u03C1\u03C9\u03C3\u03B7",
            ["Reset complete"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["Reset failed"] = "\u0397 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5",
            ["Reset the app, or back up your profiles."] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE \u03AE \u03BA\u03C1\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C4\u03C9\u03BD \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03C3\u03B1\u03C2.",
            ["Resetting all ClawTweaks settings\u2026"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03CC\u03BB\u03C9\u03BD \u03C4\u03C9\u03BD \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03C9\u03BD ClawTweaks\u2026",
            ["Resolution"] = "\u0391\u03BD\u03AC\u03BB\u03C5\u03C3\u03B7",
            ["Restart"] = "\u0395\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["Restore"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC",
            ["Restore Backup"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5",
            ["Restore Backup takes a safety copy before it writes."] = "\u0397 \u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5 \u03BA\u03C1\u03B1\u03C4\u03AC \u03B5\u03C6\u03B5\u03B4\u03C1\u03B9\u03BA\u03CC \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C0\u03C1\u03B9\u03BD \u03B3\u03C1\u03AC\u03C8\u03B5\u03B9.",
            ["Restore complete"] = "\u0397 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["Restore failed"] = "\u0397 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5",
            ["Restore the device"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03C4\u03B7\u03C2 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE\u03C2",
            ["Restore the device and remove everything."] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03BA\u03B1\u03B9 \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03C3\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03AC\u03BD\u03C4\u03B1.",
            ["Restore the device first"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE",
            ["Restore this backup?"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03C5\u03C4\u03BF\u03CD \u03C4\u03BF\u03C5 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5;",
            ["Restoring the hardware\u2026"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03C4\u03BF\u03C5 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD\u2026",
            ["Retro scaling"] = "Retro \u03BA\u03BB\u03B9\u03BC\u03AC\u03BA\u03C9\u03C3\u03B7",
            ["Right stick"] = "\u0394\u03B5\u03BE\u03B9\u03CC\u03C2 \u03BC\u03BF\u03C7\u03BB\u03CC\u03C2",
            ["Right stick actions"] = "\u0395\u03BD\u03AD\u03C1\u03B3\u03B5\u03B9\u03B5\u03C2 \u03B4\u03B5\u03BE\u03B9\u03BF\u03CD \u03BC\u03BF\u03C7\u03BB\u03BF\u03CD",
            ["Right stick: right jumps to the end, left to the start"] = "\u0394\u03B5\u03BE\u03B9\u03CC\u03C2 \u03BC\u03BF\u03C7\u03BB\u03CC\u03C2: \u03B4\u03B5\u03BE\u03B9\u03AC \u03C0\u03AC\u03B5\u03B9 \u03C3\u03C4\u03BF \u03C4\u03AD\u03BB\u03BF\u03C2, \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC \u03C3\u03C4\u03B7\u03BD \u03B1\u03C1\u03C7\u03AE",
            ["Right trigger"] = "\u0394\u03B5\u03BE\u03B9\u03AC \u03C3\u03BA\u03B1\u03BD\u03B4\u03AC\u03BB\u03B7",
            ["Route"] = "\u0394\u03B9\u03B1\u03B4\u03C1\u03BF\u03BC\u03AE",
            ["Run"] = "\u0395\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7",
            ["Run in background"] = "\u0395\u03BA\u03C4\u03AD\u03BB\u03B5\u03C3\u03B7 \u03C3\u03C4\u03BF \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03AE\u03BD\u03B9\u03BF",
            ["Running \u2014 it can fight ClawTweaks for the controller and LED. You'll be guided to deactivate it after the app is installed."] = "\u0395\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u2014 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B4\u03B9\u03B5\u03BA\u03B4\u03B9\u03BA\u03AE\u03C3\u03B5\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03C4\u03BF LED \u03B1\u03C0\u03CC \u03C4\u03BF ClawTweaks. \u0398\u03B1 \u03BA\u03B1\u03B8\u03BF\u03B4\u03B7\u03B3\u03B7\u03B8\u03B5\u03AF\u03C4\u03B5 \u03BD\u03B1 \u03C4\u03BF \u03B1\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03B5\u03C4\u03B5 \u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["Running. Press \u24B6 to close it now. For a permanent fix, uninstall it from Windows Settings \u203A Apps and reinstall the latest version if you still need it."] = "\u0395\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9. \u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24B6 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BA\u03BB\u03B5\u03AF\u03C3\u03B5\u03B9 \u03C4\u03CE\u03C1\u03B1. \u0393\u03B9\u03B1 \u03BC\u03CC\u03BD\u03B9\u03BC\u03B7 \u03BB\u03CD\u03C3\u03B7 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C0\u03CC \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 Windows \u203A \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03BA\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03B7 \u03BD\u03B5\u03CC\u03C4\u03B5\u03C1\u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B1\u03BD \u03C4\u03BF \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C3\u03C4\u03B5.",
            ["Save"] = "\u0391\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03B7",
            ["Saves all your profiles and settings into a single ZIP. The Game Bar is briefly closed so the widget's data can be copied \u2014 reopen it (Win+G) afterwards."] = "\u0391\u03C0\u03BF\u03B8\u03B7\u03BA\u03B5\u03CD\u03B5\u03B9 \u03CC\u03BB\u03B1 \u03C4\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03BA\u03B1\u03B9 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C3\u03B1\u03C2 \u03C3\u03B5 \u03AD\u03BD\u03B1 ZIP. \u03A4\u03BF Game Bar \u03BA\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9 \u03B3\u03B9\u03B1 \u03BB\u03AF\u03B3\u03BF \u03CE\u03C3\u03C4\u03B5 \u03BD\u03B1 \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03B1\u03C6\u03BF\u03CD\u03BD \u03C4\u03B1 \u03B4\u03B5\u03B4\u03BF\u03BC\u03AD\u03BD\u03B1 \u03C4\u03BF\u03C5 widget \u2014 \u03B1\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03BF \u03BE\u03B1\u03BD\u03AC (Win+G) \u03BC\u03B5\u03C4\u03AC.",
            ["Saves your session to disk."] = "\u0391\u03C0\u03BF\u03B8\u03B7\u03BA\u03B5\u03CD\u03B5\u03B9 \u03C4\u03B7 \u03C3\u03C5\u03BD\u03B5\u03B4\u03C1\u03AF\u03B1 \u03C3\u03B1\u03C2 \u03C3\u03C4\u03BF\u03BD \u03B4\u03AF\u03C3\u03BA\u03BF.",
            ["Search"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7",
            ["Search SteamGridDB for a different cover"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7 \u03AC\u03BB\u03BB\u03BF\u03C5 \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5 \u03C3\u03C4\u03BF SteamGridDB",
            ["Searching\u2026"] = "\u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7\u2026",
            ["Select"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AE",
            ["Set a SteamGridDB key in Settings first"] = "\u039F\u03C1\u03AF\u03C3\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03BA\u03BB\u03B5\u03B9\u03B4\u03AF SteamGridDB \u03C3\u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2",
            ["Set as cover"] = "\u039F\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 \u03C9\u03C2 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03BF",
            ["Set the library as the screen Center opens on in Library Settings."] = "\u039F\u03C1\u03AF\u03C3\u03C4\u03B5 \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 \u03C9\u03C2 \u03BF\u03B8\u03CC\u03BD\u03B7 \u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7\u03C2 \u03C4\u03BF\u03C5 Center \u03C3\u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2.",
            ["Set up Center M, controller and Game Bar."] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03C4\u03B5 \u03C4\u03BF Center M, \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03C4\u03BF Game Bar.",
            ["Set your status"] = "\u039F\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2",
            ["Set. Covers are downloaded for games with none."] = "\u039F\u03C1\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5. \u039A\u03B1\u03C4\u03B5\u03B2\u03B1\u03AF\u03BD\u03BF\u03C5\u03BD \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03B3\u03B9\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03C0\u03BF\u03C5 \u03B4\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD.",
            ["Setting cover\u2026"] = "\u039F\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 \u03B5\u03BE\u03C9\u03C6\u03CD\u03BB\u03BB\u03BF\u03C5\u2026",
            ["Settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2",
            ["Settings reset."] = "\u039F\u03B9 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03B5\u03C0\u03B1\u03BD\u03AE\u03BB\u03B8\u03B1\u03BD.",
            ["Show the certificate in Explorer"] = "\u0395\u03BC\u03C6\u03AC\u03BD\u03B9\u03C3\u03B7 \u03C4\u03BF\u03C5 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03BF\u03CD \u03C3\u03C4\u03B7\u03BD \u0395\u03BE\u03B5\u03C1\u03B5\u03CD\u03BD\u03B7\u03C3\u03B7",
            ["Shows your installed Steam, Xbox and Epic games."] = "\u0394\u03B5\u03AF\u03C7\u03BD\u03B5\u03B9 \u03C4\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03C3\u03B1\u03C2 \u03B1\u03C0\u03CC Steam, Xbox \u03BA\u03B1\u03B9 Epic.",
            ["Shut down"] = "\u03A4\u03B5\u03C1\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03CC\u03C2",
            ["Signing certificate"] = "\u03A0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2",
            ["Some hardware commands could not be sent."] = "\u039A\u03AC\u03C0\u03BF\u03B9\u03B5\u03C2 \u03B5\u03BD\u03C4\u03BF\u03BB\u03AD\u03C2 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD \u03B4\u03B5\u03BD \u03C3\u03C4\u03AC\u03BB\u03B8\u03B7\u03BA\u03B1\u03BD.",
            ["Square ROM art"] = "\u03A4\u03B5\u03C4\u03C1\u03AC\u03B3\u03C9\u03BD\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 ROM",
            ["Start"] = "\u0388\u03BD\u03B1\u03C1\u03BE\u03B7",
            ["Start Center with ClawTweaks"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03C4\u03BF\u03C5 Center \u03BC\u03B5 \u03C4\u03BF ClawTweaks",
            ["Start in the library"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03C3\u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7",
            ["Start menu, desktop and startup"] = "\u0388\u03BD\u03B1\u03C1\u03BE\u03B7, \u03B5\u03C0\u03B9\u03C6\u03AC\u03BD\u03B5\u03B9\u03B1 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1\u03C2, \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B7 \u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["Started from Windows"] = "\u039E\u03B5\u03BA\u03AF\u03BD\u03B7\u03C3\u03B5 \u03B1\u03C0\u03CC \u03C4\u03B1 Windows",
            ["Starting\u2026"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7\u2026",
            ["Stay open"] = "\u03A0\u03B1\u03C1\u03B1\u03BC\u03BF\u03BD\u03AE",
            ["Steam Xbox filter driver"] = "\u039F\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C6\u03AF\u03BB\u03C4\u03C1\u03BF\u03C5 Xbox \u03C4\u03BF\u03C5 Steam",
            ["Steam asks you where to put it."] = "\u03A4\u03BF Steam \u03C3\u03B1\u03C2 \u03C1\u03C9\u03C4\u03AC \u03C0\u03BF\u03CD \u03B8\u03B1 \u03C4\u03BF \u03B2\u03AC\u03BB\u03B5\u03B9.",
            ["Steam cover art is found automatically."] = "\u03A4\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03C4\u03BF\u03C5 Steam \u03B2\u03C1\u03AF\u03C3\u03BA\u03BF\u03BD\u03C4\u03B1\u03B9 \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03B1.",
            ["Steam has taken over. The download shows in Recent."] = "\u03A4\u03BF Steam \u03B1\u03BD\u03AD\u03BB\u03B1\u03B2\u03B5. \u0397 \u03BB\u03AE\u03C8\u03B7 \u03C6\u03B1\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03C3\u03C4\u03B1 \u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1.",
            ["SteamGridDB key"] = "\u039A\u03BB\u03B5\u03B9\u03B4\u03AF SteamGridDB",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "\u03A4\u03BF \u03B2\u03AE\u03BC\u03B1 1 \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03C3\u03C4\u03B5\u03AF. \u039C\u03B5\u03C4\u03AC \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03CC, \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03C3\u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C3\u03B2\u03AE\u03C3\u03B5\u03B9 \u03C4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2 \u03AE \u03BD\u03B1 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03AD\u03C8\u03B5\u03B9 \u03C4\u03BF\u03BD \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1 \u03C3\u03C4\u03BF firmware.",
            ["Stick deadzone"] = "\u039D\u03B5\u03BA\u03C1\u03AE \u03B6\u03CE\u03BD\u03B7 \u03BC\u03BF\u03C7\u03BB\u03BF\u03CD",
            ["Stretch"] = "\u03A4\u03AD\u03BD\u03C4\u03C9\u03BC\u03B1",
            ["System"] = "\u03A3\u03CD\u03C3\u03C4\u03B7\u03BC\u03B1",
            ["System language"] = "\u0393\u03BB\u03CE\u03C3\u03C3\u03B1 \u03C3\u03C5\u03C3\u03C4\u03AE\u03BC\u03B1\u03C4\u03BF\u03C2",
            ["TDP boost"] = "Boost TDP",
            ["Test versions"] = "\u0394\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AD\u03C2 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2",
            ["That is what makes the extra controller features possible."] = "\u0391\u03C5\u03C4\u03CC \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03BF\u03C5 \u03BA\u03AC\u03BD\u03B5\u03B9 \u03B4\u03C5\u03BD\u03B1\u03C4\u03AD\u03C2 \u03C4\u03B9\u03C2 \u03C0\u03C1\u03CC\u03C3\u03B8\u03B5\u03C4\u03B5\u03C2 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B5\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5.",
            ["That key was rejected."] = "\u03A4\u03BF \u03BA\u03BB\u03B5\u03B9\u03B4\u03AF \u03B1\u03C0\u03BF\u03C1\u03C1\u03AF\u03C6\u03B8\u03B7\u03BA\u03B5.",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\u03A4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2, \u03B7 \u03BA\u03B1\u03BC\u03C0\u03CD\u03BB\u03B7 \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1 \u03BA\u03B1\u03B9 \u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03BF\u03BD\u03C4\u03B1\u03B9 \u03BC\u03CC\u03BD\u03BF \u03B1\u03C0\u03CC \u03C4\u03BF ClawTweaks. \u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03BE\u03B1\u03BD\u03AC \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03C4\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03AD\u03C8\u03C4\u03B5 \u03B5\u03B4\u03CE. \u039C\u03C0\u03BF\u03C1\u03B5\u03AF\u03C4\u03B5 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03BD\u03B1 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03B5\u03C4\u03B5 \u03C4\u03BF Center.",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\u03A4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B4\u03B5\u03BD \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03AF\u03C9\u03C3\u03B5 \u2014 \u03B5\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03BF \u03C0\u03C1\u03B9\u03BD \u03C4\u03BF \u03B1\u03C0\u03BF\u03C3\u03C5\u03BD\u03B4\u03AD\u03C3\u03B5\u03C4\u03B5.",
            ["The device can be restored"] = "\u0397 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03B5\u03C1\u03B8\u03B5\u03AF",
            ["The helper did not confirm in time."] = "\u039F helper \u03B4\u03B5\u03BD \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03AF\u03C9\u03C3\u03B5 \u03B5\u03B3\u03BA\u03B1\u03AF\u03C1\u03C9\u03C2.",
            ["The helper is not answering"] = "\u039F helper \u03B4\u03B5\u03BD \u03B1\u03C0\u03B1\u03BD\u03C4\u03AC",
            ["The library comes back when the game ends."] = "\u0397 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03AD\u03C6\u03B5\u03B9 \u03CC\u03C4\u03B1\u03BD \u03C4\u03B5\u03BB\u03B5\u03B9\u03CE\u03C3\u03B5\u03B9 \u03C4\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9.",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u03A4\u03BF \u03B5\u03B3\u03B3\u03B5\u03BD\u03AD\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03C0\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03B1\u03B8\u03B1\u03C1\u03CC \u03C0\u03C1\u03B9\u03BD \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AE\u03C3\u03B5\u03B9 \u03B7 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1. \u03A3\u03C4\u03B7\u03BD \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C4\u03BF \u03C6\u03C5\u03C3\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03C1\u03CD\u03B2\u03B5\u03C4\u03B1\u03B9 \u03BA\u03B1\u03B9 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03CC \u03AD\u03BD\u03B1 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF VIIPER\u00B7 \u03C3\u03C4\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03C0\u03B5\u03C5\u03B8\u03B5\u03AF\u03B1\u03C2 \u03C4\u03BF \u03C6\u03C5\u03C3\u03B9\u03BA\u03CC.",
            ["The newest changes, least tested"] = "\u039F\u03B9 \u03BD\u03B5\u03CC\u03C4\u03B5\u03C1\u03B5\u03C2 \u03B1\u03BB\u03BB\u03B1\u03B3\u03AD\u03C2, \u03BB\u03B9\u03B3\u03CC\u03C4\u03B5\u03C1\u03BF \u03B4\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03BC\u03AD\u03BD\u03B5\u03C2",
            ["The old helper exited on its own."] = "\u039F \u03C0\u03B1\u03BB\u03B9\u03CC\u03C2 helper \u03C4\u03B5\u03C1\u03BC\u03AC\u03C4\u03B9\u03C3\u03B5 \u03BC\u03CC\u03BD\u03BF\u03C2 \u03C4\u03BF\u03C5.",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "\u0395\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B7 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03B7\u03C2 \u03C0\u03B1\u03BB\u03B9\u03AC\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2 \u2014 \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03BC\u03AE\u03BD\u03C5\u03BC\u03AC \u03C4\u03B7\u03C2. \u0397 \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03B5\u03BE\u03B1\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03BC\u03CC\u03BB\u03B9\u03C2 \u03C6\u03CD\u03B3\u03B5\u03B9 (\u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u24CE \u03B3\u03B9\u03B1 \u03B1\u03BD\u03B1\u03BD\u03AD\u03C9\u03C3\u03B7).",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\u03A4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B5 \u03BD\u03B1 \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03B8\u03B5\u03AF. \u039A\u03BB\u03B5\u03AF\u03C3\u03C4\u03B5 \u03C4\u03BF Game Bar \u03BA\u03B1\u03B9 \u03B4\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03AE \u03B1\u03C6\u03B1\u03B9\u03C1\u03AD\u03C3\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03B1\u03C0\u03CC \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u2192 \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2.",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\u0397 \u03BF\u03B9\u03BA\u03BF\u03B3\u03AD\u03BD\u03B5\u03B9\u03B1 \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF\u03C5 \u03C3\u03C5\u03B3\u03BA\u03C1\u03BF\u03CD\u03C3\u03C4\u03B7\u03BA\u03B5 \u03BC\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7. \u039A\u03B1\u03B8\u03B1\u03C1\u03B9\u03C3\u03BC\u03CC\u03C2 \u03BA\u03B1\u03B9 \u03BC\u03AF\u03B1 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03C0\u03C1\u03BF\u03C3\u03C0\u03AC\u03B8\u03B5\u03B9\u03B1\u2026",
            ["The reset did not finish."] = "\u0397 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B4\u03B5\u03BD \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5.",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\u03A4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF \u03C4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C4\u03BF \u03C0\u03B1\u03C1\u03AC\u03B8\u03C5\u03C1\u03BF \u03C4\u03C9\u03BD Windows, \u03BC\u03AF\u03B1 \u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03AC \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\u03A4\u03BF widget \u03B4\u03B5\u03AF\u03C7\u03BD\u03B5\u03B9 \u03C4\u03B9 \u03BA\u03AC\u03BD\u03B5\u03B9 \u03BF helper\u00B7 \u03B1\u03C0\u03CC \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF\u03C5 \u03B4\u03B5\u03BD \u03B1\u03BB\u03BB\u03AC\u03B6\u03B5\u03B9 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1.",
            ["The wiki page could not be read. Open it in a browser."] = "\u0397 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1 wiki \u03B4\u03B5\u03BD \u03B4\u03B9\u03B1\u03B2\u03AC\u03C3\u03C4\u03B7\u03BA\u03B5. \u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03B7\u03BD \u03C3\u03C4\u03BF \u03C0\u03C1\u03CC\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1 \u03C0\u03B5\u03C1\u03B9\u03AE\u03B3\u03B7\u03C3\u03B7\u03C2.",
            ["This Setup build is outdated"] = "\u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 Setup \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03B1\u03C1\u03C9\u03C7\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["This installs an OLDER version than the one installed."] = "\u0391\u03C5\u03C4\u03CC \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC \u03A0\u0391\u039B\u0399\u039F\u03A4\u0395\u03A1\u0397 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7.",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\u0391\u03C5\u03C4\u03AE \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BC\u03B9\u03B1 \u03B4\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AE \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03C7\u03C9\u03C1\u03AF\u03C2 \u03B5\u03BD\u03C3\u03C9\u03BC\u03B1\u03C4\u03C9\u03BC\u03AD\u03BD\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03B4\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03BD\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03B1\u03B8\u03B5\u03AF. \u03A3\u03B5 \u03C0\u03C1\u03B1\u03B3\u03BC\u03B1\u03C4\u03B9\u03BA\u03CC setup \u03C4\u03BF .msix \u03BA\u03B1\u03B9 \u03C4\u03BF .cer \u03B2\u03C1\u03AF\u03C3\u03BA\u03BF\u03BD\u03C4\u03B1\u03B9 \u03B4\u03AF\u03C0\u03BB\u03B1 \u03C3\u03B5 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF exe.",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\u0391\u03C5\u03C4\u03CC \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03B9 \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03BA\u03B1\u03B9 \u03C3\u03B2\u03AE\u03BD\u03B5\u03B9 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C3\u03B1\u03C2 ClawTweaks:",
            ["This removes ClawTweaks Center and closes it."] = "\u0391\u03C5\u03C4\u03CC \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03C4\u03BF ClawTweaks Center \u03BA\u03B1\u03B9 \u03C4\u03BF \u03BA\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9.",
            ["This removes the ClawTweaks app from Windows."] = "\u0391\u03C5\u03C4\u03CC \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE ClawTweaks \u03B1\u03C0\u03CC \u03C4\u03B1 Windows.",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "\u0391\u03C5\u03C4\u03CC \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03B9 \u039F\u039B\u0395\u03A3 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 ClawTweaks \u03C3\u03B5 \u03BA\u03B1\u03B8\u03B1\u03C1\u03AE \u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7:",
            ["This takes a moment."] = "\u0391\u03C5\u03C4\u03CC \u03B8\u03AD\u03BB\u03B5\u03B9 \u03BB\u03AF\u03B3\u03BF \u03C7\u03C1\u03CC\u03BD\u03BF.",
            ["This version can't be installed"] = "\u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B4\u03B5\u03BD \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03B1\u03B8\u03B5\u03AF",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AE\u03B4\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7. \u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03B7\u03BD \u03B1\u03C0\u03CC \u03C4\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD \u0388\u03BD\u03B1\u03C1\u03BE\u03B7 \u03AE \u03B1\u03C0\u03CC \u03C4\u03BF widget ClawTweaks \u03C3\u03C4\u03BF Game Bar, \u03B1\u03BD\u03C4\u03AF \u03BD\u03B1 \u03C4\u03C1\u03AD\u03BE\u03B5\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF Setup.",
            ["Timed out"] = "\u039B\u03AE\u03BE\u03B7 \u03C7\u03C1\u03CC\u03BD\u03BF\u03C5",
            ["Transition to new Center App - Uninstall the old version"] = "\u039C\u03B5\u03C4\u03AC\u03B2\u03B1\u03C3\u03B7 \u03C3\u03C4\u03B7 \u03BD\u03AD\u03B1 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE Center - \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03B7\u03C2 \u03C0\u03B1\u03BB\u03B9\u03AC\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\u039A\u03AC\u03BD\u03B5\u03B9 \u03AD\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2, \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03AC \u03C4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF, \u03B1\u03BD\u03BF\u03AF\u03B3\u03B5\u03B9 \u03C4\u03BF Game Bar \u03BA\u03B1\u03B9 \u03C0\u03B5\u03C1\u03B9\u03BC\u03AD\u03BD\u03B5\u03B9 \u03C4\u03BF\u03BD helper. \u039C\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03C3\u03C4\u03B5\u03AF \u03BE\u03B1\u03BD\u03AC \u03C3\u03B5 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7.",
            ["Turn MSI Center M back on"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03BE\u03B1\u03BD\u03AC \u03C4\u03BF\u03C5 MSI Center M",
            ["Turn on"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7",
            ["Turning MSI Center M back on\u2026"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7 \u03BE\u03B1\u03BD\u03AC \u03C4\u03BF\u03C5 MSI Center M\u2026",
            ["Uninstall"] = "\u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Uninstall Center"] = "\u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 Center",
            ["Update ClawTweaks Center"] = "\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks Center",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u0397 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5 \u2014 \u03B4\u03B5\u03AF\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03BA\u03B1\u03C4\u03B1\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2. \u0394\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03AE \u03B5\u03BA\u03C4\u03B5\u03BB\u03AD\u03C3\u03C4\u03B5 \u03C9\u03C2 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C2.",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\u039F\u03B9 \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03C3\u03B5\u03B9\u03C2 \u03B4\u03B5\u03BD \u03BA\u03BF\u03C3\u03C4\u03AF\u03B6\u03BF\u03C5\u03BD \u03B5\u03C1\u03CE\u03C4\u03B7\u03BC\u03B1 \u2014 \u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03B4\u03B5\u03BD \u03C6\u03AD\u03C1\u03B5\u03B9 \u03B1\u03C1\u03B9\u03B8\u03BC\u03CC \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2.",
            ["Updating..."] = "\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\u03A7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B7\u03BD \u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 ClawTweaks \u03B5\u03B4\u03CE \u03C3\u03C4\u03BF Center.",
            ["Verifying the virtual pad\u2026"] = "\u0395\u03C0\u03B1\u03BB\u03AE\u03B8\u03B5\u03C5\u03C3\u03B7 \u03C4\u03BF\u03C5 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03BF\u03CD \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5\u2026",
            ["Vibration"] = "\u0394\u03CC\u03BD\u03B7\u03C3\u03B7",
            ["Virtual controller (VIIPER)"] = "\u0395\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\u0397 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03AE\u03B4\u03B7 \u03B5\u03BD\u03B5\u03C1\u03B3\u03AE \u2014 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C5\u03B3\u03B9\u03AD\u03C2.",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\u03A4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B4\u03B5\u03BD \u03C3\u03C5\u03BD\u03B4\u03AD\u03B8\u03B7\u03BA\u03B5 \u2014 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03BF\u03C6\u03AE \u03C3\u03C4\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["Waiting for UAC\u2026"] = "\u0391\u03BD\u03B1\u03BC\u03BF\u03BD\u03AE \u03B3\u03B9\u03B1 UAC\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "\u0391\u03BD\u03B1\u03BC\u03BF\u03BD\u03AE \u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7\u03C2 \u03C4\u03BF\u03C5 helper \u03C4\u03BF\u03C5 ClawTweaks. \u0391\u03BD \u03AC\u03BD\u03BF\u03B9\u03BE\u03B5 \u03C4\u03BF Game Bar \u03B1\u03BB\u03BB\u03AC \u03B4\u03B5\u03BD \u03B3\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1, \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C4\u03BF widget ClawTweaks \u03C3\u03C4\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD widget \u03BA\u03B1\u03B9 \u03C0\u03C1\u03BF\u03C3\u03B8\u03AD\u03C3\u03C4\u03B5 \u03C4\u03BF \u2014 \u03AD\u03BD\u03B1 widget \u03C0\u03BF\u03C5 \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03C3\u03C4\u03BF Game Bar \u03B4\u03B5\u03BD \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF\u03C5 \u03C4\u03BF\u03BD helper.",
            ["Waiting for the virtual controller to settle\u2026"] = "\u0391\u03BD\u03B1\u03BC\u03BF\u03BD\u03AE \u03C3\u03C4\u03B1\u03B8\u03B5\u03C1\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7\u03C2 \u03C4\u03BF\u03C5 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03BF\u03CD \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5\u2026",
            ["What does the background helper do?"] = "\u03A4\u03B9 \u03BA\u03AC\u03BD\u03B5\u03B9 \u03BF helper \u03C3\u03C4\u03BF \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03AE\u03BD\u03B9\u03BF;",
            ["What happens"] = "\u03A4\u03B9 \u03B3\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9",
            ["What is the virtual controller for?"] = "\u03A3\u03B5 \u03C4\u03B9 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03B5\u03CD\u03B5\u03B9 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF;",
            ["What's new"] = "\u03A4\u03B9 \u03BD\u03AD\u03BF \u03C5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9",
            ["Where are my settings, and how do I back them up?"] = "\u03A0\u03BF\u03CD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BF\u03B9 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03BC\u03BF\u03C5 \u03BA\u03B1\u03B9 \u03C0\u03CE\u03C2 \u03BA\u03C1\u03B1\u03C4\u03AC\u03C9 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF;",
            ["Why does ClawTweaks ask for admin rights?"] = "\u0393\u03B9\u03B1\u03C4\u03AF \u03B6\u03B7\u03C4\u03AC \u03C4\u03BF ClawTweaks \u03B4\u03B9\u03BA\u03B1\u03B9\u03CE\u03BC\u03B1\u03C4\u03B1 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE;",
            ["Will be saved to"] = "\u0398\u03B1 \u03B1\u03C0\u03BF\u03B8\u03B7\u03BA\u03B5\u03C5\u03C4\u03B5\u03AF \u03C3\u03C4\u03BF",
            ["Windowed"] = "\u03A3\u03B5 \u03C0\u03B1\u03C1\u03AC\u03B8\u03C5\u03C1\u03BF",
            ["Windows Insider Preview detected"] = "\u0395\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 Windows Insider Preview",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "\u03A4\u03B1 Windows \u03B6\u03AE\u03C4\u03B7\u03C3\u03B1\u03BD \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 Center. \u03A4\u03B5\u03BB\u03B5\u03B9\u03CE\u03C3\u03C4\u03B5 \u03B5\u03B4\u03CE \u03AE \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 B \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BC\u03B5\u03AF\u03BD\u03BF\u03C5\u03BD \u03CC\u03BB\u03B1.",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "\u03A4\u03B1 Windows \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B1\u03BD \u03BD\u03B1 \u03B1\u03BD\u03BF\u03AF\u03BE\u03BF\u03C5\u03BD \u03C4\u03BF \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF\u03C5. \u0394\u03B5\u03BD \u03C6\u03C4\u03B1\u03AF\u03B5\u03B9 \u03C4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u2014 \u03B7 \u03C5\u03C0\u03B7\u03C1\u03B5\u03C3\u03AF\u03B1 \u03B1\u03BD\u03AC\u03C0\u03C4\u03C5\u03BE\u03B7\u03C2 (\u03C9\u03C2 SYSTEM) \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B5 \u03BD\u03B1 \u03C4\u03BF \u03B4\u03B9\u03B1\u03B2\u03AC\u03C3\u03B5\u03B9. \u0394\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF \u03B5\u03BA\u03C4\u03CC\u03C2 \u03C4\u03BF\u03C5 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03C7\u03C1\u03AE\u03C3\u03C4\u03B7 \u03BA\u03B1\u03B9 \u03B5\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03B1\u03BD \u03BF\u03B9 Gaming Services \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C5\u03B3\u03B9\u03B5\u03AF\u03C2.",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "\u03A4\u03B1 Windows \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B1\u03BD \u03BD\u03B1 \u03B1\u03BD\u03BF\u03AF\u03BE\u03BF\u03C5\u03BD \u03C4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03CC\u03BD \u03C4\u03BF\u03BD \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF. \u039D\u03AD\u03B1 \u03C0\u03C1\u03BF\u03C3\u03C0\u03AC\u03B8\u03B5\u03B9\u03B1 \u03B1\u03C0\u03CC \u03B8\u03AD\u03C3\u03B7 \u03B3\u03B9\u03B1 \u03CC\u03BB\u03BF \u03C4\u03BF \u03BC\u03B7\u03C7\u03AC\u03BD\u03B7\u03BC\u03B1\u2026",
            ["Windows file picker"] = "\u0395\u03C0\u03B9\u03BB\u03BF\u03B3\u03AD\u03B1\u03C2 \u03B1\u03C1\u03C7\u03B5\u03AF\u03C9\u03BD \u03C4\u03C9\u03BD Windows",
            ["Work down the list. Each step is optional except the last."] = "\u0394\u03BF\u03C5\u03BB\u03AD\u03C8\u03C4\u03B5 \u03C4\u03B7 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03B1\u03C0\u03CC \u03C0\u03AC\u03BD\u03C9 \u03C0\u03C1\u03BF\u03C2 \u03C4\u03B1 \u03BA\u03AC\u03C4\u03C9. \u039A\u03AC\u03B8\u03B5 \u03B2\u03AE\u03BC\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03C1\u03BF\u03B1\u03B9\u03C1\u03B5\u03C4\u03B9\u03BA\u03CC \u03B5\u03BA\u03C4\u03CC\u03C2 \u03B1\u03C0\u03CC \u03C4\u03BF \u03C4\u03B5\u03BB\u03B5\u03C5\u03C4\u03B1\u03AF\u03BF.",
            ["Working\u2026"] = "\u03A3\u03B5 \u03B5\u03BE\u03AD\u03BB\u03B9\u03BE\u03B7\u2026",
            ["XInput controllers"] = "\u03A7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03B1 XInput",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\u039D\u03B1\u03B9, \u03B1\u03BD \u03C4\u03BF ClawTweaks \u03C0\u03C1\u03AD\u03C0\u03B5\u03B9 \u03BD\u03B1 \u03B5\u03BB\u03AD\u03B3\u03C7\u03B5\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF, \u03C4\u03BF\u03BD \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03B1 LED.",
            ["Yes, install"] = "\u039D\u03B1\u03B9, \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Yes, reset everything"] = "\u039D\u03B1\u03B9, \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03CC\u03BB\u03C9\u03BD",
            ["Yes, restore"] = "\u039D\u03B1\u03B9, \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC",
            ["Yes, restore the device"] = "\u039D\u03B1\u03B9, \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03C4\u03B7\u03C2 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE\u03C2",
            ["Yes, uninstall Center"] = "\u039D\u03B1\u03B9, \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 Center",
            ["Yes, uninstall ClawTweaks"] = "\u039D\u03B1\u03B9, \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "\u03A4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03C4\u03BF\u03C5 Claw \u03C3\u03B1\u03C2 \u03BA\u03C1\u03CD\u03B2\u03B5\u03C4\u03B1\u03B9 \u03BA\u03B1\u03B9 \u03B1\u03BD\u03C4\u03B9\u03BA\u03B1\u03B8\u03AF\u03C3\u03C4\u03B1\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03AD\u03BD\u03B1 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC.",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\u039F\u03B9 \u03C4\u03C1\u03AD\u03C7\u03BF\u03C5\u03C3\u03B5\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C3\u03B1\u03C2 \u03B1\u03C0\u03BF\u03B8\u03B7\u03BA\u03B5\u03CD\u03BF\u03BD\u03C4\u03B1\u03B9 \u03C0\u03C1\u03B9\u03BD \u03C4\u03B7\u03BD \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC. \u03A4\u03BF Game Bar \u03BA\u03BB\u03B5\u03AF\u03BD\u03B5\u03B9 \u2014 \u03B1\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C4\u03BF \u03BE\u03B1\u03BD\u03AC \u03BC\u03B5 Win+G.",
            ["Your games"] = "\u03A4\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03C3\u03B1\u03C2",
            ["usbip  (required for virtual controller)"] = "usbip  (\u03B1\u03C0\u03B1\u03B9\u03C4\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B3\u03B9\u03B1 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF)",
            ["version"] = "\u03AD\u03BA\u03B4\u03BF\u03C3\u03B7",
            ["versions"] = "\u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \u038C\u03BB\u03B1 \u03C4\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB, \u03BF\u03B9 \u03BA\u03B1\u03BC\u03C0\u03CD\u03BB\u03B5\u03C2 \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1, \u03C4\u03BF TDP \u03BA\u03B1\u03B9 \u03BF\u03B9 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03BF\u03BD\u03C4\u03B1\u03B9",
            ["\u2022 Center's own settings are cleared"] = "\u2022 \u039F\u03B9 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C4\u03BF\u03C5 \u03AF\u03B4\u03B9\u03BF\u03C5 \u03C4\u03BF\u03C5 Center \u03C3\u03B2\u03AE\u03BD\u03BF\u03BD\u03C4\u03B1\u03B9",
            ["\u2022 Global and per-game profiles (TDP, fan curves, controller, gyro)"] = "\u2022 \u039A\u03B1\u03B8\u03BF\u03BB\u03B9\u03BA\u03AC \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03BA\u03B1\u03B9 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03B1\u03BD\u03AC \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9 (TDP, \u03BA\u03B1\u03BC\u03C0\u03CD\u03BB\u03B5\u03C2 \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1, \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF, gyro)",
            ["\u2022 Helper settings (global TDP, fan curve, controller emulation)"] = "\u2022 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 helper (\u03BA\u03B1\u03B8\u03BF\u03BB\u03B9\u03BA\u03CC TDP, \u03BA\u03B1\u03BC\u03C0\u03CD\u03BB\u03B7 \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1, \u03B5\u03BE\u03BF\u03BC\u03BF\u03AF\u03C9\u03C3\u03B7 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5)",
            ["\u2022 The ClawTweaks app is NOT removed by this"] = "\u2022 \u0397 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE ClawTweaks \u0394\u0395\u039D \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03CC",
            ["\u2022 The Start Menu entry and the desktop shortcut go"] = "\u2022 \u0397 \u03BA\u03B1\u03C4\u03B1\u03C7\u03CE\u03C1\u03B9\u03C3\u03B7 \u03C3\u03C4\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD \u0388\u03BD\u03B1\u03C1\u03BE\u03B7 \u03BA\u03B1\u03B9 \u03B7 \u03C3\u03C5\u03BD\u03C4\u03CC\u03BC\u03B5\u03C5\u03C3\u03B7 \u03C3\u03C4\u03B7\u03BD \u03B5\u03C0\u03B9\u03C6\u03AC\u03BD\u03B5\u03B9\u03B1 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1\u03C2 \u03C6\u03B5\u03CD\u03B3\u03BF\u03C5\u03BD",
            ["\u2022 The background helper stops and removes its scheduled task"] = "\u2022 \u039F helper \u03C0\u03B1\u03C1\u03B1\u03C3\u03BA\u03B7\u03BD\u03AF\u03BF\u03C5 \u03C3\u03C4\u03B1\u03BC\u03B1\u03C4\u03AC \u03BA\u03B1\u03B9 \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03C4\u03B7\u03BD \u03C0\u03C1\u03BF\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1\u03C4\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7 \u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u03C4\u03BF\u03C5",
            ["\u2022 The battery charge limit is switched off"] = "\u2022 \u03A4\u03BF \u03CC\u03C1\u03B9\u03BF \u03C6\u03CC\u03C1\u03C4\u03B9\u03C3\u03B7\u03C2 \u03C4\u03B7\u03C2 \u03BC\u03C0\u03B1\u03C4\u03B1\u03C1\u03AF\u03B1\u03C2 \u03B1\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF\u03C4\u03B1\u03B9",
            ["\u2022 The fan goes back to firmware control"] = "\u2022 \u039F \u03B1\u03BD\u03B5\u03BC\u03B9\u03C3\u03C4\u03AE\u03C1\u03B1\u03C2 \u03B5\u03C0\u03B9\u03C3\u03C4\u03C1\u03AD\u03C6\u03B5\u03B9 \u03C3\u03C4\u03BF\u03BD \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C4\u03BF\u03C5 firmware",
            ["\u2022 The hardware controller comes back"] = "\u2022 \u03A4\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B5\u03C0\u03B1\u03BD\u03AD\u03C1\u03C7\u03B5\u03C4\u03B1\u03B9",
            ["\u2022 The widget disappears from the Game Bar"] = "\u2022 \u03A4\u03BF widget \u03B5\u03BE\u03B1\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03C4\u03BF Game Bar",
            ["\u2022 Your profiles and settings are deleted with the app"] = "\u2022 \u03A4\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03BA\u03B1\u03B9 \u03BF\u03B9 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03C3\u03B1\u03C2 \u03B4\u03B9\u03B1\u03B3\u03C1\u03AC\u03C6\u03BF\u03BD\u03C4\u03B1\u03B9 \u03BC\u03B1\u03B6\u03AF \u03BC\u03B5 \u03C4\u03B7\u03BD \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AE",
            ["Could not start {0}."] = "\u0394\u03B5\u03BD \u03BE\u03B5\u03BA\u03AF\u03BD\u03B7\u03C3\u03B5 \u03C4\u03BF {0}.",
            ["Install {0}?"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C4\u03BF\u03C5 {0};",
            ["Start Steam with the library"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03C4\u03BF\u03C5 Steam \u03BC\u03B5 \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7",
            ["Denser grid"] = "\u03A0\u03C5\u03BA\u03BD\u03CC\u03C4\u03B5\u03C1\u03BF \u03C0\u03BB\u03AD\u03B3\u03BC\u03B1",
            ["Interface sounds"] = "\u0389\u03C7\u03BF\u03B9 \u03C0\u03B5\u03C1\u03B9\u03B2\u03AC\u03BB\u03BB\u03BF\u03BD\u03C4\u03BF\u03C2",
            ["Background music"] = "\u039C\u03BF\u03C5\u03C3\u03B9\u03BA\u03AE \u03C5\u03C0\u03CC\u03BA\u03C1\u03BF\u03C5\u03C3\u03B7",
            ["Sound settings"] = "\u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u03AE\u03C7\u03BF\u03C5",
            ["Effects volume"] = "\u0388\u03BD\u03C4\u03B1\u03C3\u03B7 \u03B5\u03C6\u03AD",
            ["Music volume"] = "\u0388\u03BD\u03C4\u03B1\u03C3\u03B7 \u03BC\u03BF\u03C5\u03C3\u03B9\u03BA\u03AE\u03C2",
            ["Change a value with left and right."] = "\u0391\u03BB\u03BB\u03AC\u03BE\u03C4\u03B5 \u03C4\u03B9\u03BC\u03AE \u03BC\u03B5 \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC \u03BA\u03B1\u03B9 \u03B4\u03B5\u03BE\u03B9\u03AC.",
            ["Navigate"] = "\u03A0\u03BB\u03BF\u03AE\u03B3\u03B7\u03C3\u03B7",
            ["Go back"] = "\u03A0\u03AF\u03C3\u03C9",
            ["Change"] = "\u0391\u03BB\u03BB\u03B1\u03B3\u03AE",
            ["Toggle"] = "\u0395\u03BD\u03B1\u03BB\u03BB\u03B1\u03B3\u03AE",
            ["Reading your stores\u2026"] = "\u0391\u03BD\u03AC\u03B3\u03BD\u03C9\u03C3\u03B7 \u03C4\u03C9\u03BD \u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03B7\u03BC\u03AC\u03C4\u03C9\u03BD \u03C3\u03B1\u03C2\u2026",
            ["Reading your Steam library\u2026"] = "\u0391\u03BD\u03AC\u03B3\u03BD\u03C9\u03C3\u03B7 \u03C4\u03B7\u03C2 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2 Steam\u2026",
            ["Center opens on the library, not on Home."] = "\u03A4\u03BF Center \u03B1\u03BD\u03BF\u03AF\u03B3\u03B5\u03B9 \u03C3\u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7, \u03CC\u03C7\u03B9 \u03C3\u03C4\u03B7\u03BD \u03B1\u03C1\u03C7\u03B9\u03BA\u03AE.",
            ["ClawTweaks starts Center when it starts itself."] = "\u03A4\u03BF ClawTweaks \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03C4\u03BF Center \u03CC\u03C4\u03B1\u03BD \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03C4\u03BF \u03AF\u03B4\u03B9\u03BF.",
            ["Closing the window leaves Center running in the tray."] = "\u039A\u03BB\u03B5\u03AF\u03BD\u03BF\u03BD\u03C4\u03B1\u03C2 \u03C4\u03BF \u03C0\u03B1\u03C1\u03AC\u03B8\u03C5\u03C1\u03BF, \u03C4\u03BF Center \u03BC\u03AD\u03BD\u03B5\u03B9 \u03C3\u03C4\u03B7\u03BD \u03C0\u03B5\u03C1\u03B9\u03BF\u03C7\u03AE \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03B5\u03C9\u03BD.",
            ["What Center does with itself once a game runs."] = "\u03A4\u03B9 \u03BA\u03AC\u03BD\u03B5\u03B9 \u03C4\u03BF Center \u03BC\u03B5 \u03C4\u03BF\u03BD \u03B5\u03B1\u03C5\u03C4\u03CC \u03C4\u03BF\u03C5 \u03BC\u03CC\u03BB\u03B9\u03C2 \u03C4\u03C1\u03AD\u03BE\u03B5\u03B9 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9.",
            ["Which tabs the library shows, and in which order."] = "\u03A0\u03BF\u03B9\u03B5\u03C2 \u03BA\u03B1\u03C1\u03C4\u03AD\u03BB\u03B5\u03C2 \u03B4\u03B5\u03AF\u03C7\u03BD\u03B5\u03B9 \u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7 \u03BA\u03B1\u03B9 \u03BC\u03B5 \u03C0\u03BF\u03B9\u03B1 \u03C3\u03B5\u03B9\u03C1\u03AC.",
            ["More covers per row, and a smaller Recent reel."] = "\u03A0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03B1\u03BD\u03AC \u03C3\u03B5\u03B9\u03C1\u03AC \u03BA\u03B1\u03B9 \u03BC\u03B9\u03BA\u03C1\u03CC\u03C4\u03B5\u03C1\u03B7 \u03BB\u03C9\u03C1\u03AF\u03B4\u03B1 \u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1.",
            ["Fades the tabs and the footer out on Recent while you idle."] = "\u03A3\u03B2\u03AE\u03BD\u03B5\u03B9 \u03C4\u03B9\u03C2 \u03BA\u03B1\u03C1\u03C4\u03AD\u03BB\u03B5\u03C2 \u03BA\u03B1\u03B9 \u03C4\u03BF \u03C5\u03C0\u03BF\u03C3\u03AD\u03BB\u03B9\u03B4\u03BF \u03C3\u03C4\u03B1 \u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1 \u03CC\u03C3\u03BF \u03B4\u03B5\u03BD \u03BA\u03AC\u03BD\u03B5\u03C4\u03B5 \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1.",
            ["Mirrors every cover in the Recent reel."] = "\u039A\u03B1\u03B8\u03C1\u03B5\u03C6\u03C4\u03AF\u03B6\u03B5\u03B9 \u03BA\u03AC\u03B8\u03B5 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03BF \u03C3\u03C4\u03B7 \u03BB\u03C9\u03C1\u03AF\u03B4\u03B1 \u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1.",
            ["Show own apps in Recent"] = "\u039F\u03B9 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03BC\u03BF\u03C5 \u03C3\u03C4\u03B9\u03C2 \u03C0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B5\u03C2",
            ["Apps you added show up in Recent after you start them here."] = "\u039F\u03B9 \u03B5\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03C0\u03BF\u03C5 \u03C0\u03C1\u03CC\u03C3\u03B8\u03B5\u03C3\u03B5\u03C2 \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03B6\u03BF\u03BD\u03C4\u03B1\u03B9 \u03C3\u03C4\u03B9\u03C2 \u03C0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B5\u03C2 \u03BC\u03CC\u03BB\u03B9\u03C2 \u03C4\u03B9\u03C2 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9\u03C2 \u03B5\u03B4\u03CE.",
            ["ROM covers are square instead of upright."] = "\u03A4\u03B1 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 ROM \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C4\u03B5\u03C4\u03C1\u03AC\u03B3\u03C9\u03BD\u03B1 \u03B1\u03BD\u03C4\u03AF \u03B3\u03B9\u03B1 \u03BA\u03AC\u03B8\u03B5\u03C4\u03B1.",
            ["The folder your own covers and backgrounds come from."] = "\u039F \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF\u03C2 \u03B1\u03C0\u03CC \u03CC\u03C0\u03BF\u03C5 \u03AD\u03C1\u03C7\u03BF\u03BD\u03C4\u03B1\u03B9 \u03C4\u03B1 \u03B4\u03B9\u03BA\u03AC \u03C3\u03B1\u03C2 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03BA\u03B1\u03B9 \u03C6\u03CC\u03BD\u03C4\u03B1.",
            ["The picture behind the library."] = "\u0397 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B1 \u03C0\u03AF\u03C3\u03C9 \u03B1\u03C0\u03CC \u03C4\u03B7 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7.",
            ["Interface sounds, music, and a volume for each."] = "\u0389\u03C7\u03BF\u03B9 \u03C0\u03B5\u03C1\u03B9\u03B2\u03AC\u03BB\u03BB\u03BF\u03BD\u03C4\u03BF\u03C2, \u03BC\u03BF\u03C5\u03C3\u03B9\u03BA\u03AE \u03BA\u03B1\u03B9 \u03BE\u03B5\u03C7\u03C9\u03C1\u03B9\u03C3\u03C4\u03AE \u03AD\u03BD\u03C4\u03B1\u03C3\u03B7 \u03B3\u03B9\u03B1 \u03C4\u03BF \u03BA\u03B1\u03B8\u03AD\u03BD\u03B1.",
            ["Downloads covers for games that have none."] = "\u039A\u03B1\u03C4\u03B5\u03B2\u03AC\u03B6\u03B5\u03B9 \u03B5\u03BE\u03CE\u03C6\u03C5\u03BB\u03BB\u03B1 \u03B3\u03B9\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03C0\u03BF\u03C5 \u03B4\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD.",
            ["Start {0}?"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03C4\u03BF\u03C5 {0};",
            ["Steam starts first. This takes longer."] = "\u03A0\u03C1\u03CE\u03C4\u03B1 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03C4\u03BF Steam. \u0391\u03C5\u03C4\u03CC \u03C0\u03B1\u03AF\u03C1\u03BD\u03B5\u03B9 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03BF.",
            ["This can take a moment."] = "\u0391\u03C5\u03C4\u03CC \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03AC\u03C1\u03B5\u03B9 \u03BB\u03AF\u03B3\u03BF.",
            ["Your images"] = "\u039F\u03B9 \u03B5\u03B9\u03BA\u03CC\u03BD\u03B5\u03C2 \u03C3\u03B1\u03C2",
