            ["{0} \u00B7 charging \u00B7 {1} h"] = "{0} \u00B7 \u03C6\u03BF\u03C1\u03C4\u03AF\u03B6\u03B5\u03B9 \u00B7 {1} \u03CE",
            ["{0} \u00B7 discharging"] = "{0} \u00B7 \u03B5\u03BA\u03C6\u03BF\u03C1\u03C4\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9",
            ["{0} \u00B7 discharging \u00B7 {1} h"] = "{0} \u00B7 \u03B5\u03BA\u03C6\u03BF\u03C1\u03C4\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u00B7 {1} \u03CE",
            ["{0} \u00B7 AC power \u00B7 fully charged"] = "{0} \u00B7 \u03C1\u03B5\u03CD\u03BC\u03B1 \u00B7 \u03C0\u03BB\u03AE\u03C1\u03C9\u03C2 \u03C6\u03BF\u03C1\u03C4\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7",
            ["{0} \u00B7 AC power \u00B7 not charging"] = "{0} \u00B7 \u03C1\u03B5\u03CD\u03BC\u03B1 \u00B7 \u03B4\u03B5\u03BD \u03C6\u03BF\u03C1\u03C4\u03AF\u03B6\u03B5\u03B9",
            ["{0} is downloading"] = "\u0393\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03BB\u03AE\u03C8\u03B7 \u03C4\u03BF\u03C5 {0}",
            ["{0} is running"] = "\u03A4\u03BF {0} \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9",
            ["{0} is starting"] = "\u03A4\u03BF {0} \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC",
            ["{0} of {1} unlocked"] = "{0} \u03B1\u03C0\u03CC {1} \u03BE\u03B5\u03BA\u03BB\u03B5\u03AF\u03B4\u03C9\u03C4\u03B1",
            ["{0}% of players"] = "{0}% \u03C4\u03C9\u03BD \u03C0\u03B1\u03B9\u03BA\u03C4\u03CE\u03BD",
            ["Drivers & Windows Updates"] = "\u039F\u03B4\u03B7\u03B3\u03BF\u03AF & \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03C3\u03B5\u03B9\u03C2 Windows",
            ["Device drivers"] = "\u039F\u03B4\u03B7\u03B3\u03BF\u03AF \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03CE\u03BD",
            ["Drivers could not be checked"] = "\u039F\u03B9 \u03BF\u03B4\u03B7\u03B3\u03BF\u03AF \u03B4\u03B5\u03BD \u03B5\u03BB\u03AD\u03B3\u03C7\u03B8\u03B7\u03BA\u03B1\u03BD",
            ["ClawTweaks is not running."] = "\u03A4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9.",
            ["No answer from ClawTweaks."] = "\u039A\u03B1\u03BC\u03AF\u03B1 \u03B1\u03C0\u03AC\u03BD\u03C4\u03B7\u03C3\u03B7 \u03B1\u03C0\u03CC \u03C4\u03BF ClawTweaks.",
            ["The driver list could not be read."] = "\u0397 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03BF\u03B4\u03B7\u03B3\u03CE\u03BD \u03B4\u03B5\u03BD \u03B4\u03B9\u03B1\u03B2\u03AC\u03C3\u03C4\u03B7\u03BA\u03B5.",
            ["The driver check failed."] = "\u039F \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03BF\u03B4\u03B7\u03B3\u03CE\u03BD \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5.",
            ["Graphics"] = "\u0393\u03C1\u03B1\u03C6\u03B9\u03BA\u03AC",
            ["Devices"] = "\u03A3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AD\u03C2",
            ["Nothing to show for this device."] = "\u03A4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03C0\u03C1\u03BF\u03C2 \u03B5\u03BC\u03C6\u03AC\u03BD\u03B9\u03C3\u03B7 \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE.",
            ["The list could not be refreshed; showing what was known last."] = "\u0397 \u03BB\u03AF\u03C3\u03C4\u03B1 \u03B4\u03B5\u03BD \u03B1\u03BD\u03B1\u03BD\u03B5\u03CE\u03B8\u03B7\u03BA\u03B5\u00B7 \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03CC,\u03C4\u03B9 \u03AE\u03C4\u03B1\u03BD \u03B3\u03BD\u03C9\u03C3\u03C4\u03CC \u03C4\u03B5\u03BB\u03B5\u03C5\u03C4\u03B1\u03AF\u03B1.",
            ["installed"] = "\u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["available"] = "\u03B4\u03B9\u03B1\u03B8\u03AD\u03C3\u03B9\u03BC\u03B7",
            ["not installed"] = "\u03BC\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["Update available"] = "\u0394\u03B9\u03B1\u03B8\u03AD\u03C3\u03B9\u03BC\u03B7 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7",
            ["Update available (beta)"] = "\u0394\u03B9\u03B1\u03B8\u03AD\u03C3\u03B9\u03BC\u03B7 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 (beta)",
            ["Muted"] = "\u03A3\u03B5 \u03C3\u03AF\u03B3\u03B1\u03C3\u03B7",
            ["Checking with Windows\u2026 this can take up to a minute."] = "\u0393\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03BC\u03B5 \u03C4\u03B1 Windows\u2026 \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C0\u03AC\u03C1\u03B5\u03B9 \u03AD\u03C9\u03C2 \u03AD\u03BD\u03B1 \u03BB\u03B5\u03C0\u03C4\u03CC.",
            ["The check asks Microsoft directly and takes a moment."] = "\u039F \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C1\u03C9\u03C4\u03AC \u03B1\u03C0\u03B5\u03C5\u03B8\u03B5\u03AF\u03B1\u03C2 \u03C4\u03B7 Microsoft \u03BA\u03B1\u03B9 \u03B8\u03AD\u03BB\u03B5\u03B9 \u03BB\u03AF\u03B3\u03BF \u03C7\u03C1\u03CC\u03BD\u03BF.",
            ["Could not check"] = "\u0394\u03B5\u03BD \u03AD\u03B3\u03B9\u03BD\u03B5 \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2",
            ["The answer could not be read."] = "\u0397 \u03B1\u03C0\u03AC\u03BD\u03C4\u03B7\u03C3\u03B7 \u03B4\u03B5\u03BD \u03B4\u03B9\u03B1\u03B2\u03AC\u03C3\u03C4\u03B7\u03BA\u03B5.",
            ["The check failed."] = "\u039F \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5.",
            ["No result from Windows Update"] = "\u039A\u03B1\u03BD\u03AD\u03BD\u03B1 \u03B1\u03C0\u03BF\u03C4\u03AD\u03BB\u03B5\u03C3\u03BC\u03B1 \u03B1\u03C0\u03CC \u03C4\u03BF Windows Update",
            ["The search ended with code {0}."] = "\u0397 \u03B1\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7 \u03C4\u03B5\u03C1\u03BC\u03AC\u03C4\u03B9\u03C3\u03B5 \u03BC\u03B5 \u03BA\u03C9\u03B4\u03B9\u03BA\u03CC {0}.",
            ["Up to date"] = "\u0395\u03BD\u03B7\u03BC\u03B5\u03C1\u03C9\u03BC\u03AD\u03BD\u03BF",
            ["Windows has nothing pending for this machine."] = "\u03A4\u03B1 Windows \u03B4\u03B5\u03BD \u03AD\u03C7\u03BF\u03C5\u03BD \u03C4\u03AF\u03C0\u03BF\u03C4\u03B1 \u03C3\u03B5 \u03B5\u03BA\u03BA\u03C1\u03B5\u03BC\u03CC\u03C4\u03B7\u03C4\u03B1 \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03BC\u03B7\u03C7\u03AC\u03BD\u03B7\u03BC\u03B1.",
            ["{0} update(s) ready"] = "{0} \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7/\u03B5\u03B9\u03C2 \u03AD\u03C4\u03BF\u03B9\u03BC\u03B5\u03C2",
            ["Install them in Windows Update."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B5\u03C2 \u03B1\u03C0\u03CC \u03C4\u03BF Windows Update.",
            ["Checked at {0}"] = "\u0395\u03BB\u03AD\u03B3\u03C7\u03B8\u03B7\u03BA\u03B5 \u03C3\u03C4\u03B9\u03C2 {0}",
            ["Restart pending"] = "\u0395\u03BA\u03BA\u03C1\u03B5\u03BC\u03B5\u03AF \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["Windows needs a restart to finish an update."] = "\u03A4\u03B1 Windows \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03BF\u03BD\u03C4\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03B3\u03B9\u03B1 \u03BD\u03B1 \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03C3\u03BF\u03C5\u03BD \u03BC\u03B9\u03B1 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7.",
            ["restart required"] = "\u03B1\u03C0\u03B1\u03B9\u03C4\u03B5\u03AF\u03C4\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["restart possible"] = "\u03C0\u03B9\u03B8\u03B1\u03BD\u03AE \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["Check Windows Update"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03BF\u03C5 Windows Update",
            ["Open Windows Update"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 Windows Update",
