            ["Install it under Update & Release."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03C3\u03C4\u03BF \u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 & \u0388\u03BA\u03B4\u03BF\u03C3\u03B7.",
            ["Driver update: {0}"] = "\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 \u03BF\u03B4\u03B7\u03B3\u03BF\u03CD: {0}",
            ["Version {0} is available."] = "\u0397 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 {0} \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03B9\u03B1\u03B8\u03AD\u03C3\u03B9\u03BC\u03B7.",
            ["{0} Windows update(s) waiting"] = "{0} \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7/\u03B5\u03B9\u03C2 Windows \u03C3\u03B5 \u03B1\u03BD\u03B1\u03BC\u03BF\u03BD\u03AE",
            ["No new notifications"] = "\u039A\u03B1\u03BC\u03AF\u03B1 \u03BD\u03AD\u03B1 \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7",
            ["Gamebar Widget Releases"] = "\u0395\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2 widget Gamebar",
            ["Check for updates and notify"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03B3\u03B9\u03B1 \u03B5\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03C3\u03B5\u03B9\u03C2 \u03BA\u03B1\u03B9 \u03B5\u03B9\u03B4\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7",
            ["Status"] = "\u039A\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7",
            ["Uninstall\u2026"] = "\u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u2026",
            ["Steam removes the game files"] = "\u03A4\u03BF Steam \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03AF \u03C4\u03B1 \u03B1\u03C1\u03C7\u03B5\u03AF\u03B1 \u03C4\u03BF\u03C5 \u03C0\u03B1\u03B9\u03C7\u03BD\u03B9\u03B4\u03B9\u03BF\u03CD",
            ["Back to Recent"] = "\u03A0\u03AF\u03C3\u03C9 \u03C3\u03C4\u03B1 \u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1",
            ["Tab visibility & order"] = "\u039F\u03C1\u03B1\u03C4\u03CC\u03C4\u03B7\u03C4\u03B1 \u03BA\u03B1\u03B9 \u03C3\u03B5\u03B9\u03C1\u03AC \u03BA\u03B1\u03C1\u03C4\u03B5\u03BB\u03CE\u03BD",
            ["Favorite"] = "\u0391\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Unfavorite"] = "\u038C\u03C7\u03B9 \u03B1\u03B3\u03B1\u03C0\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Rename\u2026"] = "\u039C\u03B5\u03C4\u03BF\u03BD\u03BF\u03BC\u03B1\u03C3\u03AF\u03B1\u2026",
            ["Rename"] = "\u039C\u03B5\u03C4\u03BF\u03BD\u03BF\u03BC\u03B1\u03C3\u03AF\u03B1",
            ["Remove"] = "\u0391\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7",
            ["Other"] = "\u0386\u03BB\u03BB\u03BF",
            ["Recent immersive"] = "\u03A0\u03C1\u03CC\u03C3\u03C6\u03B1\u03C4\u03B1 \u03BA\u03B1\u03B8\u03B7\u03BB\u03C9\u03C4\u03B9\u03BA\u03AC",
            ["OptiScaler wiki \u00B7 {0}"] = "Wiki \u03C4\u03BF\u03C5 OptiScaler \u00B7 {0}",
            ["Sleep"] = "\u0391\u03BD\u03B1\u03C3\u03C4\u03BF\u03BB\u03AE",
            ["Hibernate"] = "\u0391\u03B4\u03C1\u03B1\u03BD\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7",
            ["Launch"] = "\u0395\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7",
            ["Edit"] = "\u0395\u03C0\u03B5\u03BE\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1",
            ["Auto pre-restore \u2014 {0}"] = "\u0391\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C0\u03C1\u03B9\u03BD \u03C4\u03B7\u03BD \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u2014 {0}",
            ["ClawTweaks {0} \u00B7 {1} \u00B7 {2} stores \u00B7 {3}"] = "ClawTweaks {0} \u00B7 {1} \u00B7 {2} \u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03BC\u03B1\u03C4\u03B1 \u00B7 {3}",
            ["Choose a program"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \u03C0\u03C1\u03CC\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1",
            ["Add"] = "\u03A0\u03C1\u03BF\u03C3\u03B8\u03AE\u03BA\u03B7",
            ["Add {0}"] = "\u03A0\u03C1\u03BF\u03C3\u03B8\u03AE\u03BA\u03B7 {0}",
            ["Open Center"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03C4\u03BF\u03C5 Center",
            ["Open Library"] = "\u0386\u03BD\u03BF\u03B9\u03B3\u03BC\u03B1 \u03B2\u03B9\u03B2\u03BB\u03B9\u03BF\u03B8\u03AE\u03BA\u03B7\u03C2",
            ["Exit Center"] = "\u0388\u03BE\u03BF\u03B4\u03BF\u03C2 Center",
            ["The update could not install itself. Try the button below."] = "\u0397 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 \u03B4\u03B5\u03BD \u03BC\u03C0\u03CC\u03C1\u03B5\u03C3\u03B5 \u03BD\u03B1 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03B1\u03B8\u03B5\u03AF \u03BC\u03CC\u03BD\u03B7 \u03C4\u03B7\u03C2. \u0394\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03C4\u03BF \u03BA\u03BF\u03C5\u03BC\u03C0\u03AF \u03C0\u03B9\u03BF \u03BA\u03AC\u03C4\u03C9.",
            ["Installing\u2026"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u2026",
            ["Install update now"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B5\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7\u03C2 \u03C4\u03CE\u03C1\u03B1",
            ["Version {0} is still installed for all users, in {1}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u0397 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 {0} \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7 \u03B3\u03B9\u03B1 \u03CC\u03BB\u03BF\u03C5\u03C2 \u03C4\u03BF\u03C5\u03C2 \u03C7\u03C1\u03AE\u03C3\u03C4\u03B5\u03C2, \u03C3\u03C4\u03BF {1}. \u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B5\u03B3\u03BA\u03B1\u03B8\u03AF\u03C3\u03C4\u03B1\u03C4\u03B1\u03B9 \u03C3\u03C4\u03BF\u03BD \u03B4\u03B9\u03BA\u03CC \u03C3\u03B1\u03C2 \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF \u03C7\u03C1\u03AE\u03C3\u03C4\u03B7, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03B7 \u03C0\u03B1\u03BB\u03B9\u03AC \u03B4\u03B5\u03BD \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF\u03C4\u03B1\u03B9 \u03C0\u03B9\u03B1 \u2014 \u03BC\u03AD\u03BD\u03B5\u03B9 \u03CC\u03BC\u03C9\u03C2 \u03C3\u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u2192 \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03BA\u03B1\u03B9 \u03C3\u03C4\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD \u0388\u03BD\u03B1\u03C1\u03BE\u03B7 \u03BC\u03AD\u03C7\u03C1\u03B9 \u03BD\u03B1 \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03B8\u03B5\u03AF, \u03CC\u03C0\u03BF\u03C5 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03B5\u03CD\u03BA\u03BF\u03BB\u03B1 \u03BA\u03B1\u03C4\u03AC \u03BB\u03AC\u03B8\u03BF\u03C2.",
            ["A previous version is still installed for all users, in {0}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u039C\u03B9\u03B1 \u03C0\u03C1\u03BF\u03B7\u03B3\u03BF\u03CD\u03BC\u03B5\u03BD\u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7 \u03B3\u03B9\u03B1 \u03CC\u03BB\u03BF\u03C5\u03C2 \u03C4\u03BF\u03C5\u03C2 \u03C7\u03C1\u03AE\u03C3\u03C4\u03B5\u03C2, \u03C3\u03C4\u03BF {0}. \u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B5\u03B3\u03BA\u03B1\u03B8\u03AF\u03C3\u03C4\u03B1\u03C4\u03B1\u03B9 \u03C3\u03C4\u03BF\u03BD \u03B4\u03B9\u03BA\u03CC \u03C3\u03B1\u03C2 \u03C6\u03AC\u03BA\u03B5\u03BB\u03BF \u03C7\u03C1\u03AE\u03C3\u03C4\u03B7, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03B7 \u03C0\u03B1\u03BB\u03B9\u03AC \u03B4\u03B5\u03BD \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF\u03C4\u03B1\u03B9 \u03C0\u03B9\u03B1 \u2014 \u03BC\u03AD\u03BD\u03B5\u03B9 \u03CC\u03BC\u03C9\u03C2 \u03C3\u03C4\u03B9\u03C2 \u03A1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 \u2192 \u0395\u03C6\u03B1\u03C1\u03BC\u03BF\u03B3\u03AD\u03C2 \u03BA\u03B1\u03B9 \u03C3\u03C4\u03BF \u03BC\u03B5\u03BD\u03BF\u03CD \u0388\u03BD\u03B1\u03C1\u03BE\u03B7 \u03BC\u03AD\u03C7\u03C1\u03B9 \u03BD\u03B1 \u03B1\u03C6\u03B1\u03B9\u03C1\u03B5\u03B8\u03B5\u03AF, \u03CC\u03C0\u03BF\u03C5 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03B5\u03CD\u03BA\u03BF\u03BB\u03B1 \u03BA\u03B1\u03C4\u03AC \u03BB\u03AC\u03B8\u03BF\u03C2.",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below starts the old version's own uninstaller, so the prompt you see comes from it, about removing itself."] = "\u0397 \u03B1\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03AE \u03C4\u03B7\u03C2 \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B4\u03B9\u03BA\u03B1\u03B9\u03CE\u03BC\u03B1\u03C4\u03B1 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE. \u03A4\u03BF ClawTweaks Center \u03B4\u03B5\u03BD \u03C4\u03B1 \u03B6\u03B7\u03C4\u03AC \u03C0\u03BF\u03C4\u03AD \u2014 \u03C4\u03BF \u03BA\u03BF\u03C5\u03BC\u03C0\u03AF \u03C0\u03B9\u03BF \u03BA\u03AC\u03C4\u03C9 \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC \u03C4\u03BF \u03C0\u03C1\u03CC\u03B3\u03C1\u03B1\u03BC\u03BC\u03B1 \u03B1\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7\u03C2 \u03C4\u03B7\u03C2 \u03C0\u03B1\u03BB\u03B9\u03AC\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03C4\u03BF \u03BC\u03AE\u03BD\u03C5\u03BC\u03B1 \u03C0\u03BF\u03C5 \u03B2\u03BB\u03AD\u03C0\u03B5\u03C4\u03B5 \u03AD\u03C1\u03C7\u03B5\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03B5\u03BA\u03B5\u03AF\u03BD\u03B7, \u03B3\u03B9\u03B1 \u03C4\u03B7\u03BD \u03B1\u03C6\u03B1\u03AF\u03C1\u03B5\u03C3\u03B7 \u03C4\u03BF\u03C5 \u03B5\u03B1\u03C5\u03C4\u03BF\u03CD \u03C4\u03B7\u03C2.",
            ["Scroll"] = "\u039A\u03CD\u03BB\u03B9\u03C3\u03B7",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller still won't start."] = "\u0391\u03C5\u03C4\u03AC \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03BF\u03B4\u03B7\u03B3\u03BF\u03CD\u03C2 \u03C0\u03C5\u03C1\u03AE\u03BD\u03B1. \u03A7\u03C9\u03C1\u03AF\u03C2 \u03C4\u03B7\u03BD \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7 \u03CC\u03BB\u03B1 \u03C6\u03B1\u03AF\u03BD\u03BF\u03BD\u03C4\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B1 \u03BA\u03B1\u03B9 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B4\u03B5\u03BD \u03BE\u03B5\u03BA\u03B9\u03BD\u03AC.",
            ["Version {0}"] = "\u0388\u03BA\u03B4\u03BF\u03C3\u03B7 {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "\u03A4\u03BF \u03BD\u03AD\u03BF ClawTweaks Center \u03B4\u03B5\u03BD \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B4\u03B9\u03BA\u03B1\u03B9\u03CE\u03BC\u03B1\u03C4\u03B1 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE \u03BA\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03B8\u03AF\u03C3\u03C4\u03B1\u03C4\u03B1\u03B9 \u03C3\u03B5 \u03AC\u03BB\u03BB\u03B7 \u03B8\u03AD\u03C3\u03B7.",
            ["No Xbox games are registered for this account."] = "\u0394\u03B5\u03BD \u03C5\u03C0\u03AC\u03C1\u03C7\u03BF\u03C5\u03BD \u03BA\u03B1\u03C4\u03B1\u03C7\u03C9\u03C1\u03B7\u03BC\u03AD\u03BD\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 Xbox \u03C3\u03B5 \u03B1\u03C5\u03C4\u03CC\u03BD \u03C4\u03BF\u03BD \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03CC.",
            ["No ROMs for {0}."] = "\u039A\u03B1\u03BD\u03AD\u03BD\u03B1 ROM \u03B3\u03B9\u03B1 {0}.",
            ["Cycle"] = "\u039A\u03C5\u03BA\u03BB\u03B9\u03BA\u03AC",
            ["checking the installed version\u2026"] = "\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03B7\u03C2 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B7\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2\u2026",
            ["you have {0}."] = "\u03AD\u03C7\u03B5\u03C4\u03B5 {0}.",
            ["Requires ClawTweaks {0} or newer"] = "\u0391\u03C0\u03B1\u03B9\u03C4\u03B5\u03AF ClawTweaks {0} \u03AE \u03BD\u03B5\u03CC\u03C4\u03B5\u03C1\u03BF",
            ["Reset, Backup and Restore need ClawTweaks {0} (or 0.1.8+) \u2014 {1} Update ClawTweaks from \"Update & Release\" first."] = "\u0397 \u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC, \u03C4\u03BF \u0391\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03BA\u03B1\u03B9 \u03B7 \u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5 \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03BF\u03BD\u03C4\u03B1\u03B9 ClawTweaks {0} (\u03AE 0.1.8+) \u2014 {1} \u0395\u03BD\u03B7\u03BC\u03B5\u03C1\u03CE\u03C3\u03C4\u03B5 \u03C0\u03C1\u03CE\u03C4\u03B1 \u03C4\u03BF ClawTweaks \u03B1\u03C0\u03CC \u03C4\u03BF \"\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7 & \u0388\u03BA\u03B4\u03BF\u03C3\u03B7\".",
            ["Unknown error."] = "\u0386\u03B3\u03BD\u03C9\u03C3\u03C4\u03BF \u03C3\u03C6\u03AC\u03BB\u03BC\u03B1.",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "\u0395\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03B1\u03BD\u03C4\u03B9\u03B3\u03C1\u03AC\u03C6\u03BF\u03C5 \u2014 \u03BF helper \u03B8\u03B1 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9 \u03CC\u03C4\u03B1\u03BD \u03C4\u03B5\u03BB\u03B5\u03B9\u03CE\u03C3\u03B5\u03B9\u2026",
            ["Restore likely completed"] = "\u0397 \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03BF\u03C1\u03AC \u03BC\u03AC\u03BB\u03BB\u03BF\u03BD \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "\u039F helper \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B5 \u03C0\u03C1\u03B9\u03BD \u03B5\u03C0\u03B9\u03B2\u03B5\u03B2\u03B1\u03B9\u03CE\u03C3\u03B5\u03B9. \u0391\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03BF Game Bar (Win+G) \u03BA\u03B1\u03B9 \u03B5\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03C1\u03BF\u03C6\u03AF\u03BB \u03C3\u03B1\u03C2 \u2014 \u03B1\u03BD \u03BA\u03AC\u03C4\u03B9 \u03B4\u03B5\u03BD \u03C6\u03B1\u03AF\u03BD\u03B5\u03C4\u03B1\u03B9 \u03C3\u03C9\u03C3\u03C4\u03CC, \u03B5\u03C0\u03B1\u03BD\u03B1\u03C6\u03AD\u03C1\u03B5\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C5\u03C4\u03CC\u03BC\u03B1\u03C4\u03BF \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF.",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "\u0391\u03C5\u03C4\u03CC \u03C4\u03BF ZIP \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03AD\u03B3\u03BA\u03C5\u03C1\u03BF \u03BC\u03B1\u03BD\u03B9\u03C6\u03AD\u03C3\u03C4\u03BF ClawTweaks \u2014 \u03BF helper \u03B8\u03B1 \u03C4\u03BF \u03B1\u03C0\u03BF\u03C1\u03C1\u03AF\u03C8\u03B5\u03B9 \u03B1\u03BD \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03C1\u03B1\u03B3\u03BC\u03B1\u03C4\u03B9\u03BA\u03CC \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF.",
            ["Different ClawTweaks version"] = "\u0394\u03B9\u03B1\u03C6\u03BF\u03C1\u03B5\u03C4\u03B9\u03BA\u03AE \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 ClawTweaks",
            ["Supported."] = "\u03A5\u03C0\u03BF\u03C3\u03C4\u03B7\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9.",
            ["Recognized, but not supported yet."] = "\u0391\u03BD\u03B1\u03B3\u03BD\u03C9\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9, \u03B1\u03BB\u03BB\u03AC \u03B4\u03B5\u03BD \u03C5\u03C0\u03BF\u03C3\u03C4\u03B7\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03B1\u03BA\u03CC\u03BC\u03B7.",
            ["Not a recognized MSI Claw \u2014 installing here is untested."] = "\u0394\u03B5\u03BD \u03B1\u03BD\u03B1\u03B3\u03BD\u03C9\u03C1\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03C9\u03C2 MSI Claw \u2014 \u03B7 \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03B5\u03B4\u03CE \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B1\u03B4\u03BF\u03BA\u03AF\u03BC\u03B1\u03C3\u03C4\u03B7.",
            ["Install the missing prerequisites"] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03C1\u03BF\u03B1\u03C0\u03B1\u03B9\u03C4\u03BF\u03CD\u03BC\u03B5\u03BD\u03B1 \u03C0\u03BF\u03C5 \u03BB\u03B5\u03AF\u03C0\u03BF\u03C5\u03BD",
            ["Download each one from the vendor and run their installer, then re-check."] = "\u039A\u03B1\u03C4\u03B5\u03B2\u03AC\u03C3\u03C4\u03B5 \u03BA\u03B1\u03B8\u03AD\u03BD\u03B1 \u03B1\u03C0\u03CC \u03C4\u03BF\u03BD \u03BA\u03B1\u03C4\u03B1\u03C3\u03BA\u03B5\u03C5\u03B1\u03C3\u03C4\u03AE, \u03C4\u03C1\u03AD\u03BE\u03C4\u03B5 \u03C4\u03BF\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03C4\u03B7 \u03C4\u03BF\u03C5\u03C2 \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03BA\u03AC\u03BD\u03C4\u03B5 \u03B5\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF.",
            ["Re-check and continue"] = "\u0395\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03BA\u03B1\u03B9 \u03C3\u03C5\u03BD\u03AD\u03C7\u03B5\u03B9\u03B1",
            ["Re-check tools"] = "\u0395\u03C0\u03B1\u03BD\u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03B5\u03C1\u03B3\u03B1\u03BB\u03B5\u03AF\u03C9\u03BD",
            ["Trust the ClawTweaks signing certificate"] = "\u039A\u03AC\u03BD\u03C4\u03B5 \u03AD\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03B3\u03C1\u03B1\u03C6\u03AE\u03C2 \u03C4\u03BF\u03C5 ClawTweaks",
            ["ClawTweaks is signed with its own certificate, and Windows only installs a package whose certificate it trusts. You only have to do this once \u2014 every future build uses the same one."] = "\u03A4\u03BF ClawTweaks \u03C5\u03C0\u03BF\u03B3\u03C1\u03AC\u03C6\u03B5\u03C4\u03B1\u03B9 \u03BC\u03B5 \u03B4\u03B9\u03BA\u03CC \u03C4\u03BF\u03C5 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03BA\u03B1\u03B9 \u03C4\u03B1 Windows \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03BC\u03CC\u03BD\u03BF \u03B1\u03BD \u03B5\u03BC\u03C0\u03B9\u03C3\u03C4\u03B5\u03CD\u03BF\u03BD\u03C4\u03B1\u03B9 \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03C4\u03BF\u03C5. \u03A7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03BC\u03AF\u03B1 \u03BC\u03CC\u03BD\u03BF \u03C6\u03BF\u03C1\u03AC \u2014 \u03BA\u03AC\u03B8\u03B5 \u03BC\u03B5\u03BB\u03BB\u03BF\u03BD\u03C4\u03B9\u03BA\u03AE \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03C7\u03C1\u03B7\u03C3\u03B9\u03BC\u03BF\u03C0\u03BF\u03B9\u03B5\u03AF \u03C4\u03BF \u03AF\u03B4\u03B9\u03BF.",
            ["The certificate was imported for your user account instead of the local machine. Windows only consults the machine store when installing a package, so this has no effect. Run the import again and pick \"Local Machine\" on the first page."] = "\u03A4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03B5\u03B9\u03C3\u03AE\u03C7\u03B8\u03B7 \u03B3\u03B9\u03B1 \u03C4\u03BF\u03BD \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03CC \u03C7\u03C1\u03AE\u03C3\u03C4\u03B7 \u03C3\u03B1\u03C2 \u03B1\u03BD\u03C4\u03AF \u03B3\u03B9\u03B1 \u03C4\u03BF\u03BD \u03C4\u03BF\u03C0\u03B9\u03BA\u03CC \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE. \u03A4\u03B1 Windows \u03C3\u03C5\u03BC\u03B2\u03BF\u03C5\u03BB\u03B5\u03CD\u03BF\u03BD\u03C4\u03B1\u03B9 \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF\u03BD \u03C7\u03CE\u03C1\u03BF \u03C4\u03BF\u03C5 \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE \u03CC\u03C4\u03B1\u03BD \u03B5\u03B3\u03BA\u03B1\u03B8\u03B9\u03C3\u03C4\u03BF\u03CD\u03BD \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03B1\u03C5\u03C4\u03CC \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03B1\u03C0\u03BF\u03C4\u03AD\u03BB\u03B5\u03C3\u03BC\u03B1. \u039A\u03AC\u03BD\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03B7\u03BD \u03B5\u03B9\u03C3\u03B1\u03B3\u03C9\u03B3\u03AE \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \"\u03A4\u03BF\u03C0\u03B9\u03BA\u03CC\u03C2 \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE\u03C2\" \u03C3\u03C4\u03B7\u03BD \u03C0\u03C1\u03CE\u03C4\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1.",
            ["The certificate landed in \"Trusted Root Certification Authorities\". That is both more than ClawTweaks needs \u2014 it would make this certificate a trust anchor for anything, not just this package \u2014 and still not where Windows looks. Remove it from there and import it into \"Trusted People\" instead."] = "\u03A4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03BA\u03B1\u03C4\u03AD\u03BB\u03B7\u03BE\u03B5 \u03C3\u03C4\u03B9\u03C2 \"\u0388\u03BC\u03C0\u03B9\u03C3\u03C4\u03B5\u03C2 \u03B1\u03C1\u03C7\u03AD\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CE\u03BD \u03C1\u03AF\u03B6\u03B1\u03C2\". \u0391\u03C5\u03C4\u03CC \u03B5\u03AF\u03BD\u03B1\u03B9 \u03BA\u03B1\u03B9 \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03BF \u03B1\u03C0\u03CC \u03CC\u03C3\u03BF \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 \u03C4\u03BF ClawTweaks \u2014 \u03B8\u03B1 \u03AD\u03BA\u03B1\u03BD\u03B5 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03AC\u03B3\u03BA\u03C5\u03C1\u03B1 \u03B5\u03BC\u03C0\u03B9\u03C3\u03C4\u03BF\u03C3\u03CD\u03BD\u03B7\u03C2 \u03B3\u03B9\u03B1 \u03C4\u03B1 \u03C0\u03AC\u03BD\u03C4\u03B1, \u03CC\u03C7\u03B9 \u03BC\u03CC\u03BD\u03BF \u03B3\u03B9\u03B1 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u2014 \u03BA\u03B1\u03B9 \u03C0\u03AC\u03BB\u03B9 \u03CC\u03C7\u03B9 \u03B5\u03BA\u03B5\u03AF \u03C0\u03BF\u03C5 \u03BA\u03BF\u03B9\u03C4\u03BF\u03CD\u03BD \u03C4\u03B1 Windows. \u0391\u03C6\u03B1\u03B9\u03C1\u03AD\u03C3\u03C4\u03B5 \u03C4\u03BF \u03B1\u03C0\u03CC \u03B5\u03BA\u03B5\u03AF \u03BA\u03B1\u03B9 \u03B5\u03B9\u03C3\u03B1\u03B3\u03AC\u03B3\u03B5\u03C4\u03AD \u03C4\u03BF \u03C3\u03C4\u03B1 \"\u0388\u03BC\u03C0\u03B9\u03C3\u03C4\u03B1 \u03AC\u03C4\u03BF\u03BC\u03B1\".",
            ["Check the certificate and continue"] = "\u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03BF \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CC \u03BA\u03B1\u03B9 \u03C3\u03C5\u03BD\u03B5\u03C7\u03AF\u03C3\u03C4\u03B5",
            ["Check certificate"] = "\u0388\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03BF\u03CD",
            ["Installed, but the helper did not appear in time \u2014 open the Game Bar (Win+G) manually."] = "\u0395\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03B8\u03B7\u03BA\u03B5, \u03B1\u03BB\u03BB\u03AC \u03BF helper \u03B4\u03B5\u03BD \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B5\u03B3\u03BA\u03B1\u03AF\u03C1\u03C9\u03C2 \u2014 \u03B1\u03BD\u03BF\u03AF\u03BE\u03C4\u03B5 \u03C7\u03B5\u03B9\u03C1\u03BF\u03BA\u03AF\u03BD\u03B7\u03C4\u03B1 \u03C4\u03BF Game Bar (Win+G).",
            ["Virtual pad"] = "\u0395\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF",
            ["Virtual controller mode detected"] = "\u0395\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03AE \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["{0} active and running."] = "\u03A4\u03BF {0} \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03CC \u03BA\u03B1\u03B9 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9.",
            ["HW controller mode detected"] = "\u0395\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C5\u03BB\u03B9\u03BA\u03BF\u03CD \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["MSI HW Controller active and running."] = "\u03A4\u03BF \u03C5\u03BB\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF MSI \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03BD\u03B5\u03C1\u03B3\u03CC \u03BA\u03B1\u03B9 \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9.",
            ["Claw controller not detected."] = "\u0394\u03B5\u03BD \u03B5\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF Claw.",
            ["Controller mode unknown"] = "\u0386\u03B3\u03BD\u03C9\u03C3\u03C4\u03B7 \u03BB\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5",
            ["The download did not complete. Check your internet connection and try again."] = "\u0397 \u03BB\u03AE\u03C8\u03B7 \u03B4\u03B5\u03BD \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5. \u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03B7 \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03AE \u03C3\u03B1\u03C2 \u03BA\u03B1\u03B9 \u03B4\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC.",
            ["This version has no package to download."] = "\u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03B4\u03B5\u03BD \u03AD\u03C7\u03B5\u03B9 \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03B3\u03B9\u03B1 \u03BB\u03AE\u03C8\u03B7.",
            ["Download complete."] = "\u0397 \u03BB\u03AE\u03C8\u03B7 \u03BF\u03BB\u03BF\u03BA\u03BB\u03B7\u03C1\u03CE\u03B8\u03B7\u03BA\u03B5.",
            ["The download contains no package file."] = "\u0397 \u03BB\u03AE\u03C8\u03B7 \u03B4\u03B5\u03BD \u03C0\u03B5\u03C1\u03B9\u03AD\u03C7\u03B5\u03B9 \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF\u03C5.",
            ["The downloaded package is incomplete \u2014 its manifest is missing."] = "\u03A4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03C0\u03BF\u03C5 \u03BA\u03B1\u03C4\u03AD\u03B2\u03B7\u03BA\u03B5 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03BB\u03BB\u03B9\u03C0\u03AD\u03C2 \u2014 \u03BB\u03B5\u03AF\u03C0\u03B5\u03B9 \u03C4\u03BF \u03BC\u03B1\u03BD\u03B9\u03C6\u03AD\u03C3\u03C4\u03BF \u03C4\u03BF\u03C5.",
            ["The downloaded package is not readable."] = "\u03A4\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u03C0\u03BF\u03C5 \u03BA\u03B1\u03C4\u03AD\u03B2\u03B7\u03BA\u03B5 \u03B4\u03B5\u03BD \u03B4\u03B9\u03B1\u03B2\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9.",
            ["(received {0:N0} of {1:N0} bytes)"] = "(\u03B5\u03BB\u03AE\u03C6\u03B8\u03B7\u03C3\u03B1\u03BD {0:N0} \u03B1\u03C0\u03CC {1:N0} bytes)",
            ["The download produced an empty file."] = "\u0397 \u03BB\u03AE\u03C8\u03B7 \u03C0\u03B1\u03C1\u03AE\u03B3\u03B1\u03B3\u03B5 \u03BA\u03B5\u03BD\u03CC \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF.",
            ["Click \"Install Certificate\u2026\" on the General tab."] = "\u03A0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \"\u0395\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03BF\u03CD\u2026\" \u03C3\u03C4\u03B7\u03BD \u03BA\u03B1\u03C1\u03C4\u03AD\u03BB\u03B1 \u0393\u03B5\u03BD\u03B9\u03BA\u03AC.",
            ["Store Location: choose \"Local Machine\" (not \"Current User\"), then Next. Windows asks for administrator rights here \u2014 that prompt comes from Windows itself."] = "\u0398\u03AD\u03C3\u03B7 \u03C7\u03CE\u03C1\u03BF\u03C5 \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03B7\u03C2: \u03B5\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \"\u03A4\u03BF\u03C0\u03B9\u03BA\u03CC\u03C2 \u03C5\u03C0\u03BF\u03BB\u03BF\u03B3\u03B9\u03C3\u03C4\u03AE\u03C2\" (\u03CC\u03C7\u03B9 \"\u03A4\u03C1\u03AD\u03C7\u03C9\u03BD \u03C7\u03C1\u03AE\u03C3\u03C4\u03B7\u03C2\") \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u0395\u03C0\u03CC\u03BC\u03B5\u03BD\u03BF. \u0395\u03B4\u03CE \u03C4\u03B1 Windows \u03B6\u03B7\u03C4\u03BF\u03CD\u03BD \u03B4\u03B9\u03BA\u03B1\u03B9\u03CE\u03BC\u03B1\u03C4\u03B1 \u03B4\u03B9\u03B1\u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE \u2014 \u03B1\u03C5\u03C4\u03CC \u03C4\u03BF \u03BC\u03AE\u03BD\u03C5\u03BC\u03B1 \u03AD\u03C1\u03C7\u03B5\u03C4\u03B1\u03B9 \u03B1\u03C0\u03CC \u03C4\u03B1 \u03AF\u03B4\u03B9\u03B1 \u03C4\u03B1 Windows.",
            ["Choose \"Place all certificates in the following store\", click Browse\u2026"] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \"\u03A4\u03BF\u03C0\u03BF\u03B8\u03AD\u03C4\u03B7\u03C3\u03B7 \u03CC\u03BB\u03C9\u03BD \u03C4\u03C9\u03BD \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CE\u03BD \u03C3\u03C4\u03BF\u03BD \u03C0\u03B1\u03C1\u03B1\u03BA\u03AC\u03C4\u03C9 \u03C7\u03CE\u03C1\u03BF \u03B1\u03C0\u03BF\u03B8\u03AE\u03BA\u03B5\u03C5\u03C3\u03B7\u03C2\" \u03BA\u03B1\u03B9 \u03C0\u03B1\u03C4\u03AE\u03C3\u03C4\u03B5 \u0391\u03BD\u03B1\u03B6\u03AE\u03C4\u03B7\u03C3\u03B7\u2026",
            ["Select \"Trusted People\" \u2014 NOT \"Trusted Root Certification Authorities\"."] = "\u0395\u03C0\u03B9\u03BB\u03AD\u03BE\u03C4\u03B5 \"\u0388\u03BC\u03C0\u03B9\u03C3\u03C4\u03B1 \u03AC\u03C4\u03BF\u03BC\u03B1\" \u2014 \u039F\u03A7\u0399 \"\u0388\u03BC\u03C0\u03B9\u03C3\u03C4\u03B5\u03C2 \u03B1\u03C1\u03C7\u03AD\u03C2 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7\u03C2 \u03C0\u03B9\u03C3\u03C4\u03BF\u03C0\u03BF\u03B9\u03B7\u03C4\u03B9\u03BA\u03CE\u03BD \u03C1\u03AF\u03B6\u03B1\u03C2\".",
            ["Next, then Finish. You should see \"The import was successful.\""] = "\u0395\u03C0\u03CC\u03BC\u03B5\u03BD\u03BF \u03BA\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03A4\u03AD\u03BB\u03BF\u03C2. \u0398\u03B1 \u03B4\u03B5\u03AF\u03C4\u03B5 \"\u0397 \u03B5\u03B9\u03C3\u03B1\u03B3\u03C9\u03B3\u03AE \u03AE\u03C4\u03B1\u03BD \u03B5\u03C0\u03B9\u03C4\u03C5\u03C7\u03AE\u03C2.\"",
            ["Controller probe timed out."] = "\u039B\u03AE\u03BE\u03B7 \u03C7\u03C1\u03CC\u03BD\u03BF\u03C5 \u03C3\u03C4\u03BF\u03BD \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5.",
            ["Controller probe failed: {0}"] = "\u039F \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u03C2 \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5: {0}",
            ["MSI Claw controller not detected (VID_0DB0). Connect/enable the controller, or MSI Center M may have taken it over."] = "\u0394\u03B5\u03BD \u03B5\u03BD\u03C4\u03BF\u03C0\u03AF\u03C3\u03C4\u03B7\u03BA\u03B5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF MSI Claw (VID_0DB0). \u03A3\u03C5\u03BD\u03B4\u03AD\u03C3\u03C4\u03B5/\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03AE \u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C4\u03BF \u03AD\u03C7\u03B5\u03B9 \u03C0\u03AC\u03C1\u03B5\u03B9 \u03C4\u03BF MSI Center M.",
            ["MSI Center M is running. It can fight ClawTweaks for the controller and LED. This is handled after installation."] = "\u03A4\u03BF MSI Center M \u03B5\u03BA\u03C4\u03B5\u03BB\u03B5\u03AF\u03C4\u03B1\u03B9. \u039C\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03B4\u03B9\u03B5\u03BA\u03B4\u03B9\u03BA\u03AE\u03C3\u03B5\u03B9 \u03C4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03BA\u03B1\u03B9 \u03C4\u03BF LED \u03B1\u03C0\u03CC \u03C4\u03BF ClawTweaks. \u0391\u03C5\u03C4\u03CC \u03C1\u03C5\u03B8\u03BC\u03AF\u03B6\u03B5\u03C4\u03B1\u03B9 \u03BC\u03B5\u03C4\u03AC \u03C4\u03B7\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03AC\u03C3\u03C4\u03B1\u03C3\u03B7.",
            ["Steam's Xbox controller filter driver is present \u2014 a common cause of double input. Check Steam Input settings if you see doubled inputs."] = "\u03A5\u03C0\u03AC\u03C1\u03C7\u03B5\u03B9 \u03BF \u03BF\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C6\u03AF\u03BB\u03C4\u03C1\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 Xbox \u03C4\u03BF\u03C5 Steam \u2014 \u03C3\u03C5\u03BD\u03B7\u03B8\u03B9\u03C3\u03BC\u03AD\u03BD\u03B7 \u03B1\u03B9\u03C4\u03AF\u03B1 \u03B4\u03B9\u03C0\u03BB\u03AE\u03C2 \u03B5\u03B9\u03C3\u03CC\u03B4\u03BF\u03C5. \u0395\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03C4\u03B9\u03C2 \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03B9\u03C2 Steam Input \u03B1\u03BD \u03B2\u03BB\u03AD\u03C0\u03B5\u03C4\u03B5 \u03B4\u03B9\u03C0\u03BB\u03AD\u03C2 \u03B5\u03B9\u03C3\u03CC\u03B4\u03BF\u03C5\u03C2.",
            ["{0} XInput controllers are currently visible. Two or more while playing = double input."] = "\u0391\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03C4\u03B9\u03B3\u03BC\u03AE \u03C6\u03B1\u03AF\u03BD\u03BF\u03BD\u03C4\u03B1\u03B9 {0} \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03B1 XInput. \u0394\u03CD\u03BF \u03AE \u03C0\u03B5\u03C1\u03B9\u03C3\u03C3\u03CC\u03C4\u03B5\u03C1\u03B1 \u03C3\u03C4\u03BF \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9 = \u03B4\u03B9\u03C0\u03BB\u03AE \u03B5\u03AF\u03C3\u03BF\u03B4\u03BF\u03C2.",
            ["Controller healthy \u2014 ready to mount as a virtual pad."] = "\u03A4\u03BF \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C5\u03B3\u03B9\u03AD\u03C2 \u2014 \u03AD\u03C4\u03BF\u03B9\u03BC\u03BF \u03BD\u03B1 \u03C3\u03C5\u03BD\u03B4\u03B5\u03B8\u03B5\u03AF \u03C9\u03C2 \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC.",
            ["MSI Claw controller not found. Connect/enable it (MSI Center M may hold it)."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF MSI Claw. \u03A3\u03C5\u03BD\u03B4\u03AD\u03C3\u03C4\u03B5/\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF (\u03BC\u03C0\u03BF\u03C1\u03B5\u03AF \u03BD\u03B1 \u03C4\u03BF \u03BA\u03C1\u03B1\u03C4\u03AC \u03C4\u03BF MSI Center M).",
            ["Controller HID is held by another process \u2014 close conflicting controller software and re-check."] = "\u03A4\u03BF HID \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03C4\u03BF \u03BA\u03C1\u03B1\u03C4\u03AC \u03AC\u03BB\u03BB\u03B7 \u03B4\u03B9\u03B5\u03C1\u03B3\u03B1\u03C3\u03AF\u03B1 \u2014 \u03BA\u03BB\u03B5\u03AF\u03C3\u03C4\u03B5 \u03BB\u03BF\u03B3\u03B9\u03C3\u03BC\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03C0\u03BF\u03C5 \u03C3\u03C5\u03B3\u03BA\u03C1\u03BF\u03CD\u03B5\u03C4\u03B1\u03B9 \u03BA\u03B1\u03B9 \u03B5\u03BB\u03AD\u03B3\u03BE\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC.",
            ["Controller HID opened but did not respond \u2014 try re-checking; a reboot may be needed."] = "\u03A4\u03BF HID \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5 \u03AC\u03BD\u03BF\u03B9\u03BE\u03B5 \u03B1\u03BB\u03BB\u03AC \u03B4\u03B5\u03BD \u03B1\u03C0\u03AC\u03BD\u03C4\u03B7\u03C3\u03B5 \u2014 \u03B4\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03C4\u03B5 \u03BD\u03AD\u03BF \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF\u00B7 \u03AF\u03C3\u03C9\u03C2 \u03C7\u03C1\u03B5\u03B9\u03B1\u03C3\u03C4\u03B5\u03AF \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03AF\u03BD\u03B7\u03C3\u03B7.",
            ["Could not determine controller health."] = "\u0394\u03B5\u03BD \u03B4\u03B9\u03B1\u03C0\u03B9\u03C3\u03C4\u03CE\u03B8\u03B7\u03BA\u03B5 \u03B7 \u03C5\u03B3\u03B5\u03AF\u03B1 \u03C4\u03BF\u03C5 \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03B7\u03C1\u03AF\u03BF\u03C5.",
            ["The helper did not answer the health probe."] = "\u039F helper \u03B4\u03B5\u03BD \u03B1\u03C0\u03AC\u03BD\u03C4\u03B7\u03C3\u03B5 \u03C3\u03C4\u03BF\u03BD \u03AD\u03BB\u03B5\u03B3\u03C7\u03BF \u03C5\u03B3\u03B5\u03AF\u03B1\u03C2.",
            ["Unknown device"] = "\u0386\u03B3\u03BD\u03C9\u03C3\u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE",
            ["Could not locate the installed package \u2014 helper files not deployed."] = "\u0394\u03B5\u03BD \u03B2\u03C1\u03AD\u03B8\u03B7\u03BA\u03B5 \u03C4\u03BF \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03C0\u03B1\u03BA\u03AD\u03C4\u03BF \u2014 \u03C4\u03B1 \u03B1\u03C1\u03C7\u03B5\u03AF\u03B1 \u03C4\u03BF\u03C5 helper \u03B4\u03B5\u03BD \u03B1\u03BD\u03B1\u03C0\u03C4\u03CD\u03C7\u03B8\u03B7\u03BA\u03B1\u03BD.",
            ["Helper files were not deployed \u2014 the widget will retry when it starts the helper."] = "\u03A4\u03B1 \u03B1\u03C1\u03C7\u03B5\u03AF\u03B1 \u03C4\u03BF\u03C5 helper \u03B4\u03B5\u03BD \u03B1\u03BD\u03B1\u03C0\u03C4\u03CD\u03C7\u03B8\u03B7\u03BA\u03B1\u03BD \u2014 \u03C4\u03BF widget \u03B8\u03B1 \u03BE\u03B1\u03BD\u03B1\u03B4\u03BF\u03BA\u03B9\u03BC\u03AC\u03C3\u03B5\u03B9 \u03CC\u03C4\u03B1\u03BD \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9 \u03C4\u03BF\u03BD helper.",
            ["The helper is not answering."] = "\u039F helper \u03B4\u03B5\u03BD \u03B1\u03C0\u03B1\u03BD\u03C4\u03AC.",
            ["A backup of your settings is at {0}"] = "\u0388\u03BD\u03B1 \u03B1\u03BD\u03C4\u03AF\u03B3\u03C1\u03B1\u03C6\u03BF \u03C4\u03C9\u03BD \u03C1\u03C5\u03B8\u03BC\u03AF\u03C3\u03B5\u03CE\u03BD \u03C3\u03B1\u03C2 \u03B2\u03C1\u03AF\u03C3\u03BA\u03B5\u03C4\u03B1\u03B9 \u03C3\u03C4\u03BF {0}",
            ["Could not connect to the helper."] = "\u0394\u03B5\u03BD \u03AE\u03C4\u03B1\u03BD \u03B4\u03C5\u03BD\u03B1\u03C4\u03AE \u03B7 \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03B7 \u03BC\u03B5 \u03C4\u03BF\u03BD helper.",
            ["The helper did not respond in time."] = "\u039F helper \u03B4\u03B5\u03BD \u03B1\u03C0\u03AC\u03BD\u03C4\u03B7\u03C3\u03B5 \u03B5\u03B3\u03BA\u03B1\u03AF\u03C1\u03C9\u03C2.",
            ["Disabling\u2026"] = "\u0391\u03C0\u03B5\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7\u2026",
            ["Disabled."] = "\u0391\u03BD\u03B5\u03BD\u03B5\u03C1\u03B3\u03CC.",
            ["Enabling\u2026"] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03AF\u03B7\u03C3\u03B7\u2026",
            ["Enabled and verified ({0})."] = "\u0395\u03BD\u03B5\u03C1\u03B3\u03BF\u03C0\u03BF\u03B9\u03AE\u03B8\u03B7\u03BA\u03B5 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BB\u03B7\u03B8\u03B5\u03CD\u03C4\u03B7\u03BA\u03B5 ({0}).",
            ["virtual pad"] = "\u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF",
            ["Hides the physical gamepad so games see only the virtual controller."] = "\u039A\u03C1\u03CD\u03B2\u03B5\u03B9 \u03C4\u03BF \u03C6\u03C5\u03C3\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF \u03CE\u03C3\u03C4\u03B5 \u03C4\u03B1 \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9\u03B1 \u03BD\u03B1 \u03B2\u03BB\u03AD\u03C0\u03BF\u03C5\u03BD \u03BC\u03CC\u03BD\u03BF \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC.",
            ["Take HidHide_x.x.x.x_x64.exe."] = "\u03A0\u03AC\u03C1\u03C4\u03B5 \u03C4\u03BF HidHide_x.x.x.x_x64.exe.",
            ["Provides the virtual controller itself (the VIIPER backend)."] = "\u03A0\u03B1\u03C1\u03AD\u03C7\u03B5\u03B9 \u03C4\u03BF \u03AF\u03B4\u03B9\u03BF \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF (\u03C4\u03BF backend VIIPER).",
            ["Take USBip-0.9.8.0-x64.exe from this page. The link opens version 0.9.8.0 deliberately \u2014 it is the version ClawTweaks supports."] = "\u03A0\u03AC\u03C1\u03C4\u03B5 \u03C4\u03BF USBip-0.9.8.0-x64.exe \u03B1\u03C0\u03CC \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1. \u039F \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03BC\u03BF\u03C2 \u03B1\u03BD\u03BF\u03AF\u03B3\u03B5\u03B9 \u03C3\u03BA\u03CC\u03C0\u03B9\u03BC\u03B1 \u03C4\u03B7\u03BD \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 0.9.8.0 \u2014 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03C0\u03BF\u03C5 \u03C5\u03C0\u03BF\u03C3\u03C4\u03B7\u03C1\u03AF\u03B6\u03B5\u03B9 \u03C4\u03BF ClawTweaks.",
            ["Do not download the ARM version, and do not take an older usbip release: below 0.9.8.0 the device blue-screens while the virtual controller runs."] = "\u039C\u03B7\u03BD \u03BA\u03B1\u03C4\u03B5\u03B2\u03AC\u03C3\u03B5\u03C4\u03B5 \u03C4\u03B7\u03BD \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 ARM \u03BA\u03B1\u03B9 \u03BC\u03B7\u03BD \u03C0\u03AC\u03C1\u03B5\u03C4\u03B5 \u03C0\u03B1\u03BB\u03B9\u03CC\u03C4\u03B5\u03C1\u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 usbip: \u03BA\u03AC\u03C4\u03C9 \u03B1\u03C0\u03CC 0.9.8.0 \u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03BA\u03AC\u03BD\u03B5\u03B9 \u03BC\u03C0\u03BB\u03B5 \u03BF\u03B8\u03CC\u03BD\u03B7 \u03CC\u03C3\u03BF \u03C4\u03C1\u03AD\u03C7\u03B5\u03B9 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF.",
            ["Applies the per-game FPS cap and draws the on-screen display."] = "\u0395\u03C6\u03B1\u03C1\u03BC\u03CC\u03B6\u03B5\u03B9 \u03C4\u03BF \u03CC\u03C1\u03B9\u03BF FPS \u03B1\u03BD\u03AC \u03C0\u03B1\u03B9\u03C7\u03BD\u03AF\u03B4\u03B9 \u03BA\u03B1\u03B9 \u03C3\u03C7\u03B5\u03B4\u03B9\u03AC\u03B6\u03B5\u03B9 \u03C4\u03B7\u03BD \u03B5\u03BC\u03C6\u03AC\u03BD\u03B9\u03C3\u03B7 \u03C3\u03C4\u03B7\u03BD \u03BF\u03B8\u03CC\u03BD\u03B7.",
            ["Take RivaTuner Statistics Server."] = "\u03A0\u03AC\u03C1\u03C4\u03B5 \u03C4\u03BF RivaTuner Statistics Server.",
            ["Reads the CPU sensors ClawTweaks shows in the widget."] = "\u0394\u03B9\u03B1\u03B2\u03AC\u03B6\u03B5\u03B9 \u03C4\u03BF\u03C5\u03C2 \u03B1\u03B9\u03C3\u03B8\u03B7\u03C4\u03AE\u03C1\u03B5\u03C2 CPU \u03C0\u03BF\u03C5 \u03B4\u03B5\u03AF\u03C7\u03BD\u03B5\u03B9 \u03C4\u03BF ClawTweaks \u03C3\u03C4\u03BF widget.",
            ["Take PawnIO Setup."] = "\u03A0\u03AC\u03C1\u03C4\u03B5 \u03C4\u03BF PawnIO Setup.",
            ["This ClawTweaks Center build is outdated. Please download the latest build."] = "\u0391\u03C5\u03C4\u03AE \u03B7 \u03AD\u03BA\u03B4\u03BF\u03C3\u03B7 \u03C4\u03BF\u03C5 ClawTweaks Center \u03B5\u03AF\u03BD\u03B1\u03B9 \u03C0\u03B1\u03C1\u03C9\u03C7\u03B7\u03BC\u03AD\u03BD\u03B7. \u039A\u03B1\u03C4\u03B5\u03B2\u03AC\u03C3\u03C4\u03B5 \u03C4\u03B7 \u03BD\u03B5\u03CC\u03C4\u03B5\u03C1\u03B7.",
            ["{0} (running {1}, needs {2}+)"] = "{0} (\u03C4\u03C1\u03AD\u03C7\u03B5\u03B9 {1}, \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 {2}+)",
            ["Test build"] = "\u0394\u03BF\u03BA\u03B9\u03BC\u03B1\u03C3\u03C4\u03B9\u03BA\u03AE",
            ["BROKEN: leftover registry entries but no driver binary \u2014 reinstall and reboot"] = "\u03A7\u0391\u039B\u0391\u03A3\u039C\u0395\u039D\u039F: \u03C5\u03C0\u03BF\u03BB\u03B5\u03AF\u03BC\u03BC\u03B1\u03C4\u03B1 \u03C3\u03C4\u03BF \u03BC\u03B7\u03C4\u03C1\u03CE\u03BF \u03B1\u03BB\u03BB\u03AC \u03BA\u03B1\u03BD\u03AD\u03BD\u03B1 \u03B1\u03C1\u03C7\u03B5\u03AF\u03BF \u03BF\u03B4\u03B7\u03B3\u03BF\u03CD \u2014 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5",
            ["BROKEN: usbip's files are installed but its driver is not registered \u2014 the installer's driver step (devnode.exe) failed. The usual cause is the -arm64 download, which the release page lists above the x64 one. Uninstall usbip, re-run the installer whose name ends in -x64.exe, and reboot."] = "\u03A7\u0391\u039B\u0391\u03A3\u039C\u0395\u039D\u039F: \u03C4\u03B1 \u03B1\u03C1\u03C7\u03B5\u03AF\u03B1 \u03C4\u03BF\u03C5 usbip \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03B1 \u03B1\u03BB\u03BB\u03AC \u03BF \u03BF\u03B4\u03B7\u03B3\u03CC\u03C2 \u03C4\u03BF\u03C5 \u03B4\u03B5\u03BD \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B4\u03B7\u03BB\u03C9\u03BC\u03AD\u03BD\u03BF\u03C2 \u2014 \u03B1\u03C0\u03AD\u03C4\u03C5\u03C7\u03B5 \u03C4\u03BF \u03B2\u03AE\u03BC\u03B1 \u03BF\u03B4\u03B7\u03B3\u03BF\u03CD \u03C4\u03BF\u03C5 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03C4\u03B7 (devnode.exe). \u03A3\u03C5\u03BD\u03AE\u03B8\u03B7\u03C2 \u03B1\u03B9\u03C4\u03AF\u03B1 \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B7 \u03BB\u03AE\u03C8\u03B7 -arm64, \u03C0\u03BF\u03C5 \u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03C9\u03BD \u03B5\u03BC\u03C6\u03B1\u03BD\u03AF\u03B6\u03B5\u03B9 \u03C0\u03AC\u03BD\u03C9 \u03B1\u03C0\u03CC \u03C4\u03B7\u03BD x64. \u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF usbip, \u03C4\u03C1\u03AD\u03BE\u03C4\u03B5 \u03BE\u03B1\u03BD\u03AC \u03C4\u03BF\u03BD \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AC\u03C4\u03B7 \u03C0\u03BF\u03C5 \u03C4\u03B5\u03BB\u03B5\u03B9\u03CE\u03BD\u03B5\u03B9 \u03C3\u03B5 -x64.exe \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5.",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Older versions crash the device with a blue screen while the virtual controller is running, so ClawTweaks will not start it. Run the ClawTweaks setup, or install {1} from the link on this page, and reboot."] = "\u039C\u0397 \u03A5\u03A0\u039F\u03A3\u03A4\u0397\u03A1\u0399\u0396\u039F\u039C\u0395\u039D\u0397 \u0395\u039A\u0394\u039F\u03A3\u0397: \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03C4\u03BF usbip {0}, \u03C4\u03BF ClawTweaks \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 {1}. \u039F\u03B9 \u03C0\u03B1\u03BB\u03B9\u03CC\u03C4\u03B5\u03C1\u03B5\u03C2 \u03B5\u03BA\u03B4\u03CC\u03C3\u03B5\u03B9\u03C2 \u03C1\u03AF\u03C7\u03BD\u03BF\u03C5\u03BD \u03C4\u03B7 \u03C3\u03C5\u03C3\u03BA\u03B5\u03C5\u03AE \u03C3\u03B5 \u03BC\u03C0\u03BB\u03B5 \u03BF\u03B8\u03CC\u03BD\u03B7 \u03CC\u03C3\u03BF \u03C4\u03C1\u03AD\u03C7\u03B5\u03B9 \u03C4\u03BF \u03B5\u03B9\u03BA\u03BF\u03BD\u03B9\u03BA\u03CC \u03C7\u03B5\u03B9\u03C1\u03B9\u03C3\u03C4\u03AE\u03C1\u03B9\u03BF, \u03BF\u03C0\u03CC\u03C4\u03B5 \u03C4\u03BF ClawTweaks \u03B4\u03B5\u03BD \u03B8\u03B1 \u03C4\u03BF \u03BE\u03B5\u03BA\u03B9\u03BD\u03AE\u03C3\u03B5\u03B9. \u03A4\u03C1\u03AD\u03BE\u03C4\u03B5 \u03C4\u03BF setup \u03C4\u03BF\u03C5 ClawTweaks \u03AE \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF {1} \u03B1\u03C0\u03CC \u03C4\u03BF\u03BD \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03BC\u03BF \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5.",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Uninstall usbip, install {1} from the link on this page, and reboot."] = "\u039C\u0397 \u03A5\u03A0\u039F\u03A3\u03A4\u0397\u03A1\u0399\u0396\u039F\u039C\u0395\u039D\u0397 \u0395\u039A\u0394\u039F\u03A3\u0397: \u03B5\u03AF\u03BD\u03B1\u03B9 \u03B5\u03B3\u03BA\u03B1\u03C4\u03B5\u03C3\u03C4\u03B7\u03BC\u03AD\u03BD\u03BF \u03C4\u03BF usbip {0}, \u03C4\u03BF ClawTweaks \u03C7\u03C1\u03B5\u03B9\u03AC\u03B6\u03B5\u03C4\u03B1\u03B9 {1}. \u0391\u03C0\u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF usbip, \u03B5\u03B3\u03BA\u03B1\u03C4\u03B1\u03C3\u03C4\u03AE\u03C3\u03C4\u03B5 \u03C4\u03BF {1} \u03B1\u03C0\u03CC \u03C4\u03BF\u03BD \u03C3\u03CD\u03BD\u03B4\u03B5\u03C3\u03BC\u03BF \u03C3\u03B5 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7 \u03C3\u03B5\u03BB\u03AF\u03B4\u03B1 \u03BA\u03B1\u03B9 \u03B5\u03C0\u03B1\u03BD\u03B5\u03BA\u03BA\u03B9\u03BD\u03AE\u03C3\u03C4\u03B5.",
            ["Update"] = "\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7",
            ["Aggressive"] = "\u0395\u03C0\u03B9\u03B8\u03B5\u03C4\u03B9\u03BA\u03CC",
            ["Efficient Enabled"] = "\u0391\u03C0\u03BF\u03B4\u03BF\u03C4\u03B9\u03BA\u03CC \u03B5\u03BD\u03B5\u03C1\u03B3\u03CC",
            ["Efficient Aggressive"] = "\u0391\u03C0\u03BF\u03B4\u03BF\u03C4\u03B9\u03BA\u03CC \u03B5\u03C0\u03B9\u03B8\u03B5\u03C4\u03B9\u03BA\u03CC",
            ["Aggressive At Guaranteed"] = "\u0395\u03C0\u03B9\u03B8\u03B5\u03C4\u03B9\u03BA\u03CC \u03C3\u03C4\u03BF \u03B5\u03B3\u03B3\u03C5\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Efficient Aggressive At Guaranteed"] = "\u0391\u03C0\u03BF\u03B4\u03BF\u03C4\u03B9\u03BA\u03CC \u03B5\u03C0\u03B9\u03B8\u03B5\u03C4\u03B9\u03BA\u03CC \u03C3\u03C4\u03BF \u03B5\u03B3\u03B3\u03C5\u03B7\u03BC\u03AD\u03BD\u03BF",
            ["Mode {0}"] = "\u039B\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 {0}",
            ["LS Click"] = "\u039A\u03BB\u03B9\u03BA LS",
            ["LS Up"] = "LS \u03C0\u03AC\u03BD\u03C9",
            ["LS Down"] = "LS \u03BA\u03AC\u03C4\u03C9",
            ["LS Left"] = "LS \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC",
            ["LS Right"] = "LS \u03B4\u03B5\u03BE\u03B9\u03AC",
            ["RS Click"] = "\u039A\u03BB\u03B9\u03BA RS",
