            ["D-Pad Up"] = "\u03A3\u03C4\u03B1\u03C5\u03C1\u03CC\u03C2 \u03C0\u03AC\u03BD\u03C9",
            ["D-Pad Down"] = "\u03A3\u03C4\u03B1\u03C5\u03C1\u03CC\u03C2 \u03BA\u03AC\u03C4\u03C9",
            ["D-Pad Left"] = "\u03A3\u03C4\u03B1\u03C5\u03C1\u03CC\u03C2 \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC",
            ["D-Pad Right"] = "\u03A3\u03C4\u03B1\u03C5\u03C1\u03CC\u03C2 \u03B4\u03B5\u03BE\u03B9\u03AC",
