            ["free"] = "\u03B5\u03BB\u03B5\u03CD\u03B8\u03B5\u03C1\u03B1",
            ["OS power mode"] = "\u039B\u03B5\u03B9\u03C4\u03BF\u03C5\u03C1\u03B3\u03AF\u03B1 \u03B9\u03C3\u03C7\u03CD\u03BF\u03C2",
            ["Best power efficiency"] = "\u039C\u03AD\u03B3\u03B9\u03C3\u03C4\u03B7 \u03BF\u03B9\u03BA\u03BF\u03BD\u03BF\u03BC\u03AF\u03B1",
            ["Balanced"] = "\u0399\u03C3\u03BF\u03C1\u03C1\u03BF\u03C0\u03B7\u03BC\u03AD\u03BD\u03B7",
            ["Best performance"] = "\u039C\u03AD\u03B3\u03B9\u03C3\u03C4\u03B7 \u03B1\u03C0\u03CC\u03B4\u03BF\u03C3\u03B7",
            ["Efficiency"] = "\u039F\u03B9\u03BA\u03BF\u03BD\u03BF\u03BC\u03AF\u03B1",
            ["Overlay"] = "\u0395\u03C0\u03B9\u03BA\u03AC\u03BB\u03C5\u03C8\u03B7",
            ["Basic"] = "\u0392\u03B1\u03C3\u03B9\u03BA\u03CC",
