            ["Horizontal Custom"] = "\u039F\u03C1\u03B9\u03B6\u03CC\u03BD\u03C4\u03B9\u03BF \u03B4\u03B9\u03BA\u03CC",
            ["Vertical Custom"] = "\u039A\u03AC\u03B8\u03B5\u03C4\u03BF \u03B4\u03B9\u03BA\u03CC",
            ["Vertical"] = "\u039A\u03AC\u03B8\u03B5\u03C4\u03BF",
