            ["Position"] = "\u0398\u03AD\u03C3\u03B7",
            ["Left top"] = "\u03A0\u03AC\u03BD\u03C9 \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC",
            ["Left middle"] = "\u039C\u03AD\u03C3\u03B7 \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC",
            ["Left bottom"] = "\u039A\u03AC\u03C4\u03C9 \u03B1\u03C1\u03B9\u03C3\u03C4\u03B5\u03C1\u03AC",
            ["Center top"] = "\u03A0\u03AC\u03BD\u03C9 \u03BA\u03AD\u03BD\u03C4\u03C1\u03BF",
            ["Center bottom"] = "\u039A\u03AC\u03C4\u03C9 \u03BA\u03AD\u03BD\u03C4\u03C1\u03BF",
