            ["Set. Covers are downloaded for games with none."] = "\u5DF2\u8BBE\u7F6E\u3002\u6CA1\u6709\u5C01\u9762\u7684\u6E38\u620F\u4F1A\u81EA\u52A8\u4E0B\u8F7D\u3002",
            ["Setting cover\u2026"] = "\u6B63\u5728\u8BBE\u7F6E\u5C01\u9762\u2026",
            ["Settings"] = "\u8BBE\u7F6E",
            ["Settings reset."] = "\u8BBE\u7F6E\u5DF2\u91CD\u7F6E\u3002",
            ["Show the certificate in Explorer"] = "\u5728\u8D44\u6E90\u7BA1\u7406\u5668\u4E2D\u663E\u793A\u8BC1\u4E66",
            ["Shows your installed Steam, Xbox and Epic games."] = "\u663E\u793A\u4F60\u5DF2\u5B89\u88C5\u7684 Steam\u3001Xbox \u548C Epic \u6E38\u620F\u3002",
            ["Shut down"] = "\u5173\u673A",
            ["Signing certificate"] = "\u7B7E\u540D\u8BC1\u4E66",
            ["Some hardware commands could not be sent."] = "\u90E8\u5206\u786C\u4EF6\u6307\u4EE4\u672A\u80FD\u53D1\u9001\u3002",
            ["Square ROM art"] = "\u65B9\u5F62 ROM \u56FE",
            ["Start"] = "\u5F00\u59CB",
            ["Start Center with ClawTweaks"] = "\u968F ClawTweaks \u542F\u52A8 Center",
            ["Start in the library"] = "\u5728\u6E38\u620F\u5E93\u4E2D\u542F\u52A8",
            ["Start menu, desktop and startup"] = "\u5F00\u59CB\u83DC\u5355\u3001\u684C\u9762\u548C\u542F\u52A8\u9879",
            ["Started from Windows"] = "\u7531 Windows \u542F\u52A8",
            ["Starting\u2026"] = "\u6B63\u5728\u542F\u52A8\u2026",
            ["Stay open"] = "\u4FDD\u6301\u6253\u5F00",
            ["Steam Xbox filter driver"] = "Steam \u7684 Xbox \u8FC7\u6EE4\u9A71\u52A8",
            ["Steam asks you where to put it."] = "Steam \u4F1A\u8BE2\u95EE\u653E\u5728\u54EA\u91CC\u3002",
            ["Steam cover art is found automatically."] = "Steam \u5C01\u9762\u4F1A\u81EA\u52A8\u627E\u5230\u3002",
            ["Steam has taken over. The download shows in Recent."] = "Steam \u5DF2\u63A5\u624B\u3002\u4E0B\u8F7D\u4F1A\u663E\u793A\u5728\u300C\u6700\u8FD1\u300D\u4E2D\u3002",
            ["SteamGridDB key"] = "SteamGridDB \u5BC6\u94A5",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "\u7B2C 1 \u6B65\u5C1A\u672A\u6267\u884C\u3002\u5728\u8FD9\u4E4B\u540E\uFF0C\u8BBE\u5907\u4E0A\u6CA1\u6709\u4EFB\u4F55\u4E1C\u897F\u80FD\u5173\u6389\u5145\u7535\u9650\u5236\u6216\u628A\u98CE\u6247\u4EA4\u56DE\u56FA\u4EF6\u3002",
            ["Stick deadzone"] = "\u6447\u6746\u6B7B\u533A",
            ["Stretch"] = "\u62C9\u4F38",
            ["System"] = "\u7CFB\u7EDF",
            ["System language"] = "\u7CFB\u7EDF\u8BED\u8A00",
            ["TDP boost"] = "TDP \u52A0\u901F",
            ["Test versions"] = "\u6D4B\u8BD5\u7248\u672C",
            ["That is what makes the extra controller features possible."] = "\u6B63\u662F\u5B83\u8BA9\u989D\u5916\u7684\u624B\u67C4\u529F\u80FD\u6210\u4E3A\u53EF\u80FD\u3002",
            ["That key was rejected."] = "\u8BE5\u5BC6\u94A5\u88AB\u62D2\u7EDD\u3002",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\u5145\u7535\u9650\u5236\u3001\u98CE\u6247\u66F2\u7EBF\u548C\u624B\u67C4\u6A21\u5F0F\u53EA\u80FD\u7531 ClawTweaks \u91CD\u7F6E\u3002\u91CD\u65B0\u5B89\u88C5\u5B83\u6765\u6062\u590D\uFF0C\u7136\u540E\u56DE\u5230\u8FD9\u91CC\u3002\u4F60\u4ECD\u7136\u53EF\u4EE5\u5378\u8F7D Center\u3002",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\u624B\u67C4\u6CA1\u6709\u786E\u8BA4 \u2014 \u62D4\u7EBF\u524D\u8BF7\u68C0\u67E5\u3002",
            ["The device can be restored"] = "\u8BBE\u5907\u53EF\u4EE5\u8FD8\u539F",
            ["The helper did not confirm in time."] = "helper \u672A\u80FD\u53CA\u65F6\u786E\u8BA4\u3002",
            ["The helper is not answering"] = "helper \u6CA1\u6709\u54CD\u5E94",
            ["The library comes back when the game ends."] = "\u6E38\u620F\u7ED3\u675F\u540E\u6E38\u620F\u5E93\u4F1A\u56DE\u6765\u3002",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u539F\u751F\u624B\u67C4\u5FC5\u987B\u5904\u4E8E\u5E72\u51C0\u72B6\u6001\uFF0C\u865A\u62DF\u624B\u67C4\u6A21\u5F0F\u624D\u80FD\u5DE5\u4F5C\u3002\u865A\u62DF\u6A21\u5F0F\u4E0B\u7269\u7406\u624B\u67C4\u88AB\u9690\u85CF\uFF0C\u53EA\u6709\u4E00\u4E2A\u865A\u62DF VIIPER \u624B\u67C4\u5728\u5DE5\u4F5C\uFF1B\u786C\u4EF6\u6A21\u5F0F\u4E0B\u76F4\u63A5\u4F7F\u7528\u7269\u7406\u624B\u67C4\u3002",
            ["The newest changes, least tested"] = "\u6700\u65B0\u7684\u6539\u52A8\uFF0C\u6D4B\u8BD5\u6700\u5C11",
            ["The old helper exited on its own."] = "\u65E7\u7684 helper \u5DF2\u81EA\u884C\u9000\u51FA\u3002",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "\u65E7\u7248\u672C\u7684\u5378\u8F7D\u7A0B\u5E8F\u6B63\u5728\u8FD0\u884C \u2014 \u8BF7\u786E\u8BA4\u5B83\u7684\u63D0\u793A\u3002\u5B83\u6D88\u5931\u540E\u6B64\u63D0\u793A\u4E5F\u4F1A\u6D88\u5931 (\u6309 \u24CE \u5237\u65B0)\u3002",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\u65E0\u6CD5\u5220\u9664\u8BE5\u5305\u3002\u8BF7\u5173\u95ED Game Bar \u540E\u91CD\u8BD5\uFF0C\u6216\u4ECE\u8BBE\u7F6E \u2192 \u5E94\u7528\u4E2D\u5220\u9664 ClawTweaks\u3002",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\u5305\u7CFB\u5217\u4E0E\u6B64\u66F4\u65B0\u51B2\u7A81\u3002\u6B63\u5728\u6E05\u7406\u5E76\u91CD\u8BD5\u4E00\u6B21\u2026",
            ["The reset did not finish."] = "\u91CD\u7F6E\u6CA1\u6709\u5B8C\u6210\u3002",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\u7B7E\u540D\u8BC1\u4E66\u4F7F\u7528 Windows \u81EA\u5DF1\u7684\u63D0\u793A\uFF0C\u6BCF\u53F0\u8BBE\u5907\u4E00\u6B21\u3002",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\u5C0F\u7EC4\u4EF6\u663E\u793A helper \u5728\u505A\u4EC0\u4E48\uFF1B\u5B83\u81EA\u5DF1\u4E0D\u6539\u53D8\u4EFB\u4F55\u4E1C\u897F\u3002",
            ["The wiki page could not be read. Open it in a browser."] = "\u65E0\u6CD5\u8BFB\u53D6 wiki \u9875\u9762\u3002\u8BF7\u5728\u6D4F\u89C8\u5668\u4E2D\u6253\u5F00\u3002",
            ["This Setup build is outdated"] = "\u6B64\u5B89\u88C5\u7A0B\u5E8F\u7248\u672C\u5DF2\u8FC7\u65F6",
            ["This installs an OLDER version than the one installed."] = "\u8FD9\u4F1A\u5B89\u88C5\u6BD4\u5DF2\u88C5\u7248\u672C\u66F4\u65E7\u7684\u7248\u672C\u3002",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\u8FD9\u662F\u4E00\u4E2A\u6CA1\u6709\u6253\u5305\u5E94\u7528\u7684\u811A\u624B\u67B6\u7248\u672C\uFF0C\u8FD9\u91CC\u6CA1\u6709\u53EF\u5B89\u88C5\u7684\u5185\u5BB9\u3002\u771F\u6B63\u7684\u5B89\u88C5\u5305\u4E2D\uFF0C.msix \u548C .cer \u5C31\u5728\u8FD9\u4E2A exe \u65C1\u8FB9\u3002",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\u8FD9\u4F1A\u8BA9\u8BBE\u5907\u6062\u590D\u539F\u72B6\u5E76\u6E05\u9664\u4F60\u7684 ClawTweaks \u8BBE\u7F6E\uFF1A",
            ["This removes ClawTweaks Center and closes it."] = "\u8FD9\u4F1A\u5220\u9664 ClawTweaks Center \u5E76\u5173\u95ED\u5B83\u3002",
            ["This removes the ClawTweaks app from Windows."] = "\u8FD9\u4F1A\u4ECE Windows \u4E2D\u5220\u9664 ClawTweaks \u5E94\u7528\u3002",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "\u8FD9\u4F1A\u628A\u6240\u6709 ClawTweaks \u8BBE\u7F6E\u91CD\u7F6E\u4E3A\u5E72\u51C0\u72B6\u6001\uFF1A",
            ["This takes a moment."] = "\u8FD9\u9700\u8981\u4E00\u70B9\u65F6\u95F4\u3002",
            ["This version can't be installed"] = "\u65E0\u6CD5\u5B89\u88C5\u6B64\u7248\u672C",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\u6B64\u7248\u672C\u5DF2\u5B89\u88C5\u3002\u8BF7\u4ECE\u5F00\u59CB\u83DC\u5355\u6216 ClawTweaks \u7684 Game Bar \u5C0F\u7EC4\u4EF6\u6253\u5F00\uFF0C\u800C\u4E0D\u662F\u518D\u6B21\u8FD0\u884C\u6B64\u5B89\u88C5\u7A0B\u5E8F\u3002",
            ["Timed out"] = "\u5DF2\u8D85\u65F6",
            ["Transition to new Center App - Uninstall the old version"] = "\u8FC1\u79FB\u5230\u65B0\u7684 Center \u5E94\u7528 - \u5378\u8F7D\u65E7\u7248\u672C",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\u4FE1\u4EFB\u7B7E\u540D\u8BC1\u4E66\u3001\u5B89\u88C5\u5E94\u7528\u5305\u3001\u6253\u5F00 Game Bar \u5E76\u7B49\u5F85 helper\u3002\u66F4\u65B0\u65F6\u91CD\u590D\u8FD0\u884C\u4E5F\u662F\u5B89\u5168\u7684\u3002",
            ["Turn MSI Center M back on"] = "\u91CD\u65B0\u6253\u5F00 MSI Center M",
            ["Turn on"] = "\u5F00\u542F",
            ["Turning MSI Center M back on\u2026"] = "\u6B63\u5728\u91CD\u65B0\u6253\u5F00 MSI Center M\u2026",
            ["Uninstall"] = "\u5378\u8F7D",
            ["Uninstall Center"] = "\u5378\u8F7D Center",
            ["Update ClawTweaks Center"] = "\u66F4\u65B0 ClawTweaks Center",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u66F4\u65B0\u5931\u8D25 \u2014 \u8BE6\u60C5\u89C1\u65E5\u5FD7\u3002\u8BF7\u91CD\u8BD5\uFF0C\u6216\u4EE5\u7BA1\u7406\u5458\u8EAB\u4EFD\u8FD0\u884C\u3002",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\u66F4\u65B0\u4E0D\u4F1A\u5F39\u51FA\u63D0\u793A \u2014 \u4EFB\u52A1\u672C\u8EAB\u4E0D\u5E26\u7248\u672C\u53F7\u3002",
            ["Updating..."] = "\u6B63\u5728\u66F4\u65B0...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\u8BF7\u6539\u7528 Center \u91CC\u7684\u300C\u5378\u8F7D ClawTweaks\u300D\u3002",
            ["Verifying the virtual pad\u2026"] = "\u6B63\u5728\u6821\u9A8C\u865A\u62DF\u624B\u67C4\u2026",
            ["Vibration"] = "\u632F\u52A8",
            ["Virtual controller (VIIPER)"] = "\u865A\u62DF\u624B\u67C4 (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\u865A\u62DF\u624B\u67C4\u5DF2\u5728\u5DE5\u4F5C \u2014 \u624B\u67C4\u72B6\u6001\u826F\u597D\u3002",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\u865A\u62DF\u624B\u67C4\u672A\u80FD\u6302\u8F7D \u2014 \u6B63\u5728\u56DE\u9000\u5230\u786C\u4EF6\u624B\u67C4\u3002",
            ["Waiting for UAC\u2026"] = "\u6B63\u5728\u7B49\u5F85 UAC\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "\u6B63\u5728\u7B49\u5F85 ClawTweaks helper \u542F\u52A8\u3002\u5982\u679C Game Bar \u6253\u5F00\u4E86\u5374\u6CA1\u6709\u53CD\u5E94\uFF0C\u8BF7\u5728\u5C0F\u7EC4\u4EF6\u83DC\u5355\u4E2D\u9009\u62E9 ClawTweaks \u5C0F\u7EC4\u4EF6\u5E76\u6DFB\u52A0 \u2014 \u8FD8\u4E0D\u5728 Game Bar \u4E2D\u7684\u5C0F\u7EC4\u4EF6\u4E0D\u4F1A\u81EA\u5DF1\u542F\u52A8 helper\u3002",
            ["Waiting for the virtual controller to settle\u2026"] = "\u6B63\u5728\u7B49\u5F85\u865A\u62DF\u624B\u67C4\u7A33\u5B9A\u2026",
            ["What does the background helper do?"] = "\u540E\u53F0 helper \u505A\u4EC0\u4E48\uFF1F",
            ["What happens"] = "\u4F1A\u53D1\u751F\u4EC0\u4E48",
            ["What is the virtual controller for?"] = "\u865A\u62DF\u624B\u67C4\u6709\u4EC0\u4E48\u7528\uFF1F",
            ["What's new"] = "\u66F4\u65B0\u5185\u5BB9",
            ["Where are my settings, and how do I back them up?"] = "\u6211\u7684\u8BBE\u7F6E\u5728\u54EA\u91CC\uFF0C\u600E\u4E48\u5907\u4EFD\uFF1F",
            ["Why does ClawTweaks ask for admin rights?"] = "ClawTweaks \u4E3A\u4EC0\u4E48\u8981\u7BA1\u7406\u5458\u6743\u9650\uFF1F",
            ["Will be saved to"] = "\u5C06\u4FDD\u5B58\u5230",
            ["Windowed"] = "\u7A97\u53E3",
            ["Windows Insider Preview detected"] = "\u68C0\u6D4B\u5230 Windows Insider Preview",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows \u8981\u6C42\u5378\u8F7D Center\u3002\u5728\u6B64\u5B8C\u6210\uFF0C\u6216\u6309 B \u4FDD\u7559\u5168\u90E8\u5185\u5BB9\u3002",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows \u65E0\u6CD5\u6253\u5F00\u8FD9\u4E2A\u5305\u6587\u4EF6\u3002\u95EE\u9898\u4E0D\u5728\u5305\u672C\u8EAB \u2014 \u4EE5 SYSTEM \u8EAB\u4EFD\u8FD0\u884C\u7684\u90E8\u7F72\u670D\u52A1\u8BFB\u4E0D\u5230\u5B83\u3002\u8BF7\u4ECE\u7528\u6237\u914D\u7F6E\u6587\u4EF6\u4E4B\u5916\u7684\u6587\u4EF6\u5939\u5B89\u88C5\uFF0C\u5E76\u68C0\u67E5 Gaming Services \u662F\u5426\u6B63\u5E38\u3002",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows \u65E0\u6CD5\u4ECE\u8FD9\u4E2A\u6587\u4EF6\u5939\u6253\u5F00\u5305\u3002\u6B63\u5728\u4ECE\u5168\u673A\u4F4D\u7F6E\u91CD\u8BD5\u2026",
            ["Windows file picker"] = "Windows \u6587\u4EF6\u9009\u62E9\u5668",
            ["Work down the list. Each step is optional except the last."] = "\u6309\u987A\u5E8F\u5B8C\u6210\u5217\u8868\u3002\u9664\u6700\u540E\u4E00\u6B65\u5916\u90FD\u662F\u53EF\u9009\u7684\u3002",
            ["Working\u2026"] = "\u5904\u7406\u4E2D\u2026",
            ["XInput controllers"] = "XInput \u624B\u67C4",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\u662F\u7684\uFF0C\u5982\u679C\u8981\u8BA9 ClawTweaks \u63A7\u5236\u624B\u67C4\u3001\u98CE\u6247\u548C LED\u3002",
            ["Yes, install"] = "\u662F\uFF0C\u5B89\u88C5",
            ["Yes, reset everything"] = "\u662F\uFF0C\u5168\u90E8\u91CD\u7F6E",
            ["Yes, restore"] = "\u662F\uFF0C\u8FD8\u539F",
            ["Yes, restore the device"] = "\u662F\uFF0C\u8FD8\u539F\u8BBE\u5907",
            ["Yes, uninstall Center"] = "\u662F\uFF0C\u5378\u8F7D Center",
            ["Yes, uninstall ClawTweaks"] = "\u662F\uFF0C\u5378\u8F7D ClawTweaks",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "\u4F60\u7684 Claw \u81EA\u5E26\u624B\u67C4\u4F1A\u88AB\u9690\u85CF\uFF0C\u5E76\u7531\u4E00\u4E2A\u865A\u62DF\u624B\u67C4\u53D6\u4EE3\u3002",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\u91CD\u7F6E\u524D\u4F1A\u5907\u4EFD\u4F60\u5F53\u524D\u7684\u8BBE\u7F6E\u3002Game Bar \u4F1A\u5173\u95ED \u2014 \u8BF7\u7528 Win+G \u91CD\u65B0\u6253\u5F00\u3002",
            ["Your games"] = "\u4F60\u7684\u6E38\u620F",
            ["usbip  (required for virtual controller)"] = "usbip  (\u865A\u62DF\u624B\u67C4\u5FC5\u9700)",
            ["version"] = "\u7248\u672C",
            ["versions"] = "\u7248\u672C",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \u5168\u90E8\u914D\u7F6E\u6587\u4EF6\u3001\u98CE\u6247\u66F2\u7EBF\u3001TDP \u548C\u624B\u67C4\u8BBE\u7F6E\u90FD\u4F1A\u91CD\u7F6E",
            ["\u2022 Center's own settings are cleared"] = "\u2022 Center \u81EA\u5DF1\u7684\u8BBE\u7F6E\u4F1A\u88AB\u6E05\u9664",
            ["\u2022 Global and per-game profiles (TDP, fan curves, controller, gyro)"] = "\u2022 \u5168\u5C40\u548C\u6BCF\u4E2A\u6E38\u620F\u7684\u914D\u7F6E\u6587\u4EF6 (TDP\u3001\u98CE\u6247\u66F2\u7EBF\u3001\u624B\u67C4\u3001\u9640\u87BA\u4EEA)",
