            ["Backups live in {0}. Create one first."] = "\u5907\u4EFD\u5B58\u653E\u5728 {0}\u3002\u8BF7\u5148\u521B\u5EFA\u4E00\u4E2A\u3002",
            ["Safety copy of the previous state: {0}"] = "\u4E0A\u4E00\u4E2A\u72B6\u6001\u7684\u526F\u672C\uFF1A{0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "\u6240\u6709 ClawTweaks \u8BBE\u7F6E\u5DF2\u91CD\u7F6E\u4E3A\u5E72\u51C0\u72B6\u6001\u3002\u8BF7\u91CD\u65B0\u6253\u5F00 Game Bar (Win+G) \u7EE7\u7EED\u3002",
            ["Saved {0} stores to:\n{1}"] = "\u5DF2\u628A {0} \u4E2A\u5546\u5E97\u4FDD\u5B58\u5230\uFF1A\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "\u5DF2\u8FD8\u539F {0} \u4E2A\u6587\u4EF6\u3002helper \u6B63\u5728\u91CD\u542F \u2014 \u8BF7\u91CD\u65B0\u6253\u5F00 Game Bar (Win+G) \u7EE7\u7EED\u3002",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "\u8FD9\u4E2A\u5907\u4EFD\u6765\u81EA\u300C{0}\u300D\uFF0C\u4F46\u8FD9\u53F0\u8BBE\u5907\u770B\u8D77\u6765\u662F {1}\u3002\u4E0E\u8BBE\u5907\u76F8\u5173\u7684\u6570\u503C (TDP \u4E0A\u9650\u3001\u98CE\u6247\u523B\u5EA6) \u4F1A\u6309\u539F\u6837\u8FD8\u539F\u3002",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "\u5907\u4EFD\u6765\u81EA {0}\uFF1B\u4F60\u5B89\u88C5\u7684\u662F {1}\u3002\u8DE8\u7248\u672C\u8FD8\u539F\u901A\u5E38\u53EF\u884C\uFF0C\u4F46\u4E0D\u4FDD\u8BC1\u3002",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "\u4F60\u5728\u300C{0}\u300D\u901A\u9053 \u2014 \u5DF2\u77E5\u5B89\u88C5\u6D41\u7A0B\u5728 Insider \u7248\u672C\u4E0A\u65E0\u6CD5\u6B63\u5E38\u5DE5\u4F5C\u3002",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 GitHub \u4E0A\u6709\u66F4\u65B0\uFF1A{0} ({1})",
            ["ClawTweaks Center update available: {0}"] = "ClawTweaks Center \u6709\u66F4\u65B0\uFF1A{0}",
            ["You're running {0}. Install it here \u2014 Center restarts when it's done."] = "\u4F60\u5728\u7528 {0}\u3002\u53EF\u4EE5\u5728\u8FD9\u91CC\u5B89\u88C5 \u2014 \u5B8C\u6210\u540E Center \u4F1A\u91CD\u542F\u3002",
            ["You're running {0}. Download the new Setup file and run it \u2014 it installs over this one, and no administrator rights are needed."] = "\u4F60\u5728\u7528 {0}\u3002\u8BF7\u4E0B\u8F7D\u65B0\u7684\u5B89\u88C5\u7A0B\u5E8F\u5E76\u8FD0\u884C \u2014 \u5B83\u4F1A\u8986\u76D6\u5B89\u88C5\uFF0C\u4E5F\u4E0D\u9700\u8981\u7BA1\u7406\u5458\u6743\u9650\u3002",
            ["Installing {0}"] = "\u6B63\u5728\u5B89\u88C5 {0}",
            ["{0} \u2014 helper is up and running."] = "{0} \u2014 helper \u5DF2\u542F\u52A8\u5E76\u5728\u8FD0\u884C\u3002",
            ["Installed {0}"] = "\u5DF2\u5B89\u88C5 {0}",
            ["Updated {0} \u2192 {1}"] = "\u5DF2\u66F4\u65B0 {0} \u2192 {1}",
            ["Downgraded {0} \u2192 {1}"] = "\u5DF2\u964D\u7EA7 {0} \u2192 {1}",
            ["Reinstalled {0}"] = "\u5DF2\u91CD\u88C5 {0}",
            ["Unexpected survivor: {0} handed over, {1} terminated."] = "\u610F\u5916\u6B8B\u7559\uFF1A{0} \u5DF2\u4EA4\u63A5\uFF0C{1} \u5DF2\u7EC8\u6B62\u3002",
            ["Downloading the package ({0})\u2026"] = "\u6B63\u5728\u4E0B\u8F7D\u5305 ({0})\u2026",
            ["Package verified: {0}, {1:F1} MB."] = "\u5305\u5DF2\u6821\u9A8C\uFF1A{0}\uFF0C{1:F1} MB\u3002",
            ["Outdated version \u2014 install {0} or newer"] = "\u7248\u672C\u8FC7\u65E7 \u2014 \u8BF7\u5B89\u88C5 {0} \u6216\u66F4\u65B0\u7248\u672C",
            ["Auto-jump active (position {0})."] = "\u81EA\u52A8\u8DF3\u8F6C\u5DF2\u542F\u7528 (\u4F4D\u7F6E {0})\u3002",
            ["Auto-jump set to position {0}."] = "\u81EA\u52A8\u8DF3\u8F6C\u5DF2\u8BBE\u4E3A\u4F4D\u7F6E {0}\u3002",
            ["Could not start the old uninstaller: {0}"] = "\u65E0\u6CD5\u542F\u52A8\u65E7\u7684\u5378\u8F7D\u7A0B\u5E8F\uFF1A{0}",
            ["it is a launcher for the .dll next to it, not a standalone build."] = "\u5B83\u53EA\u662F\u65C1\u8FB9\u90A3\u4E2A .dll \u7684\u542F\u52A8\u5668\uFF0C\u4E0D\u662F\u72EC\u7ACB\u7248\u672C\u3002",
            ["it is only {0} KB, too small to carry its own runtime."] = "\u5B83\u53EA\u6709 {0} KB\uFF0C\u592A\u5C0F\u4E86\uFF0C\u88C5\u4E0D\u4E0B\u81EA\u5DF1\u7684\u8FD0\u884C\u65F6\u3002",
            ["its own file could not be inspected ({0})."] = "\u65E0\u6CD5\u68C0\u67E5\u5B83\u81EA\u5DF1\u7684\u6587\u4EF6 ({0})\u3002",
            ["This copy of Center cannot install itself: {0} Use the single-file build from the release page (or publish/), not the executable from a plain build output."] = "\u8FD9\u4E2A Center \u526F\u672C\u65E0\u6CD5\u5B89\u88C5\u81EA\u5DF1\uFF1A{0} \u8BF7\u4F7F\u7528\u53D1\u5E03\u9875 (\u6216 publish/) \u7684\u5355\u6587\u4EF6\u7248\u672C\uFF0C\u800C\u4E0D\u662F\u666E\u901A\u6784\u5EFA\u8F93\u51FA\u91CC\u7684\u53EF\u6267\u884C\u6587\u4EF6\u3002",
            ["Installing to {0}..."] = "\u6B63\u5728\u5B89\u88C5\u5230 {0}...",
            ["Could not create the desktop icon: {0}"] = "\u65E0\u6CD5\u521B\u5EFA\u684C\u9762\u56FE\u6807\uFF1A{0}",
            ["Install failed: {0}"] = "\u5B89\u88C5\u5931\u8D25\uFF1A{0}",
            ["Waiting for the running Center to close ({0}/{1})..."] = "\u6B63\u5728\u7B49\u5F85\u8FD0\u884C\u4E2D\u7684 Center \u5173\u95ED ({0}/{1})...",
            ["Connecting controller"] = "\u6B63\u5728\u8FDE\u63A5\u624B\u67C4",
            ["Setting up virtual gamepad\u2026"] = "\u6B63\u5728\u8BBE\u7F6E\u865A\u62DF\u624B\u67C4\u2026",
            ["Controller connected"] = "\u624B\u67C4\u5DF2\u8FDE\u63A5",
            ["Ready to play"] = "\u53EF\u4EE5\u5F00\u59CB\u6E38\u620F",
            ["Controller not connected"] = "\u624B\u67C4\u672A\u8FDE\u63A5",
            ["Restoring controller"] = "\u6B63\u5728\u6062\u590D\u624B\u67C4",
            ["Switching back to the hardware gamepad\u2026"] = "\u6B63\u5728\u5207\u56DE\u786C\u4EF6\u624B\u67C4\u2026",
            ["Controller restored"] = "\u624B\u67C4\u5DF2\u6062\u590D",
            ["Hardware gamepad is back"] = "\u786C\u4EF6\u624B\u67C4\u56DE\u6765\u4E86",
            ["Controller not restored"] = "\u624B\u67C4\u672A\u6062\u590D",
            ["It stays in DInput mode"] = "\u5B83\u4FDD\u6301\u5728 DInput \u6A21\u5F0F",
            ["HW Mouse ON \u2014 controller paused. Click the HW Mouse tile or press the keyboard hotkey to return."] = "\u786C\u4EF6\u9F20\u6807\u5DF2\u5F00\u542F \u2014 \u624B\u67C4\u5DF2\u6682\u505C\u3002\u70B9\u51FB\u786C\u4EF6\u9F20\u6807\u78C1\u8D34\u6216\u6309\u952E\u76D8\u5FEB\u6377\u952E\u8FD4\u56DE\u3002",
            ["Virtual mouse restored"] = "\u865A\u62DF\u9F20\u6807\u5DF2\u6062\u590D",
            ["Controller mode"] = "\u624B\u67C4\u6A21\u5F0F",
            ["Mouse mode"] = "\u9F20\u6807\u6A21\u5F0F",
            ["Charge Limit: set it up in Settings first"] = "\u5145\u7535\u9650\u5236\uFF1A\u8BF7\u5148\u5728\u8BBE\u7F6E\u4E2D\u914D\u7F6E",
            ["Charge Limit: On {0}%"] = "\u5145\u7535\u9650\u5236\uFF1A\u5F00\u542F {0}%",
            ["Charge Limit: Off"] = "\u5145\u7535\u9650\u5236\uFF1A\u5173\u95ED",
            ["FPS Limit: {0} FPS"] = "\u5E27\u7387\u9650\u5236\uFF1A{0} FPS",
            ["FPS Limit: Off"] = "\u5E27\u7387\u9650\u5236\uFF1A\u5173\u95ED",
            ["Center Settings"] = "Center \u8BBE\u7F6E",
            ["Uninstall ClawTweaks"] = "\u5378\u8F7D ClawTweaks",
            ["Onboarding"] = "\u521D\u59CB\u8BBE\u7F6E",
            ["FAQ"] = "\u5E38\u89C1\u95EE\u9898",
            ["Fixed while Center is the Windows full-screen start app."] = "Center \u4F5C\u4E3A Windows \u5168\u5C4F\u542F\u52A8\u5E94\u7528\u65F6\u56FA\u5B9A\u3002",
            ["Turn on \"Start Steam with the library\" in the library settings to speed this up next time."] = "\u5728\u6E38\u620F\u5E93\u8BBE\u7F6E\u4E2D\u5F00\u542F\u201C\u968F\u6E38\u620F\u5E93\u542F\u52A8 Steam\u201D\uFF0C\u4E0B\u6B21\u4F1A\u66F4\u5FEB\u3002",
            ["Make the library your Xbox full-screen start app"] = "\u5C06\u6E38\u620F\u5E93\u8BBE\u4E3A Xbox \u5168\u5C4F\u542F\u52A8\u5E94\u7528",
            ["Saves memory and start-up time. Run the setup from the GitHub releases page to register it."] = "\u8282\u7701\u5185\u5B58\u548C\u542F\u52A8\u65F6\u95F4\u3002\u4ECE GitHub \u53D1\u5E03\u9875\u8FD0\u884C\u5B89\u88C5\u7A0B\u5E8F\u5373\u53EF\u6CE8\u518C\u3002",
            ["Automatic check: off"] = "\u81EA\u52A8\u68C0\u67E5\uFF1A\u5173",
            ["Automatic check: {0}"] = "\u81EA\u52A8\u68C0\u67E5\uFF1A{0}",
            ["Change in Center settings"] = "\u5728 Center \u8BBE\u7F6E\u4E2D\u66F4\u6539",
            ["Mute"] = "\u9759\u97F3",
            ["Unmute"] = "\u53D6\u6D88\u9759\u97F3",
            ["Tabs order and visibility"] = "\u6807\u7B7E\u987A\u5E8F\u4E0E\u663E\u793A",
            ["Opens Steam in the tray when you open the library. The first Steam game after a boot starts faster."] = "\u6253\u5F00\u6E38\u620F\u5E93\u65F6\u5728\u6258\u76D8\u542F\u52A8 Steam\u3002\u5F00\u673A\u540E\u7B2C\u4E00\u4E2A Steam \u6E38\u620F\u542F\u52A8\u66F4\u5FEB\u3002",
            ["In fullscreen mode, Steam's window can open behind Center."] = "\u5168\u5C4F\u6A21\u5F0F\u4E0B\uFF0CSteam \u7A97\u53E3\u53EF\u80FD\u4F1A\u5728 Center \u540E\u9762\u6253\u5F00\u3002",
            ["Steam removes the game files. In fullscreen, Steam's dialog can open behind Center."] = "Steam \u4F1A\u5220\u9664\u6E38\u620F\u6587\u4EF6\u3002\u5168\u5C4F\u4E0B\u5176\u5BF9\u8BDD\u6846\u53EF\u80FD\u5728 Center \u540E\u9762\u6253\u5F00\u3002",
            ["Opens your Epic library. Uninstall the game there."] = "\u6253\u5F00\u4F60\u7684 Epic \u6E38\u620F\u5E93\u3002\u5728\u90A3\u91CC\u5378\u8F7D\u6E38\u620F\u3002",
            ["Deletes the game for this Windows user."] = "\u4E3A\u6B64 Windows \u7528\u6237\u5220\u9664\u6E38\u620F\u3002",
            ["Press again to delete the game."] = "\u518D\u6309\u4E00\u6B21\u4EE5\u5220\u9664\u6E38\u620F\u3002",
            ["No uninstaller found"] = "\u672A\u627E\u5230\u5378\u8F7D\u7A0B\u5E8F",
            ["Runs the game's own uninstaller"] = "\u8FD0\u884C\u6E38\u620F\u81EA\u5E26\u7684\u5378\u8F7D\u7A0B\u5E8F",
            ["Runs the game's own uninstaller. In fullscreen, it can open behind Center."] = "\u8FD0\u884C\u6E38\u620F\u81EA\u5E26\u7684\u5378\u8F7D\u7A0B\u5E8F\u3002\u5168\u5C4F\u65F6\u5B83\u53EF\u80FD\u5728 Center \u540E\u9762\u6253\u5F00\u3002",
            ["Graphics (WHQL only)"] = "\u663E\u5361\uFF08\u4EC5 WHQL\uFF09",
            ["Graphics (WHQL and non-WHQL)"] = "\u663E\u5361\uFF08WHQL \u548C\u975E WHQL\uFF09",
            ["Download started in the background. The installer opens when it is done."] = "\u5DF2\u5728\u540E\u53F0\u5F00\u59CB\u4E0B\u8F7D\u3002\u5B8C\u6210\u540E\u5B89\u88C5\u7A0B\u5E8F\u4F1A\u81EA\u52A8\u6253\u5F00\u3002",
            ["Download started in the background - over 800 MB. The installer opens when it is done."] = "\u5DF2\u5728\u540E\u53F0\u5F00\u59CB\u4E0B\u8F7D\uFF08\u8D85\u8FC7 800 MB\uFF09\u3002\u5B8C\u6210\u540E\u5B89\u88C5\u7A0B\u5E8F\u4F1A\u81EA\u52A8\u6253\u5F00\u3002",
            ["Download started in the background. The folder opens when it is done - run Setup.bat there."] = "\u5DF2\u5728\u540E\u53F0\u5F00\u59CB\u4E0B\u8F7D\u3002\u5B8C\u6210\u540E\u4F1A\u6253\u5F00\u6587\u4EF6\u5939\uFF0C\u8BF7\u5728\u5176\u4E2D\u8FD0\u884C Setup.bat\u3002",
            ["{0} update(s) ready, restart pending"] = "{0} \u4E2A\u66F4\u65B0\u5C31\u7EEA\uFF0C\u7B49\u5F85\u91CD\u542F",
            ["Install them in Windows Update, then restart."] = "\u5728 Windows \u66F4\u65B0\u4E2D\u5B89\u88C5\uFF0C\u7136\u540E\u91CD\u542F\u3002",
            ["Check drivers again"] = "\u91CD\u65B0\u68C0\u67E5\u9A71\u52A8",
            ["Also non-WHQL graphics drivers"] = "\u4E5F\u5305\u62EC\u975E WHQL \u663E\u5361\u9A71\u52A8",
            ["Modded Wi-Fi driver instead of stock"] = "\u4F7F\u7528\u4FEE\u6539\u7248 Wi-Fi \u9A71\u52A8\u800C\u975E\u539F\u5382",
