            ["Removes this app and closes it."] = "\u79FB\u9664\u6B64\u61C9\u7528\u7A0B\u5F0F\u4E26\u95DC\u9589\u5B83\u3002",
            ["Removing Center\u2026"] = "\u6B63\u5728\u79FB\u9664 Center\u2026",
            ["Removing ClawTweaks\u2026"] = "\u6B63\u5728\u79FB\u9664 ClawTweaks\u2026",
            ["Removing leftover helper\u2026"] = "\u6B63\u5728\u79FB\u9664\u6B98\u7559\u7684 helper\u2026",
            ["Renaming looks for new cover art."] = "\u91CD\u65B0\u547D\u540D\u6642\u6703\u5C0B\u627E\u65B0\u5C01\u9762\u3002",
            ["Required tools"] = "\u5FC5\u8981\u5DE5\u5177",
            ["Required tools (HidHide, RTSS, usbip, PawnIO) already installed."] = "\u5FC5\u8981\u5DE5\u5177 (HidHide\u3001RTSS\u3001usbip\u3001PawnIO) \u5DF2\u5B89\u88DD\u3002",
            ["Requirements"] = "\u9700\u6C42",
            ["Rescan"] = "\u91CD\u65B0\u6383\u63CF",
            ["Reset complete"] = "\u91CD\u8A2D\u5B8C\u6210",
            ["Reset failed"] = "\u91CD\u8A2D\u5931\u6557",
            ["Reset the app, or back up your profiles."] = "\u91CD\u8A2D\u61C9\u7528\u7A0B\u5F0F\uFF0C\u6216\u5099\u4EFD\u4F60\u7684\u8A2D\u5B9A\u6A94\u3002",
            ["Resetting all ClawTweaks settings\u2026"] = "\u6B63\u5728\u91CD\u8A2D\u6240\u6709 ClawTweaks \u8A2D\u5B9A\u2026",
            ["Resolution"] = "\u89E3\u6790\u5EA6",
            ["Restart"] = "\u91CD\u65B0\u555F\u52D5",
            ["Restore"] = "\u9084\u539F",
            ["Restore Backup"] = "\u9084\u539F\u5099\u4EFD",
            ["Restore Backup takes a safety copy before it writes."] = "\u300C\u9084\u539F\u5099\u4EFD\u300D\u5BEB\u5165\u524D\u6703\u5148\u7559\u4E00\u4EFD\u526F\u672C\u3002",
            ["Restore complete"] = "\u9084\u539F\u5B8C\u6210",
            ["Restore failed"] = "\u9084\u539F\u5931\u6557",
            ["Restore the device"] = "\u9084\u539F\u88DD\u7F6E",
            ["Restore the device and remove everything."] = "\u9084\u539F\u88DD\u7F6E\u4E26\u79FB\u9664\u5168\u90E8\u5167\u5BB9\u3002",
            ["Restore the device first"] = "\u8ACB\u5148\u9084\u539F\u88DD\u7F6E",
            ["Restore this backup?"] = "\u9084\u539F\u9019\u500B\u5099\u4EFD\uFF1F",
            ["Restoring the hardware\u2026"] = "\u6B63\u5728\u9084\u539F\u786C\u9AD4\u2026",
            ["Retro scaling"] = "\u5FA9\u53E4\u7E2E\u653E",
            ["Right stick"] = "\u53F3\u6416\u687F",
            ["Right stick actions"] = "\u53F3\u6416\u687F\u52D5\u4F5C",
            ["Right stick: right jumps to the end, left to the start"] = "\u53F3\u6416\u687F\uFF1A\u5411\u53F3\u8DF3\u5230\u7D50\u5C3E\uFF0C\u5411\u5DE6\u8DF3\u5230\u958B\u982D",
            ["Right trigger"] = "\u53F3\u677F\u6A5F",
            ["Route"] = "\u8DEF\u5F91",
            ["Run"] = "\u57F7\u884C",
            ["Run in background"] = "\u5728\u80CC\u666F\u57F7\u884C",
            ["Running \u2014 it can fight ClawTweaks for the controller and LED. You'll be guided to deactivate it after the app is installed."] = "\u6B63\u5728\u57F7\u884C \u2014 \u5B83\u53EF\u80FD\u8207 ClawTweaks \u6436\u63A7\u5236\u5668\u548C LED\u3002\u5B89\u88DD\u5B8C\u6210\u5F8C\u6703\u5F15\u5C0E\u4F60\u505C\u7528\u5B83\u3002",
            ["Running. Press \u24B6 to close it now. For a permanent fix, uninstall it from Windows Settings \u203A Apps and reinstall the latest version if you still need it."] = "\u6B63\u5728\u57F7\u884C\u3002\u6309 \u24B6 \u7ACB\u5373\u95DC\u9589\u3002\u8981\u5FB9\u5E95\u89E3\u6C7A\uFF0C\u8ACB\u5F9E Windows \u8A2D\u5B9A \u203A \u61C9\u7528\u7A0B\u5F0F\u4E2D\u89E3\u9664\u5B89\u88DD\uFF0C\u9700\u8981\u6642\u518D\u88DD\u6700\u65B0\u7248\u3002",
            ["Save"] = "\u5132\u5B58",
            ["Saves all your profiles and settings into a single ZIP. The Game Bar is briefly closed so the widget's data can be copied \u2014 reopen it (Win+G) afterwards."] = "\u628A\u6240\u6709\u8A2D\u5B9A\u6A94\u548C\u8A2D\u5B9A\u5B58\u6210\u4E00\u500B ZIP\u3002Game Bar \u6703\u77ED\u66AB\u95DC\u9589\u4EE5\u4FBF\u8907\u88FD\u5C0F\u5DE5\u5177\u7684\u8CC7\u6599 \u2014 \u5B8C\u6210\u5F8C\u8ACB\u7528 (Win+G) \u91CD\u65B0\u958B\u555F\u3002",
            ["Saves your session to disk."] = "\u628A\u5DE5\u4F5C\u968E\u6BB5\u5B58\u5230\u78C1\u789F\u3002",
            ["Search"] = "\u641C\u5C0B",
            ["Search SteamGridDB for a different cover"] = "\u5728 SteamGridDB \u4E0A\u641C\u5C0B\u5176\u4ED6\u5C01\u9762",
            ["Searching\u2026"] = "\u641C\u5C0B\u4E2D\u2026",
            ["Select"] = "\u9078\u64C7",
            ["Set a SteamGridDB key in Settings first"] = "\u8ACB\u5148\u5728\u8A2D\u5B9A\u4E2D\u586B\u5BEB SteamGridDB \u91D1\u9470",
            ["Set as cover"] = "\u8A2D\u70BA\u5C01\u9762",
            ["Set the library as the screen Center opens on in Library Settings."] = "\u5728\u904A\u6232\u5EAB\u8A2D\u5B9A\u4E2D\u628A\u904A\u6232\u5EAB\u8A2D\u70BA Center \u555F\u52D5\u6642\u958B\u555F\u7684\u756B\u9762\u3002",
            ["Set up Center M, controller and Game Bar."] = "\u8A2D\u5B9A Center M\u3001\u63A7\u5236\u5668\u548C Game Bar\u3002",
            ["Set your status"] = "\u8A2D\u5B9A\u4F60\u7684\u72C0\u614B",
            ["Set. Covers are downloaded for games with none."] = "\u5DF2\u8A2D\u5B9A\u3002\u6C92\u6709\u5C01\u9762\u7684\u904A\u6232\u6703\u81EA\u52D5\u4E0B\u8F09\u3002",
            ["Setting cover\u2026"] = "\u6B63\u5728\u8A2D\u5B9A\u5C01\u9762\u2026",
            ["Settings"] = "\u8A2D\u5B9A",
            ["Settings reset."] = "\u8A2D\u5B9A\u5DF2\u91CD\u8A2D\u3002",
            ["Show the certificate in Explorer"] = "\u5728\u6A94\u6848\u7E3D\u7BA1\u4E2D\u986F\u793A\u6191\u8B49",
            ["Shows your installed Steam, Xbox and Epic games."] = "\u986F\u793A\u4F60\u5DF2\u5B89\u88DD\u7684 Steam\u3001Xbox \u548C Epic \u904A\u6232\u3002",
            ["Shut down"] = "\u95DC\u6A5F",
            ["Signing certificate"] = "\u7C3D\u7F72\u6191\u8B49",
            ["Some hardware commands could not be sent."] = "\u90E8\u5206\u786C\u9AD4\u6307\u4EE4\u672A\u80FD\u9001\u51FA\u3002",
            ["Square ROM art"] = "\u65B9\u5F62 ROM \u5716",
            ["Start"] = "\u958B\u59CB",
            ["Start Center with ClawTweaks"] = "\u96A8 ClawTweaks \u555F\u52D5 Center",
            ["Start in the library"] = "\u5728\u904A\u6232\u5EAB\u4E2D\u555F\u52D5",
            ["Start menu, desktop and startup"] = "\u958B\u59CB\u529F\u80FD\u8868\u3001\u684C\u9762\u548C\u555F\u52D5\u9805",
            ["Started from Windows"] = "\u7531 Windows \u555F\u52D5",
            ["Starting\u2026"] = "\u6B63\u5728\u555F\u52D5\u2026",
            ["Stay open"] = "\u4FDD\u6301\u958B\u555F",
            ["Steam Xbox filter driver"] = "Steam \u7684 Xbox \u7BE9\u9078\u9A45\u52D5\u7A0B\u5F0F",
            ["Steam asks you where to put it."] = "Steam \u6703\u8A62\u554F\u653E\u5728\u54EA\u88E1\u3002",
            ["Steam cover art is found automatically."] = "Steam \u5C01\u9762\u6703\u81EA\u52D5\u627E\u5230\u3002",
            ["Steam has taken over. The download shows in Recent."] = "Steam \u5DF2\u63A5\u624B\u3002\u4E0B\u8F09\u6703\u986F\u793A\u5728\u300C\u6700\u8FD1\u300D\u4E2D\u3002",
            ["SteamGridDB key"] = "SteamGridDB \u91D1\u9470",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "\u7B2C 1 \u6B65\u5C1A\u672A\u57F7\u884C\u3002\u5728\u9019\u4E4B\u5F8C\uFF0C\u88DD\u7F6E\u4E0A\u6C92\u6709\u4EFB\u4F55\u6771\u897F\u80FD\u95DC\u6389\u5145\u96FB\u9650\u5236\u6216\u628A\u98A8\u6247\u4EA4\u56DE\u97CC\u9AD4\u3002",
            ["Stick deadzone"] = "\u6416\u687F\u6B7B\u5340",
            ["Stretch"] = "\u62C9\u4F38",
            ["System"] = "\u7CFB\u7D71",
            ["System language"] = "\u7CFB\u7D71\u8A9E\u8A00",
            ["TDP boost"] = "TDP \u52A0\u901F",
            ["Test versions"] = "\u6E2C\u8A66\u7248\u672C",
            ["That is what makes the extra controller features possible."] = "\u6B63\u662F\u5B83\u8B93\u984D\u5916\u7684\u63A7\u5236\u5668\u529F\u80FD\u6210\u70BA\u53EF\u80FD\u3002",
            ["That key was rejected."] = "\u8A72\u91D1\u9470\u88AB\u62D2\u7D55\u3002",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\u5145\u96FB\u9650\u5236\u3001\u98A8\u6247\u66F2\u7DDA\u548C\u63A7\u5236\u5668\u6A21\u5F0F\u53EA\u80FD\u7531 ClawTweaks \u91CD\u8A2D\u3002\u91CD\u65B0\u5B89\u88DD\u5B83\u4F86\u6062\u5FA9\uFF0C\u7136\u5F8C\u56DE\u5230\u9019\u88E1\u3002\u4F60\u4ECD\u7136\u53EF\u4EE5\u89E3\u9664\u5B89\u88DD Center\u3002",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\u63A7\u5236\u5668\u6C92\u6709\u78BA\u8A8D \u2014 \u62D4\u7DDA\u524D\u8ACB\u6AA2\u67E5\u3002",
            ["The device can be restored"] = "\u88DD\u7F6E\u53EF\u4EE5\u9084\u539F",
            ["The helper did not confirm in time."] = "helper \u672A\u80FD\u53CA\u6642\u78BA\u8A8D\u3002",
            ["The helper is not answering"] = "helper \u6C92\u6709\u56DE\u61C9",
            ["The library comes back when the game ends."] = "\u904A\u6232\u7D50\u675F\u5F8C\u904A\u6232\u5EAB\u6703\u56DE\u4F86\u3002",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u539F\u751F\u63A7\u5236\u5668\u5FC5\u9808\u8655\u65BC\u4E7E\u6DE8\u72C0\u614B\uFF0C\u865B\u64EC\u63A7\u5236\u5668\u6A21\u5F0F\u624D\u80FD\u904B\u4F5C\u3002\u865B\u64EC\u6A21\u5F0F\u4E0B\u5BE6\u9AD4\u63A7\u5236\u5668\u88AB\u96B1\u85CF\uFF0C\u53EA\u6709\u4E00\u500B\u865B\u64EC VIIPER \u63A7\u5236\u5668\u5728\u904B\u4F5C\uFF1B\u786C\u9AD4\u6A21\u5F0F\u4E0B\u76F4\u63A5\u4F7F\u7528\u5BE6\u9AD4\u63A7\u5236\u5668\u3002",
            ["The newest changes, least tested"] = "\u6700\u65B0\u7684\u8B8A\u66F4\uFF0C\u6E2C\u8A66\u6700\u5C11",
            ["The old helper exited on its own."] = "\u820A\u7684 helper \u5DF2\u81EA\u884C\u7D50\u675F\u3002",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "\u820A\u7248\u672C\u7684\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F\u6B63\u5728\u57F7\u884C \u2014 \u8ACB\u78BA\u8A8D\u5B83\u7684\u63D0\u793A\u3002\u5B83\u6D88\u5931\u5F8C\u6B64\u63D0\u793A\u4E5F\u6703\u6D88\u5931 (\u6309 \u24CE \u91CD\u65B0\u6574\u7406)\u3002",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\u7121\u6CD5\u79FB\u9664\u8A72\u5957\u4EF6\u3002\u8ACB\u95DC\u9589 Game Bar \u5F8C\u91CD\u8A66\uFF0C\u6216\u5F9E\u8A2D\u5B9A \u2192 \u61C9\u7528\u7A0B\u5F0F\u4E2D\u79FB\u9664 ClawTweaks\u3002",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\u5957\u4EF6\u7CFB\u5217\u8207\u6B64\u66F4\u65B0\u885D\u7A81\u3002\u6B63\u5728\u6E05\u9664\u4E26\u91CD\u8A66\u4E00\u6B21\u2026",
            ["The reset did not finish."] = "\u91CD\u8A2D\u6C92\u6709\u5B8C\u6210\u3002",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\u7C3D\u7F72\u6191\u8B49\u4F7F\u7528 Windows \u81EA\u5DF1\u7684\u63D0\u793A\uFF0C\u6BCF\u53F0\u88DD\u7F6E\u4E00\u6B21\u3002",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\u5C0F\u5DE5\u5177\u986F\u793A helper \u5728\u505A\u4EC0\u9EBC\uFF1B\u5B83\u81EA\u5DF1\u4E0D\u6539\u8B8A\u4EFB\u4F55\u6771\u897F\u3002",
            ["The wiki page could not be read. Open it in a browser."] = "\u7121\u6CD5\u8B80\u53D6 wiki \u9801\u9762\u3002\u8ACB\u5728\u700F\u89BD\u5668\u4E2D\u958B\u555F\u3002",
            ["This Setup build is outdated"] = "\u6B64\u5B89\u88DD\u7A0B\u5F0F\u7248\u672C\u5DF2\u904E\u6642",
            ["This installs an OLDER version than the one installed."] = "\u9019\u6703\u5B89\u88DD\u6BD4\u5DF2\u88DD\u7248\u672C\u66F4\u820A\u7684\u7248\u672C\u3002",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\u9019\u662F\u4E00\u500B\u6C92\u6709\u5167\u9644\u5957\u4EF6\u7684\u6E2C\u8A66\u7D44\u5EFA\uFF0C\u9019\u88E1\u6C92\u6709\u53EF\u5B89\u88DD\u7684\u5167\u5BB9\u3002\u771F\u6B63\u7684\u5B89\u88DD\u5305\u4E2D\uFF0C.msix \u548C .cer \u5C31\u5728\u9019\u500B exe \u65C1\u908A\u3002",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\u9019\u6703\u8B93\u88DD\u7F6E\u6062\u5FA9\u539F\u72C0\u4E26\u6E05\u9664\u4F60\u7684 ClawTweaks \u8A2D\u5B9A\uFF1A",
            ["This removes ClawTweaks Center and closes it."] = "\u9019\u6703\u79FB\u9664 ClawTweaks Center \u4E26\u95DC\u9589\u5B83\u3002",
            ["This removes the ClawTweaks app from Windows."] = "\u9019\u6703\u5F9E Windows \u4E2D\u79FB\u9664 ClawTweaks \u61C9\u7528\u7A0B\u5F0F\u3002",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "\u9019\u6703\u628A\u6240\u6709 ClawTweaks \u8A2D\u5B9A\u91CD\u8A2D\u70BA\u4E7E\u6DE8\u72C0\u614B\uFF1A",
            ["This takes a moment."] = "\u9019\u9700\u8981\u4E00\u9EDE\u6642\u9593\u3002",
            ["This version can't be installed"] = "\u7121\u6CD5\u5B89\u88DD\u6B64\u7248\u672C",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\u6B64\u7248\u672C\u5DF2\u5B89\u88DD\u3002\u8ACB\u5F9E\u958B\u59CB\u529F\u80FD\u8868\u6216 ClawTweaks \u7684 Game Bar \u5C0F\u5DE5\u5177\u958B\u555F\uFF0C\u800C\u4E0D\u662F\u518D\u6B21\u57F7\u884C\u6B64\u5B89\u88DD\u7A0B\u5F0F\u3002",
            ["Timed out"] = "\u5DF2\u903E\u6642",
            ["Transition to new Center App - Uninstall the old version"] = "\u79FB\u8F49\u5230\u65B0\u7684 Center \u61C9\u7528\u7A0B\u5F0F - \u89E3\u9664\u5B89\u88DD\u820A\u7248\u672C",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\u4FE1\u4EFB\u7C3D\u7F72\u6191\u8B49\u3001\u5B89\u88DD\u61C9\u7528\u7A0B\u5F0F\u5957\u4EF6\u3001\u958B\u555F Game Bar \u4E26\u7B49\u5F85 helper\u3002\u66F4\u65B0\u6642\u91CD\u8907\u57F7\u884C\u4E5F\u662F\u5B89\u5168\u7684\u3002",
            ["Turn MSI Center M back on"] = "\u91CD\u65B0\u958B\u555F MSI Center M",
            ["Turn on"] = "\u958B\u555F",
            ["Turning MSI Center M back on\u2026"] = "\u6B63\u5728\u91CD\u65B0\u958B\u555F MSI Center M\u2026",
            ["Uninstall"] = "\u89E3\u9664\u5B89\u88DD",
            ["Uninstall Center"] = "\u89E3\u9664\u5B89\u88DD Center",
            ["Update ClawTweaks Center"] = "\u66F4\u65B0 ClawTweaks Center",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u66F4\u65B0\u5931\u6557 \u2014 \u8A73\u60C5\u898B\u8A18\u9304\u6A94\u3002\u8ACB\u91CD\u8A66\uFF0C\u6216\u4EE5\u7CFB\u7D71\u7BA1\u7406\u54E1\u8EAB\u5206\u57F7\u884C\u3002",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\u66F4\u65B0\u4E0D\u6703\u8DF3\u51FA\u63D0\u793A \u2014 \u5DE5\u4F5C\u672C\u8EAB\u4E0D\u5E36\u7248\u672C\u865F\u3002",
            ["Updating..."] = "\u6B63\u5728\u66F4\u65B0...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\u8ACB\u6539\u7528 Center \u88E1\u7684\u300C\u89E3\u9664\u5B89\u88DD ClawTweaks\u300D\u3002",
            ["Verifying the virtual pad\u2026"] = "\u6B63\u5728\u9A57\u8B49\u865B\u64EC\u63A7\u5236\u5668\u2026",
            ["Vibration"] = "\u9707\u52D5",
            ["Virtual controller (VIIPER)"] = "\u865B\u64EC\u63A7\u5236\u5668 (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\u865B\u64EC\u63A7\u5236\u5668\u5DF2\u5728\u904B\u4F5C \u2014 \u63A7\u5236\u5668\u72C0\u614B\u826F\u597D\u3002",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\u865B\u64EC\u63A7\u5236\u5668\u672A\u80FD\u639B\u8F09 \u2014 \u6B63\u5728\u56DE\u5FA9\u70BA\u786C\u9AD4\u63A7\u5236\u5668\u3002",
            ["Waiting for UAC\u2026"] = "\u6B63\u5728\u7B49\u5F85 UAC\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "\u6B63\u5728\u7B49\u5F85 ClawTweaks helper \u555F\u52D5\u3002\u5982\u679C Game Bar \u958B\u555F\u4E86\u537B\u6C92\u6709\u53CD\u61C9\uFF0C\u8ACB\u5728\u5C0F\u5DE5\u5177\u9078\u55AE\u4E2D\u9078\u64C7 ClawTweaks \u5C0F\u5DE5\u5177\u4E26\u52A0\u5165 \u2014 \u9084\u4E0D\u5728 Game Bar \u4E2D\u7684\u5C0F\u5DE5\u5177\u4E0D\u6703\u81EA\u5DF1\u555F\u52D5 helper\u3002",
            ["Waiting for the virtual controller to settle\u2026"] = "\u6B63\u5728\u7B49\u5F85\u865B\u64EC\u63A7\u5236\u5668\u7A69\u5B9A\u2026",
            ["What does the background helper do?"] = "\u80CC\u666F helper \u505A\u4EC0\u9EBC\uFF1F",
            ["What happens"] = "\u6703\u767C\u751F\u4EC0\u9EBC",
            ["What is the virtual controller for?"] = "\u865B\u64EC\u63A7\u5236\u5668\u6709\u4EC0\u9EBC\u7528\uFF1F",
            ["What's new"] = "\u66F4\u65B0\u5167\u5BB9",
            ["Where are my settings, and how do I back them up?"] = "\u6211\u7684\u8A2D\u5B9A\u5728\u54EA\u88E1\uFF0C\u600E\u9EBC\u5099\u4EFD\uFF1F",
            ["Why does ClawTweaks ask for admin rights?"] = "ClawTweaks \u70BA\u4EC0\u9EBC\u8981\u7CFB\u7D71\u7BA1\u7406\u54E1\u6B0A\u9650\uFF1F",
            ["Will be saved to"] = "\u5C07\u5132\u5B58\u5230",
            ["Windowed"] = "\u8996\u7A97",
            ["Windows Insider Preview detected"] = "\u5075\u6E2C\u5230 Windows Insider Preview",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows \u8981\u6C42\u89E3\u9664\u5B89\u88DD Center\u3002\u5728\u6B64\u5B8C\u6210\uFF0C\u6216\u6309 B \u4FDD\u7559\u5168\u90E8\u5167\u5BB9\u3002",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows \u7121\u6CD5\u958B\u555F\u9019\u500B\u5957\u4EF6\u6A94\u6848\u3002\u554F\u984C\u4E0D\u5728\u5957\u4EF6\u672C\u8EAB \u2014 \u4EE5 SYSTEM \u8EAB\u5206\u57F7\u884C\u7684\u90E8\u7F72\u670D\u52D9\u8B80\u4E0D\u5230\u5B83\u3002\u8ACB\u5F9E\u4F7F\u7528\u8005\u8A2D\u5B9A\u6A94\u4E4B\u5916\u7684\u8CC7\u6599\u593E\u5B89\u88DD\uFF0C\u4E26\u6AA2\u67E5 Gaming Services \u662F\u5426\u6B63\u5E38\u3002",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows \u7121\u6CD5\u5F9E\u9019\u500B\u8CC7\u6599\u593E\u958B\u555F\u5957\u4EF6\u3002\u6B63\u5728\u5F9E\u5168\u6A5F\u4F4D\u7F6E\u91CD\u8A66\u2026",
            ["Windows file picker"] = "Windows \u6A94\u6848\u9078\u64C7\u5668",
            ["Work down the list. Each step is optional except the last."] = "\u4F9D\u5E8F\u5B8C\u6210\u6E05\u55AE\u3002\u9664\u6700\u5F8C\u4E00\u6B65\u5916\u90FD\u662F\u9078\u7528\u7684\u3002",
            ["Working\u2026"] = "\u8655\u7406\u4E2D\u2026",
            ["XInput controllers"] = "XInput \u63A7\u5236\u5668",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\u662F\u7684\uFF0C\u5982\u679C\u8981\u8B93 ClawTweaks \u63A7\u5236\u63A7\u5236\u5668\u3001\u98A8\u6247\u548C LED\u3002",
            ["Yes, install"] = "\u662F\uFF0C\u5B89\u88DD",
            ["Yes, reset everything"] = "\u662F\uFF0C\u5168\u90E8\u91CD\u8A2D",
            ["Yes, restore"] = "\u662F\uFF0C\u9084\u539F",
            ["Yes, restore the device"] = "\u662F\uFF0C\u9084\u539F\u88DD\u7F6E",
            ["Yes, uninstall Center"] = "\u662F\uFF0C\u89E3\u9664\u5B89\u88DD Center",
            ["Yes, uninstall ClawTweaks"] = "\u662F\uFF0C\u89E3\u9664\u5B89\u88DD ClawTweaks",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "\u4F60\u7684 Claw \u81EA\u5E36\u63A7\u5236\u5668\u6703\u88AB\u96B1\u85CF\uFF0C\u4E26\u7531\u4E00\u500B\u865B\u64EC\u63A7\u5236\u5668\u53D6\u4EE3\u3002",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\u91CD\u8A2D\u524D\u6703\u5099\u4EFD\u4F60\u76EE\u524D\u7684\u8A2D\u5B9A\u3002Game Bar \u6703\u95DC\u9589 \u2014 \u8ACB\u7528 Win+G \u91CD\u65B0\u958B\u555F\u3002",
            ["Your games"] = "\u4F60\u7684\u904A\u6232",
            ["usbip  (required for virtual controller)"] = "usbip  (\u865B\u64EC\u63A7\u5236\u5668\u5FC5\u8981)",
            ["version"] = "\u7248\u672C",
            ["versions"] = "\u7248\u672C",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \u5168\u90E8\u8A2D\u5B9A\u6A94\u3001\u98A8\u6247\u66F2\u7DDA\u3001TDP \u548C\u63A7\u5236\u5668\u8A2D\u5B9A\u90FD\u6703\u91CD\u8A2D",
            ["\u2022 Center's own settings are cleared"] = "\u2022 Center \u81EA\u5DF1\u7684\u8A2D\u5B9A\u6703\u88AB\u6E05\u9664",
            ["\u2022 Global and per-game profiles (TDP, fan curves, controller, gyro)"] = "\u2022 \u5168\u57DF\u548C\u6BCF\u6B3E\u904A\u6232\u7684\u8A2D\u5B9A\u6A94 (TDP\u3001\u98A8\u6247\u66F2\u7DDA\u3001\u63A7\u5236\u5668\u3001\u9640\u87BA\u5100)",
            ["\u2022 Helper settings (global TDP, fan curve, controller emulation)"] = "\u2022 helper \u8A2D\u5B9A (\u5168\u57DF TDP\u3001\u98A8\u6247\u66F2\u7DDA\u3001\u63A7\u5236\u5668\u6A21\u64EC)",
            ["\u2022 The ClawTweaks app is NOT removed by this"] = "\u2022 \u9019\u4E0D\u6703\u79FB\u9664 ClawTweaks \u61C9\u7528\u7A0B\u5F0F",
            ["\u2022 The Start Menu entry and the desktop shortcut go"] = "\u2022 \u958B\u59CB\u529F\u80FD\u8868\u9805\u76EE\u548C\u684C\u9762\u6377\u5F91\u6703\u6D88\u5931",
            ["\u2022 The background helper stops and removes its scheduled task"] = "\u2022 \u80CC\u666F helper \u505C\u6B62\u4E26\u79FB\u9664\u5B83\u7684\u6392\u7A0B\u5DE5\u4F5C",
            ["\u2022 The battery charge limit is switched off"] = "\u2022 \u96FB\u6C60\u5145\u96FB\u9650\u5236\u6703\u95DC\u9589",
            ["\u2022 The fan goes back to firmware control"] = "\u2022 \u98A8\u6247\u4EA4\u56DE\u97CC\u9AD4\u63A7\u5236",
            ["\u2022 The hardware controller comes back"] = "\u2022 \u786C\u9AD4\u63A7\u5236\u5668\u56DE\u4F86",
            ["\u2022 The widget disappears from the Game Bar"] = "\u2022 \u5C0F\u5DE5\u5177\u5F9E Game Bar \u4E2D\u6D88\u5931",
            ["\u2022 Your profiles and settings are deleted with the app"] = "\u2022 \u4F60\u7684\u8A2D\u5B9A\u6A94\u548C\u8A2D\u5B9A\u6703\u96A8\u61C9\u7528\u7A0B\u5F0F\u4E00\u8D77\u79FB\u9664",
            ["Could not start {0}."] = "\u7121\u6CD5\u555F\u52D5 {0}\u3002",
