            ["Reading your stores\u2026"] = "\u6B63\u5728\u8B80\u53D6\u4F60\u7684\u5546\u5E97\u2026",
            ["Reading your Steam library\u2026"] = "\u6B63\u5728\u8B80\u53D6\u4F60\u7684 Steam \u904A\u6232\u5EAB\u2026",
            ["Center opens on the library, not on Home."] = "Center \u958B\u555F\u6642\u9032\u5165\u904A\u6232\u5EAB\uFF0C\u800C\u4E0D\u662F\u4E3B\u9801\u3002",
            ["ClawTweaks starts Center when it starts itself."] = "ClawTweaks \u555F\u52D5\u6642\u6703\u4E00\u8D77\u555F\u52D5 Center\u3002",
            ["Closing the window leaves Center running in the tray."] = "\u95DC\u9589\u8996\u7A97\u5F8C Center \u4ECD\u7559\u5728\u901A\u77E5\u5340\u3002",
            ["What Center does with itself once a game runs."] = "\u904A\u6232\u57F7\u884C\u5F8C Center \u81EA\u5DF1\u600E\u9EBC\u8655\u7406\u3002",
            ["Which tabs the library shows, and in which order."] = "\u904A\u6232\u5EAB\u986F\u793A\u54EA\u4E9B\u6A19\u7C64\uFF0C\u4EE5\u53CA\u9806\u5E8F\u3002",
            ["More covers per row, and a smaller Recent reel."] = "\u6BCF\u5217\u66F4\u591A\u5C01\u9762\uFF0C\u300C\u6700\u8FD1\u300D\u6A6B\u6B04\u66F4\u5C0F\u3002",
            ["Fades the tabs and the footer out on Recent while you idle."] = "\u9592\u7F6E\u6642\u6DE1\u51FA\u300C\u6700\u8FD1\u300D\u9801\u7684\u6A19\u7C64\u548C\u9801\u5C3E\u3002",
            ["Mirrors every cover in the Recent reel."] = "\u8B93\u300C\u6700\u8FD1\u300D\u6A6B\u6B04\u4E2D\u7684\u6BCF\u5F35\u5C01\u9762\u90FD\u6709\u5012\u5F71\u3002",
            ["Show own apps in Recent"] = "\u5728\u6700\u8FD1\u4E2D\u986F\u793A\u6211\u7684\u61C9\u7528\u7A0B\u5F0F",
