            ["Downloads covers for games that have none."] = "\u70BA\u6C92\u6709\u5C01\u9762\u7684\u904A\u6232\u4E0B\u8F09\u5C01\u9762\u3002",
            ["Start {0}?"] = "\u555F\u52D5 {0}\uFF1F",
