            ["Include test versions"] = "\u5305\u542B\u6E2C\u8A66\u7248\u672C",
            ["ClawTweaks {0} is available"] = "ClawTweaks {0} \u53EF\u7528",
            ["Install it under Update & Release."] = "\u5728\u300C\u66F4\u65B0\u8207\u767C\u4F48\u300D\u4E2D\u5B89\u88DD\u3002",
            ["Driver update: {0}"] = "\u9A45\u52D5\u7A0B\u5F0F\u66F4\u65B0\uFF1A{0}",
            ["Version {0} is available."] = "\u7248\u672C {0} \u53EF\u7528\u3002",
            ["{0} Windows update(s) waiting"] = "{0} \u500B Windows \u66F4\u65B0\u7B49\u5F85\u4E2D",
            ["No new notifications"] = "\u6C92\u6709\u65B0\u901A\u77E5",
            ["Gamebar Widget Releases"] = "Gamebar \u5C0F\u5DE5\u5177\u767C\u4F48",
            ["Check for updates and notify"] = "\u6AA2\u67E5\u66F4\u65B0\u4E26\u901A\u77E5",
            ["Status"] = "\u72C0\u614B",
            ["Uninstall\u2026"] = "\u89E3\u9664\u5B89\u88DD\u2026",
            ["Steam removes the game files"] = "Steam \u6703\u522A\u9664\u904A\u6232\u6A94\u6848",
            ["Back to Recent"] = "\u8FD4\u56DE\u300C\u6700\u8FD1\u300D",
            ["Tab visibility & order"] = "\u6A19\u7C64\u986F\u793A\u8207\u9806\u5E8F",
            ["Favorite"] = "\u6536\u85CF",
            ["Unfavorite"] = "\u53D6\u6D88\u6536\u85CF",
            ["Rename\u2026"] = "\u91CD\u65B0\u547D\u540D\u2026",
            ["Rename"] = "\u91CD\u65B0\u547D\u540D",
            ["Remove"] = "\u79FB\u9664",
            ["Other"] = "\u5176\u4ED6",
            ["Recent immersive"] = "\u6700\u8FD1\u6C89\u6D78\u5F0F",
            ["Sleep"] = "\u7761\u7720",
            ["Hibernate"] = "\u4F11\u7720",
            ["Launch"] = "\u555F\u52D5",
            ["Edit"] = "\u7DE8\u8F2F",
            ["Auto pre-restore \u2014 {0}"] = "\u9084\u539F\u524D\u81EA\u52D5\u5099\u4EFD \u2014 {0}",
            ["ClawTweaks {0} \u00B7 {1} \u00B7 {2} stores \u00B7 {3}"] = "ClawTweaks {0} \u00B7 {1} \u00B7 {2} \u500B\u5546\u5E97 \u00B7 {3}",
            ["Choose a program"] = "\u9078\u64C7\u4E00\u500B\u7A0B\u5F0F",
            ["Add"] = "\u65B0\u589E",
            ["Add {0}"] = "\u65B0\u589E {0}",
            ["Open Center"] = "\u958B\u555F Center",
            ["Open Library"] = "\u958B\u555F\u904A\u6232\u5EAB",
            ["Exit Center"] = "\u7D50\u675F Center",
            ["The update could not install itself. Try the button below."] = "\u66F4\u65B0\u7121\u6CD5\u81EA\u884C\u5B89\u88DD\u3002\u8A66\u8A66\u4E0B\u9762\u7684\u6309\u9215\u3002",
            ["Installing\u2026"] = "\u6B63\u5728\u5B89\u88DD\u2026",
            ["Install update now"] = "\u7ACB\u5373\u5B89\u88DD\u66F4\u65B0",
            ["Version {0} is still installed for all users, in {1}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u7248\u672C {0} \u4ECD\u70BA\u6240\u6709\u4F7F\u7528\u8005\u5B89\u88DD\u5728 {1}\u3002\u9019\u500B\u7248\u672C\u6539\u88DD\u5230\u4F60\u81EA\u5DF1\u7684\u4F7F\u7528\u8005\u8CC7\u6599\u593E\uFF0C\u6240\u4EE5\u820A\u7684\u90A3\u500B\u4E0D\u518D\u88AB\u4F7F\u7528 \u2014 \u4F46\u5728\u79FB\u9664\u4E4B\u524D\u5B83\u4ECD\u7559\u5728\u8A2D\u5B9A \u2192 \u61C9\u7528\u7A0B\u5F0F\u548C\u958B\u59CB\u529F\u80FD\u8868\u88E1\uFF0C\u5F88\u5BB9\u6613\u8AA4\u555F\u52D5\u3002",
            ["A previous version is still installed for all users, in {0}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u4E4B\u524D\u7684\u7248\u672C\u4ECD\u70BA\u6240\u6709\u4F7F\u7528\u8005\u5B89\u88DD\u5728 {0}\u3002\u9019\u500B\u7248\u672C\u6539\u88DD\u5230\u4F60\u81EA\u5DF1\u7684\u4F7F\u7528\u8005\u8CC7\u6599\u593E\uFF0C\u6240\u4EE5\u820A\u7684\u90A3\u500B\u4E0D\u518D\u88AB\u4F7F\u7528 \u2014 \u4F46\u5728\u79FB\u9664\u4E4B\u524D\u5B83\u4ECD\u7559\u5728\u8A2D\u5B9A \u2192 \u61C9\u7528\u7A0B\u5F0F\u548C\u958B\u59CB\u529F\u80FD\u8868\u88E1\uFF0C\u5F88\u5BB9\u6613\u8AA4\u555F\u52D5\u3002",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below starts the old version's own uninstaller, so the prompt you see comes from it, about removing itself."] = "\u79FB\u9664\u5B83\u9700\u8981\u7CFB\u7D71\u7BA1\u7406\u54E1\u6B0A\u9650\u3002ClawTweaks Center \u5F9E\u4E0D\u7D22\u53D6\u9019\u4E9B\u6B0A\u9650 \u2014 \u4E0B\u9762\u7684\u6309\u9215\u555F\u52D5\u7684\u662F\u820A\u7248\u672C\u81EA\u5DF1\u7684\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F\uFF0C\u6240\u4EE5\u4F60\u770B\u5230\u7684\u63D0\u793A\u4F86\u81EA\u5B83\uFF0C\u7528\u4F86\u79FB\u9664\u5B83\u81EA\u5DF1\u3002",
            ["Scroll"] = "\u6372\u52D5",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller still won't start."] = "\u9019\u4E9B\u6703\u5B89\u88DD\u6838\u5FC3\u9A45\u52D5\u7A0B\u5F0F\u3002\u4E0D\u91CD\u65B0\u555F\u52D5\u7684\u8A71\uFF0C\u4E00\u5207\u770B\u8D77\u4F86\u90FD\u88DD\u597D\u4E86\uFF0C\u4F46\u865B\u64EC\u63A7\u5236\u5668\u4ECD\u7136\u7121\u6CD5\u555F\u52D5\u3002",
            ["Version {0}"] = "\u7248\u672C {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "\u65B0\u7684 ClawTweaks Center \u4E0D\u9700\u8981\u7CFB\u7D71\u7BA1\u7406\u54E1\u6B0A\u9650\uFF0C\u4E26\u5B89\u88DD\u5230\u53E6\u4E00\u500B\u4F4D\u7F6E\u3002",
            ["No Xbox games are registered for this account."] = "\u9019\u500B\u5E33\u865F\u6C92\u6709\u8A3B\u518A\u4EFB\u4F55 Xbox \u904A\u6232\u3002",
            ["No ROMs for {0}."] = "\u6C92\u6709 {0} \u7684 ROM\u3002",
            ["Cycle"] = "\u5FAA\u74B0",
            ["checking the installed version\u2026"] = "\u6B63\u5728\u6AA2\u67E5\u5DF2\u5B89\u88DD\u7684\u7248\u672C\u2026",
            ["you have {0}."] = "\u4F60\u73FE\u5728\u662F {0}\u3002",
            ["Requires ClawTweaks {0} or newer"] = "\u9700\u8981 ClawTweaks {0} \u6216\u66F4\u65B0\u7248\u672C",
            ["Reset, Backup and Restore need ClawTweaks {0} (or 0.1.8+) \u2014 {1} Update ClawTweaks from \"Update & Release\" first."] = "\u91CD\u8A2D\u3001\u5099\u4EFD\u548C\u9084\u539F\u9700\u8981 ClawTweaks {0} (\u6216 0.1.8+) \u2014 {1} \u8ACB\u5148\u5F9E\u300C\u66F4\u65B0\u8207\u767C\u4F48\u300D\u66F4\u65B0 ClawTweaks\u3002",
            ["Unknown error."] = "\u672A\u77E5\u932F\u8AA4\u3002",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "\u6B63\u5728\u9084\u539F\u5099\u4EFD \u2014 \u5B8C\u6210\u5F8C helper \u6703\u91CD\u65B0\u555F\u52D5\u2026",
            ["Restore likely completed"] = "\u9084\u539F\u5927\u6982\u5DF2\u5B8C\u6210",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "helper \u5728\u78BA\u8A8D\u4E4B\u524D\u5C31\u91CD\u65B0\u555F\u52D5\u4E86\u3002\u8ACB\u91CD\u65B0\u958B\u555F Game Bar (Win+G) \u6AA2\u67E5\u4F60\u7684\u8A2D\u5B9A\u6A94 \u2014 \u5982\u679C\u6709\u7570\u5E38\uFF0C\u5C31\u9084\u539F\u90A3\u4EFD\u81EA\u52D5\u9810\u5099\u4EFD\u3002",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "\u9019\u500B ZIP \u6C92\u6709\u6709\u6548\u7684 ClawTweaks \u8CC7\u8A0A\u6E05\u55AE \u2014 \u5982\u679C\u4E0D\u662F\u771F\u6B63\u7684\u5099\u4EFD\uFF0Chelper \u6703\u62D2\u7D55\u5B83\u3002",
            ["Different ClawTweaks version"] = "ClawTweaks \u7248\u672C\u4E0D\u540C",
            ["Supported."] = "\u652F\u63F4\u3002",
            ["Recognized, but not supported yet."] = "\u53EF\u4EE5\u8FA8\u8B58\uFF0C\u4F46\u5C1A\u672A\u652F\u63F4\u3002",
            ["Not a recognized MSI Claw \u2014 installing here is untested."] = "\u4E0D\u662F\u53EF\u8FA8\u8B58\u7684 MSI Claw \u2014 \u5728\u9019\u88E1\u5B89\u88DD\u672A\u7D93\u6E2C\u8A66\u3002",
            ["Install the missing prerequisites"] = "\u5B89\u88DD\u7F3A\u5C11\u7684\u5FC5\u8981\u689D\u4EF6",
            ["Download each one from the vendor and run their installer, then re-check."] = "\u5F9E\u5EE0\u5546\u8655\u5206\u5225\u4E0B\u8F09\u4E26\u57F7\u884C\u5B83\u5011\u7684\u5B89\u88DD\u7A0B\u5F0F\uFF0C\u7136\u5F8C\u91CD\u65B0\u6AA2\u67E5\u3002",
            ["Re-check and continue"] = "\u91CD\u65B0\u6AA2\u67E5\u4E26\u7E7C\u7E8C",
            ["Re-check tools"] = "\u91CD\u65B0\u6AA2\u67E5\u5DE5\u5177",
            ["Trust the ClawTweaks signing certificate"] = "\u4FE1\u4EFB ClawTweaks \u7684\u7C3D\u7F72\u6191\u8B49",
            ["ClawTweaks is signed with its own certificate, and Windows only installs a package whose certificate it trusts. You only have to do this once \u2014 every future build uses the same one."] = "ClawTweaks \u7528\u81EA\u5DF1\u7684\u6191\u8B49\u7C3D\u7F72\uFF0C\u800C Windows \u53EA\u5B89\u88DD\u5B83\u4FE1\u4EFB\u5176\u6191\u8B49\u7684\u5957\u4EF6\u3002\u9019\u53EA\u9700\u8981\u505A\u4E00\u6B21 \u2014 \u4EE5\u5F8C\u7684\u6BCF\u500B\u7248\u672C\u90FD\u7528\u540C\u4E00\u5F35\u6191\u8B49\u3002",
            ["The certificate was imported for your user account instead of the local machine. Windows only consults the machine store when installing a package, so this has no effect. Run the import again and pick \"Local Machine\" on the first page."] = "\u6191\u8B49\u88AB\u532F\u5165\u5230\u4E86\u4F60\u7684\u4F7F\u7528\u8005\u5E33\u6236\uFF0C\u800C\u4E0D\u662F\u672C\u6A5F\u96FB\u8166\u3002\u5B89\u88DD\u5957\u4EF6\u6642 Windows \u53EA\u67E5\u96FB\u8166\u5B58\u653E\u5340\uFF0C\u6240\u4EE5\u9019\u6A23\u6C92\u6709\u6548\u679C\u3002\u8ACB\u91CD\u65B0\u532F\u5165\uFF0C\u4E26\u5728\u7B2C\u4E00\u9801\u9078\u64C7\u300C\u672C\u6A5F\u96FB\u8166\u300D\u3002",
            ["The certificate landed in \"Trusted Root Certification Authorities\". That is both more than ClawTweaks needs \u2014 it would make this certificate a trust anchor for anything, not just this package \u2014 and still not where Windows looks. Remove it from there and import it into \"Trusted People\" instead."] = "\u6191\u8B49\u9032\u4E86\u300C\u53D7\u4FE1\u4EFB\u7684\u6839\u6191\u8B49\u6388\u6B0A\u55AE\u4F4D\u300D\u3002\u9019\u65E2\u8D85\u51FA\u4E86 ClawTweaks \u7684\u9700\u8981 \u2014 \u90A3\u6703\u8B93\u9019\u5F35\u6191\u8B49\u6210\u70BA\u4EFB\u4F55\u6771\u897F\u7684\u4FE1\u4EFB\u6839\uFF0C\u800C\u4E0D\u53EA\u662F\u9019\u500B\u5957\u4EF6 \u2014 \u53C8\u4ECD\u7136\u4E0D\u662F Windows \u5C0B\u627E\u7684\u4F4D\u7F6E\u3002\u8ACB\u5F9E\u90A3\u88E1\u79FB\u9664\uFF0C\u6539\u70BA\u532F\u5165\u5230\u300C\u53D7\u4FE1\u4EFB\u7684\u4EBA\u300D\u3002",
            ["Check the certificate and continue"] = "\u6AA2\u67E5\u6191\u8B49\u4E26\u7E7C\u7E8C",
            ["Check certificate"] = "\u6AA2\u67E5\u6191\u8B49",
            ["Installed, but the helper did not appear in time \u2014 open the Game Bar (Win+G) manually."] = "\u5DF2\u5B89\u88DD\uFF0C\u4F46 helper \u6C92\u6709\u53CA\u6642\u51FA\u73FE \u2014 \u8ACB\u624B\u52D5\u958B\u555F Game Bar (Win+G)\u3002",
            ["Virtual pad"] = "\u865B\u64EC\u63A7\u5236\u5668",
            ["Virtual controller mode detected"] = "\u5075\u6E2C\u5230\u865B\u64EC\u63A7\u5236\u5668\u6A21\u5F0F",
            ["{0} active and running."] = "{0} \u5DF2\u555F\u7528\u4E26\u5728\u57F7\u884C\u3002",
            ["HW controller mode detected"] = "\u5075\u6E2C\u5230\u786C\u9AD4\u63A7\u5236\u5668\u6A21\u5F0F",
            ["MSI HW Controller active and running."] = "MSI \u786C\u9AD4\u63A7\u5236\u5668\u5DF2\u555F\u7528\u4E26\u5728\u57F7\u884C\u3002",
            ["Claw controller not detected."] = "\u672A\u5075\u6E2C\u5230 Claw \u63A7\u5236\u5668\u3002",
            ["Controller mode unknown"] = "\u63A7\u5236\u5668\u6A21\u5F0F\u672A\u77E5",
            ["The download did not complete. Check your internet connection and try again."] = "\u4E0B\u8F09\u6C92\u6709\u5B8C\u6210\u3002\u8ACB\u6AA2\u67E5\u7DB2\u8DEF\u9023\u7DDA\u5F8C\u91CD\u8A66\u3002",
            ["This version has no package to download."] = "\u9019\u500B\u7248\u672C\u6C92\u6709\u53EF\u4E0B\u8F09\u7684\u5957\u4EF6\u3002",
            ["Download complete."] = "\u4E0B\u8F09\u5B8C\u6210\u3002",
            ["The download contains no package file."] = "\u4E0B\u8F09\u5167\u5BB9\u4E2D\u6C92\u6709\u5957\u4EF6\u6A94\u6848\u3002",
            ["The downloaded package is incomplete \u2014 its manifest is missing."] = "\u4E0B\u8F09\u7684\u5957\u4EF6\u4E0D\u5B8C\u6574 \u2014 \u7F3A\u5C11\u8CC7\u8A0A\u6E05\u55AE\u3002",
            ["The downloaded package is not readable."] = "\u4E0B\u8F09\u7684\u5957\u4EF6\u7121\u6CD5\u8B80\u53D6\u3002",
            ["(received {0:N0} of {1:N0} bytes)"] = "(\u5DF2\u63A5\u6536 {1:N0} \u4F4D\u5143\u7D44\u4E2D\u7684 {0:N0} \u4F4D\u5143\u7D44)",
            ["The download produced an empty file."] = "\u4E0B\u8F09\u5F97\u5230\u7684\u662F\u7A7A\u6A94\u6848\u3002",
            ["Click \"Install Certificate\u2026\" on the General tab."] = "\u5728\u300C\u4E00\u822C\u300D\u7D22\u5F15\u6A19\u7C64\u6309\u300C\u5B89\u88DD\u6191\u8B49\u2026\u300D\u3002",
            ["Store Location: choose \"Local Machine\" (not \"Current User\"), then Next. Windows asks for administrator rights here \u2014 that prompt comes from Windows itself."] = "\u5B58\u653E\u4F4D\u7F6E\uFF1A\u9078\u64C7\u300C\u672C\u6A5F\u96FB\u8166\u300D(\u4E0D\u662F\u300C\u76EE\u524D\u4F7F\u7528\u8005\u300D)\uFF0C\u7136\u5F8C\u4E0B\u4E00\u6B65\u3002Windows \u6703\u5728\u9019\u88E1\u8981\u6C42\u7CFB\u7D71\u7BA1\u7406\u54E1\u6B0A\u9650 \u2014 \u90A3\u500B\u63D0\u793A\u4F86\u81EA Windows \u672C\u8EAB\u3002",
            ["Choose \"Place all certificates in the following store\", click Browse\u2026"] = "\u9078\u64C7\u300C\u5C07\u6240\u6709\u6191\u8B49\u653E\u5165\u4E0B\u5217\u5B58\u653E\u5340\u300D\uFF0C\u6309\u300C\u700F\u89BD\u2026\u300D\u3002",
            ["Select \"Trusted People\" \u2014 NOT \"Trusted Root Certification Authorities\"."] = "\u9078\u64C7\u300C\u53D7\u4FE1\u4EFB\u7684\u4EBA\u300D\u2014 \u4E0D\u662F\u300C\u53D7\u4FE1\u4EFB\u7684\u6839\u6191\u8B49\u6388\u6B0A\u55AE\u4F4D\u300D\u3002",
            ["Next, then Finish. You should see \"The import was successful.\""] = "\u4E0B\u4E00\u6B65\uFF0C\u7136\u5F8C\u5B8C\u6210\u3002\u61C9\u7576\u986F\u793A\u300C\u532F\u5165\u6210\u529F\u3002\u300D",
            ["Controller probe timed out."] = "\u63A7\u5236\u5668\u5075\u6E2C\u903E\u6642\u3002",
            ["Controller probe failed: {0}"] = "\u63A7\u5236\u5668\u5075\u6E2C\u5931\u6557\uFF1A{0}",
            ["MSI Claw controller not detected (VID_0DB0). Connect/enable the controller, or MSI Center M may have taken it over."] = "\u672A\u5075\u6E2C\u5230 MSI Claw \u63A7\u5236\u5668 (VID_0DB0)\u3002\u8ACB\u9023\u63A5/\u555F\u7528\u63A7\u5236\u5668\uFF0C\u4E5F\u53EF\u80FD\u662F MSI Center M \u63A5\u7BA1\u4E86\u5B83\u3002",
            ["MSI Center M is running. It can fight ClawTweaks for the controller and LED. This is handled after installation."] = "MSI Center M \u6B63\u5728\u57F7\u884C\u3002\u5B83\u53EF\u80FD\u8207 ClawTweaks \u6436\u63A7\u5236\u5668\u548C LED\u3002\u9019\u6703\u5728\u5B89\u88DD\u4E4B\u5F8C\u8655\u7406\u3002",
            ["Steam's Xbox controller filter driver is present \u2014 a common cause of double input. Check Steam Input settings if you see doubled inputs."] = "\u5B58\u5728 Steam \u7684 Xbox \u63A7\u5236\u5668\u7BE9\u9078\u9A45\u52D5\u7A0B\u5F0F \u2014 \u96D9\u91CD\u8F38\u5165\u7684\u5E38\u898B\u539F\u56E0\u3002\u82E5\u51FA\u73FE\u91CD\u8907\u8F38\u5165\uFF0C\u8ACB\u6AA2\u67E5 Steam Input \u8A2D\u5B9A\u3002",
            ["{0} XInput controllers are currently visible. Two or more while playing = double input."] = "\u76EE\u524D\u53EF\u898B {0} \u500B XInput \u63A7\u5236\u5668\u3002\u904A\u6232\u4E2D\u51FA\u73FE\u5169\u500B\u6216\u66F4\u591A\u5C31\u662F\u96D9\u91CD\u8F38\u5165\u3002",
            ["Controller healthy \u2014 ready to mount as a virtual pad."] = "\u63A7\u5236\u5668\u72C0\u614B\u826F\u597D \u2014 \u53EF\u4EE5\u639B\u8F09\u70BA\u865B\u64EC\u63A7\u5236\u5668\u3002",
            ["MSI Claw controller not found. Connect/enable it (MSI Center M may hold it)."] = "\u6C92\u6709\u627E\u5230 MSI Claw \u63A7\u5236\u5668\u3002\u8ACB\u9023\u63A5/\u555F\u7528\u5B83 (\u53EF\u80FD\u88AB MSI Center M \u5360\u7528)\u3002",
            ["Controller HID is held by another process \u2014 close conflicting controller software and re-check."] = "\u63A7\u5236\u5668\u7684 HID \u88AB\u53E6\u4E00\u500B\u8655\u7406\u7A0B\u5E8F\u5360\u7528 \u2014 \u8ACB\u95DC\u9589\u885D\u7A81\u7684\u63A7\u5236\u5668\u8EDF\u9AD4\u5F8C\u91CD\u65B0\u6AA2\u67E5\u3002",
            ["Controller HID opened but did not respond \u2014 try re-checking; a reboot may be needed."] = "\u63A7\u5236\u5668\u7684 HID \u958B\u555F\u4E86\u4F46\u6C92\u6709\u56DE\u61C9 \u2014 \u8ACB\u91CD\u65B0\u6AA2\u67E5\uFF1B\u53EF\u80FD\u9700\u8981\u91CD\u65B0\u555F\u52D5\u3002",
            ["Could not determine controller health."] = "\u7121\u6CD5\u5224\u65B7\u63A7\u5236\u5668\u72C0\u614B\u3002",
            ["The helper did not answer the health probe."] = "helper \u6C92\u6709\u56DE\u61C9\u72C0\u614B\u5075\u6E2C\u3002",
            ["Unknown device"] = "\u672A\u77E5\u88DD\u7F6E",
            ["Could not locate the installed package \u2014 helper files not deployed."] = "\u627E\u4E0D\u5230\u5DF2\u5B89\u88DD\u7684\u5957\u4EF6 \u2014 helper \u6A94\u6848\u6C92\u6709\u90E8\u7F72\u3002",
            ["Helper files were not deployed \u2014 the widget will retry when it starts the helper."] = "helper \u6A94\u6848\u6C92\u6709\u90E8\u7F72 \u2014 \u5C0F\u5DE5\u5177\u555F\u52D5 helper \u6642\u6703\u91CD\u8A66\u3002",
            ["The helper is not answering."] = "helper \u6C92\u6709\u56DE\u61C9\u3002",
            ["A backup of your settings is at {0}"] = "\u4F60\u7684\u8A2D\u5B9A\u5099\u4EFD\u5728 {0}",
            ["Could not connect to the helper."] = "\u7121\u6CD5\u9023\u7DDA\u5230 helper\u3002",
            ["The helper did not respond in time."] = "helper \u6C92\u6709\u53CA\u6642\u56DE\u61C9\u3002",
            ["Disabling\u2026"] = "\u6B63\u5728\u505C\u7528\u2026",
            ["Disabled."] = "\u5DF2\u505C\u7528\u3002",
            ["Enabling\u2026"] = "\u6B63\u5728\u555F\u7528\u2026",
            ["Enabled and verified ({0})."] = "\u5DF2\u555F\u7528\u4E26\u9A57\u8B49 ({0})\u3002",
            ["virtual pad"] = "\u865B\u64EC\u63A7\u5236\u5668",
            ["Hides the physical gamepad so games see only the virtual controller."] = "\u96B1\u85CF\u5BE6\u9AD4\u63A7\u5236\u5668\uFF0C\u8B93\u904A\u6232\u53EA\u770B\u5230\u865B\u64EC\u63A7\u5236\u5668\u3002",
            ["Take HidHide_x.x.x.x_x64.exe."] = "\u9078\u64C7 HidHide_x.x.x.x_x64.exe\u3002",
            ["Provides the virtual controller itself (the VIIPER backend)."] = "\u63D0\u4F9B\u865B\u64EC\u63A7\u5236\u5668\u672C\u8EAB (VIIPER \u5F8C\u7AEF)\u3002",
            ["Take USBip-0.9.8.0-x64.exe from this page. The link opens version 0.9.8.0 deliberately \u2014 it is the version ClawTweaks supports."] = "\u5F9E\u9019\u500B\u9801\u9762\u9078\u64C7 USBip-0.9.8.0-x64.exe\u3002\u9023\u7D50\u7279\u610F\u958B\u555F 0.9.8.0 \u2014 \u9019\u662F ClawTweaks \u652F\u63F4\u7684\u7248\u672C\u3002",
            ["Do not download the ARM version, and do not take an older usbip release: below 0.9.8.0 the device blue-screens while the virtual controller runs."] = "\u4E0D\u8981\u4E0B\u8F09 ARM \u7248\u672C\uFF0C\u4E5F\u4E0D\u8981\u7528\u66F4\u820A\u7684 usbip\uFF1A\u4F4E\u65BC 0.9.8.0 \u6642\uFF0C\u865B\u64EC\u63A7\u5236\u5668\u57F7\u884C\u4E2D\u88DD\u7F6E\u6703\u85CD\u5E55\u3002",
            ["Applies the per-game FPS cap and draws the on-screen display."] = "\u5957\u7528\u6BCF\u6B3E\u904A\u6232\u7684\u5E40\u7387\u9650\u5236\u4E26\u7E6A\u88FD\u87A2\u5E55\u986F\u793A\u3002",
            ["Take RivaTuner Statistics Server."] = "\u9078\u64C7 RivaTuner Statistics Server\u3002",
            ["Reads the CPU sensors ClawTweaks shows in the widget."] = "\u8B80\u53D6 ClawTweaks \u5728\u5C0F\u5DE5\u5177\u4E2D\u986F\u793A\u7684 CPU \u611F\u6E2C\u5668\u3002",
            ["Take PawnIO Setup."] = "\u9078\u64C7 PawnIO Setup\u3002",
            ["This ClawTweaks Center build is outdated. Please download the latest build."] = "\u9019\u500B ClawTweaks Center \u7248\u672C\u5DF2\u904E\u6642\u3002\u8ACB\u4E0B\u8F09\u6700\u65B0\u7248\u672C\u3002",
            ["{0} (running {1}, needs {2}+)"] = "{0} (\u76EE\u524D {1}\uFF0C\u9700\u8981 {2}+)",
            ["Test build"] = "\u6E2C\u8A66\u7248",
            ["Release"] = "\u6B63\u5F0F\u7248",
            ["BROKEN: leftover registry entries but no driver binary \u2014 reinstall and reboot"] = "\u5DF2\u640D\u58DE\uFF1A\u767B\u9304\u6A94\u6B98\u7559\u4F46\u6C92\u6709\u9A45\u52D5\u7A0B\u5F0F\u6A94\u6848 \u2014 \u8ACB\u91CD\u88DD\u4E26\u91CD\u65B0\u555F\u52D5",
            ["BROKEN: usbip's files are installed but its driver is not registered \u2014 the installer's driver step (devnode.exe) failed. The usual cause is the -arm64 download, which the release page lists above the x64 one. Uninstall usbip, re-run the installer whose name ends in -x64.exe, and reboot."] = "\u5DF2\u640D\u58DE\uFF1Ausbip \u7684\u6A94\u6848\u5DF2\u5B89\u88DD\uFF0C\u4F46\u9A45\u52D5\u7A0B\u5F0F\u6C92\u6709\u8A3B\u518A \u2014 \u5B89\u88DD\u7A0B\u5F0F\u7684\u9A45\u52D5\u7A0B\u5F0F\u6B65\u9A5F (devnode.exe) \u5931\u6557\u4E86\u3002\u5E38\u898B\u539F\u56E0\u662F\u4E0B\u8F09\u4E86 -arm64 \u7248\uFF0C\u767C\u4F48\u9801\u628A\u5B83\u5217\u5728 x64 \u4E4B\u4E0A\u3002\u8ACB\u89E3\u9664\u5B89\u88DD usbip\uFF0C\u57F7\u884C\u540D\u7A31\u4EE5 -x64.exe \u7D50\u5C3E\u7684\u5B89\u88DD\u7A0B\u5F0F\uFF0C\u7136\u5F8C\u91CD\u65B0\u555F\u52D5\u3002",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Older versions crash the device with a blue screen while the virtual controller is running, so ClawTweaks will not start it. Run the ClawTweaks setup, or install {1} from the link on this page, and reboot."] = "\u4E0D\u652F\u63F4\u7684\u7248\u672C\uFF1A\u5DF2\u5B89\u88DD usbip {0}\uFF0CClawTweaks \u9700\u8981 {1}\u3002\u66F4\u820A\u7684\u7248\u672C\u6703\u5728\u865B\u64EC\u63A7\u5236\u5668\u57F7\u884C\u6642\u8B93\u88DD\u7F6E\u85CD\u5E55\uFF0C\u6240\u4EE5 ClawTweaks \u4E0D\u6703\u555F\u52D5\u5B83\u3002\u8ACB\u57F7\u884C ClawTweaks \u5B89\u88DD\u7A0B\u5F0F\uFF0C\u6216\u5F9E\u672C\u9801\u9023\u7D50\u5B89\u88DD {1}\uFF0C\u7136\u5F8C\u91CD\u65B0\u555F\u52D5\u3002",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Uninstall usbip, install {1} from the link on this page, and reboot."] = "\u4E0D\u652F\u63F4\u7684\u7248\u672C\uFF1A\u5DF2\u5B89\u88DD usbip {0}\uFF0CClawTweaks \u9700\u8981 {1}\u3002\u8ACB\u89E3\u9664\u5B89\u88DD usbip\uFF0C\u5F9E\u672C\u9801\u9023\u7D50\u5B89\u88DD {1}\uFF0C\u7136\u5F8C\u91CD\u65B0\u555F\u52D5\u3002",
