            ["Pictures"] = "\u5716\u7247",
            ["No release notes."] = "\u6C92\u6709\u767C\u884C\u8AAA\u660E\u3002",
            ["Backups live in {0}. Create one first."] = "\u5099\u4EFD\u5B58\u653E\u5728 {0}\u3002\u8ACB\u5148\u5EFA\u7ACB\u4E00\u500B\u3002",
            ["Safety copy of the previous state: {0}"] = "\u4E0A\u4E00\u500B\u72C0\u614B\u7684\u526F\u672C\uFF1A{0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "\u6240\u6709 ClawTweaks \u8A2D\u5B9A\u5DF2\u91CD\u8A2D\u70BA\u4E7E\u6DE8\u72C0\u614B\u3002\u8ACB\u91CD\u65B0\u958B\u555F Game Bar (Win+G) \u7E7C\u7E8C\u3002",
            ["Saved {0} stores to:\n{1}"] = "\u5DF2\u628A {0} \u500B\u5546\u5E97\u5132\u5B58\u5230\uFF1A\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "\u5DF2\u9084\u539F {0} \u500B\u6A94\u6848\u3002helper \u6B63\u5728\u91CD\u65B0\u555F\u52D5 \u2014 \u8ACB\u91CD\u65B0\u958B\u555F Game Bar (Win+G) \u7E7C\u7E8C\u3002",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "\u9019\u500B\u5099\u4EFD\u4F86\u81EA\u300C{0}\u300D\uFF0C\u4F46\u9019\u53F0\u88DD\u7F6E\u770B\u8D77\u4F86\u662F {1}\u3002\u8207\u88DD\u7F6E\u76F8\u95DC\u7684\u6578\u503C (TDP \u4E0A\u9650\u3001\u98A8\u6247\u523B\u5EA6) \u6703\u4F9D\u539F\u6A23\u9084\u539F\u3002",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "\u5099\u4EFD\u4F86\u81EA {0}\uFF1B\u4F60\u5B89\u88DD\u7684\u662F {1}\u3002\u8DE8\u7248\u672C\u9084\u539F\u901A\u5E38\u53EF\u884C\uFF0C\u4F46\u4E0D\u4FDD\u8B49\u3002",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "\u4F60\u5728\u300C{0}\u300D\u901A\u9053 \u2014 \u5DF2\u77E5\u5B89\u88DD\u6D41\u7A0B\u5728 Insider \u7248\u672C\u4E0A\u7121\u6CD5\u6B63\u5E38\u904B\u4F5C\u3002",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 GitHub \u4E0A\u6709\u66F4\u65B0\uFF1A{0} ({1})",
            ["ClawTweaks Center update available: {0}"] = "ClawTweaks Center \u6709\u66F4\u65B0\uFF1A{0}",
            ["You're running {0}. Install it here \u2014 Center restarts when it's done."] = "\u4F60\u5728\u7528 {0}\u3002\u53EF\u4EE5\u5728\u9019\u88E1\u5B89\u88DD \u2014 \u5B8C\u6210\u5F8C Center \u6703\u91CD\u65B0\u555F\u52D5\u3002",
            ["You're running {0}. Download the new Setup file and run it \u2014 it installs over this one, and no administrator rights are needed."] = "\u4F60\u5728\u7528 {0}\u3002\u8ACB\u4E0B\u8F09\u65B0\u7684\u5B89\u88DD\u7A0B\u5F0F\u4E26\u57F7\u884C \u2014 \u5B83\u6703\u8986\u84CB\u5B89\u88DD\uFF0C\u4E5F\u4E0D\u9700\u8981\u7CFB\u7D71\u7BA1\u7406\u54E1\u6B0A\u9650\u3002",
            ["Installing {0}"] = "\u6B63\u5728\u5B89\u88DD {0}",
            ["{0} \u2014 helper is up and running."] = "{0} \u2014 helper \u5DF2\u555F\u52D5\u4E26\u5728\u57F7\u884C\u3002",
            ["Installed {0}"] = "\u5DF2\u5B89\u88DD {0}",
            ["Updated {0} \u2192 {1}"] = "\u5DF2\u66F4\u65B0 {0} \u2192 {1}",
            ["Downgraded {0} \u2192 {1}"] = "\u5DF2\u964D\u7D1A {0} \u2192 {1}",
            ["Reinstalled {0}"] = "\u5DF2\u91CD\u88DD {0}",
            ["Unexpected survivor: {0} handed over, {1} terminated."] = "\u610F\u5916\u6B98\u7559\uFF1A{0} \u5DF2\u4EA4\u63A5\uFF0C{1} \u5DF2\u7D42\u6B62\u3002",
            ["Downloading the package ({0})\u2026"] = "\u6B63\u5728\u4E0B\u8F09\u5957\u4EF6 ({0})\u2026",
            ["Package verified: {0}, {1:F1} MB."] = "\u5957\u4EF6\u5DF2\u9A57\u8B49\uFF1A{0}\uFF0C{1:F1} MB\u3002",
            ["Outdated version \u2014 install {0} or newer"] = "\u7248\u672C\u904E\u820A \u2014 \u8ACB\u5B89\u88DD {0} \u6216\u66F4\u65B0\u7248\u672C",
            ["Auto-jump active (position {0})."] = "\u81EA\u52D5\u8DF3\u8F49\u5DF2\u555F\u7528 (\u4F4D\u7F6E {0})\u3002",
            ["Auto-jump set to position {0}."] = "\u81EA\u52D5\u8DF3\u8F49\u5DF2\u8A2D\u70BA\u4F4D\u7F6E {0}\u3002",
            ["Could not start the old uninstaller: {0}"] = "\u7121\u6CD5\u555F\u52D5\u820A\u7684\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F\uFF1A{0}",
            ["it is a launcher for the .dll next to it, not a standalone build."] = "\u5B83\u53EA\u662F\u65C1\u908A\u90A3\u500B .dll \u7684\u555F\u52D5\u5668\uFF0C\u4E0D\u662F\u7368\u7ACB\u7248\u672C\u3002",
            ["it is only {0} KB, too small to carry its own runtime."] = "\u5B83\u53EA\u6709 {0} KB\uFF0C\u592A\u5C0F\u4E86\uFF0C\u88DD\u4E0D\u4E0B\u81EA\u5DF1\u7684\u57F7\u884C\u968E\u6BB5\u3002",
            ["its own file could not be inspected ({0})."] = "\u7121\u6CD5\u6AA2\u67E5\u5B83\u81EA\u5DF1\u7684\u6A94\u6848 ({0})\u3002",
            ["This copy of Center cannot install itself: {0} Use the single-file build from the release page (or publish/), not the executable from a plain build output."] = "\u9019\u500B Center \u526F\u672C\u7121\u6CD5\u5B89\u88DD\u81EA\u5DF1\uFF1A{0} \u8ACB\u4F7F\u7528\u767C\u4F48\u9801 (\u6216 publish/) \u7684\u55AE\u4E00\u6A94\u6848\u7248\u672C\uFF0C\u800C\u4E0D\u662F\u4E00\u822C\u7D44\u5EFA\u8F38\u51FA\u88E1\u7684\u57F7\u884C\u6A94\u3002",
            ["Installing to {0}..."] = "\u6B63\u5728\u5B89\u88DD\u5230 {0}...",
            ["Could not create the desktop icon: {0}"] = "\u7121\u6CD5\u5EFA\u7ACB\u684C\u9762\u5716\u793A\uFF1A{0}",
            ["Install failed: {0}"] = "\u5B89\u88DD\u5931\u6557\uFF1A{0}",
            ["Waiting for the running Center to close ({0}/{1})..."] = "\u6B63\u5728\u7B49\u5F85\u57F7\u884C\u4E2D\u7684 Center \u95DC\u9589 ({0}/{1})...",
            ["Connecting controller"] = "\u6B63\u5728\u9023\u63A5\u63A7\u5236\u5668",
            ["Setting up virtual gamepad\u2026"] = "\u6B63\u5728\u8A2D\u5B9A\u865B\u64EC\u63A7\u5236\u5668\u2026",
            ["Controller connected"] = "\u63A7\u5236\u5668\u5DF2\u9023\u63A5",
            ["Ready to play"] = "\u53EF\u4EE5\u958B\u59CB\u904A\u6232",
            ["Controller not connected"] = "\u63A7\u5236\u5668\u672A\u9023\u63A5",
            ["Restoring controller"] = "\u6B63\u5728\u9084\u539F\u63A7\u5236\u5668",
            ["Switching back to the hardware gamepad\u2026"] = "\u6B63\u5728\u5207\u56DE\u786C\u9AD4\u63A7\u5236\u5668\u2026",
            ["Controller restored"] = "\u63A7\u5236\u5668\u5DF2\u9084\u539F",
            ["Hardware gamepad is back"] = "\u786C\u9AD4\u63A7\u5236\u5668\u56DE\u4F86\u4E86",
            ["Controller not restored"] = "\u63A7\u5236\u5668\u672A\u9084\u539F",
