            ["FAQ"] = "\u5E38\u898B\u554F\u984C",
            ["Fixed while Center is the Windows full-screen start app."] = "Center \u4F5C\u70BA Windows \u5168\u87A2\u5E55\u555F\u52D5\u61C9\u7528\u7A0B\u5F0F\u6642\u56FA\u5B9A\u3002",
            ["Turn on \"Start Steam with the library\" in the library settings to speed this up next time."] = "\u5728\u904A\u6232\u5EAB\u8A2D\u5B9A\u4E2D\u958B\u555F\u300C\u96A8\u904A\u6232\u5EAB\u555F\u52D5 Steam\u300D\uFF0C\u4E0B\u6B21\u6703\u66F4\u5FEB\u3002",
            ["Make the library your Xbox full-screen start app"] = "\u5C07\u904A\u6232\u5EAB\u8A2D\u70BA Xbox \u5168\u87A2\u5E55\u555F\u52D5\u61C9\u7528\u7A0B\u5F0F",
            ["Saves memory and start-up time. Run the setup from the GitHub releases page to register it."] = "\u7BC0\u7701\u8A18\u61B6\u9AD4\u548C\u555F\u52D5\u6642\u9593\u3002\u5F9E GitHub \u767C\u884C\u9801\u57F7\u884C\u5B89\u88DD\u7A0B\u5F0F\u5373\u53EF\u8A3B\u518A\u3002",
            ["Automatic check: off"] = "\u81EA\u52D5\u6AA2\u67E5\uFF1A\u95DC",
            ["Automatic check: {0}"] = "\u81EA\u52D5\u6AA2\u67E5\uFF1A{0}",
            ["Change in Center settings"] = "\u5728 Center \u8A2D\u5B9A\u4E2D\u8B8A\u66F4",
            ["Mute"] = "\u975C\u97F3",
            ["Unmute"] = "\u53D6\u6D88\u975C\u97F3",
            ["Tabs order and visibility"] = "\u5206\u9801\u9806\u5E8F\u8207\u986F\u793A",
            ["Opens Steam in the tray when you open the library. The first Steam game after a boot starts faster."] = "\u958B\u555F\u904A\u6232\u5EAB\u6642\u5728\u7CFB\u7D71\u5323\u555F\u52D5 Steam\u3002\u958B\u6A5F\u5F8C\u7B2C\u4E00\u500B Steam \u904A\u6232\u555F\u52D5\u66F4\u5FEB\u3002",
            ["In fullscreen mode, Steam's window can open behind Center."] = "\u5168\u87A2\u5E55\u6A21\u5F0F\u4E0B\uFF0CSteam \u8996\u7A97\u53EF\u80FD\u6703\u5728 Center \u5F8C\u9762\u958B\u555F\u3002",
            ["Steam removes the game files. In fullscreen, Steam's dialog can open behind Center."] = "Steam \u6703\u522A\u9664\u904A\u6232\u6A94\u6848\u3002\u5168\u87A2\u5E55\u4E0B\u5176\u5C0D\u8A71\u6846\u53EF\u80FD\u5728 Center \u5F8C\u9762\u958B\u555F\u3002",
            ["Opens your Epic library. Uninstall the game there."] = "\u958B\u555F\u4F60\u7684 Epic \u904A\u6232\u5EAB\u3002\u5728\u90A3\u88E1\u89E3\u9664\u5B89\u88DD\u904A\u6232\u3002",
            ["Deletes the game for this Windows user."] = "\u70BA\u6B64 Windows \u4F7F\u7528\u8005\u522A\u9664\u904A\u6232\u3002",
            ["Press again to delete the game."] = "\u518D\u6309\u4E00\u6B21\u4EE5\u522A\u9664\u904A\u6232\u3002",
            ["No uninstaller found"] = "\u627E\u4E0D\u5230\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F",
            ["Runs the game's own uninstaller"] = "\u57F7\u884C\u904A\u6232\u81EA\u5E36\u7684\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F",
            ["Runs the game's own uninstaller. In fullscreen, it can open behind Center."] = "\u57F7\u884C\u904A\u6232\u81EA\u5E36\u7684\u89E3\u9664\u5B89\u88DD\u7A0B\u5F0F\u3002\u5168\u87A2\u5E55\u6642\u5B83\u53EF\u80FD\u5728 Center \u5F8C\u9762\u958B\u555F\u3002",
            ["Graphics (WHQL only)"] = "\u986F\u793A\u5361\uFF08\u50C5 WHQL\uFF09",
            ["Graphics (WHQL and non-WHQL)"] = "\u986F\u793A\u5361\uFF08WHQL \u548C\u975E WHQL\uFF09",
            ["Download started in the background. The installer opens when it is done."] = "\u5DF2\u5728\u80CC\u666F\u958B\u59CB\u4E0B\u8F09\u3002\u5B8C\u6210\u5F8C\u5B89\u88DD\u7A0B\u5F0F\u6703\u81EA\u52D5\u958B\u555F\u3002",
            ["Download started in the background - over 800 MB. The installer opens when it is done."] = "\u5DF2\u5728\u80CC\u666F\u958B\u59CB\u4E0B\u8F09\uFF08\u8D85\u904E 800 MB\uFF09\u3002\u5B8C\u6210\u5F8C\u5B89\u88DD\u7A0B\u5F0F\u6703\u81EA\u52D5\u958B\u555F\u3002",
            ["Download started in the background. The folder opens when it is done - run Setup.bat there."] = "\u5DF2\u5728\u80CC\u666F\u958B\u59CB\u4E0B\u8F09\u3002\u5B8C\u6210\u5F8C\u6703\u958B\u555F\u8CC7\u6599\u593E\uFF0C\u8ACB\u5728\u5176\u4E2D\u57F7\u884C Setup.bat\u3002",
            ["{0} update(s) ready, restart pending"] = "{0} \u500B\u66F4\u65B0\u5C31\u7DD2\uFF0C\u7B49\u5F85\u91CD\u65B0\u555F\u52D5",
            ["Install them in Windows Update, then restart."] = "\u5728 Windows Update \u4E2D\u5B89\u88DD\uFF0C\u7136\u5F8C\u91CD\u65B0\u555F\u52D5\u3002",
            ["Check drivers again"] = "\u91CD\u65B0\u6AA2\u67E5\u9A45\u52D5\u7A0B\u5F0F",
            ["Also non-WHQL graphics drivers"] = "\u4E5F\u5305\u62EC\u975E WHQL \u986F\u793A\u5361\u9A45\u52D5\u7A0B\u5F0F",
            ["Modded Wi-Fi driver instead of stock"] = "\u4F7F\u7528\u4FEE\u6539\u7248 Wi-Fi \u9A45\u52D5\u7A0B\u5F0F\u800C\u975E\u539F\u5EE0",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). Optionally the library and Center settings too."] = "\u91CD\u8A2D\u6240\u6709 ClawTweaks \u8A2D\u5B9A\uFF08\u8A2D\u5B9A\u6A94\u3001\u98A8\u6247\u66F2\u7DDA\u3001TDP\u3001\u63A7\u5236\u5668\uFF09\u3002\u53EF\u9078\u540C\u6642\u91CD\u8A2D\u904A\u6232\u5EAB\u548C Center \u8A2D\u5B9A\u3002",
            ["Save all your profiles and settings into a single ZIP you can restore later. Optionally with the library, Center settings and your game art."] = "\u5C07\u6240\u6709\u8A2D\u5B9A\u6A94\u548C\u8A2D\u5B9A\u5132\u5B58\u70BA\u4E00\u500B ZIP\uFF0C\u4EE5\u4FBF\u65E5\u5F8C\u9084\u539F\u3002\u53EF\u9078\u5305\u542B\u904A\u6232\u5EAB\u3001Center \u8A2D\u5B9A\u548C\u4F60\u7684\u904A\u6232\u5C01\u9762\u3002",
            ["Also reset the library and Center settings"] = "\u540C\u6642\u91CD\u8A2D\u904A\u6232\u5EAB\u548C Center \u8A2D\u5B9A",
