            ["No release notes."] = "Nessuna nota di rilascio.",
            ["Backups live in {0}. Create one first."] = "I backup si trovano in {0}. Creane prima uno.",
            ["Safety copy of the previous state: {0}"] = "Copia di sicurezza dello stato precedente: {0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "Tutte le impostazioni ClawTweaks sono state azzerate. Riapri la Game Bar (Win+G) per continuare.",
            ["Saved {0} stores to:\n{1}"] = "Salvati {0} archivi in:\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "Ripristinati {0} file. L'helper si sta riavviando \u2014 riapri la Game Bar (Win+G) per continuare.",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "Questo backup viene da '{0}', ma questo dispositivo sembra {1}. I valori specifici del dispositivo (limiti TDP, scala ventola) verranno ripristinati cos\u00EC come sono.",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "Il backup viene da {0}; hai installato {1}. Il ripristino tra versioni di solito funziona, ma non \u00E8 garantito.",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "Sei sul canale \"{0}\" \u2014 al momento la routine di installazione notoriamente non funziona bene sulle build Insider.",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 Aggiornamento disponibile su GitHub: {0} ({1})",
            ["ClawTweaks Center update available: {0}"] = "Aggiornamento di ClawTweaks Center disponibile: {0}",
            ["You're running {0}. Install it here \u2014 Center restarts when it's done."] = "Hai {0}. Installalo qui \u2014 Center si riavvia alla fine.",
            ["You're running {0}. Download the new Setup file and run it \u2014 it installs over this one, and no administrator rights are needed."] = "Hai {0}. Scarica il nuovo file di Setup ed eseguilo \u2014 si installa sopra questo, senza diritti di amministratore.",
            ["Installing {0}"] = "Installazione di {0}",
            ["{0} \u2014 helper is up and running."] = "{0} \u2014 l'helper \u00E8 attivo.",
            ["Installed {0}"] = "Installato {0}",
            ["Updated {0} \u2192 {1}"] = "Aggiornato {0} \u2192 {1}",
