            ["Pictures"] = "Imagens",
            ["No release notes."] = "Sem notas de release.",
            ["Backups live in {0}. Create one first."] = "Os backups ficam em {0}. Crie um primeiro.",
            ["Safety copy of the previous state: {0}"] = "C\u00F3pia de seguran\u00E7a do estado anterior: {0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "Todas as configura\u00E7\u00F5es do ClawTweaks foram redefinidas. Reabra a Game Bar (Win+G) para continuar.",
            ["Saved {0} stores to:\n{1}"] = "{0} reposit\u00F3rios salvos em:\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "{0} arquivos restaurados. O helper est\u00E1 reiniciando \u2014 reabra a Game Bar (Win+G) para continuar.",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "Este backup \u00E9 de '{0}', mas este dispositivo parece ser {1}. Valores espec\u00EDficos do dispositivo (limites de TDP, escala da ventoinha) ser\u00E3o restaurados como est\u00E3o.",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "O backup \u00E9 de {0}; voc\u00EA tem {1} instalado. Restaurar entre vers\u00F5es costuma funcionar, mas n\u00E3o \u00E9 garantido.",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "Voc\u00EA est\u00E1 no canal \"{0}\" \u2014 a rotina de instala\u00E7\u00E3o atualmente n\u00E3o funciona bem em builds Insider.",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 Atualiza\u00E7\u00E3o dispon\u00EDvel no GitHub: {0} ({1})",
            ["ClawTweaks Center update available: {0}"] = "Atualiza\u00E7\u00E3o do ClawTweaks Center dispon\u00EDvel: {0}",
            ["You're running {0}. Install it here \u2014 Center restarts when it's done."] = "Voc\u00EA usa {0}. Instale aqui \u2014 o Center reinicia ao terminar.",
            ["You're running {0}. Download the new Setup file and run it \u2014 it installs over this one, and no administrator rights are needed."] = "Voc\u00EA usa {0}. Baixe o novo arquivo de Setup e execute-o \u2014 ele instala por cima deste, sem direitos de administrador.",
            ["Installing {0}"] = "Instalando {0}",
            ["{0} \u2014 helper is up and running."] = "{0} \u2014 o helper est\u00E1 em execu\u00E7\u00E3o.",
            ["Installed {0}"] = "Instalado {0}",
            ["Updated {0} \u2192 {1}"] = "Atualizado {0} \u2192 {1}",
