            ["Reinstalled {0}"] = "Reinstalado {0}",
            ["Unexpected survivor: {0} handed over, {1} terminated."] = "Sobrevivente inesperado: {0} entregues, {1} encerrados.",
            ["Downloading the package ({0})\u2026"] = "Baixando o pacote ({0})\u2026",
            ["Package verified: {0}, {1:F1} MB."] = "Pacote verificado: {0}, {1:F1} MB.",
            ["Outdated version \u2014 install {0} or newer"] = "Vers\u00E3o desatualizada \u2014 instale {0} ou mais recente",
            ["Auto-jump active (position {0})."] = "Salto autom\u00E1tico ativo (posi\u00E7\u00E3o {0}).",
            ["Auto-jump set to position {0}."] = "Salto autom\u00E1tico definido na posi\u00E7\u00E3o {0}.",
            ["Could not start the old uninstaller: {0}"] = "N\u00E3o foi poss\u00EDvel iniciar o desinstalador antigo: {0}",
            ["it is a launcher for the .dll next to it, not a standalone build."] = "\u00E9 um launcher para a .dll ao lado, n\u00E3o um build aut\u00F4nomo.",
            ["it is only {0} KB, too small to carry its own runtime."] = "tem s\u00F3 {0} KB, pequeno demais para conter o pr\u00F3prio runtime.",
            ["its own file could not be inspected ({0})."] = "n\u00E3o foi poss\u00EDvel inspecionar seu pr\u00F3prio arquivo ({0}).",
            ["This copy of Center cannot install itself: {0} Use the single-file build from the release page (or publish/), not the executable from a plain build output."] = "Esta c\u00F3pia do Center n\u00E3o pode se instalar: {0} Use o build de arquivo \u00FAnico da p\u00E1gina de releases (ou publish/), n\u00E3o o execut\u00E1vel de um build comum.",
            ["Installing to {0}..."] = "Instalando em {0}...",
            ["Could not create the desktop icon: {0}"] = "N\u00E3o foi poss\u00EDvel criar o \u00EDcone na \u00E1rea de trabalho: {0}",
            ["Install failed: {0}"] = "Falha na instala\u00E7\u00E3o: {0}",
            ["Waiting for the running Center to close ({0}/{1})..."] = "Aguardando o Center em execu\u00E7\u00E3o fechar ({0}/{1})...",
            ["Connecting controller"] = "Conectando o controle",
            ["Setting up virtual gamepad\u2026"] = "Preparando o controle virtual\u2026",
            ["Controller connected"] = "Controle conectado",
            ["Ready to play"] = "Pronto para jogar",
            ["Controller not connected"] = "Controle n\u00E3o conectado",
            ["Restoring controller"] = "Restaurando o controle",
            ["Switching back to the hardware gamepad\u2026"] = "Voltando ao controle f\u00EDsico\u2026",
            ["Controller restored"] = "Controle restaurado",
            ["Hardware gamepad is back"] = "O controle f\u00EDsico voltou",
            ["Controller not restored"] = "Controle n\u00E3o restaurado",
            ["It stays in DInput mode"] = "Ele fica em modo DInput",
            ["HW Mouse ON \u2014 controller paused. Click the HW Mouse tile or press the keyboard hotkey to return."] = "Mouse HW ligado \u2014 controle pausado. Clique no bloco Mouse HW ou use o atalho para voltar.",
            ["Virtual mouse restored"] = "Mouse virtual restaurado",
            ["Controller mode"] = "Modo controle",
            ["Mouse mode"] = "Modo mouse",
            ["Charge Limit: set it up in Settings first"] = "Limite de carga: configure antes nas configura\u00E7\u00F5es",
            ["Charge Limit: On {0}%"] = "Limite de carga: ligado {0}%",
