            ["Reset complete"] = "\u30EA\u30BB\u30C3\u30C8\u5B8C\u4E86",
            ["Reset failed"] = "\u30EA\u30BB\u30C3\u30C8\u306B\u5931\u6557",
            ["Reset the app, or back up your profiles."] = "\u30A2\u30D7\u30EA\u3092\u30EA\u30BB\u30C3\u30C8\u3059\u308B\u304B\u3001\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u3092\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3057\u307E\u3059\u3002",
            ["Resetting all ClawTweaks settings\u2026"] = "ClawTweaks \u306E\u8A2D\u5B9A\u3092\u3059\u3079\u3066\u30EA\u30BB\u30C3\u30C8\u4E2D\u2026",
