            ["Set as cover"] = "\u30AB\u30D0\u30FC\u306B\u8A2D\u5B9A",
            ["Set the library as the screen Center opens on in Library Settings."] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u8A2D\u5B9A\u3067\u3001Center \u304C\u958B\u304F\u753B\u9762\u3092\u30E9\u30A4\u30D6\u30E9\u30EA\u306B\u3067\u304D\u307E\u3059\u3002",
            ["Set up Center M, controller and Game Bar."] = "Center M\u3001\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3001Game Bar \u3092\u8A2D\u5B9A\u3057\u307E\u3059\u3002",
            ["Set your status"] = "\u30B9\u30C6\u30FC\u30BF\u30B9\u3092\u8A2D\u5B9A",
            ["Set. Covers are downloaded for games with none."] = "\u8A2D\u5B9A\u6E08\u307F\u3002\u30AB\u30D0\u30FC\u304C\u7121\u3044\u30B2\u30FC\u30E0\u306F\u81EA\u52D5\u3067\u53D6\u5F97\u3057\u307E\u3059\u3002",
            ["Setting cover\u2026"] = "\u30AB\u30D0\u30FC\u3092\u8A2D\u5B9A\u4E2D\u2026",
            ["Settings"] = "\u8A2D\u5B9A",
            ["Settings reset."] = "\u8A2D\u5B9A\u3092\u30EA\u30BB\u30C3\u30C8\u3057\u307E\u3057\u305F\u3002",
            ["Show the certificate in Explorer"] = "\u8A3C\u660E\u66F8\u3092\u30A8\u30AF\u30B9\u30D7\u30ED\u30FC\u30E9\u30FC\u3067\u8868\u793A",
            ["Shows your installed Steam, Xbox and Epic games."] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u306E Steam\u3001Xbox\u3001Epic \u306E\u30B2\u30FC\u30E0\u3092\u8868\u793A\u3057\u307E\u3059\u3002",
            ["Shut down"] = "\u30B7\u30E3\u30C3\u30C8\u30C0\u30A6\u30F3",
            ["Signing certificate"] = "\u7F72\u540D\u8A3C\u660E\u66F8",
            ["Some hardware commands could not be sent."] = "\u4E00\u90E8\u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u547D\u4EE4\u3092\u9001\u308C\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["Square ROM art"] = "\u6B63\u65B9\u5F62\u306E ROM \u753B\u50CF",
            ["Start"] = "\u958B\u59CB",
            ["Start Center with ClawTweaks"] = "ClawTweaks \u3068\u4E00\u7DD2\u306B Center \u3092\u8D77\u52D5",
            ["Start in the library"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3067\u8D77\u52D5",
            ["Start menu, desktop and startup"] = "\u30B9\u30BF\u30FC\u30C8\u30E1\u30CB\u30E5\u30FC\u3001\u30C7\u30B9\u30AF\u30C8\u30C3\u30D7\u3001\u30B9\u30BF\u30FC\u30C8\u30A2\u30C3\u30D7",
            ["Started from Windows"] = "Windows \u304B\u3089\u8D77\u52D5",
            ["Starting\u2026"] = "\u8D77\u52D5\u4E2D\u2026",
            ["Stay open"] = "\u958B\u3044\u305F\u307E\u307E",
            ["Steam Xbox filter driver"] = "Steam \u306E Xbox \u30D5\u30A3\u30EB\u30BF\u30FC\u30C9\u30E9\u30A4\u30D0\u30FC",
            ["Steam asks you where to put it."] = "\u4FDD\u5B58\u5148\u306F Steam \u304C\u5C0B\u306D\u307E\u3059\u3002",
            ["Steam cover art is found automatically."] = "Steam \u306E\u30AB\u30D0\u30FC\u306F\u81EA\u52D5\u3067\u898B\u3064\u304B\u308A\u307E\u3059\u3002",
            ["Steam has taken over. The download shows in Recent."] = "Steam \u304C\u5F15\u304D\u7D99\u304E\u307E\u3057\u305F\u3002\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306F\u300C\u6700\u8FD1\u300D\u306B\u8868\u793A\u3055\u308C\u307E\u3059\u3002",
            ["SteamGridDB key"] = "SteamGridDB \u30AD\u30FC",
            ["Step 1 has not run. After this, nothing on the device can switch the charge limit off or hand the fan back to firmware."] = "\u624B\u9806 1 \u304C\u5B9F\u884C\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002\u3053\u308C\u4EE5\u964D\u3001\u30C7\u30D0\u30A4\u30B9\u4E0A\u3067\u5145\u96FB\u5236\u9650\u3092\u89E3\u9664\u3057\u305F\u308A\u30D5\u30A1\u30F3\u3092\u30D5\u30A1\u30FC\u30E0\u30A6\u30A7\u30A2\u306B\u623B\u3057\u305F\u308A\u3067\u304D\u308B\u3082\u306E\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
            ["Stick deadzone"] = "\u30B9\u30C6\u30A3\u30C3\u30AF\u306E\u904A\u3073",
            ["Stretch"] = "\u5F15\u304D\u4F38\u3070\u3059",
            ["System"] = "\u30B7\u30B9\u30C6\u30E0",
            ["System language"] = "\u30B7\u30B9\u30C6\u30E0\u306E\u8A00\u8A9E",
            ["TDP boost"] = "TDP \u30D6\u30FC\u30B9\u30C8",
            ["Test versions"] = "\u30C6\u30B9\u30C8\u7248",
            ["That is what makes the extra controller features possible."] = "\u305D\u308C\u304C\u8FFD\u52A0\u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u6A5F\u80FD\u3092\u53EF\u80FD\u306B\u3057\u3066\u3044\u307E\u3059\u3002",
            ["That key was rejected."] = "\u305D\u306E\u30AD\u30FC\u306F\u62D2\u5426\u3055\u308C\u307E\u3057\u305F\u3002",
            ["The charge limit, the fan curve and the controller mode can only be reset by ClawTweaks. Install it again to restore them, then come back here. You can still uninstall Center."] = "\u5145\u96FB\u5236\u9650\u3001\u30D5\u30A1\u30F3\u30AB\u30FC\u30D6\u3001\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30E2\u30FC\u30C9\u306F ClawTweaks \u3067\u3057\u304B\u623B\u305B\u307E\u305B\u3093\u3002\u5165\u308C\u76F4\u3057\u3066\u304B\u3089\u3001\u3053\u3053\u306B\u623B\u3063\u3066\u304F\u3060\u3055\u3044\u3002Center \u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u4ECA\u3082\u3067\u304D\u307E\u3059\u3002",
            ["The controller did not confirm \u2014 check it before you unplug."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u5FDC\u7B54\u3057\u307E\u305B\u3093\u3067\u3057\u305F \u2014 \u5916\u3059\u524D\u306B\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["The device can be restored"] = "\u30C7\u30D0\u30A4\u30B9\u3092\u5FA9\u5143\u3067\u304D\u307E\u3059",
            ["The helper did not confirm in time."] = "\u30D8\u30EB\u30D1\u30FC\u304C\u6642\u9593\u5185\u306B\u5FDC\u7B54\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["The helper is not answering"] = "\u30D8\u30EB\u30D1\u30FC\u304C\u5FDC\u7B54\u3057\u307E\u305B\u3093",
            ["The library comes back when the game ends."] = "\u30B2\u30FC\u30E0\u304C\u7D42\u308F\u308B\u3068\u30E9\u30A4\u30D6\u30E9\u30EA\u306B\u623B\u308A\u307E\u3059\u3002",
            ["The native controller must be clean before the virtual controller mode can work. In virtual mode the physical pad is hidden and one virtual VIIPER controller is active; in hardware mode the physical pad is used directly."] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30E2\u30FC\u30C9\u3092\u4F7F\u3046\u306B\u306F\u3001\u672C\u4F53\u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u304D\u308C\u3044\u306A\u72B6\u614B\u3067\u3042\u308B\u5FC5\u8981\u304C\u3042\u308A\u307E\u3059\u3002\u4EEE\u60F3\u30E2\u30FC\u30C9\u3067\u306F\u7269\u7406\u30D1\u30C3\u30C9\u304C\u96A0\u3055\u308C\u3001\u4EEE\u60F3 VIIPER \u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C 1 \u53F0\u6709\u52B9\u306B\u306A\u308A\u307E\u3059\u3002\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u30E2\u30FC\u30C9\u3067\u306F\u7269\u7406\u30D1\u30C3\u30C9\u3092\u305D\u306E\u307E\u307E\u4F7F\u3044\u307E\u3059\u3002",
            ["The newest changes, least tested"] = "\u6700\u65B0\u306E\u5909\u66F4\u3001\u30C6\u30B9\u30C8\u306F\u6700\u5C11",
            ["The old helper exited on its own."] = "\u53E4\u3044\u30D8\u30EB\u30D1\u30FC\u306F\u81EA\u5206\u3067\u7D42\u4E86\u3057\u307E\u3057\u305F\u3002",
            ["The old version's uninstaller is running \u2014 confirm its prompt. This notice disappears once it's gone (press \u24CE to refresh)."] = "\u53E4\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u52D5\u4F5C\u4E2D\u3067\u3059 \u2014 \u305D\u306E\u78BA\u8A8D\u306B\u5FDC\u3058\u3066\u304F\u3060\u3055\u3044\u3002\u6D88\u3048\u308B\u3068\u3001\u3053\u306E\u8868\u793A\u3082\u306A\u304F\u306A\u308A\u307E\u3059 (\u24CE \u3067\u66F4\u65B0)\u3002",
            ["The package could not be removed. Close the Game Bar and try again, or remove ClawTweaks from Settings \u2192 Apps."] = "\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u524A\u9664\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002Game Bar \u3092\u9589\u3058\u3066\u3084\u308A\u76F4\u3059\u304B\u3001\u8A2D\u5B9A \u2192 \u30A2\u30D7\u30EA\u304B\u3089 ClawTweaks \u3092\u524A\u9664\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["The package family conflicted with this update. Clearing it and retrying once\u2026"] = "\u30D1\u30C3\u30B1\u30FC\u30B8\u30D5\u30A1\u30DF\u30EA\u30FC\u304C\u3053\u306E\u66F4\u65B0\u3068\u885D\u7A81\u3057\u307E\u3057\u305F\u3002\u6D88\u53BB\u3057\u3066\u4E00\u5EA6\u3060\u3051\u518D\u8A66\u884C\u3057\u307E\u3059\u2026",
            ["The reset did not finish."] = "\u30EA\u30BB\u30C3\u30C8\u304C\u5B8C\u4E86\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["The signing certificate uses Windows' own prompt, once per device."] = "\u7F72\u540D\u8A3C\u660E\u66F8\u306F Windows \u81EA\u8EAB\u306E\u78BA\u8A8D\u753B\u9762\u3092\u4F7F\u3044\u3001\u30C7\u30D0\u30A4\u30B9\u3054\u3068\u306B\u4E00\u5EA6\u3060\u3051\u3067\u3059\u3002",
            ["The widget shows what the helper does; it changes nothing by itself."] = "\u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u306F\u30D8\u30EB\u30D1\u30FC\u306E\u52D5\u4F5C\u3092\u8868\u793A\u3059\u308B\u3060\u3051\u3067\u3001\u305D\u308C\u81EA\u4F53\u306F\u4F55\u3082\u5909\u3048\u307E\u305B\u3093\u3002",
            ["The wiki page could not be read. Open it in a browser."] = "wiki \u30DA\u30FC\u30B8\u3092\u8AAD\u307F\u8FBC\u3081\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30D6\u30E9\u30A6\u30B6\u30FC\u3067\u958B\u3044\u3066\u304F\u3060\u3055\u3044\u3002",
            ["This Setup build is outdated"] = "\u3053\u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u306F\u53E4\u3044\u30D3\u30EB\u30C9\u3067\u3059",
            ["This installs an OLDER version than the one installed."] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u3088\u308A\u53E4\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u5165\u308C\u307E\u3059\u3002",
            ["This is a scaffold build without a bundled package, so there's nothing to install here. In a real setup bundle the .msix and .cer sit next to this exe."] = "\u3053\u308C\u306F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u540C\u68B1\u3057\u306A\u3044\u8A66\u4F5C\u30D3\u30EB\u30C9\u306A\u306E\u3067\u3001\u3053\u3053\u304B\u3089\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3059\u308B\u3082\u306E\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u672C\u6765\u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3067\u306F .msix \u3068 .cer \u304C\u3053\u306E exe \u306E\u96A3\u306B\u3042\u308A\u307E\u3059\u3002",
            ["This puts the device back and clears your ClawTweaks settings:"] = "\u30C7\u30D0\u30A4\u30B9\u3092\u5143\u306B\u623B\u3057\u3001ClawTweaks \u306E\u8A2D\u5B9A\u3092\u6D88\u3057\u307E\u3059:",
            ["This removes ClawTweaks Center and closes it."] = "ClawTweaks Center \u3092\u524A\u9664\u3057\u3066\u9589\u3058\u307E\u3059\u3002",
            ["This removes the ClawTweaks app from Windows."] = "ClawTweaks \u30A2\u30D7\u30EA\u3092 Windows \u304B\u3089\u524A\u9664\u3057\u307E\u3059\u3002",
            ["This resets ALL ClawTweaks settings to a clean state:"] = "ClawTweaks \u306E\u8A2D\u5B9A\u3092\u3059\u3079\u3066\u307E\u3063\u3055\u3089\u306A\u72B6\u614B\u306B\u623B\u3057\u307E\u3059:",
            ["This takes a moment."] = "\u5C11\u3057\u6642\u9593\u304C\u304B\u304B\u308A\u307E\u3059\u3002",
            ["This version can't be installed"] = "\u3053\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u307E\u305B\u3093",
            ["This version is already installed. Open it from the Start Menu or the ClawTweaks Game Bar widget instead of running this Setup file again."] = "\u3053\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u3067\u3059\u3002\u3053\u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u5B9F\u884C\u3057\u76F4\u3055\u305A\u3001\u30B9\u30BF\u30FC\u30C8\u30E1\u30CB\u30E5\u30FC\u304B ClawTweaks \u306E Game Bar \u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u304B\u3089\u958B\u3044\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Timed out"] = "\u30BF\u30A4\u30E0\u30A2\u30A6\u30C8",
            ["Transition to new Center App - Uninstall the old version"] = "\u65B0\u3057\u3044 Center \u30A2\u30D7\u30EA\u3078\u306E\u79FB\u884C - \u53E4\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Trusts the signing certificate, installs the app package, opens the Game Bar and waits for the helper. Safe to run again on an update."] = "\u7F72\u540D\u8A3C\u660E\u66F8\u3092\u4FE1\u983C\u3057\u3001\u30A2\u30D7\u30EA\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3001Game Bar \u3092\u958B\u3044\u3066\u30D8\u30EB\u30D1\u30FC\u3092\u5F85\u3061\u307E\u3059\u3002\u66F4\u65B0\u6642\u306B\u3082\u3046\u4E00\u5EA6\u5B9F\u884C\u3057\u3066\u3082\u5B89\u5168\u3067\u3059\u3002",
            ["Turn MSI Center M back on"] = "MSI Center M \u3092\u623B\u3059",
            ["Turn on"] = "\u30AA\u30F3\u306B\u3059\u308B",
            ["Turning MSI Center M back on\u2026"] = "MSI Center M \u3092\u623B\u3057\u3066\u3044\u307E\u3059\u2026",
            ["Uninstall"] = "\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Uninstall Center"] = "Center \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Update ClawTweaks Center"] = "ClawTweaks Center \u3092\u66F4\u65B0",
            ["Update failed \u2014 see the log for details. Try again, or run as Administrator."] = "\u66F4\u65B0\u306B\u5931\u6557\u3057\u307E\u3057\u305F \u2014 \u8A73\u7D30\u306F\u30ED\u30B0\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u518D\u8A66\u884C\u3059\u308B\u304B\u3001\u7BA1\u7406\u8005\u3068\u3057\u3066\u5B9F\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Updates cost no prompt \u2014 the task does not carry a version number."] = "\u66F4\u65B0\u3067\u306F\u78BA\u8A8D\u306F\u51FA\u307E\u305B\u3093 \u2014 \u30BF\u30B9\u30AF\u306B\u30D0\u30FC\u30B8\u30E7\u30F3\u756A\u53F7\u304C\u7121\u3044\u305F\u3081\u3067\u3059\u3002",
            ["Updating..."] = "\u66F4\u65B0\u4E2D...",
            ["Use Uninstall ClawTweaks here in Center instead."] = "\u3053\u3053 Center \u306E\u300CClawTweaks \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u300D\u3092\u4F7F\u3063\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Verifying the virtual pad\u2026"] = "\u4EEE\u60F3\u30D1\u30C3\u30C9\u3092\u78BA\u8A8D\u4E2D\u2026",
            ["Vibration"] = "\u632F\u52D5",
            ["Virtual controller (VIIPER)"] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC (VIIPER)",
            ["Virtual controller already active \u2014 controller is healthy."] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306F\u3059\u3067\u306B\u6709\u52B9\u3067\u3059 \u2014 \u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306F\u6B63\u5E38\u3067\u3059\u3002",
            ["Virtual pad did not mount \u2014 rolling back to the hardware controller."] = "\u4EEE\u60F3\u30D1\u30C3\u30C9\u3092\u63A5\u7D9A\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F \u2014 \u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306B\u623B\u3057\u307E\u3059\u3002",
            ["Waiting for UAC\u2026"] = "UAC \u3092\u5F85\u3063\u3066\u3044\u307E\u3059\u2026",
            ["Waiting for the ClawTweaks helper to start. If the Game Bar opened but nothing happens, select the ClawTweaks Widget in its widget menu and add it \u2014 a widget that isn't in the Game Bar yet doesn't start the helper on its own."] = "ClawTweaks \u30D8\u30EB\u30D1\u30FC\u306E\u8D77\u52D5\u3092\u5F85\u3063\u3066\u3044\u307E\u3059\u3002Game Bar \u306F\u958B\u3044\u305F\u306E\u306B\u4F55\u3082\u8D77\u304D\u306A\u3044\u5834\u5408\u306F\u3001\u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u30E1\u30CB\u30E5\u30FC\u3067 ClawTweaks \u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u3092\u9078\u3093\u3067\u8FFD\u52A0\u3057\u3066\u304F\u3060\u3055\u3044 \u2014 Game Bar \u306B\u307E\u3060\u7121\u3044\u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u306F\u3001\u30D8\u30EB\u30D1\u30FC\u3092\u81EA\u5206\u3067\u8D77\u52D5\u3057\u307E\u305B\u3093\u3002",
            ["Waiting for the virtual controller to settle\u2026"] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u5B89\u5B9A\u3059\u308B\u306E\u3092\u5F85\u3063\u3066\u3044\u307E\u3059\u2026",
            ["What does the background helper do?"] = "\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u306E\u30D8\u30EB\u30D1\u30FC\u306F\u4F55\u3092\u3057\u307E\u3059\u304B\uFF1F",
            ["What happens"] = "\u4F55\u304C\u8D77\u304D\u308B\u304B",
            ["What is the virtual controller for?"] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306F\u4F55\u306E\u305F\u3081\u3067\u3059\u304B\uFF1F",
            ["What's new"] = "\u66F4\u65B0\u5185\u5BB9",
            ["Where are my settings, and how do I back them up?"] = "\u8A2D\u5B9A\u306F\u3069\u3053\u306B\u3042\u308A\u3001\u3069\u3046\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3057\u307E\u3059\u304B\uFF1F",
            ["Why does ClawTweaks ask for admin rights?"] = "ClawTweaks \u306F\u306A\u305C\u7BA1\u7406\u8005\u6A29\u9650\u3092\u6C42\u3081\u308B\u306E\u3067\u3059\u304B\uFF1F",
            ["Will be saved to"] = "\u4FDD\u5B58\u5148",
            ["Windowed"] = "\u30A6\u30A3\u30F3\u30C9\u30A6",
            ["Windows Insider Preview detected"] = "Windows Insider Preview \u3092\u691C\u51FA\u3057\u307E\u3057\u305F",
            ["Windows asked to uninstall Center. Finish here, or press B to keep everything."] = "Windows \u304C Center \u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u6C42\u3081\u307E\u3057\u305F\u3002\u3053\u3053\u3067\u5B8C\u4E86\u3059\u308B\u304B\u3001B \u3067\u3059\u3079\u3066\u6B8B\u305B\u307E\u3059\u3002",
            ["Windows could not open the package file. This is not a problem with the package itself \u2014 the deployment service (running as SYSTEM) could not read it. Try installing from a folder outside your user profile, and check whether Gaming Services is healthy."] = "Windows \u304C\u30D1\u30C3\u30B1\u30FC\u30B8\u30D5\u30A1\u30A4\u30EB\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30D1\u30C3\u30B1\u30FC\u30B8\u81EA\u4F53\u306E\u554F\u984C\u3067\u306F\u306A\u304F\u3001SYSTEM \u3068\u3057\u3066\u52D5\u304F\u914D\u7F6E\u30B5\u30FC\u30D3\u30B9\u304C\u8AAD\u3081\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30E6\u30FC\u30B6\u30FC\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u5916\u306E\u30D5\u30A9\u30EB\u30C0\u30FC\u304B\u3089\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3001Gaming Services \u304C\u6B63\u5E38\u304B\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Windows could not open the package from this folder. Retrying from a machine-wide location\u2026"] = "Windows \u306F\u3053\u306E\u30D5\u30A9\u30EB\u30C0\u30FC\u304B\u3089\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u958B\u3051\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC\u5171\u901A\u306E\u5834\u6240\u304B\u3089\u518D\u8A66\u884C\u3057\u307E\u3059\u2026",
            ["Windows file picker"] = "Windows \u306E\u30D5\u30A1\u30A4\u30EB\u9078\u629E",
            ["Work down the list. Each step is optional except the last."] = "\u4E0A\u304B\u3089\u9806\u306B\u9032\u3081\u3066\u304F\u3060\u3055\u3044\u3002\u6700\u5F8C\u306E\u624B\u9806\u4EE5\u5916\u306F\u4EFB\u610F\u3067\u3059\u3002",
            ["Working\u2026"] = "\u51E6\u7406\u4E2D\u2026",
            ["XInput controllers"] = "XInput \u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC",
            ["Yes, if ClawTweaks should control the controller, the fan and the LEDs."] = "\u306F\u3044\u3001ClawTweaks \u306B\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3001\u30D5\u30A1\u30F3\u3001LED \u3092\u4EFB\u305B\u308B\u5834\u5408\u306F\u5FC5\u8981\u3067\u3059\u3002",
            ["Yes, install"] = "\u306F\u3044\u3001\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Yes, reset everything"] = "\u306F\u3044\u3001\u3059\u3079\u3066\u30EA\u30BB\u30C3\u30C8\u3057\u307E\u3059",
            ["Yes, restore"] = "\u306F\u3044\u3001\u5FA9\u5143\u3057\u307E\u3059",
            ["Yes, restore the device"] = "\u306F\u3044\u3001\u30C7\u30D0\u30A4\u30B9\u3092\u5FA9\u5143\u3057\u307E\u3059",
            ["Yes, uninstall Center"] = "\u306F\u3044\u3001Center \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Yes, uninstall ClawTweaks"] = "\u306F\u3044\u3001ClawTweaks \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u307E\u3059",
            ["Your Claw's own gamepad is hidden and replaced by a virtual one."] = "Claw \u672C\u4F53\u306E\u30B2\u30FC\u30E0\u30D1\u30C3\u30C9\u3092\u96A0\u3057\u3001\u4EEE\u60F3\u306E\u3082\u306E\u306B\u7F6E\u304D\u63DB\u3048\u307E\u3059\u3002",
            ["Your current settings are backed up before the reset. The Game Bar closes \u2014 reopen it with Win+G."] = "\u30EA\u30BB\u30C3\u30C8\u524D\u306B\u73FE\u5728\u306E\u8A2D\u5B9A\u3092\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3057\u307E\u3059\u3002Game Bar \u306F\u9589\u3058\u307E\u3059 \u2014 Win+G \u3067\u958B\u304D\u76F4\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Your games"] = "\u3042\u306A\u305F\u306E\u30B2\u30FC\u30E0",
            ["usbip  (required for virtual controller)"] = "usbip  (\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306B\u5FC5\u8981)",
            ["version"] = "\u30D0\u30FC\u30B8\u30E7\u30F3",
            ["versions"] = "\u30D0\u30FC\u30B8\u30E7\u30F3",
            ["\u2022 All profiles, fan curves, TDP and controller settings are reset"] = "\u2022 \u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u3001\u30D5\u30A1\u30F3\u30AB\u30FC\u30D6\u3001TDP\u3001\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u8A2D\u5B9A\u3092\u3059\u3079\u3066\u30EA\u30BB\u30C3\u30C8",
