            ["Remove"] = "\u524A\u9664",
            ["Other"] = "\u305D\u306E\u4ED6",
            ["Recent immersive"] = "\u6700\u8FD1\u3092\u5927\u304D\u304F\u8868\u793A",
            ["OptiScaler wiki \u00B7 {0}"] = "OptiScaler \u306E wiki \u00B7 {0}",
            ["Sleep"] = "\u30B9\u30EA\u30FC\u30D7",
            ["Hibernate"] = "\u4F11\u6B62\u72B6\u614B",
            ["Launch"] = "\u8D77\u52D5",
            ["Edit"] = "\u7DE8\u96C6",
            ["Auto pre-restore \u2014 {0}"] = "\u5FA9\u5143\u524D\u306E\u81EA\u52D5\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7 \u2014 {0}",
            ["ClawTweaks {0} \u00B7 {1} \u00B7 {2} stores \u00B7 {3}"] = "ClawTweaks {0} \u00B7 {1} \u00B7 {2} \u30B9\u30C8\u30A2 \u00B7 {3}",
            ["Choose a program"] = "\u30D7\u30ED\u30B0\u30E9\u30E0\u3092\u9078\u3076",
            ["Add"] = "\u8FFD\u52A0",
            ["Add {0}"] = "{0} \u3092\u8FFD\u52A0",
            ["Open Center"] = "Center \u3092\u958B\u304F",
            ["Open Library"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3092\u958B\u304F",
            ["Exit Center"] = "Center \u3092\u7D42\u4E86",
            ["The update could not install itself. Try the button below."] = "\u66F4\u65B0\u304C\u81EA\u5206\u3067\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u4E0B\u306E\u30DC\u30BF\u30F3\u3092\u8A66\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Installing\u2026"] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u4E2D\u2026",
            ["Install update now"] = "\u4ECA\u3059\u3050\u66F4\u65B0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Version {0} is still installed for all users, in {1}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u30D0\u30FC\u30B8\u30E7\u30F3 {0} \u304C\u5168\u30E6\u30FC\u30B6\u30FC\u5411\u3051\u306B {1} \u306B\u307E\u3060\u5165\u3063\u3066\u3044\u307E\u3059\u3002\u3053\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u3042\u306A\u305F\u306E\u30E6\u30FC\u30B6\u30FC\u30D5\u30A9\u30EB\u30C0\u30FC\u306B\u5165\u308B\u306E\u3067\u53E4\u3044\u65B9\u306F\u4F7F\u308F\u308C\u307E\u305B\u3093\u304C\u3001\u524A\u9664\u3059\u308B\u307E\u3067\u8A2D\u5B9A \u2192 \u30A2\u30D7\u30EA\u3068\u30B9\u30BF\u30FC\u30C8\u30E1\u30CB\u30E5\u30FC\u306B\u6B8B\u308A\u3001\u9593\u9055\u3063\u3066\u8D77\u52D5\u3057\u3084\u3059\u3044\u72B6\u614B\u3067\u3059\u3002",
            ["A previous version is still installed for all users, in {0}. This version installs into your own user folder instead, so the old one is no longer used \u2014 but it stays in Settings \u2192 Apps and in the Start Menu until it's removed, where it's easy to launch by mistake."] = "\u4EE5\u524D\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u304C\u5168\u30E6\u30FC\u30B6\u30FC\u5411\u3051\u306B {0} \u306B\u307E\u3060\u5165\u3063\u3066\u3044\u307E\u3059\u3002\u3053\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u3042\u306A\u305F\u306E\u30E6\u30FC\u30B6\u30FC\u30D5\u30A9\u30EB\u30C0\u30FC\u306B\u5165\u308B\u306E\u3067\u53E4\u3044\u65B9\u306F\u4F7F\u308F\u308C\u307E\u305B\u3093\u304C\u3001\u524A\u9664\u3059\u308B\u307E\u3067\u8A2D\u5B9A \u2192 \u30A2\u30D7\u30EA\u3068\u30B9\u30BF\u30FC\u30C8\u30E1\u30CB\u30E5\u30FC\u306B\u6B8B\u308A\u3001\u9593\u9055\u3063\u3066\u8D77\u52D5\u3057\u3084\u3059\u3044\u72B6\u614B\u3067\u3059\u3002",
            ["Removing it needs administrator rights. ClawTweaks Center never asks for those \u2014 the button below starts the old version's own uninstaller, so the prompt you see comes from it, about removing itself."] = "\u524A\u9664\u306B\u306F\u7BA1\u7406\u8005\u6A29\u9650\u304C\u5FC5\u8981\u3067\u3059\u3002ClawTweaks Center \u304C\u305D\u308C\u3092\u6C42\u3081\u308B\u3053\u3068\u306F\u3042\u308A\u307E\u305B\u3093 \u2014 \u4E0B\u306E\u30DC\u30BF\u30F3\u306F\u53E4\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u81EA\u8EAB\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u8D77\u52D5\u3059\u308B\u306E\u3067\u3001\u8868\u793A\u3055\u308C\u308B\u78BA\u8A8D\u306F\u305D\u3061\u3089\u306E\u3082\u306E\u3067\u3059\u3002",
            ["Scroll"] = "\u30B9\u30AF\u30ED\u30FC\u30EB",
            ["These install kernel drivers. Without the restart everything looks installed and the virtual controller still won't start."] = "\u3053\u308C\u3089\u306F\u30AB\u30FC\u30CD\u30EB\u30C9\u30E9\u30A4\u30D0\u30FC\u3092\u5165\u308C\u307E\u3059\u3002\u518D\u8D77\u52D5\u3057\u306A\u3044\u3068\u3001\u898B\u305F\u76EE\u306F\u5165\u3063\u3066\u3044\u3066\u3082\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306F\u8D77\u52D5\u3057\u307E\u305B\u3093\u3002",
            ["Version {0}"] = "\u30D0\u30FC\u30B8\u30E7\u30F3 {0}",
            ["The new ClawTweaks Center needs no administrator rights and installs to a different location."] = "\u65B0\u3057\u3044 ClawTweaks Center \u306F\u7BA1\u7406\u8005\u6A29\u9650\u304C\u4E0D\u8981\u3067\u3001\u5225\u306E\u5834\u6240\u306B\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u307E\u3059\u3002",
            ["No Xbox games are registered for this account."] = "\u3053\u306E\u30A2\u30AB\u30A6\u30F3\u30C8\u306B\u767B\u9332\u3055\u308C\u305F Xbox \u306E\u30B2\u30FC\u30E0\u304C\u3042\u308A\u307E\u305B\u3093\u3002",
            ["No ROMs for {0}."] = "{0} \u306E ROM \u304C\u3042\u308A\u307E\u305B\u3093\u3002",
            ["Cycle"] = "\u5207\u308A\u66FF\u3048",
            ["checking the installed version\u2026"] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u3092\u78BA\u8A8D\u4E2D\u2026",
            ["you have {0}."] = "\u73FE\u5728\u306F {0} \u3067\u3059\u3002",
            ["Requires ClawTweaks {0} or newer"] = "ClawTweaks {0} \u4EE5\u964D\u304C\u5FC5\u8981\u3067\u3059",
            ["Reset, Backup and Restore need ClawTweaks {0} (or 0.1.8+) \u2014 {1} Update ClawTweaks from \"Update & Release\" first."] = "\u30EA\u30BB\u30C3\u30C8\u3001\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3001\u5FA9\u5143\u306B\u306F ClawTweaks {0} (\u307E\u305F\u306F 0.1.8+) \u304C\u5FC5\u8981\u3067\u3059 \u2014 {1} \u5148\u306B\u300C\u66F4\u65B0\u3068\u30EA\u30EA\u30FC\u30B9\u300D\u304B\u3089 ClawTweaks \u3092\u66F4\u65B0\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Unknown error."] = "\u4E0D\u660E\u306A\u30A8\u30E9\u30FC\u3067\u3059\u3002",
            ["Restoring backup \u2014 the helper will restart when done\u2026"] = "\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3092\u5FA9\u5143\u4E2D \u2014 \u5B8C\u4E86\u3059\u308B\u3068\u30D8\u30EB\u30D1\u30FC\u304C\u518D\u8D77\u52D5\u3057\u307E\u3059\u2026",
            ["Restore likely completed"] = "\u5FA9\u5143\u306F\u304A\u305D\u3089\u304F\u5B8C\u4E86\u3057\u307E\u3057\u305F",
            ["The helper restarted before confirming. Reopen the Game Bar (Win+G) and check your profiles \u2014 if anything looks off, restore the auto pre-restore backup."] = "\u30D8\u30EB\u30D1\u30FC\u304C\u78BA\u8A8D\u524D\u306B\u518D\u8D77\u52D5\u3057\u307E\u3057\u305F\u3002Game Bar (Win+G) \u3092\u958B\u3044\u3066\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u3092\u78BA\u8A8D\u3057\u3001\u304A\u304B\u3057\u3051\u308C\u3070\u5FA9\u5143\u524D\u306E\u81EA\u52D5\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3092\u623B\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["This ZIP has no valid ClawTweaks manifest \u2014 the helper will refuse it if it isn't a real backup."] = "\u3053\u306E ZIP \u306B\u306F\u6709\u52B9\u306A ClawTweaks \u306E\u30DE\u30CB\u30D5\u30A7\u30B9\u30C8\u304C\u3042\u308A\u307E\u305B\u3093 \u2014 \u672C\u7269\u306E\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u3067\u306A\u3051\u308C\u3070\u30D8\u30EB\u30D1\u30FC\u304C\u62D2\u5426\u3057\u307E\u3059\u3002",
            ["Different ClawTweaks version"] = "ClawTweaks \u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u304C\u9055\u3044\u307E\u3059",
            ["Supported."] = "\u5BFE\u5FDC\u3057\u3066\u3044\u307E\u3059\u3002",
            ["Recognized, but not supported yet."] = "\u8A8D\u8B58\u3057\u307E\u3057\u305F\u304C\u3001\u307E\u3060\u5BFE\u5FDC\u3057\u3066\u3044\u307E\u305B\u3093\u3002",
            ["Not a recognized MSI Claw \u2014 installing here is untested."] = "MSI Claw \u3068\u3057\u3066\u8A8D\u8B58\u3067\u304D\u307E\u305B\u3093 \u2014 \u3053\u3053\u3067\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u306F\u672A\u691C\u8A3C\u3067\u3059\u3002",
            ["Install the missing prerequisites"] = "\u4E0D\u8DB3\u3057\u3066\u3044\u308B\u524D\u63D0\u6761\u4EF6\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Download each one from the vendor and run their installer, then re-check."] = "\u305D\u308C\u305E\u308C\u30D9\u30F3\u30C0\u30FC\u304B\u3089\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u3066\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u5B9F\u884C\u3057\u3001\u518D\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Re-check and continue"] = "\u518D\u78BA\u8A8D\u3057\u3066\u7D9A\u3051\u308B",
            ["Re-check tools"] = "\u30C4\u30FC\u30EB\u3092\u518D\u78BA\u8A8D",
            ["Trust the ClawTweaks signing certificate"] = "ClawTweaks \u306E\u7F72\u540D\u8A3C\u660E\u66F8\u3092\u4FE1\u983C\u3059\u308B",
            ["ClawTweaks is signed with its own certificate, and Windows only installs a package whose certificate it trusts. You only have to do this once \u2014 every future build uses the same one."] = "ClawTweaks \u306F\u81EA\u524D\u306E\u8A3C\u660E\u66F8\u3067\u7F72\u540D\u3055\u308C\u3066\u304A\u308A\u3001Windows \u306F\u4FE1\u983C\u3057\u305F\u8A3C\u660E\u66F8\u306E\u30D1\u30C3\u30B1\u30FC\u30B8\u3057\u304B\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u307E\u305B\u3093\u3002\u5FC5\u8981\u306A\u306E\u306F\u4E00\u5EA6\u3060\u3051\u3067\u3001\u4ECA\u5F8C\u306E\u30D3\u30EB\u30C9\u3082\u540C\u3058\u8A3C\u660E\u66F8\u3092\u4F7F\u3044\u307E\u3059\u3002",
            ["The certificate was imported for your user account instead of the local machine. Windows only consults the machine store when installing a package, so this has no effect. Run the import again and pick \"Local Machine\" on the first page."] = "\u8A3C\u660E\u66F8\u304C\u30ED\u30FC\u30AB\u30EB\u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC\u3067\u306F\u306A\u304F\u30E6\u30FC\u30B6\u30FC\u30A2\u30AB\u30A6\u30F3\u30C8\u306B\u30A4\u30F3\u30DD\u30FC\u30C8\u3055\u308C\u307E\u3057\u305F\u3002Windows \u306F\u30D1\u30C3\u30B1\u30FC\u30B8\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6642\u306B\u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC\u306E\u30B9\u30C8\u30A2\u3057\u304B\u898B\u306A\u3044\u305F\u3081\u3001\u3053\u308C\u3067\u306F\u52B9\u679C\u304C\u3042\u308A\u307E\u305B\u3093\u3002\u3082\u3046\u4E00\u5EA6\u30A4\u30F3\u30DD\u30FC\u30C8\u3057\u3001\u6700\u521D\u306E\u30DA\u30FC\u30B8\u3067\u300C\u30ED\u30FC\u30AB\u30EB \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC\u300D\u3092\u9078\u3093\u3067\u304F\u3060\u3055\u3044\u3002",
            ["The certificate landed in \"Trusted Root Certification Authorities\". That is both more than ClawTweaks needs \u2014 it would make this certificate a trust anchor for anything, not just this package \u2014 and still not where Windows looks. Remove it from there and import it into \"Trusted People\" instead."] = "\u8A3C\u660E\u66F8\u304C\u300C\u4FE1\u983C\u3055\u308C\u305F\u30EB\u30FC\u30C8\u8A3C\u660E\u6A5F\u95A2\u300D\u306B\u5165\u308A\u307E\u3057\u305F\u3002\u3053\u308C\u306F ClawTweaks \u306B\u5FC5\u8981\u306A\u7BC4\u56F2\u3092\u8D85\u3048\u3066\u304A\u308A (\u3053\u306E\u30D1\u30C3\u30B1\u30FC\u30B8\u3060\u3051\u3067\u306A\u304F\u4F55\u306B\u3067\u3082\u52B9\u304F\u4FE1\u983C\u306E\u8D77\u70B9\u306B\u306A\u308A\u307E\u3059)\u3001\u3057\u304B\u3082 Windows \u304C\u898B\u308B\u5834\u6240\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002\u305D\u3053\u304B\u3089\u524A\u9664\u3057\u3001\u300C\u4FE1\u983C\u3055\u308C\u305F\u4EBA\u300D\u306B\u30A4\u30F3\u30DD\u30FC\u30C8\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Check the certificate and continue"] = "\u8A3C\u660E\u66F8\u3092\u78BA\u8A8D\u3057\u3066\u7D9A\u3051\u308B",
            ["Check certificate"] = "\u8A3C\u660E\u66F8\u3092\u78BA\u8A8D",
            ["Installed, but the helper did not appear in time \u2014 open the Game Bar (Win+G) manually."] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u307E\u3057\u305F\u304C\u3001\u30D8\u30EB\u30D1\u30FC\u304C\u6642\u9593\u5185\u306B\u73FE\u308C\u307E\u305B\u3093\u3067\u3057\u305F \u2014 Game Bar (Win+G) \u3092\u624B\u52D5\u3067\u958B\u3044\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Virtual pad"] = "\u4EEE\u60F3\u30D1\u30C3\u30C9",
            ["Virtual controller mode detected"] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30E2\u30FC\u30C9\u3092\u691C\u51FA",
            ["{0} active and running."] = "{0} \u304C\u6709\u52B9\u3067\u52D5\u4F5C\u4E2D\u3067\u3059\u3002",
            ["HW controller mode detected"] = "\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30E2\u30FC\u30C9\u3092\u691C\u51FA",
            ["MSI HW Controller active and running."] = "MSI \u306E\u30CF\u30FC\u30C9\u30A6\u30A7\u30A2\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u6709\u52B9\u3067\u52D5\u4F5C\u4E2D\u3067\u3059\u3002",
            ["Claw controller not detected."] = "Claw \u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3092\u691C\u51FA\u3067\u304D\u307E\u305B\u3093\u3002",
            ["Controller mode unknown"] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u30E2\u30FC\u30C9\u304C\u4E0D\u660E",
            ["The download did not complete. Check your internet connection and try again."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u304C\u5B8C\u4E86\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002\u30A4\u30F3\u30BF\u30FC\u30CD\u30C3\u30C8\u63A5\u7D9A\u3092\u78BA\u8A8D\u3057\u3066\u3084\u308A\u76F4\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["This version has no package to download."] = "\u3053\u306E\u30D0\u30FC\u30B8\u30E7\u30F3\u306B\u306F\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3059\u308B\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u3042\u308A\u307E\u305B\u3093\u3002",
            ["Download complete."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u304C\u5B8C\u4E86\u3057\u307E\u3057\u305F\u3002",
            ["The download contains no package file."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u306B\u30D1\u30C3\u30B1\u30FC\u30B8\u30D5\u30A1\u30A4\u30EB\u304C\u542B\u307E\u308C\u3066\u3044\u307E\u305B\u3093\u3002",
            ["The downloaded package is incomplete \u2014 its manifest is missing."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u4E0D\u5B8C\u5168\u3067\u3059 \u2014 \u30DE\u30CB\u30D5\u30A7\u30B9\u30C8\u304C\u3042\u308A\u307E\u305B\u3093\u3002",
            ["The downloaded package is not readable."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u305F\u30D1\u30C3\u30B1\u30FC\u30B8\u3092\u8AAD\u307F\u53D6\u308C\u307E\u305B\u3093\u3002",
            ["(received {0:N0} of {1:N0} bytes)"] = "({1:N0} \u30D0\u30A4\u30C8\u4E2D {0:N0} \u30D0\u30A4\u30C8\u53D7\u4FE1)",
            ["The download produced an empty file."] = "\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u305F\u30D5\u30A1\u30A4\u30EB\u304C\u7A7A\u3067\u3059\u3002",
            ["Click \"Install Certificate\u2026\" on the General tab."] = "\u300C\u5168\u822C\u300D\u30BF\u30D6\u306E\u300C\u8A3C\u660E\u66F8\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u2026\u300D\u3092\u62BC\u3057\u307E\u3059\u3002",
            ["Store Location: choose \"Local Machine\" (not \"Current User\"), then Next. Windows asks for administrator rights here \u2014 that prompt comes from Windows itself."] = "\u4FDD\u5B58\u5834\u6240: \u300C\u73FE\u5728\u306E\u30E6\u30FC\u30B6\u30FC\u300D\u3067\u306F\u306A\u304F\u300C\u30ED\u30FC\u30AB\u30EB \u30B3\u30F3\u30D4\u30E5\u30FC\u30BF\u30FC\u300D\u3092\u9078\u3073\u3001\u300C\u6B21\u3078\u300D\u3002\u3053\u3053\u3067 Windows \u304C\u7BA1\u7406\u8005\u6A29\u9650\u3092\u6C42\u3081\u307E\u3059\u304C\u3001\u305D\u308C\u306F Windows \u81EA\u8EAB\u306E\u78BA\u8A8D\u3067\u3059\u3002",
            ["Choose \"Place all certificates in the following store\", click Browse\u2026"] = "\u300C\u8A3C\u660E\u66F8\u3092\u3059\u3079\u3066\u6B21\u306E\u30B9\u30C8\u30A2\u306B\u914D\u7F6E\u3059\u308B\u300D\u3092\u9078\u3073\u3001\u300C\u53C2\u7167\u300D\u3092\u62BC\u3057\u307E\u3059\u3002",
            ["Select \"Trusted People\" \u2014 NOT \"Trusted Root Certification Authorities\"."] = "\u300C\u4FE1\u983C\u3055\u308C\u305F\u4EBA\u300D\u3092\u9078\u3073\u307E\u3059 \u2014 \u300C\u4FE1\u983C\u3055\u308C\u305F\u30EB\u30FC\u30C8\u8A3C\u660E\u6A5F\u95A2\u300D\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
            ["Next, then Finish. You should see \"The import was successful.\""] = "\u300C\u6B21\u3078\u300D\u3001\u305D\u3057\u3066\u300C\u5B8C\u4E86\u300D\u3002\u300C\u6B63\u3057\u304F\u30A4\u30F3\u30DD\u30FC\u30C8\u3055\u308C\u307E\u3057\u305F\u3002\u300D\u3068\u8868\u793A\u3055\u308C\u307E\u3059\u3002",
            ["Controller probe timed out."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u78BA\u8A8D\u304C\u30BF\u30A4\u30E0\u30A2\u30A6\u30C8\u3057\u307E\u3057\u305F\u3002",
            ["Controller probe failed: {0}"] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u78BA\u8A8D\u306B\u5931\u6557\u3057\u307E\u3057\u305F: {0}",
            ["MSI Claw controller not detected (VID_0DB0). Connect/enable the controller, or MSI Center M may have taken it over."] = "MSI Claw \u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3092\u691C\u51FA\u3067\u304D\u307E\u305B\u3093 (VID_0DB0)\u3002\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3092\u63A5\u7D9A/\u6709\u52B9\u5316\u3057\u3066\u304F\u3060\u3055\u3044\u3002MSI Center M \u304C\u5360\u6709\u3057\u3066\u3044\u308B\u53EF\u80FD\u6027\u3082\u3042\u308A\u307E\u3059\u3002",
            ["MSI Center M is running. It can fight ClawTweaks for the controller and LED. This is handled after installation."] = "MSI Center M \u304C\u52D5\u4F5C\u4E2D\u3067\u3059\u3002\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3068 LED \u3092 ClawTweaks \u3068\u596A\u3044\u5408\u3046\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002\u3053\u308C\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u5F8C\u306B\u51E6\u7406\u3057\u307E\u3059\u3002",
            ["Steam's Xbox controller filter driver is present \u2014 a common cause of double input. Check Steam Input settings if you see doubled inputs."] = "Steam \u306E Xbox \u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30D5\u30A3\u30EB\u30BF\u30FC\u30C9\u30E9\u30A4\u30D0\u30FC\u304C\u3042\u308A\u307E\u3059 \u2014 \u4E8C\u91CD\u5165\u529B\u306E\u3088\u304F\u3042\u308B\u539F\u56E0\u3067\u3059\u3002\u5165\u529B\u304C\u91CD\u306A\u308B\u5834\u5408\u306F Steam Input \u306E\u8A2D\u5B9A\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["{0} XInput controllers are currently visible. Two or more while playing = double input."] = "\u73FE\u5728 {0} \u53F0\u306E XInput \u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u898B\u3048\u3066\u3044\u307E\u3059\u3002\u30D7\u30EC\u30A4\u4E2D\u306B 2 \u53F0\u4EE5\u4E0A\u3042\u308B\u3068\u4E8C\u91CD\u5165\u529B\u3067\u3059\u3002",
            ["Controller healthy \u2014 ready to mount as a virtual pad."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306F\u6B63\u5E38\u3067\u3059 \u2014 \u4EEE\u60F3\u30D1\u30C3\u30C9\u3068\u3057\u3066\u63A5\u7D9A\u3067\u304D\u307E\u3059\u3002",
            ["MSI Claw controller not found. Connect/enable it (MSI Center M may hold it)."] = "MSI Claw \u306E\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093\u3002\u63A5\u7D9A/\u6709\u52B9\u5316\u3057\u3066\u304F\u3060\u3055\u3044 (MSI Center M \u304C\u63E1\u3063\u3066\u3044\u308B\u53EF\u80FD\u6027\u304C\u3042\u308A\u307E\u3059)\u3002",
            ["Controller HID is held by another process \u2014 close conflicting controller software and re-check."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E HID \u3092\u5225\u306E\u30D7\u30ED\u30BB\u30B9\u304C\u63E1\u3063\u3066\u3044\u307E\u3059 \u2014 \u7AF6\u5408\u3059\u308B\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u30BD\u30D5\u30C8\u3092\u9589\u3058\u3066\u518D\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Controller HID opened but did not respond \u2014 try re-checking; a reboot may be needed."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E HID \u306F\u958B\u3051\u307E\u3057\u305F\u304C\u5FDC\u7B54\u3057\u307E\u305B\u3093 \u2014 \u518D\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044\u3002\u518D\u8D77\u52D5\u304C\u5FC5\u8981\u306A\u5834\u5408\u3082\u3042\u308A\u307E\u3059\u3002",
            ["Could not determine controller health."] = "\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u72B6\u614B\u3092\u5224\u65AD\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["The helper did not answer the health probe."] = "\u30D8\u30EB\u30D1\u30FC\u304C\u72B6\u614B\u78BA\u8A8D\u306B\u5FDC\u7B54\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["Unknown device"] = "\u4E0D\u660E\u306A\u30C7\u30D0\u30A4\u30B9",
            ["Could not locate the installed package \u2014 helper files not deployed."] = "\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u6E08\u307F\u30D1\u30C3\u30B1\u30FC\u30B8\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093 \u2014 \u30D8\u30EB\u30D1\u30FC\u306E\u30D5\u30A1\u30A4\u30EB\u304C\u914D\u7F6E\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002",
            ["Helper files were not deployed \u2014 the widget will retry when it starts the helper."] = "\u30D8\u30EB\u30D1\u30FC\u306E\u30D5\u30A1\u30A4\u30EB\u304C\u914D\u7F6E\u3055\u308C\u307E\u305B\u3093\u3067\u3057\u305F \u2014 \u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u304C\u30D8\u30EB\u30D1\u30FC\u3092\u8D77\u52D5\u3059\u308B\u3068\u304D\u306B\u518D\u8A66\u884C\u3057\u307E\u3059\u3002",
            ["The helper is not answering."] = "\u30D8\u30EB\u30D1\u30FC\u304C\u5FDC\u7B54\u3057\u307E\u305B\u3093\u3002",
            ["A backup of your settings is at {0}"] = "\u8A2D\u5B9A\u306E\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u306F {0} \u306B\u3042\u308A\u307E\u3059",
            ["Could not connect to the helper."] = "\u30D8\u30EB\u30D1\u30FC\u306B\u63A5\u7D9A\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["The helper did not respond in time."] = "\u30D8\u30EB\u30D1\u30FC\u304C\u6642\u9593\u5185\u306B\u5FDC\u7B54\u3057\u307E\u305B\u3093\u3067\u3057\u305F\u3002",
            ["Disabling\u2026"] = "\u7121\u52B9\u5316\u4E2D\u2026",
            ["Disabled."] = "\u7121\u52B9\u3067\u3059\u3002",
            ["Enabling\u2026"] = "\u6709\u52B9\u5316\u4E2D\u2026",
            ["Enabled and verified ({0})."] = "\u6709\u52B9\u306B\u306A\u308A\u78BA\u8A8D\u3057\u307E\u3057\u305F ({0})\u3002",
            ["virtual pad"] = "\u4EEE\u60F3\u30D1\u30C3\u30C9",
            ["Hides the physical gamepad so games see only the virtual controller."] = "\u7269\u7406\u30B2\u30FC\u30E0\u30D1\u30C3\u30C9\u3092\u96A0\u3057\u3001\u30B2\u30FC\u30E0\u304B\u3089\u306F\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u3060\u3051\u304C\u898B\u3048\u308B\u3088\u3046\u306B\u3057\u307E\u3059\u3002",
            ["Take HidHide_x.x.x.x_x64.exe."] = "HidHide_x.x.x.x_x64.exe \u3092\u9078\u3093\u3067\u304F\u3060\u3055\u3044\u3002",
            ["Provides the virtual controller itself (the VIIPER backend)."] = "\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u672C\u4F53 (VIIPER \u30D0\u30C3\u30AF\u30A8\u30F3\u30C9) \u3092\u63D0\u4F9B\u3057\u307E\u3059\u3002",
            ["Take USBip-0.9.8.0-x64.exe from this page. The link opens version 0.9.8.0 deliberately \u2014 it is the version ClawTweaks supports."] = "\u3053\u306E\u30DA\u30FC\u30B8\u304B\u3089 USBip-0.9.8.0-x64.exe \u3092\u9078\u3093\u3067\u304F\u3060\u3055\u3044\u3002\u30EA\u30F3\u30AF\u306F\u610F\u56F3\u7684\u306B 0.9.8.0 \u3092\u958B\u304D\u307E\u3059 \u2014 ClawTweaks \u304C\u5BFE\u5FDC\u3059\u308B\u30D0\u30FC\u30B8\u30E7\u30F3\u3067\u3059\u3002",
            ["Do not download the ARM version, and do not take an older usbip release: below 0.9.8.0 the device blue-screens while the virtual controller runs."] = "ARM \u7248\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u305B\u305A\u3001\u53E4\u3044 usbip \u3082\u4F7F\u308F\u306A\u3044\u3067\u304F\u3060\u3055\u3044\u30020.9.8.0 \u672A\u6E80\u3067\u306F\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u52D5\u4F5C\u4E2D\u306B\u30D6\u30EB\u30FC\u30B9\u30AF\u30EA\u30FC\u30F3\u306B\u306A\u308A\u307E\u3059\u3002",
            ["Applies the per-game FPS cap and draws the on-screen display."] = "\u30B2\u30FC\u30E0\u3054\u3068\u306E FPS \u4E0A\u9650\u3092\u9069\u7528\u3057\u3001\u753B\u9762\u8868\u793A\u3092\u63CF\u753B\u3057\u307E\u3059\u3002",
            ["Take RivaTuner Statistics Server."] = "RivaTuner Statistics Server \u3092\u9078\u3093\u3067\u304F\u3060\u3055\u3044\u3002",
            ["Reads the CPU sensors ClawTweaks shows in the widget."] = "ClawTweaks \u304C\u30A6\u30A3\u30B8\u30A7\u30C3\u30C8\u306B\u8868\u793A\u3059\u308B CPU \u30BB\u30F3\u30B5\u30FC\u3092\u8AAD\u307F\u53D6\u308A\u307E\u3059\u3002",
            ["Take PawnIO Setup."] = "PawnIO Setup \u3092\u9078\u3073\u307E\u3059\u3002",
            ["This ClawTweaks Center build is outdated. Please download the latest build."] = "\u3053\u306E ClawTweaks Center \u306F\u53E4\u3044\u30D3\u30EB\u30C9\u3067\u3059\u3002\u6700\u65B0\u306E\u30D3\u30EB\u30C9\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["{0} (running {1}, needs {2}+)"] = "{0} ({1} \u304C\u5165\u3063\u3066\u3044\u307E\u3059\u3002{2}+ \u304C\u5FC5\u8981)",
            ["Test build"] = "\u30C6\u30B9\u30C8\u30D3\u30EB\u30C9",
            ["Release"] = "\u30EA\u30EA\u30FC\u30B9",
            ["BROKEN: leftover registry entries but no driver binary \u2014 reinstall and reboot"] = "\u58CA\u308C\u3066\u3044\u307E\u3059: \u30EC\u30B8\u30B9\u30C8\u30EA\u306E\u6B8B\u9AB8\u3060\u3051\u3067\u30C9\u30E9\u30A4\u30D0\u30FC\u672C\u4F53\u304C\u3042\u308A\u307E\u305B\u3093 \u2014 \u5165\u308C\u76F4\u3057\u3066\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044",
            ["BROKEN: usbip's files are installed but its driver is not registered \u2014 the installer's driver step (devnode.exe) failed. The usual cause is the -arm64 download, which the release page lists above the x64 one. Uninstall usbip, re-run the installer whose name ends in -x64.exe, and reboot."] = "\u58CA\u308C\u3066\u3044\u307E\u3059: usbip \u306E\u30D5\u30A1\u30A4\u30EB\u306F\u3042\u308A\u307E\u3059\u304C\u30C9\u30E9\u30A4\u30D0\u30FC\u304C\u767B\u9332\u3055\u308C\u3066\u3044\u307E\u305B\u3093 \u2014 \u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u306E\u30C9\u30E9\u30A4\u30D0\u30FC\u624B\u9806 (devnode.exe) \u304C\u5931\u6557\u3057\u307E\u3057\u305F\u3002\u3088\u304F\u3042\u308B\u539F\u56E0\u306F -arm64 \u7248\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3067\u3001\u30EA\u30EA\u30FC\u30B9\u30DA\u30FC\u30B8\u3067\u306F x64 \u7248\u306E\u4E0A\u306B\u4E26\u3093\u3067\u3044\u307E\u3059\u3002usbip \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3001\u540D\u524D\u304C -x64.exe \u3067\u7D42\u308F\u308B\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u5B9F\u884C\u3057\u3066\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Older versions crash the device with a blue screen while the virtual controller is running, so ClawTweaks will not start it. Run the ClawTweaks setup, or install {1} from the link on this page, and reboot."] = "\u975E\u5BFE\u5FDC\u30D0\u30FC\u30B8\u30E7\u30F3: usbip {0} \u304C\u5165\u3063\u3066\u3044\u307E\u3059\u304C\u3001ClawTweaks \u306B\u306F {1} \u304C\u5FC5\u8981\u3067\u3059\u3002\u53E4\u3044\u30D0\u30FC\u30B8\u30E7\u30F3\u306F\u4EEE\u60F3\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\u306E\u52D5\u4F5C\u4E2D\u306B\u30D6\u30EB\u30FC\u30B9\u30AF\u30EA\u30FC\u30F3\u3092\u8D77\u3053\u3059\u305F\u3081\u3001ClawTweaks \u306F\u8D77\u52D5\u3057\u307E\u305B\u3093\u3002ClawTweaks \u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u5B9F\u884C\u3059\u308B\u304B\u3001\u3053\u306E\u30DA\u30FC\u30B8\u306E\u30EA\u30F3\u30AF\u304B\u3089 {1} \u3092\u5165\u308C\u3066\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["UNSUPPORTED VERSION: usbip {0} is installed, ClawTweaks needs {1}. Uninstall usbip, install {1} from the link on this page, and reboot."] = "\u975E\u5BFE\u5FDC\u30D0\u30FC\u30B8\u30E7\u30F3: usbip {0} \u304C\u5165\u3063\u3066\u3044\u307E\u3059\u304C\u3001ClawTweaks \u306B\u306F {1} \u304C\u5FC5\u8981\u3067\u3059\u3002usbip \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3001\u3053\u306E\u30DA\u30FC\u30B8\u306E\u30EA\u30F3\u30AF\u304B\u3089 {1} \u3092\u5165\u308C\u3066\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
