            ["Uninstall ClawTweaks"] = "ClawTweaks \u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB",
            ["Onboarding"] = "\u521D\u671F\u8A2D\u5B9A",
            ["FAQ"] = "\u3088\u304F\u3042\u308B\u8CEA\u554F",
            ["Fixed while Center is the Windows full-screen start app."] = "Center \u304C Windows \u306E\u5168\u753B\u9762\u30B9\u30BF\u30FC\u30C8\u30A2\u30D7\u30EA\u306E\u9593\u306F\u56FA\u5B9A\u3067\u3059\u3002",
            ["Turn on \"Start Steam with the library\" in the library settings to speed this up next time."] = "\u6B21\u56DE\u901F\u304F\u3059\u308B\u306B\u306F\u3001\u30E9\u30A4\u30D6\u30E9\u30EA\u8A2D\u5B9A\u3067\u300C\u30E9\u30A4\u30D6\u30E9\u30EA\u3068\u4E00\u7DD2\u306B Steam \u3092\u8D77\u52D5\u300D\u3092\u30AA\u30F3\u306B\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Make the library your Xbox full-screen start app"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3092 Xbox \u5168\u753B\u9762\u30B9\u30BF\u30FC\u30C8\u30A2\u30D7\u30EA\u306B\u3059\u308B",
            ["Saves memory and start-up time. Run the setup from the GitHub releases page to register it."] = "\u30E1\u30E2\u30EA\u3068\u8D77\u52D5\u6642\u9593\u3092\u7BC0\u7D04\u3057\u307E\u3059\u3002GitHub \u306E\u30EA\u30EA\u30FC\u30B9\u30DA\u30FC\u30B8\u304B\u3089\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u3092\u5B9F\u884C\u3057\u3066\u767B\u9332\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Automatic check: off"] = "\u81EA\u52D5\u30C1\u30A7\u30C3\u30AF\uFF1A\u30AA\u30D5",
            ["Automatic check: {0}"] = "\u81EA\u52D5\u30C1\u30A7\u30C3\u30AF\uFF1A{0}",
            ["Change in Center settings"] = "Center \u8A2D\u5B9A\u3067\u5909\u66F4",
            ["Mute"] = "\u30DF\u30E5\u30FC\u30C8",
            ["Unmute"] = "\u30DF\u30E5\u30FC\u30C8\u89E3\u9664",
            ["Tabs order and visibility"] = "\u30BF\u30D6\u306E\u9806\u5E8F\u3068\u8868\u793A",
            ["Opens Steam in the tray when you open the library. The first Steam game after a boot starts faster."] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3092\u958B\u304F\u3068 Steam \u3092\u30C8\u30EC\u30A4\u306B\u8D77\u52D5\u3057\u307E\u3059\u3002\u8D77\u52D5\u5F8C\u6700\u521D\u306E Steam \u30B2\u30FC\u30E0\u304C\u3088\u308A\u901F\u304F\u59CB\u307E\u308A\u307E\u3059\u3002",
            ["In fullscreen mode, Steam's window can open behind Center."] = "\u5168\u753B\u9762\u30E2\u30FC\u30C9\u3067\u306F Steam \u306E\u30A6\u30A3\u30F3\u30C9\u30A6\u304C Center \u306E\u80CC\u5F8C\u306B\u958B\u304F\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002",
            ["Steam removes the game files. In fullscreen, Steam's dialog can open behind Center."] = "Steam \u304C\u30B2\u30FC\u30E0\u30D5\u30A1\u30A4\u30EB\u3092\u524A\u9664\u3057\u307E\u3059\u3002\u5168\u753B\u9762\u3067\u306F\u30C0\u30A4\u30A2\u30ED\u30B0\u304C Center \u306E\u80CC\u5F8C\u306B\u958B\u304F\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002",
            ["Opens your Epic library. Uninstall the game there."] = "Epic \u30E9\u30A4\u30D6\u30E9\u30EA\u3092\u958B\u304D\u307E\u3059\u3002\u305D\u3053\u3067\u30B2\u30FC\u30E0\u3092\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Deletes the game for this Windows user."] = "\u3053\u306E Windows \u30E6\u30FC\u30B6\u30FC\u306E\u30B2\u30FC\u30E0\u3092\u524A\u9664\u3057\u307E\u3059\u3002",
            ["Press again to delete the game."] = "\u3082\u3046\u4E00\u5EA6\u62BC\u3059\u3068\u30B2\u30FC\u30E0\u3092\u524A\u9664\u3057\u307E\u3059\u3002",
            ["No uninstaller found"] = "\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u898B\u3064\u304B\u308A\u307E\u305B\u3093",
            ["Runs the game's own uninstaller"] = "\u30B2\u30FC\u30E0\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u5B9F\u884C\u3057\u307E\u3059",
            ["Runs the game's own uninstaller. In fullscreen, it can open behind Center."] = "\u30B2\u30FC\u30E0\u306E\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u3092\u5B9F\u884C\u3057\u307E\u3059\u3002\u5168\u753B\u9762\u3067\u306F Center \u306E\u5F8C\u308D\u306B\u958B\u304F\u3053\u3068\u304C\u3042\u308A\u307E\u3059\u3002",
            ["Graphics (WHQL only)"] = "\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF\u30B9\uFF08WHQL \u306E\u307F\uFF09",
            ["Graphics (WHQL and non-WHQL)"] = "\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF\u30B9\uFF08WHQL \u3068\u975E WHQL\uFF09",
            ["Download started in the background. The installer opens when it is done."] = "\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u3067\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u958B\u59CB\u3057\u307E\u3057\u305F\u3002\u5B8C\u4E86\u3059\u308B\u3068\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u958B\u304D\u307E\u3059\u3002",
            ["Download started in the background - over 800 MB. The installer opens when it is done."] = "\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u3067\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u958B\u59CB\u3057\u307E\u3057\u305F\uFF08800 MB \u4EE5\u4E0A\uFF09\u3002\u5B8C\u4E86\u3059\u308B\u3068\u30A4\u30F3\u30B9\u30C8\u30FC\u30E9\u30FC\u304C\u958B\u304D\u307E\u3059\u3002",
            ["Download started in the background. The folder opens when it is done - run Setup.bat there."] = "\u30D0\u30C3\u30AF\u30B0\u30E9\u30A6\u30F3\u30C9\u3067\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3092\u958B\u59CB\u3057\u307E\u3057\u305F\u3002\u5B8C\u4E86\u3059\u308B\u3068\u30D5\u30A9\u30EB\u30C0\u30FC\u304C\u958B\u304F\u306E\u3067\u3001\u305D\u3053\u3067 Setup.bat \u3092\u5B9F\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["{0} update(s) ready, restart pending"] = "{0} \u4EF6\u306E\u66F4\u65B0\u304C\u6E96\u5099\u5B8C\u4E86\u3001\u518D\u8D77\u52D5\u5F85\u3061",
            ["Install them in Windows Update, then restart."] = "Windows Update \u3067\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3057\u3066\u304B\u3089\u518D\u8D77\u52D5\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
            ["Check drivers again"] = "\u30C9\u30E9\u30A4\u30D0\u30FC\u3092\u518D\u78BA\u8A8D",
            ["Also non-WHQL graphics drivers"] = "\u975E WHQL \u306E\u30B0\u30E9\u30D5\u30A3\u30C3\u30AF\u30B9\u30C9\u30E9\u30A4\u30D0\u30FC\u3082",
            ["Modded Wi-Fi driver instead of stock"] = "\u7D14\u6B63\u306E\u4EE3\u308F\u308A\u306B\u6539\u9020 Wi-Fi \u30C9\u30E9\u30A4\u30D0\u30FC",
            ["Wipe every ClawTweaks setting back to a clean state (all profiles, fan curves, TDP, controller). Optionally the library and Center settings too."] = "ClawTweaks \u306E\u5168\u8A2D\u5B9A\u3092\u521D\u671F\u5316\u3057\u307E\u3059\uFF08\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u3001\u30D5\u30A1\u30F3\u30AB\u30FC\u30D6\u3001TDP\u3001\u30B3\u30F3\u30C8\u30ED\u30FC\u30E9\u30FC\uFF09\u3002\u4EFB\u610F\u3067\u30E9\u30A4\u30D6\u30E9\u30EA\u3068 Center \u306E\u8A2D\u5B9A\u3082\u3002",
            ["Save all your profiles and settings into a single ZIP you can restore later. Optionally with the library, Center settings and your game art."] = "\u3059\u3079\u3066\u306E\u30D7\u30ED\u30D5\u30A1\u30A4\u30EB\u3068\u8A2D\u5B9A\u3092\u5F8C\u3067\u5FA9\u5143\u3067\u304D\u308B 1 \u3064\u306E ZIP \u306B\u4FDD\u5B58\u3057\u307E\u3059\u3002\u4EFB\u610F\u3067\u30E9\u30A4\u30D6\u30E9\u30EA\u3001Center \u306E\u8A2D\u5B9A\u3001\u30B2\u30FC\u30E0\u30A2\u30FC\u30C8\u3082\u3002",
            ["Also reset the library and Center settings"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3068 Center \u306E\u8A2D\u5B9A\u3082\u521D\u671F\u5316",
            ["Favorites, play history, your own apps, cover picks and every Center setting. Center restarts afterwards. The safety backup includes them too."] = "\u304A\u6C17\u306B\u5165\u308A\u3001\u30D7\u30EC\u30A4\u5C65\u6B74\u3001\u81EA\u5206\u3067\u8FFD\u52A0\u3057\u305F\u30A2\u30D7\u30EA\u3001\u9078\u3093\u3060\u30AB\u30D0\u30FC\u3001Center \u306E\u5168\u8A2D\u5B9A\u3002\u305D\u306E\u5F8C Center \u304C\u518D\u8D77\u52D5\u3057\u307E\u3059\u3002\u5B89\u5168\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7\u306B\u3082\u542B\u307E\u308C\u307E\u3059\u3002",
            ["Also back up the library and Center settings"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3068 Center \u306E\u8A2D\u5B9A\u3082\u30D0\u30C3\u30AF\u30A2\u30C3\u30D7",
            ["Favorites, play history, your own apps, cover picks, the art cache and every Center setting."] = "\u304A\u6C17\u306B\u5165\u308A\u3001\u30D7\u30EC\u30A4\u5C65\u6B74\u3001\u81EA\u5206\u3067\u8FFD\u52A0\u3057\u305F\u30A2\u30D7\u30EA\u3001\u9078\u3093\u3060\u30AB\u30D0\u30FC\u3001\u30A2\u30FC\u30C8\u30AD\u30E3\u30C3\u30B7\u30E5\u3001Center \u306E\u5168\u8A2D\u5B9A\u3002",
            ["with library and Center settings"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3068 Center \u8A2D\u5B9A\u3092\u542B\u3080",
            ["Library and Center settings included"] = "\u30E9\u30A4\u30D6\u30E9\u30EA\u3068 Center \u8A2D\u5B9A\u3092\u542B\u307F\u307E\u3059",
            ["Favorites, play history, your own apps, cover picks and every Center setting come back too. Center restarts when it is done."] = "\u304A\u6C17\u306B\u5165\u308A\u3001\u30D7\u30EC\u30A4\u5C65\u6B74\u3001\u81EA\u5206\u3067\u8FFD\u52A0\u3057\u305F\u30A2\u30D7\u30EA\u3001\u9078\u3093\u3060\u30AB\u30D0\u30FC\u3001Center \u306E\u5168\u8A2D\u5B9A\u3082\u623B\u308A\u307E\u3059\u3002\u5B8C\u4E86\u3059\u308B\u3068 Center \u304C\u518D\u8D77\u52D5\u3057\u307E\u3059\u3002",
            ["Center data: included"] = "Center \u30C7\u30FC\u30BF\uFF1A\u542B\u3080",
