            ["No release notes."] = "Brak informacji o wydaniu.",
            ["Backups live in {0}. Create one first."] = "Kopie s\u0105 w {0}. Najpierw utw\u00F3rz jedn\u0105.",
            ["Safety copy of the previous state: {0}"] = "Kopia bezpiecze\u0144stwa poprzedniego stanu: {0}",
            ["All ClawTweaks settings were reset to a clean state. Reopen the Game Bar (Win+G) to continue."] = "Wszystkie ustawienia ClawTweaks zosta\u0142y zresetowane. Otw\u00F3rz Game Bar (Win+G), aby kontynuowa\u0107.",
            ["Saved {0} stores to:\n{1}"] = "Zapisano {0} magazyn\u00F3w w:\n{1}",
            ["Restored {0} files. The helper is restarting \u2014 reopen the Game Bar (Win+G) to continue."] = "Przywr\u00F3cono {0} plik\u00F3w. Helper uruchamia si\u0119 ponownie \u2014 otw\u00F3rz Game Bar (Win+G), aby kontynuowa\u0107.",
            ["This backup is from '{0}', but this device looks like {1}. Device-specific values (TDP limits, fan scale) will be restored as-is."] = "Ta kopia pochodzi z \u201E{0}\u201D, a to urz\u0105dzenie wygl\u0105da na {1}. Warto\u015Bci specyficzne dla urz\u0105dzenia (limity TDP, skala wentylatora) zostan\u0105 przywr\u00F3cone bez zmian.",
            ["Backup is from {0}; you have {1} installed. Restoring across versions usually works, but isn't guaranteed."] = "Kopia pochodzi z {0}; masz zainstalowane {1}. Przywracanie mi\u0119dzy wersjami zwykle dzia\u0142a, ale nie jest gwarantowane.",
            ["You're on the \"{0}\" channel \u2014 the install routine is currently known not to work correctly on Insider builds."] = "Jeste\u015B na kanale \u201E{0}\u201D \u2014 procedura instalacji obecnie nie dzia\u0142a poprawnie na wersjach Insider.",
            ["\u25B2 Update available on GitHub: {0} ({1})"] = "\u25B2 Aktualizacja dost\u0119pna na GitHub: {0} ({1})",
            ["ClawTweaks Center update available: {0}"] = "Dost\u0119pna aktualizacja ClawTweaks Center: {0}",
            ["You're running {0}. Install it here \u2014 Center restarts when it's done."] = "Masz {0}. Zainstaluj tutaj \u2014 Center uruchomi si\u0119 ponownie po zako\u0144czeniu.",
            ["You're running {0}. Download the new Setup file and run it \u2014 it installs over this one, and no administrator rights are needed."] = "Masz {0}. Pobierz nowy plik instalatora i uruchom go \u2014 instaluje si\u0119 na obecnej wersji, bez uprawnie\u0144 administratora.",
            ["Installing {0}"] = "Instalowanie {0}",
            ["{0} \u2014 helper is up and running."] = "{0} \u2014 helper dzia\u0142a.",
            ["Installed {0}"] = "Zainstalowano {0}",
            ["Updated {0} \u2192 {1}"] = "Zaktualizowano {0} \u2192 {1}",
            ["Downgraded {0} \u2192 {1}"] = "Cofni\u0119to {0} \u2192 {1}",
            ["Reinstalled {0}"] = "Przeinstalowano {0}",
            ["Unexpected survivor: {0} handed over, {1} terminated."] = "Nieoczekiwany ocala\u0142y: {0} przekazanych, {1} zako\u0144czonych.",
            ["Downloading the package ({0})\u2026"] = "Pobieranie pakietu ({0})\u2026",
            ["Package verified: {0}, {1:F1} MB."] = "Pakiet zweryfikowany: {0}, {1:F1} MB.",
            ["Outdated version \u2014 install {0} or newer"] = "Nieaktualna wersja \u2014 zainstaluj {0} lub nowsz\u0105",
            ["Auto-jump active (position {0})."] = "Automatyczny skok aktywny (pozycja {0}).",
            ["Auto-jump set to position {0}."] = "Automatyczny skok ustawiony na pozycj\u0119 {0}.",
            ["Could not start the old uninstaller: {0}"] = "Nie uda\u0142o si\u0119 uruchomi\u0107 starego deinstalatora: {0}",
            ["it is a launcher for the .dll next to it, not a standalone build."] = "to launcher dla pliku .dll obok, nie samodzielna wersja.",
            ["it is only {0} KB, too small to carry its own runtime."] = "ma tylko {0} KB, za ma\u0142o na w\u0142asne \u015Brodowisko uruchomieniowe.",
            ["its own file could not be inspected ({0})."] = "nie uda\u0142o si\u0119 sprawdzi\u0107 jego pliku ({0}).",
            ["This copy of Center cannot install itself: {0} Use the single-file build from the release page (or publish/), not the executable from a plain build output."] = "Ta kopia Center nie mo\u017Ce si\u0119 zainstalowa\u0107: {0} U\u017Cyj jednoplikowej wersji ze strony wyda\u0144 (lub publish/), nie pliku exe ze zwyk\u0142ej kompilacji.",
            ["Installing to {0}..."] = "Instalowanie w {0}...",
            ["Could not create the desktop icon: {0}"] = "Nie uda\u0142o si\u0119 utworzy\u0107 ikony na pulpicie: {0}",
            ["Install failed: {0}"] = "Instalacja nie powiod\u0142a si\u0119: {0}",
            ["Waiting for the running Center to close ({0}/{1})..."] = "Oczekiwanie na zamkni\u0119cie dzia\u0142aj\u0105cego Center ({0}/{1})...",
            ["Connecting controller"] = "\u0141\u0105czenie kontrolera",
            ["Setting up virtual gamepad\u2026"] = "Przygotowywanie kontrolera wirtualnego\u2026",
            ["Controller connected"] = "Kontroler po\u0142\u0105czony",
